# ==================== MODELS ====================

def serialize_id(obj):
    """Convert MongoDB _id to string id and ensure datetime fields are UTC-marked"""
    if obj and '_id' in obj:
        obj['id'] = str(obj['_id'])
        del obj['_id']
    # Ensure all datetime fields are serialized with UTC indicator
    if obj:
        for key, value in obj.items():
            if isinstance(value, datetime):
                # MongoDB returns naive datetimes that are actually UTC.
                # Mark them explicitly so JS `new Date()` parses correctly.
                if value.tzinfo is None:
                    obj[key] = value.replace(tzinfo=timezone.utc)
    return obj

def serialize_list(items):
    """Convert list of MongoDB docs to serialized format"""
    return [serialize_id(item) for item in items]

async def paginated_query(
    collection,
    query: dict,
    sort_field: str = "created_at",
    sort_dir: int = -1,
    limit: int = 50,
    skip: int = 0,
    projection: dict = None,
):
    """
    Standard paginated query. Returns {items, total, limit, skip, has_more}.
    Use instead of .to_list(1000) on every list endpoint.
    """
    cursor = collection.find(query, projection).sort(sort_field, sort_dir).skip(skip).limit(limit)
    items = []
    async for doc in cursor:
        items.append(serialize_id(dict(doc)))
    total = await collection.count_documents(query)
    return {
        "items": items,
        "total": total,
        "limit": limit,
        "skip": skip,
        "has_more": (skip + limit) < total,
    }

def get_today_range_est():
    """Get today's start/end in UTC, aligned to Eastern Time midnight.
    Uses zoneinfo to automatically handle EST (-5) vs EDT (-4)."""
    from zoneinfo import ZoneInfo
    eastern = ZoneInfo("America/New_York")
    now_eastern = datetime.now(eastern)
    today_midnight_eastern = now_eastern.replace(hour=0, minute=0, second=0, microsecond=0)
    today_start_utc = today_midnight_eastern.astimezone(timezone.utc)
    today_end_utc = today_start_utc + timedelta(hours=24)
    return today_start_utc, today_end_utc

def get_day_range_est(date_str):
    """UTC start/end for the given 'YYYY-MM-DD' calendar day in Eastern Time.
    Companion to get_today_range_est() for an explicit date; zoneinfo handles
    EST (-5) vs EDT (-4) for that specific day. Use this instead of parsing the
    date as UTC midnight, which buckets a late-evening Eastern check-in into the
    next calendar day."""
    from zoneinfo import ZoneInfo
    eastern = ZoneInfo("America/New_York")
    day_midnight_eastern = datetime.strptime(date_str, "%Y-%m-%d").replace(tzinfo=eastern)
    day_start_utc = day_midnight_eastern.astimezone(timezone.utc)
    return day_start_utc, day_start_utc + timedelta(hours=24)


def eastern_date(when=None) -> str:
    """The NEW YORK calendar date for an instant, as 'YYYY-MM-DD'.

    The date-only companion to the two range helpers above, which return
    datetimes. It did not exist, so every caller that wanted just a day string
    reached for `datetime.now(timezone.utc).strftime("%Y-%m-%d")` — which is
    the UTC day, and from 20:00 EDT (19:00 EST) that is TOMORROW in New York.

    Two different failures come out of that, and the second is the serious one:
      * in a QUERY the screen asks for the wrong day and looks empty;
      * on a RECORD a logbook is FILED stamped with tomorrow's date. That
        persists, and an inspector reads it.

    NYC DOB compliance is anchored to the New York calendar day, so this is the
    correct default for anything that names a day. Use the UTC clock only for
    instants (`check_in_time`, `created_at`) and for keys that merely need to be
    unique per rotation, never for a calendar date.
    """
    from zoneinfo import ZoneInfo
    when = when or datetime.now(timezone.utc)
    return when.astimezone(ZoneInfo("America/New_York")).strftime("%Y-%m-%d")


def eastern_today() -> str:
    """Today's New York calendar date, as 'YYYY-MM-DD'."""
    return eastern_date()






def eastern_datetime(when) -> str:
    """The New York day AND time for an instant: 'August 11, 2026 at 6:47 AM EDT'.

    Sibling of `eastern_clock`, for the places that print both halves — the
    "generated on" footers, most of all. The DAY is the New York day for the
    same reason `eastern_date` exists: 01:30 UTC is still the previous evening
    here, and a document stamped tomorrow is the failure that helper was
    written to stop.

    NOT strftime('%B %-d'): '%-d' is a glibc extension and this module is
    imported on Windows, so the day is interpolated (matching
    `_photo_added_after_filing_caption`, which learned it the hard way).
    """
    dt = _as_eastern_instant(when)
    return f"{dt.strftime('%B')} {dt.day}, {dt.year} at {eastern_clock(dt)}"

VALID_PROJECT_CLASSES = {"regular", "major_a", "major_b"}


# ── MR.5+ — third instance of "Pydantic default protects reads but
# not writes" defensive lift ──────────────────────────────────────
#
# Pattern history:
#   1. backend/requirements.txt missing redis package — production
#      500 because the lazy import path fired only in production,
#      tests mocked the helper.
#   2. companies.filing_reps[].credentials field default [] did not
#      survive Mongo writes on legacy filing-rep docs that predated
#      the field. MR.10 fixed via on-the-fly $set + a backfill
#      migration. Both the field and the lift logic are GONE in
#      MR.14 commit 4b — the credentials field no longer exists.
#   3. THIS — projects.gates (and 5 sibling list fields) default
#      protected reads via Pydantic's `[]` default, but
#      ProjectCreate.gates: Optional[List[...]] = None was carried
#      through model_dump() into the Mongo insert as null, then
#      ProjectResponse(**project_dict) rejected the null on response
#      construction (its type is non-Optional List, default = []).
#
# Same shape, same fix shape:
#   • forward-init in the write path
#   • defensive lift on the read path
#   • backfill migration for already-stranded legacy docs
#
# Future MR-N+ — CI check that scans Pydantic models for fields with
# defaults and verifies each appears explicitly in the corresponding
# insert dict. ~50 lines of AST walk; would have caught all three.

_PROJECT_LIST_DEFAULT_FIELDS = (
    "gates",
    "report_email_list",
    "site_device_subfolders",
    "trade_assignments",
    "required_logbooks",
    "nfc_tags",
)


def _lift_project_list_defaults(project: dict) -> dict:
    """Coerce list-typed fields from None → []. Idempotent.

    Mutates the input dict in place AND returns it (for fluent
    use at call sites). Two transformations, both safe:
      1. If a list field is present with value None → coerce to [].
         (This is the case Pydantic rejects on ProjectResponse
         construction, the production-500 trigger.)
      2. If a list field is missing entirely → set to [].
         (Defensive — keeps inserts shape-stable, makes it cheaper
         to reason about Mongo documents downstream.)

    Real-list values (including non-empty lists) pass through
    untouched. Idempotent: running twice on the same doc has no
    effect after the first call.
    """
    if not project:
        return project
    for fld in _PROJECT_LIST_DEFAULT_FIELDS:
        if project.get(fld) is None:  # matches both None-valued AND missing
            project[fld] = []
    return project


def _lift_project_retention_view(project: dict) -> dict:
    """Attach the COMPUTED `purge_eligible_at` for the response. In place.

    Called immediately before every ProjectResponse construction, and NOWHERE
    that writes. The value is derived from `job_completion_date` on each read
    and never persisted: a stored eligibility date would go stale the moment a
    completion date is corrected, and — worse — a stored date is something a
    future query can sort on, which is the first step toward the automated
    purge this feature deliberately does not have.

    Mirrors _lift_project_list_defaults above: mutate and return, so call sites
    can chain. Safe on a document that has no completion date — the helper
    reports None, which means "not computable", forever.
    """
    if project is None:
        return project
    project["purge_eligible_at"] = purge_eligible_at(project)
    return project


def classify_project(stories, footprint_sqft, full_demo, demo_stories, building_height=None):
    """NYC Building Code §3310 classification.
    Major Building = 10+ stories OR 125+ ft OR 100,000+ sqft footprint.
    SSM required = 15+ stories OR 200+ ft OR footprint > 100,000 sqft.
    SSC can substitute for SSM if < 15 stories AND < 200 ft AND <= 100,000 sqft.

    RETURNS None WHEN THERE WAS NOTHING TO CLASSIFY — the case this function
    used to answer "regular".

    Every input is Optional on ProjectCreate, so a project can be created with
    no storeys, no height, no footprint and no demolition. Not one threshold
    below fires, and the function fell through to `return "regular"`: NEVER
    ASSESSED and MEASURED AND FOUND NON-MAJOR became the same answer, stored
    in the same field, indistinguishable afterwards.

    That is only a cosmetic defect until something removes obligations on the
    strength of it. get_required_logbooks does exactly that — a non-major
    project is not required to keep the Concrete Safety Manager log or the
    SSC/SSM daily log — so a genuinely major project created before anybody
    typed its storey count would have had two required logs silently dropped.

    The rule this follows is already in this file, on `structural_system`:
    "NEVER inferred ... because guessing it would put the wrong trades in front
    of the CP." Same shape, heavier consequence. None is the honest answer and
    get_required_logbooks fails CLOSED on it.

    `full_demo` counts as an input on its own: declaring a full demolition is
    an assessment even with no storey count beside it. A zero or blank
    measurement is not an input — no building has zero storeys.
    """
    if not full_demo and not any(
        v for v in (stories, footprint_sqft, building_height, demo_stories)
    ):
        return None

    is_major = False
    needs_ssm = False

    # Check stories
    if stories and stories >= 15:
        is_major = True
        needs_ssm = True
    elif stories and stories >= 10:
        is_major = True

    # Check height
    if building_height and building_height >= 200:
        is_major = True
        needs_ssm = True
    elif building_height and building_height >= 125:
        is_major = True

    # Check footprint
    if footprint_sqft and footprint_sqft >= 100000:
        is_major = True
        needs_ssm = True

    # Full demolition of major building
    if full_demo and demo_stories and demo_stories >= 15:
        is_major = True
        needs_ssm = True
    elif full_demo and demo_stories and demo_stories >= 10:
        is_major = True

    if needs_ssm:
        return "major_b"
    if is_major:
        return "major_a"
    return "regular"

def classification_assessed(project) -> bool:
    """Has this project's §3310 classification actually been decided?

    A project_class OUTSIDE the valid set — missing, null, empty, junk — means
    nobody has assessed it. See classify_project: it returns None rather than
    "regular" when there was nothing to classify.

    This is the ONE question the fail-closed branch below turns on, so it is a
    named predicate rather than an inline truth test repeated at three call
    sites.
    """
    return str((project or {}).get("project_class") or "") in VALID_PROJECT_CLASSES


def logbook_activations(project=None) -> list:
    """Every log that has to be SWITCHED ON, and whether it currently is.

    One entry per registry type carrying a `conditional`, so the screen renders
    the toggles from the model instead of hardcoding four of them — and a fifth
    conditional type added to the registry appears with no client change.

    `activated_by` rides along because the answer differs per log and the
    client must not guess it: three of these are site conditions the CP can
    see, and hot work rests on an FDNY permit the admin holds.
    """
    proj = project or {}
    out = []
    for entry in LOGBOOK_TYPE_REGISTRY:
        field = entry.get("conditional")
        if not field:
            continue
        out.append({
            "log_type": entry["key"],
            "label": entry.get("label") or entry["key"],
            "field": field,
            "active": bool(proj.get(field)),
            "activated_by": entry.get("activated_by") or "cp",
        })
    return out


def logbook_activation_entry(log_type: str):
    """The registry entry for a log that can be switched on, or None."""
    for entry in LOGBOOK_TYPE_REGISTRY:
        if entry["key"] == log_type and entry.get("conditional"):
            return entry
    return None


def get_required_logbooks(project_class, project=None):
    """The logbooks this project must keep, RESOLVED FROM THE PROJECT.

    ── ONE MODEL, AND IT LIVES IN LOGBOOK_TYPE_REGISTRY ────────────────────
    This function used to hand-build the list, and the registry declared its
    own `conditional` keys that nothing read. The two disagreed on every
    conditional type: the registry said concrete needed >= 5 storeys and crane
    needed a permit; this function implemented the storey rule, keyed
    excavation on `adjacent_to_occupied` (a field nothing writes), and never
    appended crane under any condition at all — so the crane log was
    unreachable on every project this app has ever had.

    Now there is one declaration. Each registry entry carries:

      applicable_classes   which §3310 classes the log can apply to
      conditional          a project field that must be TRUE for it to apply
      activated_by         who may set that field — "cp" or "admin"

    ── TWO INDEPENDENT TESTS, and they are not the same kind of fact ───────
    CLASS is a building classification: it is decided once, from measurements,
    and the CP cannot change it. CONDITION is a site fact: a scaffold is up, a
    crane is on site, an excavation is open, the site holds a hot-work permit.
    A toggle is therefore applied whether or not the class is known — the
    scaffold is up regardless of how many storeys anybody typed.

    ── UNASSESSED FAILS CLOSED ────────────────────────────────────────────
    When the class has never been decided, the class test is SKIPPED rather
    than defaulted, so every class-restricted log is included. On a project
    with no classification that means the Concrete Safety Manager log and the
    SSC/SSM daily log both appear.

    That is deliberately the noisier error. The alternative — treating blank as
    "regular" — REMOVES two required logs from a project that may well be major,
    and a missing obligation on a compliance record is invisible in exactly the
    way an extra one is not. The caller is told which case it is
    (classification_assessed) so it can say so on screen instead of leaving the
    CP to wonder why two logs appeared.

    Order is registry order, which is the display order the CP list renders in.
    """
    proj = project or {}
    assessed = str(project_class or "") in VALID_PROJECT_CLASSES
    out = []
    for entry in LOGBOOK_TYPE_REGISTRY:
        classes = entry.get("applicable_classes") or ()
        if assessed and project_class not in classes:
            continue
        cond = entry.get("conditional")
        if cond and not proj.get(cond):
            continue
        out.append(entry["key"])
    return out

def normalize_phone(phone: str) -> str:
    """Normalize phone to E.164 format."""
    if not phone:
        return ""
    digits = re.sub(r'\D', '', phone)
    if len(digits) == 10:
        return f"+1{digits}"
    if len(digits) == 11 and digits[0] == '1':
        return f"+{digits}"
    return f"+{digits}"

def format_phone(phone: str) -> str:
    """Format a 10-digit phone number as XXX-XXX-XXXX"""
    digits = ''.join(c for c in (phone or '') if c.isdigit())
    if len(digits) == 11 and digits[0] == '1':
        digits = digits[1:]  # strip leading 1
    if len(digits) == 10:
        return f"{digits[:3]}-{digits[3:6]}-{digits[6:]}"
    return phone or ""
 
# ==================== NYC BIN RESOLUTION ====================
 
def _is_placeholder_bin(bin_str: str) -> bool:
    """NYC DOB uses BINs of the form X000000 (e.g. 2000000 for the Bronx)
    as placeholders when a building has no real BIN yet. Every DOB API
    returns zero records against these. Treat them as "no BIN" rather
    than a real lookup hit."""
    if not bin_str or not str(bin_str).isdigit() or len(str(bin_str)) != 7:
        return True
    # First digit is borough code (1–5); remaining six must not all be 0
    return str(bin_str)[1:] == "000000"


async def _resolve_bin_from_bbl(bbl: str) -> Optional[str]:
    """Secondary BIN lookup keyed off the BBL.

    When GeoSearch resolves an address to a borough *placeholder* BIN
    (e.g. 2000000) — common for "street without borough" inputs like
    "852 East 176th Street" — it still returns the exact 10-digit BBL
    (Borough-Block-Lot). The BBL is an unambiguous key, so a DOB-dataset
    lookup on it deterministically recovers the real 7-digit BIN, where
    fragile address-string matching against DOB's canonical street forms
    ("EAST 176 STREET") would miss.

    Uses DOB NOW: Build – Job Application Filings (ic3t-wcy2), which
    carries both `bbl` and `bin__`. Returns the majority-vote real BIN,
    or None on any miss/error so callers fall through to the existing
    address-based heal and the "No BIN on File" UI (no regression).
    """
    bbl = (bbl or "").strip()
    if len(bbl) != 10 or not bbl.isdigit():
        return None
    try:
        async with ServerHttpClient(timeout=10.0) as http_client:
            resp = await http_client.get(
                "https://data.cityofnewyork.us/resource/ic3t-wcy2.json",
                params={"bbl": bbl, "$limit": "50"},
            )
            if resp.status_code != 200:
                logger.warning(
                    f"BBL->BIN lookup returned {resp.status_code} for bbl={bbl}"
                )
                return None
            rows = resp.json() or []
    except Exception as e:
        logger.warning(f"BBL->BIN lookup error for bbl={bbl}: {e}")
        return None

    # DOB rows expose BIN as `bin__` (DOB NOW) or `bin`. Majority-vote a
    # real BIN across rows; ignore placeholders/blanks.
    votes: Dict[str, int] = {}
    for row in rows:
        cand = str(row.get("bin__") or row.get("bin") or "").strip()
        if cand and not _is_placeholder_bin(cand):
            votes[cand] = votes.get(cand, 0) + 1
    if not votes:
        return None
    return max(votes, key=votes.get)


async def fetch_nyc_bin_from_address(address: str) -> dict:
    """
    Query NYC GeoSearch to resolve an address into a BIN + BBL and a
    canonical normalized address string. Returns:
        {
          "nyc_bin": str|None,          # 7-digit BIN; None if placeholder or missing
          "bbl": str|None,              # 10-digit BBL; renamed from nyc_bbl in step 9.1
          "track_dob_status": bool,     # True only if we got a REAL BIN
          "normalized_address": str|None,
        }

    Field-name note: the BBL key was renamed from `nyc_bbl` to `bbl`
    on 2026-04-27 (step 9.1). The `nyc_` prefix was redundant — BBL is
    by definition NYC. The function name itself is misleading (it
    fetches BOTH BIN and BBL); a follow-up cleanup will rename to
    `fetch_nyc_dob_ids_from_address`. Tracked but not blocking step 9.1.

    Placeholder BINs (X000000) are REJECTED — stored as None — so the
    caller falls back to address-based DOB queries and the diagnostic
    UI correctly reports "No BIN on file" instead of "BIN 2000000 with
    zero records".

    The normalized_address (GeoSearch's canonical `label`, e.g.
    "852 EAST 176 STREET, Bronx, NY, USA") gives the caller a clean
    address string to store, so downstream Socrata LIKE queries match
    DOB's canonical street forms like "EAST 176 STREET" instead of
    failing on user shorthand like "E 176".
    """
    result = {
        "nyc_bin": None,
        "bbl": None,
        "track_dob_status": False,
        "normalized_address": None,
    }
    if not address or len(address.strip()) < 5:
        return result

    endpoints = [
        "https://geosearch.planninglabs.nyc/v2/search",
        "https://geosearch.planning.nyc.gov/v2/search",
    ]

    for endpoint in endpoints:
        try:
            async with ServerHttpClient(timeout=10.0) as http_client:
                resp = await http_client.get(
                    endpoint,
                    params={"text": address.strip(), "size": "1"},
                )
                if resp.status_code != 200:
                    logger.warning(
                        f"GeoSearch {endpoint} returned {resp.status_code} for '{address}'"
                    )
                    continue

                data = resp.json()
                features = data.get("features", [])
                if not features:
                    logger.info(f"GeoSearch: no features for '{address}' via {endpoint}")
                    continue

                props = features[0].get("properties", {})
                pad_bin = (
                    props.get("pad_bin", "")
                    or props.get("addendum", {}).get("pad", {}).get("bin", "")
                )
                pad_bbl = (
                    props.get("pad_bbl", "")
                    or props.get("addendum", {}).get("pad", {}).get("bbl", "")
                )
                label = (props.get("label") or "").strip() or None

                # Canonical address — always capture it. A clean street
                # name unlocks the address-based DOB query fallback even
                # when the BIN is a placeholder or missing.
                if label:
                    result["normalized_address"] = label

                # Validate BIN: 7 digits, numeric, AND not a placeholder.
                if pad_bin and not _is_placeholder_bin(str(pad_bin)):
                    result["nyc_bin"] = str(pad_bin)
                    result["track_dob_status"] = True
                elif pad_bin:
                    logger.info(
                        f"GeoSearch returned placeholder BIN {pad_bin} for "
                        f"'{address}' — treating as no BIN so address-based "
                        f"DOB lookups are used instead."
                    )

                if pad_bbl:
                    result["bbl"] = str(pad_bbl)

                # BBL->BIN recovery: GeoSearch handed back a borough
                # placeholder (or no) BIN but a real BBL. Resolve the
                # real BIN from the exact BBL before giving up — this is
                # what auto-heals "street without borough" addresses at
                # creation/config time instead of leaving them in the
                # "No BIN on File" state.
                if not result["nyc_bin"] and result["bbl"]:
                    recovered = await _resolve_bin_from_bbl(result["bbl"])
                    if recovered:
                        result["nyc_bin"] = recovered
                        result["track_dob_status"] = True
                        logger.info(
                            f"BBL->BIN recovery: '{address}' "
                            f"bbl={result['bbl']} -> BIN={recovered}"
                        )

                logger.info(
                    f"GeoSearch resolved '{address}' -> BIN={result['nyc_bin']} "
                    f"BBL={result['bbl']} label={label!r} via {endpoint}"
                )
                return result

        except Exception as e:
            logger.warning(f"GeoSearch error for '{address}' via {endpoint}: {e}")
            continue

    logger.error(f"All GeoSearch endpoints failed for '{address}'")
    return result
 
class UserCreate(BaseModel):
    email: EmailStr
    password: str
    name: str
    # THE DEFAULT IS STILL "worker" AND IT IS NO LONGER ASSIGNABLE. The two
    # facts do not conflict: `register` (self-serve signup) overwrites `role`
    # with ROLE_DEMO before it writes and never reads this default, and
    # create_admin_user now runs every value through `assert_assignable_role`,
    # so a POST /admin/users that omits the field is refused by name instead of
    # quietly minting the role the ruling withdrew. Removing the default would
    # make `role` required on the REGISTER body too, which is a public contract
    # change for no gain.
    role: str = "worker"
    company_name: Optional[str] = None
    company_id: Optional[str] = None
    phone: Optional[str] = None
    trade: Optional[str] = None
    # ── The superintendent's DOB registration ───────────────────────────────
    # Accepted on create for a `superintendent` and REFUSED for every other
    # role — see create_admin_user. `dob_card_image` is a base64 data URL and
    # is never stored on the user document: it goes to R2 and the document
    # keeps the key and the URL.
    dob_superintendent_number: Optional[str] = None
    dob_registration_expiry: Optional[str] = None
    dob_card_image: Optional[str] = None

class UserLogin(BaseModel):
    email: str
    password: str

class UserResponse(BaseModel):
    id: str
    email: str
    name: str
    role: str
    company_name: Optional[str] = None
    company_id: Optional[str] = None
    phone: Optional[str] = None
    trade: Optional[str] = None
    assigned_projects: List[str] = []
    created_at: Optional[datetime] = None
    # Account activation gating: "pending" (new self-serve signups, read-only
    # demo) or "approved" (full access). Server-controlled — never set by client.
    account_status: Optional[str] = None
    # READ-ONLY exposure so the client can hide UI a non-operator cannot use
    # (e.g. the owner-portal entrance). This is a RESPONSE model — declaring it
    # here cannot make it settable. The write side is guarded separately: the
    # field appears in NO request model and in NO field allow-list
    # (ALLOWED_USER_FIELDS / _SUB_ / _WORKER_ / _FIELDS), which
    # test_flag_is_in_no_allowlist asserts. It is DB-write only, by a human.
    #
    # Hiding the door is a UX courtesy, NOT the security boundary: the boundary
    # is require_platform_operator on the endpoints themselves. A client that
    # ignores this field still gets 403s.
    is_platform_operator: bool = False
    # ── The superintendent's DOB registration ───────────────────────────────
    # Present on a superintendent and None on everybody else. `dob_card_r2_url`
    # is the pointer to the card photograph; the image bytes never ride this
    # model, for the same reason USER_LIST_FIELDS is an inclusion projection.
    dob_superintendent_number: Optional[str] = None
    dob_registration_expiry: Optional[str] = None
    dob_card_r2_url: Optional[str] = None
    # DERIVED, NEVER STORED. {state, expires_on, days_remaining} from
    # `superintendent_licence_state`. Computed on read so that a licence which
    # lapsed while nobody opened the screen still reads as expired -- a stored
    # verdict would be the state of the world on the day it was written.
    licence: Optional[Dict[str, Any]] = None

class TokenResponse(BaseModel):
    token: str
    token_type: str = "bearer"
class UpdateProfileRequest(BaseModel):
    name: Optional[str] = None
    phone: Optional[str] = None

class UpdatePasswordRequest(BaseModel):
    current_password: str
    new_password: str

# Project Models
# ── THE TRADE VOCABULARY ───────────────────────────────────────────
#
# ONE SOURCE OF TRUTH. This list was duplicated as DEFAULT_TRADES here and
# TRADE_SUGGESTIONS in app/project/[id]/trades.jsx -- twenty identical strings
# in two files, and NEITHER validated anything. The admin's control was a plain
# TextInput; the suggestion dropdown only filled it in. So "Framers" reached
# production, which is in neither list, and the file header on that screen
# claimed "No free-text" while sitting directly above a free-text field.
#
# The server owns the list. The client fetches it. A test asserts there is no
# second copy.
#
# THE LABEL IS THE KEY, NOT A CODE. A filed record must hold the canonical
# ENGLISH string -- the DOB reads English -- so storing CONCRETE and rendering
# a label was ruled out. Translation, when it lands, keys on the label.
#
# ** A PUBLISHED LABEL IS IMMUTABLE. **
#
# Deprecate an entry; NEVER re-spell one. A filed subcontractor_orientation
# holds the string forever, and re-spelling "Concrete / Cement" to "Concrete"
# would orphan every record carrying the old text -- silently, because nothing
# joins on it. That is why the deprecated list below exists instead of edits.
TRADE_VOCABULARY: List[str] = [
    "Concrete",
    # STAYS SEPARATE from Concrete, ruled: always done by the foundation
    # company on these sites, and it is a distinct crew.
    "Formwork",
    "Excavation",
    "Masonry",
    "Steel / Ironwork",
    "Framing",
    "Drywall",
    "Roofing",
    "Waterproofing",
    "Plumber",
    # STAYS SEPARATE from Plumber, ruled: never the same crew in NYC.
    "Water Main",
    "Electrical",
    "HVAC / Mechanical",
    "Sprinkler",
    "Fire Protection",
    "Elevator",
    "Glazing",
    "Painting",
    "Flooring",
    "Demolition",
    "Abatement",
    "Scaffolding",
    "Surveying",
    "Safety",
    "Cleaning",
]

# Valid on rows that already carry them, hidden from the picker, NEVER
# re-spelled. The stored string stays exactly as filed; the value here records
# what supersedes it so a reader is not left guessing why two spellings of one
# trade both count as vocabulary.
DEPRECATED_TRADES: Dict[str, str] = {
    "Concrete / Cement": "Concrete",
    "Framers": "Framing",
    "Electrician": "Electrical",
    # Ruled: always under Framing on these sites.
    "Carpentry": "Framing",
}

# Match key -> canonical label, for BOTH lists. Populated beside _roster_key,
# which is where the one normalization rule lives.
_TRADE_BY_KEY: Dict[str, str] = {}


def _trade_source(trade) -> str:
    """"vocabulary" if this string is a known trade, else "custom".

    THE ONLY THING THE MIGRATION WRITES. The stored `trade` is never touched --
    a value that matches nothing keeps its exact spelling and renders, files and
    prints identically. Only this flag differs, which is what lets a translator
    know no lookup exists and lets the admin screen count off-vocabulary rows.

    Deprecated labels count as VOCABULARY. They were published; a row carrying
    one is not an admin's off-list improvisation.
    """
    return "vocabulary" if _roster_key(trade) in _TRADE_BY_KEY else "custom"


class TradeAssignment(BaseModel):
    """One subcontractor assignment on a project.
    trade: the construction trade (e.g. 'HVAC / Mechanical')
    company: the sub doing that trade on this project (e.g. 'Air Star')
    id: stable server-minted row id. DECLARED so Pydantic v2 does not
        silently drop it (default model_config is extra="ignore", so an
        undeclared `id` never reaches the handler at all — a frontend-only
        fix is impossible). It is nonetheless SERVER-OWNED: update_project
        discards whatever the client sends and re-derives the id by
        matching the row against the stored roster (see
        _merge_trade_assignments).
    trade_source: "vocabulary" | "custom" -- SERVER-DERIVED, never accepted
        from the client. It says whether `trade` matches a published label, so
        a translator knows when no lookup exists and the admin screen can count
        off-vocabulary rows. The stored `trade` is a plain English string with
        no marker either way, so the DOB record, the report and the PDF are
        byte-identical whichever path produced the row.
    status: "inactive" marks a soft-deleted row. MUST stay a string —
        ProjectResponse.trade_assignments is List[Dict[str, str]], so a
        bool (or a None id) in the stored array 500s every later GET.
    """
    trade: str
    company: str
    id: Optional[str] = None
    status: Optional[str] = None
    trade_source: Optional[str] = None


class ProjectGate(BaseModel):
    """Per-project NFC gate. One row per mounted tag; workers tap the
    tag to open /checkin/{project_id}/{gate_id}. See card_audit module.
    """
    gate_id: str
    label: Optional[str] = None
    lat: Optional[float] = None
    lng: Optional[float] = None


class ProjectCreate(BaseModel):
    name: str
    location: Optional[str] = None
    address: Optional[str] = None
    status: str = "active"
    # ── THE NAME PEOPLE ACTUALLY CALL THIS JOB ─────────────────────────────
    #
    # Optional, free text, and the only field on a project that exists purely
    # for matching. A WhatsApp group is named by whoever made it — "The Church
    # Job", "Ridgewood", "Mrs. Katz" — and none of that appears in an address.
    # lib/group_match.py scores the group name against this alongside the
    # street, so one field filled in once removes a guess for every group on
    # that job.
    #
    # Never displayed in place of the address and never used to identify a
    # project anywhere else. A nickname is a hint, not a key.
    nickname: Optional[str] = None
    # NYC DOB Classification (§3310)
    building_stories: Optional[int] = None
    building_height: Optional[int] = None  # feet
    footprint_sqft: Optional[int] = None  # square feet
    has_full_demolition: bool = False
    demolition_stories: Optional[int] = None
    # ── WHICH LEVELS THIS BUILDING ACTUALLY HAS ─────────────────────────
    #
    # A STOREY COUNT IS NOT A LIST OF FLOORS. `building_stories` above says how
    # many storeys the §3310 test counts; it cannot say whether there is a
    # cellar under them or a bulkhead over them, and those are where work
    # happens and where a CP has to say work happened. The daily jobsite log
    # derives its location chips from this, and until these existed a CP on a
    # building with a cellar had "Somewhere else" and free text for it.
    #
    # THEY ARE NOT §3310 INPUTS AND MUST NOT BECOME ONE. `classify_project`
    # takes storeys, height, footprint and demolition storeys, and none of
    # these four is any of those -- a cellar does not make a building major.
    # They are deliberately absent from `classification_fields` in
    # update_project, so setting one re-classifies nothing.
    #
    # None MEANS NOBODY SAID, which is not False. An unset flag offers no chip
    # rather than asserting the building has no cellar; the CP still has free
    # text, exactly as he does for an unset storey count.
    has_sub_cellar: Optional[bool] = None
    has_cellar: Optional[bool] = None
    has_mezzanine: Optional[bool] = None
    has_roof_bulkhead: Optional[bool] = None
    project_class: Optional[str] = None  # admin override
    # Which superstructure loop this project runs. Drives which activity chips
    # the sequence ranker offers. NEVER inferred: when this is unset the ranker
    # reports structural_system_set=False and offers BOTH loops, because
    # guessing it would put the wrong trades in front of the CP.
    structural_system: Optional[Literal["cast_in_place", "cfs", "unknown"]] = None
    ssp_number: Optional[str] = None
    ssp_filing_date: Optional[str] = None
    ssp_expiration_date: Optional[str] = None
    # PR #14B — DOB project type taxonomy. Drives the cohort-aware
    # peer comparison (see lib/statistical_engine/cohort_config.py).
    # Populated either by the auto-classification trigger
    # (prewarm.maybe_classify_project_dob_type) on the next
    # compliance-sync after nyc_bin is set, OR via the admin
    # ``POST /api/admin/projects/{id}/classify-dob`` endpoint.
    dob_project_type: Optional[Literal[
        "new_building",
        "major_alt_with_enlargement",
        "minor_alt",
        "full_demo",
        "unknown",
    ]] = None
    dob_job_snapshot: Optional[Dict[str, Any]] = None
    dob_extracted_scope: Optional[Dict[str, Any]] = None
    # Card audit / NFC gate check-in config. See backend/card_audit.py.
    lat: Optional[float] = None
    lng: Optional[float] = None
    geofence_radius_m: Optional[int] = 150
    gates: Optional[List[ProjectGate]] = None

class ProjectUpdate(BaseModel):
    name: Optional[str] = None
    location: Optional[str] = None
    address: Optional[str] = None
    status: Optional[str] = None
    # See ProjectCreate. Editable from project settings.
    nickname: Optional[str] = None
    report_email_list: Optional[List[str]] = None
    report_send_time: Optional[str] = None
    building_stories: Optional[int] = None
    building_height: Optional[int] = None
    footprint_sqft: Optional[int] = None
    has_full_demolition: Optional[bool] = None
    demolition_stories: Optional[int] = None
    # See ProjectCreate. Not §3310 inputs and not in `classification_fields`;
    # None means nobody said, which is not False.
    has_sub_cellar: Optional[bool] = None
    has_cellar: Optional[bool] = None
    has_mezzanine: Optional[bool] = None
    has_roof_bulkhead: Optional[bool] = None
    project_class: Optional[str] = None
    # See ProjectCreate — unset means "not known", never "cast in place".
    structural_system: Optional[Literal["cast_in_place", "cfs", "unknown"]] = None
    ssp_number: Optional[str] = None
    ssp_filing_date: Optional[str] = None
    ssp_expiration_date: Optional[str] = None
    # PR #14B — DOB project type taxonomy. See ProjectCreate
    # docstring for usage.
    dob_project_type: Optional[Literal[
        "new_building",
        "major_alt_with_enlargement",
        "minor_alt",
        "full_demo",
        "unknown",
    ]] = None
    dob_job_snapshot: Optional[Dict[str, Any]] = None
    dob_extracted_scope: Optional[Dict[str, Any]] = None
    # Per-project subcontractor roster. Each entry pairs a trade with
    # the specific company doing that trade on this project. Workers
    # pick one combined entry from the dropdown at check-in time and
    # both their `trade` and `company` fields get populated from it.
    # Strict: the check-in endpoint rejects submissions whose
    # (trade, company) pair isn't in this list.
    trade_assignments: Optional[List[TradeAssignment]] = None
    # Card audit / NFC gate check-in config. See backend/card_audit.py.
    lat: Optional[float] = None
    lng: Optional[float] = None
    geofence_radius_m: Optional[int] = None
    gates: Optional[List[ProjectGate]] = None
    # ── Completion, legal hold, and the no-completion attestation ─────────
    #
    # THE COMPLETION IS A PAIR AND ONLY EVER A PAIR. A claim about a legal
    # event carries the event's identifier, so the CO number and the date are
    # accepted together or not at all; update_project refuses a half entry
    # rather than storing one. "YYYY-MM-DD", asserted by a human — see
    # lib/project_retention.py for why it is never inferred from updated_at,
    # last_dob_sync_at or status, and why it is a calendar-date string rather
    # than a tz-aware datetime.
    job_completion_date: Optional[str] = None
    job_completion_co_number: Optional[str] = None
    # `completed_by` and `completion_source` are NOT declared here, so a client
    # that sends them has them DROPPED rather than honoured — pydantic ignores
    # undeclared fields. Both are stamped by the server from the authenticated
    # caller, and the source is always the weakest value: nothing in this app
    # verifies a CO number, so every completion it holds is an attestation and
    # is recorded as one. See VALID_COMPLETION_SOURCES.
    #
    # The hold is a plain bool so that FALSE survives update_project's
    # drop-the-Nones filter and can therefore be LIFTED through this path.
    # `legal_hold_by` / `legal_hold_at` are server-stamped, like completed_by.
    legal_hold: Optional[bool] = None
    legal_hold_reason: Optional[str] = None
    # The other statement a named person can make about whether these records
    # may be destroyed: that this project was never completed, so there is no
    # completion to wait seven years from. Same bool-plus-reason shape as the
    # hold, and liftable for the same reason. `_by` / `_at` are server-stamped.
    no_completion_attested: Optional[bool] = None
    no_completion_reason: Optional[str] = None

class ProjectResponse(BaseModel):
    id: str
    name: str
    location: Optional[str] = None
    address: Optional[str] = None
    status: str = "active"
    # DECLARED HERE OR IT DOES NOT EXIST. A response_model is an allow-list:
    # pydantic drops every undeclared field with no error anywhere, which is
    # how three live Dropbox fields once reported every project as unlinked.
    # The settings screen reads this back after saving.
    nickname: Optional[str] = None
    company_id: Optional[str] = None
    company_name: Optional[str] = None
    nfc_tags: List[Dict] = []
    # ── Dropbox ───────────────────────────────────────────────────────────
    # dropbox_folder and dropbox_enabled ARE DEAD FIELDS. create_project sets
    # them False/None and NOTHING has written either since. They are declared
    # here only because project/[id].jsx still reads them, and removing them
    # changes that screen -- which belongs with the Dropbox redesign, not here.
    dropbox_folder: Optional[str] = None
    dropbox_enabled: bool = False

    # THE THREE BELOW ARE THE LIVE ONES, AND THEIR ABSENCE WAS A SILENT OUTAGE.
    #
    # A response_model is an ALLOW-LIST: pydantic drops every field it does not
    # declare, with no error anywhere. link-dropbox writes dropbox_folder_path,
    # the sync writes dropbox_last_synced, and #252 writes dropbox_sync -- none
    # were declared, so GET /projects/{id} reported every project as unlinked
    # no matter what the database held.
    #
    # The consequence was not cosmetic. Construction Plans renders its Sync
    # control as `project?.dropbox_folder_path ? <Sync> : <Link folder>`, so the
    # sync button was UNREACHABLE on every project that has ever been linked,
    # and Dropbox Settings showed a linked project as unlinked. The admin
    # integrations screen looked correct only because it reads the LIST
    # endpoint, which carries no response model -- two endpoints giving opposite
    # answers about the same project.
    dropbox_folder_path: Optional[str] = None
    dropbox_last_synced: Optional[datetime] = None
    # The run summary from #252: {run_id, status, expected, synced, failed,
    # started_at, finished_at}. Dict rather than a model because the client
    # reads it through dropboxSyncState.js, which already treats a missing or
    # malformed summary as "never synced" and fails toward letting the CP work.
    dropbox_sync: Optional[Dict] = None
    created_at: Optional[datetime] = None
    nyc_bin: Optional[str] = None
    # BBL field — 10-digit Borough-Block-Lot. Renamed from nyc_bbl
    # 2026-04-27 (step 9.1) per the §12 BIN-matcher spec. The
    # `nyc_` prefix was redundant (BBL is by definition NYC) and
    # produced naming inconsistency with §12 architecture refs.
    # During the transition window the legacy `nyc_bbl` field may
    # still be present on older Mongo docs; reads go through
    # _project_bbl() helper which prefers `bbl` and falls back to
    # `nyc_bbl`. Cleanup commit drops the legacy field after deploy.
    bbl: Optional[str] = None
    # BBL provenance metadata. Drives the §12 BIN-matcher tier-1
    # lookup. The legacy field was populated only at project creation
    # via fetch_nyc_bin_from_address; the step 9.1 migration stamps
    # that legacy path as 'address_lookup_at_creation' and lets future
    # admin / PLUTO-lookup edits track their source.
    bbl_source: Optional[str] = None  # "address_lookup_at_creation" | "pluto_lookup" | "manual_entry" | "geosupport" | "user_corrected"
    bbl_last_synced: Optional[datetime] = None
    # Rolling DOB-sync freshness, written by run_dob_sync_for_project on every
    # successful run. MUST be declared here: this model filters the project
    # DETAIL response, so an undeclared field is silently dropped — which is
    # exactly why the detail badge read undefined and showed "NEVER SYNCED" for
    # every project regardless of how recently it had synced.
    last_dob_sync_at: Optional[datetime] = None
    # MR.14 (commit 2a) — default True. The v1 monitoring product
    # treats DOB-signal polling as the core feature; opt-in to "no,
    # don't track me" is now the unusual case. Existing False docs
    # are NOT migrated (operator F7 — customer choice to flip).
    track_dob_status: bool = True
    report_email_list: List[str] = []
    report_send_time: str = "18:00"
    # "REGULAR", RESTORED BY RULING. This briefly defaulted to None, on the
    # reasoning that an absent key meant "nobody assessed this §3310
    # classification" and defaulting it asserted an assessment nobody made.
    #
    # The operator has since ruled that REGULAR IS THE ANSWER, not a guess: a
    # project starts regular and an admin changes it when the project changes.
    # So an absent key is not an unanswered question — it is a project nobody
    # has needed to reclassify.
    #
    # WHAT THE DEFAULT DOES AND DOES NOT REACH, checked rather than assumed.
    # It fires only on an ABSENT key, which after this ruling means exactly one
    # population: legacy documents written before the classification model
    # landed. Both write paths always SET the key, and the create form now
    # always sends a class.
    #
    # It does NOT reach the fail-closed logbook rule. Every
    # get_required_logbooks caller (:9865, :18322, :20294, :24443) reads
    # `project.get("project_class")` off the RAW MONGO DOCUMENT, never off this
    # model — so a legacy project keeps being computed as unassessed
    # server-side and keeps its full logbook set. This default changes what the
    # API says, not what the compliance rule decides.
    project_class: Optional[str] = "regular"
    suggested_class: Optional[str] = None
    building_stories: Optional[int] = None
    building_height: Optional[int] = None
    footprint_sqft: Optional[int] = None
    has_full_demolition: bool = False
    demolition_stories: Optional[int] = None
    # See ProjectCreate. Not §3310 inputs and not in `classification_fields`;
    # None means nobody said, which is not False.
    has_sub_cellar: Optional[bool] = None
    has_cellar: Optional[bool] = None
    has_mezzanine: Optional[bool] = None
    has_roof_bulkhead: Optional[bool] = None
    #: Free-text levels a CP typed under "Somewhere else", remembered per
    #: project so the man who knows the building can name a level the office
    #: never entered and have it be a chip for everybody tomorrow. Read-only
    #: here: it is written by the logbook save, never by a project update.
    #: See PROJECT_OTHER_LOCATIONS_FIELD.
    remembered_other_locations: List[str] = []
    required_logbooks: List[str] = []
    ssp_number: Optional[str] = None
    ssp_filing_date: Optional[str] = None
    ssp_expiration_date: Optional[str] = None
    # Site-device visibility allowlist: top-level subfolder names
    # (relative to dropbox_folder_path) that users with role=site_device
    # are allowed to see. Empty list = site devices see nothing.
    # Admins/CPs always see the full folder regardless.
    site_device_subfolders: List[str] = []
    # Per-project subcontractor roster for the NFC check-in dropdown.
    # Each item is {trade, company}. Workers pick one combined entry.
    trade_assignments: List[Dict[str, str]] = []
    # Card audit / NFC gate check-in config. See backend/card_audit.py.
    lat: Optional[float] = None
    lng: Optional[float] = None
    geofence_radius_m: int = 150
    gates: List[Dict[str, Any]] = []

    # ── Completion, legal hold, and the retention brake ───────────────────
    #
    # DECLARED, DELIBERATELY AND COMPLETELY. This model is an ALLOW-LIST:
    # pydantic drops every field it does not declare, with no error anywhere.
    # That has already cost one outage — dropbox_folder_path, dropbox_sync and
    # dropbox_last_synced were written by the backend and undeclared here, so
    # the Sync control was unreachable on every linked project. The same
    # omission here would show "no legal hold" on a project that is under one,
    # to the exact person deciding whether to purge it.
    #
    # job_completion_date is "YYYY-MM-DD" — the ssp_expiration_date convention.
    # See lib/project_retention.py for the dob_logs TTL incident that dictates
    # it is asserted by a human and inferred from nothing.
    job_completion_date: Optional[str] = None
    # The certificate's own number, stored as attested. NOT format-checked —
    # project_retention.co_number_problem() carries the argument, and the short
    # version is that this repo reads the DOB CO column under three different
    # spellings across two files, so it is in no position to rule on the shape
    # of the value inside it.
    job_completion_co_number: Optional[str] = None
    completed_by: Optional[str] = None
    completion_source: Optional[str] = None

    # THE NO-COMPLETION ATTESTATION. Declared for the same allow-list reason as
    # everything else here, and it matters more than most: this is the single
    # field that distinguishes "nobody has looked into this project's
    # completion" from "a named person stated it has none and may be purged".
    # Dropping it would show the second as the first, on the screen of the
    # person deciding whether to destroy the records.
    no_completion_attested: bool = False
    no_completion_reason: Optional[str] = None
    no_completion_attested_by: Optional[str] = None
    no_completion_attested_at: Optional[Any] = None

    # A hold NEVER EXPIRES. Default False so a legacy document with no key
    # reads as "not held" rather than None — the screen renders a badge off
    # this, and None would be a third state nothing handles.
    legal_hold: bool = False
    legal_hold_reason: Optional[str] = None
    legal_hold_by: Optional[str] = None
    # str | datetime: server-stamped as a UTC instant, but legacy or seeded
    # documents may carry a string. Typed permissively so a malformed stamp
    # cannot 500 the whole project read.
    legal_hold_at: Optional[Any] = None

    # COMPUTED ON EVERY READ, STORED NEVER, ACTED ON NEVER. The first day the
    # retention brake stops objecting — not a deadline, not a trigger. None
    # means "not computable", which for a project with no asserted completion
    # is the answer forever, NOT "eligible now". Nothing schedules off this.
    purge_eligible_at: Optional[str] = None

# ==================== CERTIFICATION MODELS ====================

class CertificationType(str, Enum):
    OSHA_10 = "OSHA_10"
    OSHA_30 = "OSHA_30"
    SST_FULL = "SST_FULL"
    SST_LIMITED = "SST_LIMITED"
    SST_SUPERVISOR = "SST_SUPERVISOR"
    FDNY_COF = "FDNY_COF"
    SCAFFOLD = "SCAFFOLD"
    RIGGING = "RIGGING"
    WELDING = "WELDING"
    ASBESTOS = "ASBESTOS"
    LEAD = "LEAD"
    CONFINED_SPACE = "CONFINED_SPACE"
    OTHER = "OTHER"

# SST cards are valid ~5 years; an expiry more than this many years in the
# future is a physically impossible OCR misread, not a real credential. Named
# so the sanity gate and its tests share one source of truth.
SST_EXPIRY_MAX_YEARS = 7

class WorkerCertification(BaseModel):
    type: str
    card_number: Optional[str] = None
    issue_date: Optional[datetime] = None
    expiration_date: Optional[datetime] = None
    verified: bool = False
    verified_by: Optional[str] = None
    verified_at: Optional[datetime] = None
    card_image_url: Optional[str] = None
    ocr_confidence: Optional[float] = None
    notes: Optional[str] = None
    # ── Capture-integrity fields (persist as raw dict keys today; declared here
    #    for documentation and future typed reads). ──
    # True when OCR extraction was incomplete or a value was sanity-flagged;
    # surfaces the row in the CP/admin cert-review queue.
    needs_review: bool = False
    # Machine code for WHY review is needed (frontend maps to EN/ES). One of:
    # CLASS_UNVERIFIED, EXPIRY_IMPLAUSIBLE, EXPIRY_UNPARSEABLE, EXPIRY_CONFLICT,
    # DUPLICATE_SST, EXTRACTION_INCOMPLETE.
    review_reason: Optional[str] = None
    # The raw OCR expiry string that FAILED the sanity gate. Retained so an
    # admin can correct it; NEVER promoted to expiration_date automatically.
    expiration_raw_rejected: Optional[str] = None
    # Deterministic 0..1 fraction of expected fields cleanly extracted. Replaces
    # the uncalibrated model self-`confidence` that was structurally null.
    extraction_completeness: Optional[float] = None

# ==================== CERTIFICATION GATE LOGIC ====================

