class LL196GenerateRequest(BaseModel):
    year: int
    month: int


@api_router.post("/projects/{project_id}/logbook/attestations/generate", dependencies=[Depends(require_approved), Depends(require_project_access)])
async def generate_ll196_attestation_endpoint(
    project_id: str,
    body: LL196GenerateRequest,
    current_user = Depends(get_current_user),
):
    """Trigger LL196 PDF generation for one project + month.
    Idempotent — re-generation overwrites the R2 object in place
    and upserts the logbook_entries row."""
    if not await _logbook_flag_enabled_for(current_user):
        _logbook_404()
    if body.month < 1 or body.month > 12:
        raise HTTPException(status_code=422, detail="month must be 1..12")
    if body.year < 2020 or body.year > 2100:
        raise HTTPException(status_code=422, detail="year out of range")

    from lib.logbook.ll196 import generate_ll196_attestation
    try:
        entry = await generate_ll196_attestation(
            db,
            project_id=project_id,
            year=body.year,
            month=body.month,
            triggered_by_user_id=str(current_user.get("id") or ""),
        )
    except ValueError as e:
        raise HTTPException(status_code=404, detail=str(e))
    return {"entry": serialize_id(dict(entry))}


@api_router.get("/projects/{project_id}/logbook/export")
async def export_logbook(
    project_id: str,
    format: str = "pdf",
    start_date: Optional[str] = None,
    end_date: Optional[str] = None,
    current_user = Depends(get_current_user),
):
    """Render the full audit window as a single PDF for download
    by compliance staff / inspectors. Streamed inline; no R2
    persistence — exports are point-in-time snapshots."""
    if not await _logbook_flag_enabled_for(current_user):
        _logbook_404()
    if format != "pdf":
        raise HTTPException(status_code=422, detail="format must be pdf")

    end_d = _logbook.schema.str_to_date(end_date) if end_date else datetime.now(timezone.utc).date()
    start_d = _logbook.schema.str_to_date(start_date) if start_date else (end_d - timedelta(days=30))
    if not start_d or not end_d or start_d > end_d:
        raise HTTPException(status_code=422, detail="Invalid date range")

    cursor = db.logbook_entries.find({
        "project_id": project_id,
        "entry_date": {
            "$gte": _logbook.schema.date_to_str(start_d),
            "$lte": _logbook.schema.date_to_str(end_d),
        },
    }).sort("entry_date", 1)
    entries = []
    async for d in cursor:
        entries.append(serialize_id(d))

    project = await db.projects.find_one({"_id": to_query_id(project_id)})
    project_name = (project or {}).get("name", "")

    # Build a minimal HTML rendering — same style language as the
    # LL196 PDF so the output looks consistent.
    rows = []
    for e in entries:
        rows.append(
            f"<tr>"
            f"<td>{e.get('entry_date','')}</td>"
            f"<td>{e.get('category','')}</td>"
            f"<td>{e.get('status','')}</td>"
            f"<td>{(e.get('deficiency_reason') or '').replace('<', '&lt;')[:200]}</td>"
            f"</tr>"
        )
    html = f"""<!doctype html><html><head><meta charset='utf-8'>
<title>Compliance audit — {project_name}</title>
<style>
  body {{ font-family:'Helvetica',sans-serif; padding:32px; }}
  h1 {{ font-size:22px; margin-bottom:6px; }}
  .meta {{ color:#555; font-size:12px; margin-bottom:24px; }}
  table {{ width:100%; border-collapse:collapse; font-size:11px; }}
  th, td {{ text-align:left; padding:5px 7px; border-bottom:1px solid #e5e7eb; }}
  th {{ background:#f9fafb; }}
</style></head><body>
<h1>Compliance audit — {project_name}</h1>
<div class='meta'>Period: {_logbook.schema.date_to_str(start_d)} to
  {_logbook.schema.date_to_str(end_d)} · Entries: {len(entries)}</div>
<table>
<thead><tr><th>Date</th><th>Category</th><th>Status</th><th>Notes</th></tr></thead>
<tbody>{''.join(rows)}</tbody>
</table></body></html>"""

    try:
        from weasyprint import HTML  # type: ignore
        # OFF THE EVENT LOOP. weasyprint is CPU-bound and synchronous, and a
        # render here blocked every other request for its whole duration --
        # including the once-a-minute report scheduler. The scheduled path
        # already does exactly this and says why: "doing it inline would stall
        # the once-a-minute scheduler for every other project due this tick."
        # These three on-demand endpoints were the ones it did not cover.
        def _render_pdf(h: str) -> bytes:
            return HTML(string=h).write_pdf()

        pdf_bytes = await asyncio.to_thread(_render_pdf, html)
    except Exception as e:
        logger.error(f"[logbook] export weasyprint failed: {e!r}")
        raise HTTPException(status_code=500, detail="PDF render failed")
    return Response(
        content=pdf_bytes,
        media_type="application/pdf",
        headers={
            "Content-Disposition": (
                f'inline; filename="logbook-{project_id}-'
                f'{_logbook.schema.date_to_str(start_d)}-'
                f'{_logbook.schema.date_to_str(end_d)}.pdf"'
            ),
        },
    )


# ==================== V2.2 RISK SCORE ENDPOINTS =================
#
# Phase V2.2 — Statistical Risk Engine + Event Predictor.
# Replaces V2.1's heuristic risk score entirely. NO feature flag —
# V2.2 is the only risk-score code path. The endpoints below
# preserve the V2.1 URL paths so the existing FE
# (RiskScoreCircle / RiskScoreDrawer) keeps working unchanged
# from the network perspective.
#
# In Commit 1 (V2.2 scaffolding) the endpoints exist but return
# minimal data — the new collections are empty until the operator
# triggers the initial 2-year backfill via the admin endpoint
# that lands in Commit 6. Commits 2–5 fill out the scoring
# pipeline; this commit just gets the URL surface in place so
# the FE doesn't 404.

@api_router.get("/projects/{project_id}/risk-score")
async def get_project_risk_score(
    project_id: str,
    current_user = Depends(get_current_user),
):
    """Return the latest risk score for a project. 404 if no
    score has been calculated yet — frontend renders the
    "PENDING" state (V2.1.4 design) until then.

    V2.2.1 fix: filter by `model_version: "statistical-v1"`
    so we don't return stale V2.1 heuristic-v1 rows. The
    `risk_scores` collection has both V2.1 and V2.2 documents
    on production (V2.2 didn't migrate or delete V2.1 rows).
    Without this filter the FE saw V2.1's old heuristic score
    instead of V2.2's statistical score."""
    cur = db.risk_scores.find({
        "project_id": project_id,
        "model_version": _stat_engine.MODEL_VERSION,
    }).sort("calculated_at", -1).limit(1)
    latest = None
    async for doc in cur:
        latest = doc
    if latest is None:
        raise HTTPException(status_code=404, detail="No score yet")

    # V2.3 Commit 6 — opportunistic prediction-resolution check.
    # Fire-and-forget: while the operator is viewing this
    # project's score, refresh any active 311-inspection
    # predictions for the same project. Picks up actual DOB
    # inspections that landed in the window between the last
    # 30-min sweep and now, so the FE sees current resolution
    # status without waiting for the scheduled tick. Wrapped in
    # try/except so a spawn-side bug never breaks the GET.
    try:
        asyncio.create_task(
            _stat_engine.opportunistic_resolution_check(db, project_id),
            name=f"prediction_resolution_check:{project_id}",
        )
    except Exception as _e:
        logger.warning(
            f"[prediction_resolution] opportunistic spawn failed for "
            f"{project_id}: {_e!r}",
        )

    return {"score": serialize_id(latest)}


@api_router.get("/projects/{project_id}/risk-score/history")
async def get_project_risk_score_history(
    project_id: str,
    days: int = Query(30, ge=1, le=365),
    current_user = Depends(get_current_user),
):
    """Return the time series of risk scores for charting. Capped
    at 365 days of history; default 30.

    V2.2.1.1 fix: same `model_version` filter applied as the
    GET-latest endpoint (V2.2.1). Without it, the trend chart
    on a long-lived project would mix V2.1 heuristic-v1 points
    with V2.2 statistical-v1 points — visually continuous but
    semantically apples-and-oranges since the two models have
    different scoring distributions."""
    cutoff = datetime.now(timezone.utc) - timedelta(days=days)
    docs = await db.risk_scores.find({
        "project_id": project_id,
        "model_version": _stat_engine.MODEL_VERSION,
        "calculated_at": {"$gte": cutoff},
    }).sort("calculated_at", -1).limit(500).to_list(500)
    return {"history": [serialize_id(d) for d in docs]}


@api_router.post("/projects/{project_id}/risk-score/calculate", dependencies=[Depends(require_approved), Depends(require_project_access)])
async def calculate_project_risk_score(
    project_id: str,
    current_user = Depends(get_current_user),
):
    """On-demand recalculation using the V2.2 statistical
    engine. Runs all 8 triggers, gathers inputs, computes the
    score + CI + factor breakdown, persists to risk_scores."""
    project = await db.projects.find_one({"_id": to_query_id(project_id)})
    if project is None:
        raise HTTPException(status_code=404, detail="Project not found")
    doc = await _stat_engine.recompute_and_persist(db, project)
    if not doc:
        raise HTTPException(status_code=422, detail="Score not produced")
    return {"score": serialize_id(doc)}


