@api_router.get("/reports/logbook/{logbook_id}/pdf")
async def get_single_logbook_pdf(logbook_id: str, token: Optional[str] = None, current_user=Depends(get_current_user)):
    """Generate PDF for a single logbook entry (per-type PDF).
    Reuses the combined report HTML generator but filters to one log type."""
    from fastapi.responses import Response
    
    logbook = await db.logbooks.find_one({"_id": to_query_id(logbook_id), "is_deleted": {"$ne": True}})
    if not logbook:
        raise HTTPException(status_code=404, detail="Logbook not found")
    
    project_id = logbook.get("project_id")
    date = logbook.get("date")
    log_type = logbook.get("log_type")
    
    # Generate full report HTML but we'll use it as-is since it filters by date
    # For a single-type PDF, generate targeted HTML
    html = await generate_single_logbook_html(logbook)
    
    try:
        from weasyprint import HTML
        # OFF THE EVENT LOOP -- see the note at the first of these three.
        def _render_pdf(h: str) -> bytes:
            return HTML(string=h).write_pdf()

        pdf_bytes = await asyncio.to_thread(_render_pdf, html)
    except Exception as e:
        logger.error(f"PDF generation failed: {e}")
        raise HTTPException(status_code=500, detail=f"PDF generation failed: {str(e)}")
    
    project = await db.projects.find_one({"_id": to_query_id(project_id)})
    project_name = (project.get("name", "report") if project else "report").replace(" ", "_")
    type_label = log_type.replace("_", "-") if log_type else "log"
    filename = f"Levelog_{type_label}_{project_name}_{date}.pdf"
    
    return Response(
        content=pdf_bytes,
        media_type="application/pdf",
        headers={"Content-Disposition": f'attachment; filename="{filename}"'},
    )
 
 
# ── THE CACHE KEY HAS TO CARRY THE RENDERER, NOT JUST THE RECORD ────────────
#
# Two caches serve the legal PDF and BOTH key on the record alone: the site
# device names its offline copy `{id}.{version}.pdf` from the log's own
# timestamp, and `_logbook_thumbnail_url` keys its R2 object on `updated_at`.
# Neither moves when this renderer changes, so a restyle would be invisible on
# exactly the two surfaces that matter -- the tablet an inspector reads from,
# and the thumbnails on the project record -- on every document that did not
# change. Which is every filed document, because a filed document cannot.
#
# BUMP THIS WHENEVER THE RENDERED APPEARANCE CHANGES. Not when the data
# changes: the record's own timestamp already covers that. This number exists
# for changes the record cannot see.
LEGAL_RENDERER_VERSION = 1


def _logbook_record_stamp(logbook: dict) -> str:
    """The record half of a cache version: first timestamp that exists.

    SAME PRECEDENCE AS THE CLIENT'S, deliberately -- docCache keys a logbook
    PDF on `updated_at || submitted_at || created_at` and the site screen
    writes the file under exactly that name. A different precedence here would
    name the same file twice and leave both on the tablet for ever.

    NORMALISED TO ALPHANUMERICS rather than passed through as an ISO string.
    The client sanitises the version into a filename the same way, and a raw
    datetime reaches it through a JSON encoder and a `new Date()` -- two
    conversions that have each produced a second on-disk copy before. A string
    with nothing in it to convert cannot.
    """
    for field in ("updated_at", "submitted_at", "created_at", "date"):
        v = logbook.get(field)
        if v is None or v == "":
            continue
        return re.sub(r"[^0-9A-Za-z]", "", str(v))[:32] or "0"
    return "0"


def _logbook_cache_version(logbook: dict) -> str:
    """The name every cache of this logbook's PDF must agree on.

    ONE FUNCTION, THREE CONSUMERS -- the thumbnail's R2 key, the site
    manifest's `rv`, and the `cache_version` on a submitted-log row. They are
    not allowed to disagree: the manifest builds the sweep's KEEP-SET and the
    submitted row names the FILE, so a mismatch is not a stale picture, it is
    the sweep deleting the offline record an inspector came to read.
    """
    return f"{_logbook_record_stamp(logbook)}r{LEGAL_RENDERER_VERSION}"


async def generate_single_logbook_html(logbook: dict) -> str:
    """The per-logbook PDF an inspector downloads. ONE MEDIUM: PAPER.

    THE STALE CLAIM THIS REPLACES: "Reuses the same styling as the combined
    report." It does not, and the difference is the whole of this change.
    `generate_combined_report` genuinely serves TWO media -- it is emailed AND
    handed to WeasyPrint -- so its wrapper is 680px because that is the right
    column for an email client, and a `@media print` block releases the width
    for the sheet of paper. This renderer has exactly ONE caller,
    `get_single_logbook_pdf` (server.py:18720), which hands the string straight
    to WeasyPrint and returns application/pdf. Nothing emails it. Its 700px
    wrapper was a constraint borrowed from a medium this document does not
    have: 700px on a ~794px A4 page, leaving a dead strip down the right.

    THE FIX WAS NEVER PORTED, AND THAT IS THE FINDING. The combined report
    corrected exactly this defect -- same page size, same cause, same dead
    strip -- and the correction stopped at the renderer someone was reading.
    Two renderers print the same stored records; fixing one of them fixes one
    document. The print block below is that block, ported.

    The width release stays inside `@media print` rather than simply deleting
    the 700px, so that a future email consumer of this string is not handed a
    full-bleed table. WeasyPrint renders at media type `print`, so the release
    applies on the only path that exists today.
    """

    # ONE SOURCE. This was the same literal written twice as a local, in
    # this renderer and in the investor report.
    BASE_URL = PUBLIC_API_BASE_URL
    
    project_id = logbook.get("project_id")
    project = await db.projects.find_one({"_id": to_query_id(project_id)})
    project_name = project.get("name", "Unknown") if project else "Unknown"
    project_address = project.get("address", "") if project else ""
    date = logbook.get("date", "N/A")
    log_type = logbook.get("log_type", "unknown")
    data = logbook.get("data", {})
    
    # THE ZONE IS PART OF THE FACT. This printed a UTC clock with the word
    # UTC beside it -- not wrong, but the only Eastern-looking number on a
    # New York document, sitting four hours from every other time on it.
    # `eastern_datetime` carries its own zone, so the literal goes with it.
    gen_time = eastern_datetime(datetime.now(timezone.utc))
    
    # Reuse existing style constants
    TH = (
        'style="background-color:#1e293b;color:#ffffff;padding:10px 12px;'
        'text-align:left;font-weight:600;font-size:11px;text-transform:uppercase;'
        'letter-spacing:0.5px;" bgcolor="#1e293b"'
    )
    TD = 'style="padding:10px 12px;border-bottom:1px solid #e2e8f0;color:#334155;"'
    
    
    def bold_para(label, value):
        return f'<p style="color:#475569;margin:6px 0;"><strong style="color:#0A1929;">{label}:</strong> {value}</p>'
    


    # ── ABSENT IS STATED, NEVER IMPLIED ──────────────────────────────────────
    # This renderer is read by a DOB inspector. A key the CP never filled must
    # never render as a VALUE — no invented "None", no silent "No". It renders
    # "— Not recorded", the same words generate_combined_report already prints
    # for the same fact (server.py:17486, :17553, :17612, :17696, :17862,
    # :17916, :17932). Two compliance surfaces must not disagree about one
    # record, and a blank is ambiguous: an inspector cannot tell whether the
    # field was never asked or asked and left unanswered.
    #
    # TWO KINDS OF ABSENCE, and they are NOT the same:
    #   (a) a FIELD missing from a section that IS being rendered
    #       -> "— Not recorded"
    #   (b) a ROW missing from a repeating list (load_entries,
    #       adjacent_buildings, slump_tests, osha entries)
    #       -> DROPPED, exactly as the combined report drops it. A row that
    #          does not exist is not an unrecorded field, and printing one
    #          would invent a record of work nobody logged.
    # A whole SECTION whose payload is entirely absent stays absent too — a
    # page of "— Not recorded" rows for a log that was never filled is the
    # same fabrication in a different direction.
    #
    # False and 0 ARE captured values and render as captured.
    #
    # THE LOCAL `NOT_RECORDED = "&mdash; Not recorded"` IS GONE. There were two
    # constants with the same name and DIFFERENT literals -- this one and the
    # module-level `"— Not recorded"` -- so the same absence read one way
    # on the per-logbook PDF and another on the combined report, and each had a
    # test pinning its own spelling. The module-level one wins because it is
    # tied to the device: test_weather_display_and_chip_trade pins it against
    # `fNotRecorded` in en.js, on the rule that one record must read the same in
    # the app and in the PDF. The entity and the character render identically.


    _raw = lambda v: v
    _yn = lambda v: "Yes" if v else "No"








    # Build type-specific content
    body_html = ""
    type_title = ""

    # Top-level attestation, shared by every branch below. Rendered only when
    # it is actually on the document.
    cp_name_line = (
        bold_para("CP", _capitalize_first(logbook.get("cp_name") or ""))
        if logbook.get("cp_name") else ""
    )
    cp_sig_block = render_signature_html(logbook.get("cp_signature"), "CP Signature")

    # ── A RECORD THAT IS NOT FILED SAYS SO, UNDER THE LETTERHEAD ────────
    #
    # PLAIN DATA, NOT HTML, and that is a deliberate difference from the
    # amendment banner below. That banner is shared with the twelve types
    # still on the old renderer and arrives pre-rendered because it already
    # had a design. This line exists only on the engine's sheet, so composing
    # its markup here would mean copying the engine's type tokens into this
    # file -- a second spelling of the visual system. The words belong with
    # the status constants; the ink belongs with the other primitives.
    #
    # ABOVE THE SWITCH, for the same reason the banner is: the switch returns.
    _filing_state = filing_state_notice(logbook.get("status"))

    # ── AN AMENDED RECORD SAYS SO, ON ITS OWN FACE ──────────────────────
    #
    # `amendment_sentence` reads the CHILD document -- amendment_reason,
    # created_by_name, created_at -- and never the clock, so an amendment
    # filed in September for an August log reads the same in December.
    #
    # IT PRINTS HERE AND NOT ON THE INVESTOR REPORT. The report indexes the
    # filing; the filing carries its own audit trail. The old placement was
    # the report's header, which reached the daily jobsite log and no other
    # type -- an amended toolbox talk or OSHA register said nothing anywhere.
    #
    # ESCAPED LOCALLY. The reason is operator-supplied text on its way into
    # an HTML document.
    #
    # COMPOSED ABOVE THE PER-TYPE SWITCH, WHICH RETURNS. This sat below the
    # switch, and a type rendering through the engine returned before ever
    # reaching it -- so the orientation sheet stopped carrying it the day it
    # was converted, on 15 amended records, and nothing said so. Every
    # renderer of this document now gets the same composed banner.
    import html as _amend_esc
    _amend_line = amendment_sentence(amendment_state(logbook))
    amendment_html = (
        f'<div style="margin-top:16px;padding:12px 14px;'
        f'background-color:#fffbeb;border-left:3px solid #b45309;">'
        f'<span style="font-size:10px;text-transform:uppercase;'
        f'letter-spacing:1.5px;color:#b45309;font-weight:600;">'
        f'AMENDED RECORD</span><br />'
        f'<span style="font-size:13px;color:#0A1929;">'
        f'{_amend_esc.escape(_amend_line)}</span></div>'
    ) if _amend_line else ""

    # ── WHAT THE ENGINE CANNOT AWAIT, RESOLVED HERE ─────────────────────
    #
    # `render` is synchronous and will stay that way: a renderer that can
    # await is a renderer that can query, and a declaration that can trigger a
    # database read is the branch chain growing back with a different shape.
    #
    # SO THE CALLER DOES THE AWAITING. Both of these are pre-shift's, and both
    # cross as DATA -- the same shape the filing-state line and the appended
    # photographs already use.
    _ctx_extra = {}
    if log_type == "site_superintendent_log":
        # WHICH ITEMS THE DATE REQUIRES, AND WHAT EACH ONE SAYS. Both live in
        # `cs_applicable_items` / `_cs_item_body`, which hold the BC 3301.13.13
        # selection rules and the per-item provenance lines. A declaration
        # cannot express a date-dependent statutory item list without becoming
        # a second copy of that rule.
        try:
            _cs_attr = await cs_attribution_for(
                db, project_id, date, (data or {}).get("presence") or {})
        except Exception as _e:                       # pragma: no cover
            logger.warning(f"cs attribution failed: {_e}")
            _cs_attr = None
        _ctx_extra["register_rows"] = _cs_register_rows(
            logbook, attribution=_cs_attr)
        # THE ATTRIBUTION SENTENCE, WHICH IS ALSO DEFECT A2.
        #
        # It says how this log's superintendent was matched to the filing, and
        # on the BC 3301.13.13 sheet it describes that match "by licence
        # number" -- a term the DOB card does not use; the card carries a
        # REGISTRATION number, and `registration_number` appears nowhere in
        # this repository.
        #
        # IT IS CARRIED VERBATIM AND NOT CORRECTED HERE. A conversion's job is
        # that the document still says what it said; changing the words on a
        # filed compliance record is a separate decision with the operator's
        # name on it, and it is recorded as A2 in the defect document.
        if _cs_attr:
            _ctx_extra["cs_attribution_sentence"] = attribution_sentence(
                _cs_attr)

    if log_type == "preshift_signin":
        _ps_workers = list((data or {}).get("workers") or [])
        try:
            _ps_resolved = await _resolve_signin_signatures(_ps_workers)
        except Exception as _e:                       # pragma: no cover
            logger.warning(f"signin signature resolution failed: {_e}")
            _ps_resolved = {}
        # INLINED ONTO THE ROW, not passed alongside it. The row formatter is
        # handed ONE row and must decide from it; a lookup table it would have
        # to index is a second source of truth for the same cell.
        #
        # A COPY, NEVER THE STORED ROW. This document must not mutate the
        # record it prints -- the row that reaches Mongo is the row the CP
        # filed.
        _rows = []
        for _w in _ps_workers:
            _w = dict(_w or {})
            _sid = str(_w.get("signin_id") or "")
            if _sid and not _w.get("signature"):
                _hit = _ps_resolved.get(_sid)
                if _hit:
                    _w["signature"] = _hit
                else:
                    # RECORDED AND NOT DRAWABLE is not "did not sign".
                    _w["signature_unavailable"] = True
            _rows.append(_w)
        _ctx_extra["rows_override"] = {"data.workers": _rows}
        try:
            _ctx_extra["preshift_affirmation_count"] = (
                await preshift_affirmation_count(db, project_id, date))
        except Exception as _e:                       # pragma: no cover
            logger.warning(f"affirmation count failed: {_e}")

    # ── THE PER-TYPE SWITCH ─────────────────────────────────────────────
    #
    # A type with a schema renders through the one engine. Everything else
    # falls through to the chain below, which is untouched -- that is the whole
    # safety of converting one type at a time, and it is asserted byte-for-byte
    # rather than assumed.
    #
    # REMOVING A NAME FROM CONVERTED_TYPES IS THE ROLLBACK: one line, no revert.
    # And a converted type's old branch is deleted in the FOLLOWING change,
    # once it has rendered in production and been read. Required, not optional:
    # "we will delete it later" is how one `if` acquired thirteen branches.
    if log_type in legal_render.CONVERTED_TYPES:
        _decl = legal_render.SCHEMAS[log_type]
        _records = [logbook]
        if (_decl.get("source") or {}).get("kind") == "group":
            # ONE SHEET PER (PROJECT, DATE), DRAWN FROM MANY FILED RECORDS.
            # They are not merged: each stays its own separately signed
            # document and contributes its own row carrying its own signature.
            try:
                _found = await db.logbooks.find({
                    "project_id": project_id,
                    "date": date,
                    "log_type": log_type,
                    "is_deleted": {"$ne": True},
                }).to_list(500)
                # SORTED IN PYTHON, NOT BY MONGO. `.sort("created_at", 1)` on
                # `logbooks` is an UNSERVED SORT ON A BASE64 COLLECTION, and the
                # sort ratchet refused it -- correctly: this collection holds
                # photographs, and an unindexed sort loads the matched set into
                # memory to order it. The group is one project on one date, so
                # ordering a few dozen rows in Python costs nothing.
                _found.sort(key=lambda r: str(r.get("created_at") or ""))
            except Exception as _e:
                logger.warning(f"legal_render group read failed: {_e}")
                _found = []
            # THE REQUESTED RECORD MUST BE ON THE SHEET. A draft, or a row the
            # group query cannot see, would otherwise produce a document that
            # does not contain the log somebody actually asked for.
            if any(str(_r.get("_id")) == str(logbook.get("_id")) for _r in _found):
                _records = _found
        _sheet = legal_render.render(log_type, _records, {
            "project":    project or {},
            "contractor": ((project or {}).get("company_name")
                           or (project or {}).get("name") or ""),
            "address":    project_address or project_name,
            # THE NAME AND THE ADDRESS ARE NOT THE SAME STRING and the sheet
            # needs both. `address` is what Site Information prints; this is
            # what the site is FILED under, and on one project in the corpus
            # they differ -- "857 Prescott Pl" against "8 PRESCOTT PLACE,
            # Brooklyn". The old document title carried the name, so a reader
            # searching his own filing by it found the record.
            "project_name": project_name,
            "date":       date,
            "date_line":  f"Date: {date}",
            # ONE STROKE RECONSTRUCTION, PASSED IN. A second copy of that
            # geometry inside the engine would drift from this one, and this
            # file has been bitten by exactly that twice.
            "signature_svg": _signature_paths_to_svg,
            # AND THE SAME ARGUMENT FOR THE AFFIRMATION BANNER, which the
            # engine's first version simply did not draw. `ink` appends what
            # this returns beneath every mark, so the sheet says whether the
            # signature under it was affirmed FOR THIS DOCUMENT -- and, when it
            # was not, prints the deficiency rather than a clean-looking blank.
            "signature_affirmation": _signature_affirmation_html,
            # WHAT THIS DOCUMENT IS, before what happened to it. The engine
            # draws this above the amendment banner: a reader needs to know a
            # record is a draft before he reads that somebody amended it.
            "filing_state": _filing_state,
            # RESOLVED HERE, DRAWN THERE. The walk is two levels deep, filters
            # on a flag and reads a UTC instant as a New York day; the engine
            # learns none of that for one block on one sheet.
            "appended_photographs": _appended_photo_rows(data),
            **_ctx_extra,
            # CONTENT, NOT CHROME. Composed above this switch for the reason
            # written there.
            "amendment_html": amendment_html,
        })
        if _sheet:
            return _sheet
        # A CONVERTED TYPE THAT PRODUCED NOTHING IS A CONTRADICTION, not a
        # fall-through. `render` returns None in exactly one case -- the type
        # has no schema -- and this arm only runs when it has one.
        #
        # WHAT IT WOULD FALL TO IS THE GENERIC BRANCH AT THE END, which prints
        # the type's title and the word Status. On a §3301 record that is a
        # statutory document demoted to a stub, and it would be filed and
        # signed looking deliberate. Loud beats plausible.
        raise RuntimeError(
            f"legal_render has a schema for {log_type!r} and returned no "
            f"sheet; the filed document would have printed as a stub")

    # THE CHAIN IS GONE, AND SO IS THE DOCUMENT IT BUILT.
    #
    # Thirteen hand-written arms composed an email-shell document with its
    # own stylesheet, and every one of them has been converted and deleted.
    # The dispatch above either returns the engine's sheet or raises --
    # `legal_render.render` declines only a type with no schema, and there
    # is no such type -- so nothing below this point could ever run again.
    #
    # WHAT WENT WITH IT: the `@page` box and the `@media print` width
    # release, the `tr.shell` exemption, `section_title`, `field_lines`,
    # `maybe_info_box`, `cell` and `toggle_block`. Their rules live in
    # lib/legal_render as primitives and formatters; the markup was the
    # only thing that did not move, and it was the only thing left.

    # ── A TYPE NOTHING RENDERS: A DOCUMENT, NOT A STUB AND NOT A 500 ───────
    #
    # THE CHAIN IS GONE AND SO IS ITS GENERIC ARM. That arm printed the type's
    # title and the word Status for anything nobody had written a branch for,
    # and the dispatch above calls that "a statutory document demoted to a
    # stub" -- filed and signed looking deliberate.
    #
    # DELETING IT OUTRIGHT WAS THE WRONG FIX AND A TEST SAID SO FIRST:
    #
    #     PASSES EITHER WAY. The fix must not be to delete the fallback --
    #     a record whose type was retired still has to render as something.
    #
    # That is right. A type is retired by a code change; the RECORDS filed
    # under it are not, and an inspector who asks for one must get a document
    # rather than a server error. Measured 2026-09-13: zero stored records
    # carry a type without a schema, so nothing takes this path today -- which
    # is a fact about today and not a reason to have no path.
    #
    # SO IT SAYS WHAT IT IS. Not the record's contents dressed as a sheet --
    # there is no renderer for them, and inventing one field layout for an
    # unknown type is how the stub came to look deliberate. It carries the
    # record's IDENTITY, states plainly that no renderer is configured, and
    # tells the reader to ask for the record another way. A document that
    # admits what it cannot show is not a compliance record and does not read
    # like one.
    # LOCALLY IMPORTED, like the other three escapers in this file. `server`
    # has no module-level `html` -- the name is shadowed by the HTML strings it
    # builds -- and every place that needs it imports it under its own alias.
    import html as _esc
    _t = _esc.escape(str(log_type or "").replace("_", " ").title() or
                     "Unrecognised record")
    logger.error(
        f"no renderer for log_type={log_type!r} (logbook "
        f"{logbook.get('_id')!r}); served the not-configured notice")
    return (
        "<!DOCTYPE html><html><head><meta charset=\"utf-8\">"
        f"<title>{_t} — {_esc.escape(str(project_name))} — "
        f"{_esc.escape(str(date))}</title>"
        "<style>@page { size: Letter portrait; margin: 0.75in; }"
        "body{font:400 11px Helvetica,Arial,sans-serif;color:#111;margin:0;}"
        "</style></head><body>"
        "<div style=\"border:1px solid #111;padding:16px;\">"
        "<div style=\"font:700 8px Helvetica,Arial,sans-serif;"
        "letter-spacing:0.12em;color:#555;\">PROJECT RECORD — "
        "NOT RENDERABLE</div>"
        f"<div style=\"font:700 18px Helvetica,Arial,sans-serif;"
        f"margin:6px 0 10px;\">{_t}</div>"
        f"<div>Job: {_esc.escape(str(project_address or project_name))}</div>"
        f"<div>Date: {_esc.escape(str(date))}</div>"
        f"<div>Status: {_esc.escape(str(logbook.get('status') or ''))}</div>"
        f"<div>Record: {_esc.escape(str(logbook.get('_id') or ''))}</div>"
        "<p style=\"margin:14px 0 0;\">This record was filed under a logbook "
        "type for which no renderer is configured, so its contents cannot be "
        "printed. <strong>This page is not the record.</strong> The stored "
        "record is intact; ask for it through support rather than treating "
        "this page as the filing.</p>"
        "</div></body></html>"
    )

# ==================== STATS / DASHBOARD ====================
@api_router.get("/stats/dashboard")
async def get_dashboard_stats(current_user = Depends(get_current_user)):
    company_id = get_user_company_id(current_user)
    today_start, today_end = get_today_range_est()
    
    query = {"is_deleted": {"$ne": True}}
    # The tenant filter is not conditional. `if company_id:` alone let a
    # caller with NO company read every tenant's rows, and that is the
    # DEFAULT state after self-serve registration. `_id: None` is
    # unsatisfiable, so one code path and one response shape;
    # `company_id: None` would match precisely the orphan rows. The
    # carve-out is the FLAG, never the `owner` role -- that role is what
    # every signup receives. Reasoned in full on get_all_checkins and
    # asserted by test_tenant_scope_census.py.
    # Counts only, no personal data -- and still wrong: it reported the
    # whole platform's worker and project totals to a caller who had not
    # onboarded.
    if company_id:
        query["company_id"] = company_id
    elif not is_platform_operator(current_user):
        query["_id"] = None
    
    total_workers = await db.workers.count_documents(query)

    # ON SITE = checked in AND within the Eastern-local "today" window, matching
    # the per-project active tile (GET /checkins/project/{id}/active). Without the
    # date bound this counted stale checked-in rows from prior days.
    on_site_query = {
        **query,
        "status": "checked_in",
        "check_in_time": {"$gte": today_start, "$lt": today_end},
    }
    unique_on_site = await db.checkins.distinct("worker_id", on_site_query)
    on_site_now = len(unique_on_site)
    
    project_query = {**query, "status": "active"}
    total_projects = await db.projects.count_documents(project_query)
    
    today_query = {**query, "check_in_time": {"$gte": today_start, "$lt": today_end}}
    today_checkins = await db.checkins.count_documents(today_query)
    
    return {
        "total_workers": total_workers,
        "total_projects": total_projects,
        "on_site_now": on_site_now,
        "today_checkins": today_checkins
    }
    


# ==================== CHECKLIST READ SHAPE ====================
#
# EVERY CHECKLIST READ SERVES `checklist` NESTED. The four read endpoints below
# hand back an assignment with a `checklist` object (title, description, items)
# and a computed `completions` list. Nothing serves `checklist_title` or
# `checklist_items` flat any more: no client ever read them, and
# `app/checklists.jsx:101` was calling `details.checklist.items.forEach` on a
# payload with no `checklist` key. That threw into the surrounding catch and
# told the CP "Could not load checklist" — so a newly assigned checklist could
# not be opened by the person it was assigned to, and only that person, and
# only until a completion record existed to send the other branch.
#
# THE TITLE IS DERIVED ON EVERY READ, AND THAT IS THE POINT — DO NOT "RESTORE"
# THE FLAT KEY. `assign_checklist` copies the title onto the assignment
# document at creation and `update_checklist` never propagates a rename, so
# `checklist_assignments.checklist_title` goes stale the first time a checklist
# is renamed. Joining db.checklists on every read makes that stale copy
# INVISIBLE WITHOUT A MIGRATION — the second copy still sits on the document,
# nothing serves it, so nothing can print the old name. Serving the stored key
# again (for a cheaper read, or because the field looks unused) brings the bug
# back with it. Do not store a third copy either; derive it.
#
# `completions` IS COMPUTED, NOT STORED, and is not a rename of anything.
# `complete_checklist` persists `item_completions` (a dict of
# {checked, note, timestamp}) and `user_name`; there has never been a
# `progress` object anywhere in checklist_completions.


def _checklist_scale(checklist):
    """(live item ids, item count) — computed once per checklist and reused for
    every completion measured against it."""
    items = (checklist or {}).get("items", []) or []
    ids = {str(i["id"]) for i in items if isinstance(i, dict) and i.get("id")}
    return ids, len(items)


def _checklist_progress(completion, item_ids, total):
    """{completed, total} for one completion, measured against LIVE items.

    `total` is the number of items on the checklist now. `completed` counts
    only checked keys that still name one of those items, so an item deleted
    after someone ticked it cannot leave a stored completion reporting 5/4:
    completed <= total always.
    """
    checked = 0
    for item_id, state in ((completion or {}).get("item_completions", {}) or {}).items():
        if str(item_id) not in item_ids:
            continue
        if isinstance(state, dict):
            if state.get("checked"):
                checked += 1
        elif state:
            checked += 1
    return {"completed": checked, "total": total}


def _completion_row(completion, item_ids, total):
    """One row of the `completions` list both admin surfaces render:
    [{user_id, user_name, progress: {completed, total}}]."""
    return {
        "user_id": completion.get("user_id"),
        "user_name": completion.get("user_name", ""),
        "progress": _checklist_progress(completion, item_ids, total),
    }


def _nested_checklist(checklist):
    """The `checklist` object every client reads off an assignment."""
    if not checklist:
        return None
    return {
        "id": str(checklist.get("_id", checklist.get("id", ""))),
        "title": checklist.get("title", ""),
        "description": checklist.get("description"),
        "items": checklist.get("items", []) or [],
    }


def _serialize_assignment(assignment):
    """Serialize an assignment WITHOUT its frozen `checklist_title` copy — the
    title is derived from db.checklists per request instead. See above."""
    out = serialize_id(dict(assignment))
    out.pop("checklist_title", None)
    return out


async def _checklists_by_id(checklist_ids):
    """The checklists for a whole page of assignments in one $in, instead of a
    find_one per assignment. Keyed by the id as a STRING, which is how
    assignments store it."""
    wanted = {str(cid) for cid in checklist_ids if cid}
    if not wanted:
        return {}
    out = {}
    async for doc in db.checklists.find({"_id": {"$in": [to_query_id(c) for c in wanted]}}):
        out[str(doc["_id"])] = doc
    return out


async def _completions_by_assignment(assignment_ids, user_id=None):
    """Completions for a whole page of assignments in one $in, grouped by
    assignment id. `assignment_id` is a STRING on checklist_completions
    (`complete_checklist` writes `str(_id)`), so these are not ObjectIds."""
    wanted = [str(a) for a in assignment_ids if a]
    if not wanted:
        return {}
    query = {"assignment_id": {"$in": wanted}}
    if user_id:
        query["user_id"] = user_id
    out = {}
    async for doc in db.checklist_completions.find(query):
        out.setdefault(str(doc.get("assignment_id")), []).append(doc)
    return out


def _serialize_completion(completion, item_ids, total):
    """The owner's own completion record, plus the `progress` object
    `app/checklists.jsx:198` draws its bar from. The stored document has never
    carried one, so that bar read 0/0 · 0% for every CP — including one who had
    just ticked every item — until it was computed here."""
    if not completion:
        return None
    out = serialize_id(dict(completion))
    out.setdefault("user_name", "")
    out["progress"] = _checklist_progress(completion, item_ids, total)
    return out


# ==================== PROJECT CHECKLISTS ====================

@api_router.get("/projects/{project_id}/checklists")
async def get_project_checklists(project_id: str, current_user = Depends(get_current_user), _proj = Depends(require_project_access)):
    """Get all checklist assignments for a project"""
    assignments = await db.checklist_assignments.find({
        "project_id": project_id,
        "is_deleted": {"$ne": True}
    }).to_list(200)
    if not assignments:
        return []

    checklists = await _checklists_by_id(a.get("checklist_id") for a in assignments)
    completions = await _completions_by_assignment(str(a["_id"]) for a in assignments)

    result = []
    for assignment in assignments:
        checklist = checklists.get(str(assignment.get("checklist_id")))
        if not checklist:
            continue
        item_ids, total = _checklist_scale(checklist)
        item = _serialize_assignment(assignment)
        item["checklist"] = _nested_checklist(checklist)
        item["completions"] = [
            _completion_row(c, item_ids, total)
            for c in completions.get(str(assignment["_id"]), [])
        ]
        result.append(item)

    return result

# ==================== ADMIN CHECKLISTS ====================

@api_router.get("/admin/checklists")
async def get_checklists(admin = Depends(get_admin_user)):
    """Get all checklists for the admin's company"""
    company_id = get_user_company_id(admin)
    query = {"is_deleted": {"$ne": True}}
    # The tenant filter is not conditional. `if company_id:` alone let a
    # caller with NO company read every tenant's rows, and that is the
    # DEFAULT state after self-serve registration. `_id: None` is
    # unsatisfiable, so one code path and one response shape;
    # `company_id: None` would match precisely the orphan rows. The
    # carve-out is the FLAG, never the `owner` role -- that role is what
    # every signup receives. Reasoned in full on get_all_checkins and
    # asserted by test_tenant_scope_census.py.
    if company_id:
        query["company_id"] = company_id
    elif not is_platform_operator(admin):
        query["_id"] = None
    
    checklists = await db.checklists.find(query).sort("created_at", -1).to_list(200)
    result = []
    for cl in checklists:
        serialized = serialize_id(cl)
        # Get creator name
        if cl.get("created_by"):
            creator = await db.users.find_one({"_id": to_query_id(cl["created_by"])})
            serialized["created_by_name"] = creator.get("name") if creator else "Unknown"
        result.append(serialized)
    return result

@api_router.post("/admin/checklists")
async def create_checklist(checklist_data: ChecklistCreate, admin = Depends(get_admin_user)):
    """Create a new checklist"""
    company_id = get_user_company_id(admin)
    now = datetime.now(timezone.utc)
    
    # Add IDs to items if not present
    items = []
    for i, item in enumerate(checklist_data.items):
        if "id" not in item:
            item["id"] = str(uuid.uuid4())
        if "order" not in item:
            item["order"] = i
        items.append(item)
    
    checklist_dict = {
        "title": checklist_data.title,
        "description": checklist_data.description,
        "items": items,
        "company_id": company_id,
        "created_by": admin.get("id"),
        "created_at": now,
        "updated_at": now,
        "is_deleted": False
    }
    
    result = await db.checklists.insert_one(checklist_dict)
    checklist_dict["id"] = str(result.inserted_id)
    checklist_dict.pop("_id", None)
    
    # Add creator name
    checklist_dict["created_by_name"] = admin.get("name")
    
    return checklist_dict

@api_router.get("/admin/checklists/{checklist_id}")
async def get_checklist(checklist_id: str, admin = Depends(get_admin_user)):
    """Get a single checklist by ID"""
    checklist = await db.checklists.find_one({"_id": to_query_id(checklist_id), "is_deleted": {"$ne": True}})
    if not checklist:
        raise HTTPException(status_code=404, detail="Checklist not found")
    
    serialized = serialize_id(checklist)
    if checklist.get("created_by"):
        creator = await db.users.find_one({"_id": to_query_id(checklist["created_by"])})
        serialized["created_by_name"] = creator.get("name") if creator else "Unknown"
    
    return serialized

@api_router.put("/admin/checklists/{checklist_id}")
async def update_checklist(checklist_id: str, checklist_data: dict, admin = Depends(get_admin_user)):
    """Update a checklist"""
    update_fields = {}
    if "title" in checklist_data:
        update_fields["title"] = checklist_data["title"]
    if "description" in checklist_data:
        update_fields["description"] = checklist_data["description"]
    if "items" in checklist_data:
        items = []
        for i, item in enumerate(checklist_data["items"]):
            if "id" not in item:
                item["id"] = str(uuid.uuid4())
            if "order" not in item:
                item["order"] = i
            items.append(item)
        update_fields["items"] = items
    
    update_fields["updated_at"] = datetime.now(timezone.utc)
    
    result = await db.checklists.update_one(
        {"_id": to_query_id(checklist_id), "is_deleted": {"$ne": True}},
        {"$set": update_fields}
    )
    if result.matched_count == 0:
        raise HTTPException(status_code=404, detail="Checklist not found")
    
    checklist = await db.checklists.find_one({"_id": to_query_id(checklist_id)})
    return serialize_id(checklist)

@api_router.delete("/admin/checklists/{checklist_id}")
async def delete_checklist(checklist_id: str, admin = Depends(get_admin_user)):
    """Soft delete a checklist"""
    result = await db.checklists.update_one(
        {"_id": to_query_id(checklist_id)},
        {"$set": {"is_deleted": True, "deleted_at": datetime.now(timezone.utc), "updated_at": datetime.now(timezone.utc)}}
    )
    if result.matched_count == 0:
        raise HTTPException(status_code=404, detail="Checklist not found")
    
    # Also soft-delete related assignments
    await db.checklist_assignments.update_many(
        {"checklist_id": checklist_id},
        {"$set": {"is_deleted": True, "deleted_at": datetime.now(timezone.utc), "updated_at": datetime.now(timezone.utc)}}
    )
    
    return {"message": "Checklist deleted successfully"}

@api_router.post("/admin/checklists/{checklist_id}/assign")
async def assign_checklist(checklist_id: str, assignment_data: ChecklistAssignmentCreate, admin = Depends(get_admin_user)):
    """Assign a checklist to projects and users.

    ── THREE IDS FROM THE CALLER, NONE OF THEM AUTHORIZED ───────────────────

    The checklist was fetched BY ID with no company scope, and the
    `project_ids` and `user_ids` in the body were never checked against the
    caller's tenant. `Depends(get_admin_user)` admits any role in
    ("admin", "owner") and `register` gives every self-serve signup
    `role = "owner"`, so an account that had merely registered could assign
    another tenant's checklist onto another tenant's projects, naming another
    tenant's users -- and the write lands in `checklist_assignments` with the
    CALLER's company_id, which is how it stayed invisible.

    All three are scoped here. The checklist and the projects are refused
    outright when they are outside the caller's company; unknown user ids were
    already dropped by the `if user:` below and are now dropped for being out
    of company too, silently, because a partial assignment is better than
    refusing the whole call over one stale id in a list.
    """
    now = datetime.now(timezone.utc)
    company_id = get_user_company_id(admin)
    _operator = is_platform_operator(admin)

    _cl_query: Dict[str, Any] = {
        "_id": to_query_id(checklist_id), "is_deleted": {"$ne": True},
    }
    if company_id:
        _cl_query["company_id"] = company_id
    elif not _operator:
        _cl_query["_id"] = None
    checklist = await db.checklists.find_one(_cl_query)
    if not checklist:
        # 404 AND NOT 403, DELIBERATELY. A 403 would confirm that a checklist
        # with this id exists in some other tenant, which is the fact the
        # scoping exists to withhold.
        raise HTTPException(status_code=404, detail="Checklist not found")
    created_assignments = []
    
    # The [{id, name}] list the admin surfaces actually PRINT. It does not vary
    # by project, so it is built once for the call and written on BOTH paths
    # below. The re-assign path used to $set `assigned_user_ids` alone: that
    # changed the list the server queries by and left the list the screen
    # renders naming whoever was assigned before.
    assigned_users = []
    for user_id in assignment_data.user_ids:
        user = await db.users.find_one({"_id": to_query_id(user_id)})
        # OUT-OF-COMPANY IDS ARE DROPPED, not refused: a stale id in a list
        # must not fail the whole assignment, and naming a stranger must not
        # put his name on this tenant's screen.
        if user and (_operator or (company_id and
                                   user.get("company_id") == company_id)):
            assigned_users.append({"id": user_id, "name": user.get("name", "")})

    for project_id in assignment_data.project_ids:
        # THE PROJECT IS AUTHORIZED BEFORE ANYTHING IS WRITTEN AGAINST IT.
        # Raises 403/404 from the shared gate rather than a local check, so
        # this route cannot drift from the rule every other project write
        # applies.
        await _assert_project_access(project_id, admin)
        # Check if assignment already exists
        existing = await db.checklist_assignments.find_one({
            "checklist_id": checklist_id,
            "project_id": project_id,
            "is_deleted": {"$ne": True}
        })
        if existing:
            # Update existing assignment's users — both copies of them.
            await db.checklist_assignments.update_one(
                {"_id": existing["_id"]},
                {"$set": {
                    "assigned_user_ids": assignment_data.user_ids,
                    "assigned_users": assigned_users,
                    "updated_at": now,
                }}
            )
            continue
        
        # Get project name
        project = await db.projects.find_one({"_id": to_query_id(project_id)})
        project_name = project.get("name", "") if project else ""
        
        assignment_dict = {
            "checklist_id": checklist_id,
            "checklist_title": checklist.get("title", ""),
            "project_id": project_id,
            "project_name": project_name,
            "assigned_user_ids": assignment_data.user_ids,
            "assigned_users": assigned_users,
            "company_id": company_id,
            "created_by": admin.get("id"),
            "created_at": now,
            "updated_at": now,
            "is_deleted": False
        }
        
        result = await db.checklist_assignments.insert_one(assignment_dict)
        assignment_dict["id"] = str(result.inserted_id)
        assignment_dict.pop("_id", None)
        created_assignments.append(assignment_dict)
    
    return created_assignments

@api_router.get("/admin/checklists/{checklist_id}/assignments")
async def get_checklist_assignments(checklist_id: str, admin = Depends(get_admin_user)):
    """Get all assignments for a checklist"""
    assignments = await db.checklist_assignments.find({
        "checklist_id": checklist_id,
        "is_deleted": {"$ne": True}
    }).to_list(200)
    if not assignments:
        return []

    # Every assignment on this page is an assignment OF this checklist, so the
    # title/items join is one read for the whole page.
    checklist = await db.checklists.find_one({"_id": to_query_id(checklist_id)})
    nested = _nested_checklist(checklist)
    item_ids, total = _checklist_scale(checklist)

    completions = await _completions_by_assignment(str(a["_id"]) for a in assignments)

    result = []
    for assignment in assignments:
        serialized = _serialize_assignment(assignment)
        serialized["checklist"] = nested
        rows = [
            _completion_row(c, item_ids, total)
            for c in completions.get(str(assignment["_id"]), [])
        ]
        serialized["completions"] = rows

        # Unchanged meaning: `completed` is how many completion RECORDS exist,
        # exactly what the per-assignment count_documents this replaced
        # returned. Nothing reads it (see followups) — it is kept because
        # removing a served key is its own decision, not a side effect.
        serialized["completion_stats"] = {
            "total_assigned": len(assignment.get("assigned_user_ids", [])),
            "completed": len(rows),
        }
        result.append(serialized)

    return result

# ==================== USER CHECKLISTS ====================

@api_router.get("/checklists/assigned")
async def get_assigned_checklists(current_user = Depends(get_current_user)):
    """Get checklists assigned to the current user"""
    user_id = current_user.get("id")

    assignments = await db.checklist_assignments.find({
        "assigned_user_ids": user_id,
        "is_deleted": {"$ne": True}
    }).to_list(200)
    if not assignments:
        return []

    checklists = await _checklists_by_id(a.get("checklist_id") for a in assignments)
    # This is the CP's list of their OWN work, not a roster — scope the one
    # $in to them rather than reading everyone's completions and discarding.
    completions = await _completions_by_assignment(
        (str(a["_id"]) for a in assignments), user_id=user_id,
    )

    result = []
    for assignment in assignments:
        checklist = checklists.get(str(assignment.get("checklist_id")))
        if not checklist:
            continue

        item_ids, total = _checklist_scale(checklist)
        serialized = _serialize_assignment(assignment)
        serialized["checklist"] = _nested_checklist(checklist)

        mine = completions.get(str(assignment["_id"]), [])
        completion = mine[0] if mine else None
        serialized["is_completed"] = completion is not None
        serialized["completion"] = _serialize_completion(completion, item_ids, total)

        result.append(serialized)

    return result

@api_router.get("/checklists/assignments/{assignment_id}")
async def get_assignment_details(assignment_id: str, current_user = Depends(get_current_user)):
    """Get details of a specific checklist assignment"""
    # Named on it, or project access. See _assert_assignment_access.
    assignment = await _assert_assignment_access(assignment_id, current_user)

    checklist = await db.checklists.find_one({"_id": to_query_id(assignment["checklist_id"])})
    if not checklist:
        # There is no checklist to open. The list endpoints already skip an
        # assignment whose checklist is gone, so this only answers a stale deep
        # link, and 404 is the honest answer. Serving the assignment with
        # `checklist: null` would put the client back where it started —
        # dereferencing a key that is not there.
        raise HTTPException(status_code=404, detail="Checklist not found")

    item_ids, total = _checklist_scale(checklist)
    serialized = _serialize_assignment(assignment)
    serialized["checklist"] = _nested_checklist(checklist)

    # Get user's completion
    user_id = current_user.get("id")
    completion = await db.checklist_completions.find_one({
        "assignment_id": assignment_id,
        "user_id": user_id
    })
    serialized["completion"] = _serialize_completion(completion, item_ids, total)

    return serialized

@api_router.put("/checklists/assignments/{assignment_id}/complete")
async def complete_checklist(assignment_id: str, completion_data: ChecklistCompletionUpdate, current_user = Depends(get_current_user)):
    """Submit or update checklist completion"""
    # NAMED ON IT, AND NOTHING ELSE — a completion is one person's attestation
    # that they did the work, so project access does not authorize filing one.
    assignment = await _assert_assignment_access(
        assignment_id, current_user, write=True,
    )
    
    user_id = current_user.get("id")
    now = datetime.now(timezone.utc)
    
    # Check if completion already exists
    existing = await db.checklist_completions.find_one({
        "assignment_id": assignment_id,
        "user_id": user_id
    })
    
    completion_dict = {
        "assignment_id": assignment_id,
        "checklist_id": assignment.get("checklist_id"),
        "project_id": assignment.get("project_id"),
        "user_id": user_id,
        "user_name": current_user.get("name", ""),
        "item_completions": completion_data.item_completions,
        "updated_at": now,
    }
    
    if existing:
        await db.checklist_completions.update_one(
            {"_id": existing["_id"]},
            {"$set": completion_dict}
        )
        completion_dict["id"] = str(existing["_id"])
    else:
        completion_dict["created_at"] = now
        result = await db.checklist_completions.insert_one(completion_dict)
        completion_dict["id"] = str(result.inserted_id)
    
    completion_dict.pop("_id", None)
    return completion_dict

