try:
    from backend.permit_renewal import create_permit_renewal_routes, nightly_renewal_scan
except ModuleNotFoundError:
    from permit_renewal import create_permit_renewal_routes, nightly_renewal_scan

create_permit_renewal_routes(
    api_router=api_router,
    db=db,
    get_current_user=get_current_user,
    get_admin_user=get_admin_user,
    to_query_id=to_query_id,
    get_user_company_id=get_user_company_id,
    serialize_id=serialize_id,
)

# ==================== WHATSAPP INTEGRATION ====================

import random
import string as _string
import io

# ---------- helpers ----------

# -- ITEM 4: THE PROMPT BAN DID NOT HOLD, SO THIS IS NOT A PROMPT CHANGE ----
#
# The system prompt already says NEVER end with a generic offer and names
# "anything else?" explicitly. "Need anything else?" arrived in the live test
# of 2026-09-14 anyway. A prompt is a request; this is the last thing every
# outbound line passes through, and a request that has been measured failing
# gets replaced by a guarantee.
#
# IT SITS IN send_whatsapp_message SO NOTHING CAN ROUTE AROUND IT. Thirty call
# sites send text, some from the agent and some from handlers, and a stripper
# bolted to one of them is a stripper the next one forgets.
#
# WHAT IT MUST NOT EAT IS THE POINT. "Want me to start renewal for PL-4412?"
# and "Want them?" after naming two sheets are specific offers that name a
# thing and do work. Every pattern below is anchored to the END of the message
# and matches only the contentless forms; none of them admits an object, so an
# offer with one in it cannot match.
_GENERIC_OFFER_RE = re.compile(
    r"(?:^|\n)\s*(?:"
    r"(?:is\s+there\s+)?(?:anything|something)\s+else"
    r"(?:\s+(?:that\s+)?(?:i\s+can\s+)?(?:help|do|assist)\w*"
    r"(?:\s+(?:you\s+)?with)?)?"
    r"|(?:do\s+you\s+)?need\s+(?:anything|something)\s+else"
    r"|(?:just\s+)?let\s+me\s+know(?:\s+if\s+you\s+need\s+anything)?"
    r"|happy\s+to\s+help"
    r"|hope\s+(?:this|that)\s+helps"
    r"|feel\s+free\s+to\s+ask"
    r"|(?:i'm|i\s+am)\s+here\s+(?:to\s+help|if\s+you\s+need)"
    r")\s*[!.?]*\s*$",
    re.IGNORECASE,
)


def _strip_generic_offer(text: str) -> str:
    """Remove a trailing contentless offer. Never returns an empty message."""
    if not text:
        return text
    out = _GENERIC_OFFER_RE.sub("", text).rstrip()
    # A message that was NOTHING but the offer keeps its original text. An
    # empty send is a bot that looks broken, and silence is never the better
    # repair for a badly-shaped reply.
    return out if out.strip() else text


async def send_whatsapp_message(
    chat_id: str, message: str, reply_to: Optional[str] = None,
):
    """Send a WhatsApp message via WaAPI HTTP API.

    ── A REPLY THAT DOES NOT QUOTE IS UNREADABLE IN A BUSY GROUP ──────────
    #
    # Reported from the live test of 2026-09-14: replies arrive out of order.
    # The bot answers a plan question in sixty seconds while the crew keeps
    # talking, so the answer lands eight messages below the question and
    # nothing connects the two. With four people in a group and two questions
    # in flight it is not merely hard to read, it is ambiguous — there is no
    # way to tell which answer belongs to which question.
    #
    # `reply_to` is WaAPI's `replyToMessageId`, and its format is the
    # SERIALIZED message id — {fromMe}_{chatId}_{messageId} — which is exactly
    # what parse_inbound_message already returns as `message_id_serialized`.
    #
    # BEST EFFORT, NEVER FATAL. A quote that cannot be formed is a message
    # that reads worse, not a message that must not be sent, so an absent or
    # stale id sends the reply unquoted rather than dropping it.
    """
    if not WAAPI_INSTANCE_ID or not WAAPI_TOKEN:
        logger.warning("WhatsApp send skipped — WAAPI credentials not configured")
        return None
    url = f"{WAAPI_BASE_URL}/instances/{WAAPI_INSTANCE_ID}/client/action/send-message"
    headers = {"Authorization": f"Bearer {WAAPI_TOKEN}", "Content-Type": "application/json"}
    message = _strip_generic_offer(message)
    payload = {"chatId": chat_id, "message": message}
    if reply_to:
        payload["replyToMessageId"] = reply_to
    try:
        async with ServerHttpClient(timeout=15) as client_http:
            resp = await client_http.post(url, json=payload, headers=headers)
            resp.raise_for_status()
            # Log outbound bot turn into whatsapp_messages so the agent's
            # history loader can recall it on the next user message (makes
            # multi-turn clarifications work). Best-effort — never fail send.
            try:
                now = datetime.now(timezone.utc)
                await db.whatsapp_messages.insert_one({
                    "group_id":   chat_id,
                    "sender":     "bot",
                    "body":       message,
                    "has_audio":  False,
                    "message_id": "",
                    "timestamp":  now,
                    "created_at": now,
                })
            except Exception as _log_err:
                logger.debug(f"whatsapp_messages bot-log skipped: {_log_err}")
            return resp.json()
    except Exception as e:
        logger.error(f"WhatsApp send failed to {chat_id}: {e}")
        return None


# The WaAPI events that are about a GROUP rather than about a message. They
# nest under data.notification and share none of a message's shape.
_GROUP_LIFECYCLE_EVENTS = frozenset({
    "group_join", "group_leave", "group_update",
})


def parse_inbound_message(payload: dict, vendor: str = "waapi") -> dict:
    """Normalize a WaAPI inbound webhook payload to a standard format.

    WaAPI puts most fields inside msg._data (the raw WhatsApp-Web payload).
    Some fields are duplicated at msg level, others are only inside _data.
    We read with a `_data`-first fallback so either shape works.
    """
    if vendor == "waapi":
        data = payload.get("data", {})

        # ── group_join ARRIVES SOMEWHERE ELSE IN THE PAYLOAD ───────────────
        #
        # Every WaAPI message event nests under data.message. The group
        # lifecycle events — group_join, group_leave, group_update — nest under
        # data.NOTIFICATION instead, and carry no body, no author in the usual
        # place, and no `from`.
        #
        # Nothing here read the event type, so `data.get("message", data)` fell
        # back to `data` itself, every _pick() came back empty, and a join
        # event parsed as a DIRECT MESSAGE FROM AN EMPTY SENDER. Measured
        # before this change: is_group False, group_id None, sender "". It then
        # walked into the DM branch, looked up a contact for "", found none,
        # and returned — silently, having learned nothing from an event whose
        # entire purpose is to tell us a group exists.
        #
        # A notification is now parsed as what it is. `event` and `notification`
        # travel on the parsed dict so the processor can route on them rather
        # than inferring from empty fields.
        event = str(payload.get("event") or "").strip().lower()
        notification = data.get("notification")
        if isinstance(notification, dict) and event in _GROUP_LIFECYCLE_EVENTS:
            chat_id = str(notification.get("chatId") or "")
            nid = notification.get("id") if isinstance(
                notification.get("id"), dict) else {}
            if not chat_id:
                chat_id = str(nid.get("remote") or "")
            author = str(notification.get("author") or "")
            recipients = notification.get("recipientIds")
            recipients = [str(r) for r in recipients] if isinstance(
                recipients, list) else []
            return {
                "event":             event,
                "notification":      notification,
                "notification_type": str(notification.get("type") or ""),
                "group_id":          chat_id or None,
                "is_group":          bool(chat_id),
                # `author` is the person who performed the action — for a
                # group_join of type "add", the person who did the adding.
                "sender":            author,
                "from":              chat_id,
                "to":                "",
                "body":              "",
                "recipient_ids":     recipients,
                "message_id":        str(nid.get("id") or ""),
                "message_id_serialized": str(nid.get("_serialized") or ""),
                "timestamp":         notification.get("timestamp"),
                "quoted_body":       "",
                "quoted_type":       "",
                "quoted_is_audio":   False,
                "quoted_message_id": "",
                "quoted_from_me":    False,
                "quoted_author":     "",
                "mentioned_jids":    [],
                "has_audio":         False,
                "audio_url":         None,
                "has_image":         False,
                "image_url":         None,
                "raw":               notification,
            }

        msg = data.get("message", data)
        inner = (msg.get("_data") or {}) if isinstance(msg.get("_data"), dict) else {}

        # Auto-learn bot LID: if this webhook is for a message FROM us
        # (fromMe=true) whose author JID is a @lid, that IS our bot's
        # LID. Learn it once; subsequent inbound @mentions will match
        # even without WAAPI_BOT_LID configured.
        try:
            msg_id_blob = msg.get("id") or inner.get("id") or {}
            from_me = False
            if isinstance(msg_id_blob, dict):
                from_me = bool(msg_id_blob.get("fromMe"))
            if from_me:
                for cand in (
                    msg.get("author"),
                    inner.get("author"),
                    msg.get("from"),
                    inner.get("from"),
                    msg_id_blob.get("participant") if isinstance(msg_id_blob, dict) else None,
                ):
                    if isinstance(cand, str) and "@lid" in cand:
                        _learn_bot_lid(_jid_digits(cand))
                        break
        except Exception:
            pass

        def _pick(field, default=""):
            # Prefer top-level, fall back to _data
            v = msg.get(field)
            if v is None or v == "":
                v = inner.get(field, default)
            return v if v is not None else default

        from_field = _pick("from", "")
        to_field = _pick("to", "")
        body = _pick("body", "")
        mtype = _pick("type", "")
        author = _pick("author", "") or from_field  # in groups, author = sender

        is_group = "@g.us" in from_field

        # Audio / voice notes
        has_audio = mtype in ("audio", "ptt")
        audio_url = None
        if has_audio:
            media = msg.get("media") or inner or {}
            audio_url = media.get("url") or media.get("directPath")

        # Images
        has_image = (mtype == "image")
        image_url = None
        if has_image:
            media = msg.get("media") or {}
            image_url = media.get("url") or media.get("directPath") or None

        # Message id can live at msg.id.id (nested), msg.id (string), or inner.id.id
        raw_id = msg.get("id")
        if isinstance(raw_id, dict):
            msg_id = raw_id.get("id", "")
        elif raw_id:
            msg_id = str(raw_id)
        else:
            inner_id = inner.get("id")
            if isinstance(inner_id, dict):
                msg_id = inner_id.get("id", "")
            else:
                msg_id = str(inner_id or "")

        # Serialized id — WaAPI's download-media action rejects the short
        # hash and requires the full 'false_<chatId>_<hash>_<sender>@lid'
        # form. Live in id._serialized on both outer msg and inner._data.
        msg_id_serialized = ""
        for src in (msg.get("id"), inner.get("id")):
            if isinstance(src, dict):
                v = src.get("_serialized")
                if isinstance(v, str) and v:
                    msg_id_serialized = v
                    break

        # Timestamp — WaAPI uses 't' (epoch seconds) inside _data, 'timestamp' elsewhere
        ts = msg.get("timestamp") or inner.get("t") or inner.get("timestamp") or 0
        try:
            ts = int(ts)
        except Exception:
            ts = 0

        # Quoted message (reply context). WhatsApp puts the quoted message
        # under quotedMsg / quotedMessage / contextInfo.quotedMessage
        # depending on payload version. We need:
        #   - body text (for @levelog threading on text replies),
        #   - type + messageId (for voicenote-replied-to-with-@levelog, so
        #     we can pull the voicenote audio out and transcribe it).
        quoted_body = ""
        quoted_type = ""
        quoted_message_id = ""
        quoted_node = None
        for path in (
            ("quotedMsg",),
            ("quotedMessage",),
            ("contextInfo", "quotedMessage"),
        ):
            node = msg
            for k in path:
                if not isinstance(node, dict):
                    node = None
                    break
                node = node.get(k)
            if isinstance(node, dict):
                quoted_node = node
                quoted_body = (node.get("body") or node.get("conversation") or "").strip()
                quoted_type = (node.get("type") or "").strip()
                if quoted_body or quoted_type:
                    break
        if quoted_node is None:
            inner_ctx = inner.get("quotedMsg") or inner.get("contextInfo") or {}
            if isinstance(inner_ctx, dict):
                q = inner_ctx.get("quotedMessage") or inner_ctx
                if isinstance(q, dict):
                    quoted_node = q
                    quoted_body = (q.get("body") or q.get("conversation") or "").strip()
                    quoted_type = (q.get("type") or "").strip()
        # quotedStanzaID / quotedParticipant / stanzaId — WaAPI surfaces one of
        # these as the id of the quoted message. Check both the outer msg
        # context and the inner _data context.
        for src in (msg, inner):
            if not isinstance(src, dict):
                continue
            ctx = src.get("contextInfo") or src.get("context_info") or {}
            if isinstance(ctx, dict):
                for key in ("stanzaId", "stanzaID", "quotedStanzaID", "quotedStanzaId", "quotedMessageId"):
                    v = ctx.get(key)
                    if isinstance(v, str) and v:
                        quoted_message_id = v
                        break
            if quoted_message_id:
                break
        # Fallback: if the quoted node itself carries an id, use it.
        if not quoted_message_id and isinstance(quoted_node, dict):
            qid = quoted_node.get("id")
            if isinstance(qid, dict):
                qid = qid.get("id")
            if isinstance(qid, str) and qid:
                quoted_message_id = qid

        # ── WHO WROTE THE MESSAGE THIS ONE IS REPLYING TO ──────────────────
        #
        # _is_bot_addressed's docstring has always claimed that a reply to a bot
        # message counts as addressing the bot. It could not: the only thing
        # this parser returned about a quoted message was its TEXT, and the
        # bot's replies do not contain "@levelog", so the check fell through to
        # "not addressed" every time.
        #
        # Measured, that is where the crew falls off. "Done 2" and "Done 3" —
        # replies to a checklist the bot itself posted — were among eleven
        # unaddressed messages out of thirty-four that were real answers to the
        # bot, silently dropped.
        #
        # TWO SIGNALS, AND fromMe IS THE STRONG ONE. If WhatsApp says the quoted
        # message was sent by this account, it was the bot; there is no other
        # writer on this number. The participant JID is the fallback for
        # payloads that carry the author but not the flag, and it is matched
        # against the same identifier set an @mention is matched against, so an
        # auto-learned LID works here too.
        quoted_from_me = False
        quoted_author = ""
        for src in (quoted_node, msg, inner):
            if not isinstance(src, dict):
                continue
            qid = src.get("id")
            if isinstance(qid, dict) and qid.get("fromMe") is not None:
                if src is quoted_node:
                    quoted_from_me = bool(qid.get("fromMe"))
                    break
        if isinstance(quoted_node, dict) and not quoted_from_me:
            if quoted_node.get("fromMe") is not None:
                quoted_from_me = bool(quoted_node.get("fromMe"))
        for src in (msg, inner):
            if not isinstance(src, dict):
                continue
            ctx = src.get("contextInfo") or src.get("context_info") or {}
            if isinstance(ctx, dict):
                for key in ("participant", "quotedParticipant", "remoteJid"):
                    v = ctx.get(key)
                    if isinstance(v, str) and v:
                        quoted_author = v
                        break
            if quoted_author:
                break
        if not quoted_author and isinstance(quoted_node, dict):
            for key in ("author", "from", "participant"):
                v = quoted_node.get(key)
                if isinstance(v, str) and v:
                    quoted_author = v
                    break

        # Mentions — WhatsApp's native @-mention (tap @ then pick a contact)
        # doesn't put "@Levelog" in the body as text; it stores the mentioned
        # contact's JID(s) in mentionedJidList / mentionedIds / contextInfo.
        # The body contains the bare phone number like "@15165494475 show me…"
        # (with the human-readable contact name rendered only client-side).
        mentioned_jids: list = []
        for path in (
            ("mentionedJidList",),
            ("mentionedIds",),
            ("contextInfo", "mentionedJid"),
            ("contextInfo", "mentionedJidList"),
        ):
            node = msg
            for k in path:
                if not isinstance(node, dict):
                    node = None
                    break
                node = node.get(k)
            if isinstance(node, list):
                mentioned_jids.extend(str(j) for j in node if j)
        # Also look inside _data
        for path in (
            ("mentionedJidList",),
            ("mentionedIds",),
            ("contextInfo", "mentionedJid"),
        ):
            node = inner
            for k in path:
                if not isinstance(node, dict):
                    node = None
                    break
                node = node.get(k)
            if isinstance(node, list):
                mentioned_jids.extend(str(j) for j in node if j)
        # De-duplicate while preserving order
        seen = set()
        mentioned_jids = [j for j in mentioned_jids if not (j in seen or seen.add(j))]

        # Flag: the quoted message is a voicenote (ptt/audio). Used by the
        # processor to fetch + transcribe the quoted audio when a text
        # reply with @levelog quotes a voicenote.
        quoted_is_audio = quoted_type.lower() in ("audio", "ptt", "voice") or (
            isinstance(quoted_node, dict) and (
                "ptt" in (quoted_node.get("type") or "").lower()
                or bool(quoted_node.get("audioMessage"))
                or bool(quoted_node.get("pttMessage"))
            )
        )

        return {
            # Present on every parsed payload so the processor can branch on it
            # without asking whether the key exists.
            "event": str(payload.get("event") or "").strip().lower() or "message",
            "message_id": msg_id,
            "message_id_serialized": msg_id_serialized,
            "from": from_field,
            "sender": author,
            "to": to_field,
            "body": body,
            "quoted_body": quoted_body,
            "quoted_type": quoted_type,
            "quoted_is_audio": quoted_is_audio,
            "quoted_message_id": quoted_message_id,
            "quoted_from_me": quoted_from_me,
            "quoted_author": quoted_author,
            "mentioned_jids": mentioned_jids,
            "is_group": is_group,
            "group_id": from_field if is_group else None,
            "timestamp": ts,
            "has_audio": has_audio,
            "audio_url": audio_url,
            "has_image": has_image,
            "image_url": image_url,
            "raw": msg,
        }
    # Fallback — return as-is with safe defaults
    return {
        "message_id": str(payload.get("id", "")),
        "from": payload.get("from", ""),
        "sender": payload.get("from", ""),
        "to": payload.get("to", ""),
        "body": payload.get("body", ""),
        "is_group": False,
        "group_id": None,
        "timestamp": 0,
        "has_audio": False,
        "audio_url": None,
        "has_image": False,
        "image_url": None,
        "raw": payload,
    }


def _decrypt_whatsapp_media(
    encrypted: bytes,
    media_key_b64: str,
    media_type: str = "audio",
) -> Optional[bytes]:
    """Decrypt a WhatsApp .enc media blob using its mediaKey.

    WhatsApp media is AES-256-CBC encrypted with HKDF-SHA256 derived
    keys. Reference: WhatsApp / Signal protocol media spec, implemented
    the same way Baileys / whatsmeow / wa-automate do.

    Pipeline:
      1. HKDF-SHA256(mediaKey, salt=zero32, info=<type-specific>) → 112 bytes
      2. iv = keys[0:16], cipherKey = keys[16:48]
      3. ciphertext = encrypted[:-10]  (strip 10-byte MAC tag)
      4. AES-256-CBC decrypt, PKCS7 unpad → decoded media bytes
    """
    try:
        from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
        from cryptography.hazmat.primitives.kdf.hkdf import HKDF
        from cryptography.hazmat.primitives import hashes
    except Exception as e:
        logger.error(f"cryptography import failed: {e}")
        return None

    info_map = {
        "image":    b"WhatsApp Image Keys",
        "video":    b"WhatsApp Video Keys",
        "audio":    b"WhatsApp Audio Keys",
        "document": b"WhatsApp Document Keys",
    }
    info = info_map.get(media_type, b"WhatsApp Audio Keys")

    try:
        key = base64.b64decode(media_key_b64)
    except Exception as e:
        logger.warning(f"mediaKey b64 decode failed: {e}")
        return None
    if len(key) != 32:
        logger.warning(
            f"mediaKey unexpected length {len(key)} (expected 32 bytes)"
        )
        return None

    try:
        keys = HKDF(
            algorithm=hashes.SHA256(),
            length=112,
            salt=b"\x00" * 32,
            info=info,
        ).derive(key)
    except Exception as e:
        logger.warning(f"HKDF derive failed: {e}")
        return None

    iv = keys[0:16]
    cipher_key = keys[16:48]

    if len(encrypted) < 11:
        return None
    ciphertext = encrypted[:-10]  # last 10 bytes are MAC; we don't verify here

    try:
        decryptor = Cipher(algorithms.AES(cipher_key), modes.CBC(iv)).decryptor()
        padded = decryptor.update(ciphertext) + decryptor.finalize()
    except Exception as e:
        logger.warning(f"AES decrypt failed: {e}")
        return None

    # PKCS7 unpad
    if not padded:
        return None
    pad_len = padded[-1]
    if 1 <= pad_len <= 16 and padded[-pad_len:] == bytes([pad_len]) * pad_len:
        return padded[:-pad_len]
    return padded


# Shared dict caller can set on parsed_msg — download_audio fills it with
# decrypt-attempt diagnostics so the processor can persist it into the
# audio_diag row. Keys: mediakey_found(bool), mediakey_len(int),
# decrypt_attempted(bool), decrypt_produced_ogg(bool), decrypt_error(str).
_AUDIO_DIAG_KEY = "__audio_diag__"


# ── FIVE WRITERS, TWO FORMATS, ONE READER ──────────────────────────────────
#
# whatsapp_contacts is written from six places and they do not agree on what a
# phone number looks like. The activation backfill strips to digits
# (15165494475); every other writer passes through the E.164 value
# normalize_phone produced (+15165494475). Both lookups searched for the digits
# of the sender's WhatsApp JID, which never carries a plus.
#
# So every contact row written since the integration was switched on has been
# unfindable. Silently, on both sides: the row is there and looks right, and the
# bot simply never answers. The checklist refusal message even tells the user to
# fix it in Settings, which runs the writer that produces the format that does
# not match.
#
# FIXED ON THE READ, NOT THE WRITE, DELIBERATELY. Normalising the writers means
# a migration over live rows to repair the ones already stored, and it leaves
# the next writer free to invent a third format. Normalising the read costs one
# $in over a handful of candidates, repairs every existing row without touching
# the database, and cannot be undone by a future call site.
#
# The candidates are the formats this codebase actually produces, not every
# format imaginable. A US 11-digit number with a country code also answers to
# its 10-digit self, because that is what a user types into a profile field.
def _contact_phone_variants(phone: str) -> list:
    """Every spelling of one number that any writer in this repo can produce."""
    digits = re.sub(r"\D", "", phone or "")
    if not digits:
        return []
    out = [digits, f"+{digits}"]
    if len(digits) == 11 and digits.startswith("1"):
        bare = digits[1:]
        out += [bare, f"+{bare}", f"+1{bare}"]
    elif len(digits) == 10:
        out += [f"1{digits}", f"+1{digits}"]
    seen = set()
    return [p for p in out if not (p in seen or seen.add(p))]


async def _find_whatsapp_contact(phone: str) -> Optional[dict]:
    """A contact row for this number in any format a writer here can produce.

    `user_id: {$ne: None}` is carried from the original queries and matters:
    deleting a user nulls that field rather than dropping the row, so a
    deleted user's number must not resolve to a live contact."""
    variants = _contact_phone_variants(phone)
    if not variants:
        return None
    try:
        return await db.whatsapp_contacts.find_one(
            {"phone": {"$in": variants}, "user_id": {"$ne": None}},
        )
    except Exception as e:
        logger.warning(f"contact lookup failed for {phone[-4:]}: {e}")
        return None


async def download_audio(parsed_msg: dict) -> Optional[bytes]:
    """Download audio bytes for a voicenote.

    WhatsApp delivers voicenote media as an encrypted `directPath` in
    the webhook — raw GETs against that path return 404. We have to
    go through WaAPI's download-media endpoint (or mediaUrl if WaAPI
    already re-hosted it).

    Order of attempts:
      1. If audio_url is an https URL pointing at WaAPI's CDN
         (contains 'waapi'), try the GET with the WaAPI Bearer token.
      2. Otherwise, POST to the WaAPI download-media endpoint with
         the messageId — this returns base64 bytes we decode.
      3. Last resort, try the raw URL with no auth in case WaAPI
         already re-hosted it on an open CDN.
    """
    # WaAPI's download-media action wants the SERIALIZED messageId
    # (bool_chatId_hash_sender@lid), not the short hash. The serialized
    # form is what the webhook delivers under id._serialized. Caller
    # may pass either — prefer serialized, fall back to short.
    message_id_ser = parsed_msg.get("message_id_serialized") or ""
    message_id = message_id_ser or parsed_msg.get("message_id") or ""
    audio_url = parsed_msg.get("audio_url")
    probe_trace: List[Dict[str, Any]] = []

    if WAAPI_INSTANCE_ID and WAAPI_TOKEN and message_id:
        # WaAPI v1 exposes multiple equivalent endpoints for media download;
        # try the most common names in order. We stop on the first 2xx.
        # Each failure writes a trace entry so the debug endpoint can show
        # which names actually exist on this account.
        # Only client/action/download-media exists on WaAPI v1 — the
        # others are 404s. Kept in the list but first in priority so
        # the common path is fast; we fall through on error for
        # diagnostic coverage only.
        paths = [
            "client/action/download-media",
        ]
        for path in paths:
            try:
                async with ServerHttpClient(timeout=45) as client_http:
                    resp = await client_http.post(
                        f"{WAAPI_BASE_URL}/instances/{WAAPI_INSTANCE_ID}/{path}",
                        headers={
                            "Authorization": f"Bearer {WAAPI_TOKEN}",
                            "Content-Type":  "application/json",
                        },
                        json={"messageId": message_id},
                    )
                    if 200 <= resp.status_code < 300:
                        probe_trace.append({
                            "path":   path,
                            "status": resp.status_code,
                            "body":   (resp.text or "")[:4000],
                        })
                        j = resp.json() if resp.content else {}

                        # Recursively walk the response looking for a
                        # base64 audio payload or a media URL. WaAPI
                        # nests under data.data.media / data.data.message,
                        # different plans may vary.
                        def _find_audio(node: Any, depth: int = 0) -> Optional[bytes]:
                            if depth > 8 or node is None:
                                return None
                            if isinstance(node, str):
                                # Heuristic: base64 audio blobs are >500 chars
                                # and start with common OGG/OPUS magic-encoded
                                # prefixes. data: URI has the mime prefix.
                                s = node
                                if s.startswith("data:") and ";base64," in s:
                                    try:
                                        return base64.b64decode(s.split(",", 1)[1])
                                    except Exception:
                                        return None
                                # Heuristic: pure base64 of audio (>500 chars,
                                # only base64 alphabet) — try decode.
                                if len(s) > 500 and re.fullmatch(r"[A-Za-z0-9+/=\s]+", s):
                                    try:
                                        b = base64.b64decode(s, validate=False)
                                        # Very rough sanity: ogg starts b"OggS".
                                        if len(b) > 200:
                                            return b
                                    except Exception:
                                        return None
                                return None
                            if isinstance(node, dict):
                                # Check common explicit keys first.
                                for key in (
                                    "base64", "mediaBase64", "audioBase64",
                                    "dataUrl", "dataURL",
                                ):
                                    v = node.get(key)
                                    if isinstance(v, str) and len(v) > 100:
                                        r = _find_audio(v, depth + 1)
                                        if r:
                                            return r
                                # Then any string child long enough.
                                for k, v in node.items():
                                    r = _find_audio(v, depth + 1)
                                    if r:
                                        return r
                            elif isinstance(node, list):
                                for item in node:
                                    r = _find_audio(item, depth + 1)
                                    if r:
                                        return r
                            return None

                        audio_bytes_found = _find_audio(j)
                        # Populate caller-visible diag.
                        diag_slot = parsed_msg.setdefault(_AUDIO_DIAG_KEY, {})
                        diag_slot["raw_bytes_size"] = (
                            len(audio_bytes_found) if audio_bytes_found else 0
                        )
                        if audio_bytes_found:
                            diag_slot["raw_first16"] = audio_bytes_found[:16].hex()
                            magic = audio_bytes_found[:16].hex()
                            known_magics = (
                                b"OggS", b"ID3", b"\xff\xfb", b"\xff\xf3",
                                b"\xff\xf2", b"RIFF",
                            )
                            is_decoded = any(
                                audio_bytes_found.startswith(m) for m in known_magics
                            )
                            diag_slot["already_decoded"] = is_decoded
                            if not is_decoded:
                                def _find_mediakey(node: Any, depth: int = 0) -> Optional[str]:
                                    if depth > 10 or node is None:
                                        return None
                                    if isinstance(node, dict):
                                        # Explicit key first.
                                        v = node.get("mediaKey")
                                        if isinstance(v, str) and len(v) >= 40:
                                            return v
                                        for key, val in node.items():
                                            if key == "mediaKey" and isinstance(val, str):
                                                return val
                                            r = _find_mediakey(val, depth + 1)
                                            if r:
                                                return r
                                    elif isinstance(node, list):
                                        for item in node:
                                            r = _find_mediakey(item, depth + 1)
                                            if r:
                                                return r
                                    return None

                                media_key_b64 = _find_mediakey(j)
                                diag_slot["mediakey_found"] = bool(media_key_b64)
                                diag_slot["mediakey_len"] = (
                                    len(media_key_b64) if media_key_b64 else 0
                                )
                                if media_key_b64:
                                    diag_slot["decrypt_attempted"] = True
                                    try:
                                        decrypted = _decrypt_whatsapp_media(
                                            audio_bytes_found, media_key_b64, "audio"
                                        )
                                    except Exception as _de:
                                        decrypted = None
                                        diag_slot["decrypt_error"] = (
                                            f"{type(_de).__name__}: {str(_de)[:160]}"
                                        )
                                    diag_slot["decrypt_returned_bytes"] = bool(decrypted)
                                    if decrypted:
                                        diag_slot["decrypt_first16"] = (
                                            decrypted[:16].hex()
                                        )
                                        diag_slot["decrypt_produced_ogg"] = (
                                            decrypted.startswith(b"OggS")
                                        )
                                        audio_bytes_found = decrypted
                                        magic = audio_bytes_found[:16].hex()
                            probe_trace.append({
                                "path":          path + " [SUCCESS]",
                                "size":          len(audio_bytes_found),
                                "first16":       magic,
                                "ascii8":        audio_bytes_found[:8].decode(
                                    "ascii", errors="replace"
                                ),
                                "was_encrypted": not is_decoded,
                                "decrypt_done":  not is_decoded and magic.startswith("4f6767"),
                            })
                            logger.info(
                                f"audio success probe: size={len(audio_bytes_found)} "
                                f"magic={magic} was_enc={not is_decoded}"
                            )
                            try:
                                await db.whatsapp_audio_probe.insert_one({
                                    "message_id":  message_id,
                                    "trace":       probe_trace,
                                    "received_at": datetime.now(timezone.utc),
                                    "outcome":     "success",
                                })
                            except Exception as _ins_err:
                                logger.error(
                                    f"audio probe insert failed: {_ins_err}"
                                )
                            return audio_bytes_found

                        # Fall back to URL discovery.
                        def _find_url(node: Any, depth: int = 0) -> Optional[str]:
                            if depth > 8 or node is None:
                                return None
                            if isinstance(node, str):
                                if node.startswith("http") and ("." in node):
                                    return node
                                return None
                            if isinstance(node, dict):
                                for key in ("mediaUrl", "url", "downloadUrl", "directUrl"):
                                    v = node.get(key)
                                    if isinstance(v, str) and v.startswith("http"):
                                        return v
                                for v in node.values():
                                    r = _find_url(v, depth + 1)
                                    if r:
                                        return r
                            elif isinstance(node, list):
                                for item in node:
                                    r = _find_url(item, depth + 1)
                                    if r:
                                        return r
                            return None

                        media_url = _find_url(j)
                        if isinstance(media_url, str) and media_url.startswith("http"):
                            # WaAPI handed us a CDN URL instead of inline bytes.
                            try:
                                resp2 = await client_http.get(media_url)
                                if 200 <= resp2.status_code < 300 and resp2.content:
                                    return resp2.content
                            except Exception as e:
                                logger.warning(
                                    f"audio download: CDN GET failed: {e}"
                                )
                    else:
                        probe_trace.append({
                            "path": path,
                            "status": resp.status_code,
                            "body": (resp.text or "")[:250],
                        })
                        logger.info(
                            f"audio download: {path} returned "
                            f"{resp.status_code} body={(resp.text or '')[:200]!r}"
                        )
            except Exception as e:
                probe_trace.append({"path": path, "error": str(e)[:200]})
                logger.warning(f"audio download: {path} exception: {e}")
                continue

    # Attempt 1/3: fall back to the raw URL GET if we have one.
    if audio_url:
        try:
            headers = {}
            if WAAPI_TOKEN and "waapi" in audio_url:
                headers["Authorization"] = f"Bearer {WAAPI_TOKEN}"
            async with ServerHttpClient(timeout=30) as client_http:
                resp = await client_http.get(audio_url, headers=headers)
                if 200 <= resp.status_code < 300 and resp.content:
                    return resp.content
                probe_trace.append({
                    "path": "direct_get",
                    "status": resp.status_code,
                    "size":   len(resp.content),
                })
                logger.warning(
                    f"audio download: direct GET returned "
                    f"{resp.status_code} size={len(resp.content)}"
                )
        except Exception as e:
            probe_trace.append({"path": "direct_get", "error": str(e)[:200]})
            logger.warning(f"audio download: direct GET exception: {e}")

    # Persist full probe trace so the debug endpoint surfaces what each
    # WaAPI endpoint responded with. Best-effort — we don't block on this.
    try:
        await db.whatsapp_audio_probe.insert_one({
            "message_id":  message_id,
            "trace":       probe_trace,
            "received_at": datetime.now(timezone.utc),
        })
    except Exception:
        pass

    logger.error(f"audio download: all strategies failed msg_id={message_id}")
    return None


async def transcribe_audio(audio_bytes: bytes) -> str:
    """Transcribe a voicenote via OpenAI Whisper.

    No `language` hint is sent — Whisper auto-detects, which handles
    English, Yiddish, Spanish, Hebrew, etc. without forcing the wrong
    decoder. Previously we hard-coded 'yi' (Yiddish) which made
    English voicenotes return empty and the agent hallucinate a
    'text only' reply.

    A 'prompt' hint is still useful: it biases Whisper toward
    construction vocabulary + the handful of languages our crews
    actually speak.
    """
    if not OPENAI_API_KEY:
        logger.warning("Transcription skipped — OPENAI_API_KEY not set")
        return ""
    if not audio_bytes or len(audio_bytes) < 200:
        logger.warning(f"Transcription skipped — audio too small ({len(audio_bytes) if audio_bytes else 0} bytes)")
        return ""
    try:
        url = "https://api.openai.com/v1/audio/transcriptions"
        headers = {"Authorization": f"Bearer {OPENAI_API_KEY}"}
        files_payload = {
            "file": ("audio.ogg", io.BytesIO(audio_bytes), "audio/ogg"),
            "model": (None, "whisper-1"),
            # Biasing vocabulary, NOT a language lock.
            "prompt": (
                None,
                "NYC construction site radio: permits, violations, "
                "DOB, inspection, plumbing, electrical, mechanical, "
                "sheet A-101, ME-401, P-1, hoist, scaffold, riser.",
            ),
        }
        async with ServerHttpClient(timeout=60) as client_http:
            resp = await client_http.post(url, headers=headers, files=files_payload)
            if resp.status_code != 200:
                logger.error(
                    f"Whisper transcription failed status={resp.status_code} "
                    f"body={resp.text[:300]}"
                )
                return ""
            text = (resp.json().get("text") or "").strip()
            if not text:
                logger.warning(
                    f"Whisper returned empty text for {len(audio_bytes)}B audio"
                )
            return text
    except Exception as e:
        logger.error(f"Whisper transcription failed: {e}")
        return ""


async def classify_intent(message: str) -> Optional[str]:
    """Classify a WhatsApp message intent. String match first, GPT-4o-mini fallback."""
    text = message.lower().strip()
    # Quick string-match rules
    if any(kw in text for kw in ["who on site", "who is on site", "who's on site", "whose on site", "workers on site"]):
        return "who_on_site"
    if any(kw in text for kw in ["dob status", "dob update", "violations", "dob check"]):
        return "dob_status"
    if any(kw in text for kw in ["open items", "open observations", "punch list", "uncorrected"]):
        return "open_items"
    # Material delivery receipt
    material_delivery_keywords = ["delivery", "arrived", "received", "delivered", "dropped off",
                                   "on site now", "material here", "truck came", "receipt",
                                   "shortage", "missing", "short", "only got"]
    if any(kw in text for kw in material_delivery_keywords):
        return "material_receipt"
    # Material status query
    material_status_keywords = ["material status", "what's missing", "delivery status",
                                 "outstanding materials", "what do we need", "materials needed"]
    if any(kw in text for kw in material_status_keywords):
        return "material_status"
    # GPT-4o-mini fallback
    if not OPENAI_API_KEY:
        return None
    try:
        import json as _json
        url = "https://api.openai.com/v1/chat/completions"
        headers = {"Authorization": f"Bearer {OPENAI_API_KEY}", "Content-Type": "application/json"}
        payload = {
            "model": "gpt-4o-mini",
            "temperature": 0,
            "max_tokens": 30,
            "messages": [
                {"role": "system", "content": (
                    "Classify the user message into one of these intents: "
                    "who_on_site, dob_status, open_items, material_receipt, material_status, or none. "
                    "Reply with ONLY the intent label."
                )},
                {"role": "user", "content": message},
            ],
        }
        async with ServerHttpClient(timeout=10) as client_http:
            resp = await client_http.post(url, json=payload, headers=headers)
            resp.raise_for_status()
            label = resp.json()["choices"][0]["message"]["content"].strip().lower()
            if label in ("who_on_site", "dob_status", "open_items", "material_receipt", "material_status"):
                return label
            return None
    except Exception as e:
        logger.error(f"Intent classification failed: {e}")
        return None


# ---------- intent handlers ----------

# ── "CHECK WITH HR" IS NEVER THE ANSWER FOR DATA WE HOLD ───────────────────
#
# Live test, 2026-09-14: asked whether a man on site had a current SST card,
# the agent told the superintendent to check with HR. The card status was two
# fields away — frozen onto the very check-in row the roster was built from —
# and the roster handler simply did not render it, so the model had no way to
# know it existed and correctly declined to guess.
#
# That is worse than a wrong answer. A superintendent standing at a gate is
# asking the one question this product exists to answer, and being told to ask
# somebody else teaches him the bot does not know things it knows.
#
# THE CHECK-IN ROW IS THE RECORD, NOT THE WORKER ROW. `checkins` freezes
# sst_status, sst_expiration and sst_card_number at the moment of check-in and
# never updates them, precisely so "did this man hold a valid card on this
# date" is answerable later. The roster path reads those frozen fields. The
# full-roster path has no check-in to read and derives the same three-state
# verdict from the worker's certifications live — different source, same
# vocabulary, so the agent never sees two words for one state.
# ── "WAS THE UNCONFIRMED SST APPROVED?" WAS ANSWERED FROM PRIOR ────────────
#
# Live test, 2026-09-14 23:33. The agent answered a question about a CP's
# review decision out of the model's own head, because the roster it was
# reading carried the card STATE and not the DECISION — and a model given a
# question it has no data for will answer it anyway.
#
# The decision is already on the same check-in row the roster is built from:
# review_decision ("approved" or "sent_home"), reviewed_by_name, reviewed_at,
# written by the review endpoint and never overwritten. Exactly the shape of
# the SST-card defect before it, and the same fix: render what the row holds.
#
# A CARD THAT IS UNCONFIRMED AND UNREVIEWED IS NOT THE SAME AS ONE A CP LOOKED
# AT AND CLEARED, and that distinction is the whole question being asked. So
# "unconfirmed" and "unconfirmed, CP approved" read differently, and a man sent
# home says so in the roster rather than appearing as merely unconfirmed.
# The reviewer's name is appended as "by <name>", so neither label carries its
# own "by" — "SENT HOME by CP by Roy F" was the first draft and it stutters.
_REVIEW_LABEL = {
    "approved":  "CP approved",
    "sent_home": "SENT HOME",
}


def _review_suffix(ci: dict) -> str:
    """The CP's decision on this check-in, as a short clause.

    Empty when nobody has reviewed it — which is a real state and not the same
    as approval. A roster that says nothing about review is saying "not
    reviewed", and that has to stay distinguishable from "cleared"."""
    label = _REVIEW_LABEL.get((ci.get("review_decision") or "").lower())
    if not label:
        return ""
    who = (ci.get("reviewed_by_name") or "").strip()
    when = ci.get("reviewed_at")
    bits = [label]
    if who:
        bits.append(f"by {who}")
    if isinstance(when, datetime):
        bits.append(when.strftime("%Y-%m-%d"))
    return " — " + " ".join(bits)


_SST_LABEL = {
    "valid":         "SST ok",
    "expiring_soon": "SST EXPIRING",
    "expired":       "SST EXPIRED",
    "missing":       "NO SST CARD",
    "unknown":       "SST unconfirmed",
}


def _sst_suffix(status: Optional[str], expiration: Any) -> str:
    """The card state as a short clause, for one line of a roster.

    Empty string when there is nothing known to say, so a roster of workers
    with no card data reads exactly as it did before this existed."""
    label = _SST_LABEL.get((status or "").lower())
    if not label:
        return ""
    date_txt = ""
    exp = expiration
    if isinstance(exp, str) and exp:
        try:
            exp = datetime.fromisoformat(exp.replace("Z", "+00:00"))
        except (ValueError, TypeError):
            exp = None
    if isinstance(exp, datetime):
        date_txt = f" exp {exp.strftime('%Y-%m-%d')}"
    elif status == "unknown":
        # The whole point of `unknown` is that the expiry could not be read.
        # Printing nothing where a date belongs is what makes it unknown.
        date_txt = ""
    return f" — {label}{date_txt}"


def _sst_from_worker(worker: dict, now: Optional[datetime] = None) -> tuple:
    """(status, expiration) for the full-roster path, from live certifications.

    Mirrors the three-state gate frozen onto a check-in: expired, then
    expiring within 30 days, then a class/expiry we could not confirm, then
    missing, then valid. NEVER silently valid — an unreadable card is
    `unknown`, which is the distinction the whole cert vocabulary exists for."""
    now = now or datetime.now(timezone.utc)
    certs = worker.get("certifications") or []
    sst = [c for c in certs
           if str(c.get("type") or "") in RECOGNIZED_SST_TYPES]
    if not sst:
        return "missing", None

    # Prefer a class-confirmed card when the worker carries more than one.
    cert = next(
        (c for c in sst if str(c.get("type") or "") in SST_CLASS_TYPES),
        sst[0],
    )
    exp = cert.get("expiration_date")
    if isinstance(exp, str) and exp:
        try:
            exp = datetime.fromisoformat(exp.replace("Z", "+00:00"))
        except (ValueError, TypeError):
            exp = None
    if isinstance(exp, datetime) and exp.tzinfo is None:
        exp = exp.replace(tzinfo=timezone.utc)

    class_unknown = str(cert.get("type") or "") not in SST_CLASS_TYPES
    expiry_unknown = (
        not isinstance(exp, datetime) or bool(cert.get("expiration_raw_rejected"))
    )
    if isinstance(exp, datetime) and exp <= now:
        return "expired", exp
    if class_unknown or expiry_unknown:
        return "unknown", exp if isinstance(exp, datetime) else None
    if exp <= now + timedelta(days=30):
        return "expiring_soon", exp
    return "valid", exp


def _sst_tally(states: list) -> str:
    """A one-line headline so the agent can answer "is everyone current?"
    without counting the list itself, which is what it got wrong."""
    counts = {}
    for st in states:
        if st:
            counts[st] = counts.get(st, 0) + 1
    if not counts:
        return ""
    order = ("expired", "missing", "unknown", "expiring_soon", "valid")
    bits = [f"{counts[k]} {_SST_LABEL[k]}" for k in order if k in counts]
    return "SST: " + ", ".join(bits)


async def _handle_who_on_site(
    project_id: str,
    trade: Optional[str] = None,
    company: Optional[str] = None,
) -> str:
    """Return formatted worker list on site. Optionally filter by trade or company."""
    today_start, today_end = get_today_range_est()
    checkins = await db.checkins.find({
        "project_id": project_id,
        "check_in_time": {"$gte": today_start, "$lt": today_end},
        "status": "checked_in",
        "is_deleted": {"$ne": True},
    }).to_list(500)

    def _match(ci: dict) -> bool:
        if trade:
            t = (ci.get("worker_trade") or ci.get("trade") or "").lower()
            if trade.lower() not in t:
                return False
        if company:
            # ONE CHANGE DECLARED, not smuggled: the original did not strip, so
            # " Acme " and "Acme" were two groups in this report. _worker_company
            # strips. A grouping key cannot be SPLIT by stripping, only merged,
            # and merging two groups that differ by whitespace is the documented
            # bug class _norm_key exists for.
            c = _worker_company(ci.get("worker_company"), ci.get("company"),
                                ci.get("company_name")).lower()
            if company.lower() not in c:
                return False
        return True

    filtered = [ci for ci in checkins if _match(ci)]
    n = len(filtered)

    filter_desc = ""
    if trade and company:
        filter_desc = f" ({trade} at {company})"
    elif trade:
        filter_desc = f" ({trade})"
    elif company:
        filter_desc = f" ({company})"

    if not filtered:
        if trade or company:
            return f"No {trade or company} workers checked in on site today{filter_desc}."
        return "No workers currently checked in on site."

    # Each man's card state travels with his name, because a roster that
    # answers "who is here" and not "is he cleared to be here" sends the
    # superintendent somewhere else for the half he actually needs.
    def _entry(ci: dict) -> str:
        return (ci.get("worker_name", "Unknown")
                + _sst_suffix(ci.get("sst_status"), ci.get("sst_expiration"))
                + _review_suffix(ci))

    tally = _sst_tally([ci.get("sst_status") for ci in filtered])
    head = f"*{n} on site today{filter_desc}:*"
    if tally:
        head += f"\n{tally}"

    # Group by company (or trade if filtering by company)
    if company:
        by_key: Dict[str, list] = {}
        for ci in filtered:
            key = (ci.get("worker_trade") or ci.get("trade") or "General").title()
            by_key.setdefault(key, []).append(_entry(ci))
        lines = [head]
        for k, entries in sorted(by_key.items()):
            lines.append(f"\n_{k}_ ({len(entries)}):")
            for e in sorted(entries):
                lines.append(f"  - {e}")
    else:
        by_company: Dict[str, list] = {}
        for ci in filtered:
            co = _worker_company(ci.get("worker_company"), ci.get("company"),
                                 ci.get("company_name")) or "Unknown"
            by_company.setdefault(co, []).append(_entry(ci))
        lines = [head]
        for co, entries in sorted(by_company.items()):
            lines.append(f"\n_{co}_ ({len(entries)}):")
            for e in sorted(entries):
                lines.append(f"  - {e}")
    return "\n".join(lines)


async def _handle_list_workers(
    company_id: Optional[str],
    trade: Optional[str] = None,
    company: Optional[str] = None,
) -> str:
    """Return the full worker roster, optionally filtered by trade/company.
    Not limited to who's on site today — the full roster."""
    # A COMPANY-LESS CALLER HAS NO ROSTER, and this helper takes `company_id`
    # as a PARAMETER rather than a user, so there is no
    # `is_platform_operator(...)` to ask here. `if company_id:` alone returned
    # every worker on the platform to the assistant. The caller resolves the
    # company; if it could not, the honest answer is that there is nobody to
    # list.
    if not company_id:
        return "No workers on file for this account."
    query: Dict[str, Any] = {"is_deleted": {"$ne": True}, "company_id": company_id}
    workers = await db.workers.find(query).to_list(1000)

    def _match(w: dict) -> bool:
        if trade:
            t = (w.get("trade") or "").lower()
            if trade.lower() not in t:
                return False
        if company:
            c = (w.get("company") or "").lower()
            if company.lower() not in c:
                return False
        return True

    filtered = [w for w in workers if _match(w)]
    n = len(filtered)
    if not filtered:
        if trade or company:
            return f"No workers match filter ({trade or company})."
        return "No workers in the roster yet."

    filter_desc = ""
    if trade and company:
        filter_desc = f" — {trade} at {company}"
    elif trade:
        filter_desc = f" — {trade}"
    elif company:
        filter_desc = f" — {company}"

    # No check-in row here, so the verdict is derived live from the worker's
    # certifications — same three states, same words, so the agent is never
    # reading two vocabularies for one fact.
    now = datetime.now(timezone.utc)
    states = []
    by_trade: Dict[str, list] = {}
    for w in filtered:
        t = (w.get("trade") or "General").title()
        status, exp = _sst_from_worker(w, now)
        states.append(status)
        by_trade.setdefault(t, []).append(
            w.get("name", "Unknown") + _sst_suffix(status, exp))
    lines = [f"*{n} workers{filter_desc}:*"]
    tally = _sst_tally(states)
    if tally:
        lines.append(tally)
    for t, entries in sorted(by_trade.items()):
        lines.append(f"\n_{t}_ ({len(entries)}):")
        for e in sorted(entries):
            lines.append(f"  - {e}")
    return "\n".join(lines)


async def _handle_dob_status(project_id: str) -> str:
    """Return project DOB info summary."""
    project = await db.projects.find_one({"_id": to_query_id(project_id)})
    if not project:
        return "Project not found."

    # BIN lives at the top level as nyc_bin in current schema; fall back to
    # the legacy dob_config.bin_number for older records.
    bin_number = (
        project.get("nyc_bin")
        or (project.get("dob_config") or {}).get("bin_number")
        or "N/A"
    )
    bbl = project.get("bbl") or project.get("nyc_bbl") or (project.get("dob_config") or {}).get("bbl") or ""

    lines = [f"*DOB Status for {project.get('name') or 'this project'}*"]
    lines.append(f"BIN: {bin_number}")
    if bbl:
        lines.append(f"BBL: {bbl}")

    # Recent violations — be defensive about None-valued fields (Mongo stores
    # explicit None, and None[:80] raises TypeError).
    recent = await db.dob_logs.find({
        "project_id": project_id,
        "record_type": "violation",
    }).sort("detected_at", -1).to_list(5)
    if recent:
        lines.append(f"\nRecent violations ({len(recent)}):")
        for v in recent:
            desc = v.get("description") or v.get("raw_dob_id") or v.get("violation_number") or "(no details)"
            desc = str(desc)[:80]
            lines.append(f"  - {desc}")
    else:
        lines.append("\nNo recent violations on file.")
    return "\n".join(lines)


# ── WHAT A DAY'S LOG ACTUALLY CONTAINS ────────────────────────────────────
#
# This tool read `daily_logs` and reported `observations`, `status` and
# `signed_by_name`. Measured on production, 2026-09-16: 0 of 92 daily_logs
# carry `observations`, 0 carry `signed_by_name`, 1 carries `status`. So the
# answer was always "0 observation(s), 0 uncorrected" — well formed, and empty
# of everything the log holds.
#
# The schema it was reading belongs to `logbooks`, a different collection, four
# times larger, which nothing reached at all. And on 588 Boyland — the one
# project the bot is used on — there are 329 logbooks and ZERO daily_logs, so
# every date answered "No daily log filed" whatever had been filed that day.
#
# Both collections are read now, and what is printed is what is there.
_LOGBOOK_LABEL = {
    "daily_jobsite": "daily jobsite log",
    "site_superintendent_log": "superintendent log",
    "toolbox_talk": "toolbox talk",
    "osha_log": "OSHA log",
    "preshift_signin": "pre-shift sign-in",
    "scaffold_maintenance": "scaffold maintenance",
    "subcontractor_orientation": "subcontractor orientation",
}
_LOGBOOK_ORDER = ("daily_jobsite", "site_superintendent_log", "toolbox_talk",
                  "osha_log", "preshift_signin", "scaffold_maintenance",
                  "subcontractor_orientation")
DAILY_LOG_MAX_CHARS = 1600


def _log_clean(v: Any) -> str:
    return re.sub(r"\s+", " ", str(v or "")).strip()


def _log_field(v: Any) -> str:
    """A checkbox group is a dict, and `{'compressor': True}` is not a line a
    superintendent reads. The ticked names are."""
    if isinstance(v, dict):
        return ", ".join(k.replace("_", " ") for k, on in v.items() if on)
    if isinstance(v, list):
        return ", ".join(_log_clean(x) for x in v if _log_clean(x))
    return _log_clean(v)


def _weather_line(d: Dict[str, Any]) -> Optional[str]:
    """One weather line, not the same reading twice.

    daily_logs carries BOTH a composed `weather` ("Light Rain, 62F, wind 10
    mph E") and the pieces it was composed from, so joining every field gave
    "Light Rain, 62F, wind 10 mph E, Light Rain, 62F, 10 mph E"."""
    whole = _log_clean(d.get("weather"))
    parts = [_log_clean(d.get(k)) for k in ("weather_condition", "weather_temp",
                                            "weather_wind")]
    parts = [p for p in dict.fromkeys(parts) if p]
    if whole and all(p.split()[0].rstrip(",") in whole for p in parts if p):
        return whole                      # already composed from the pieces
    bits = [b for b in dict.fromkeys([whole] + parts) if b]
    return ", ".join(bits) or None


def _render_daily_jobsite(data: Dict[str, Any]) -> List[str]:
    out: List[str] = []
    w = _weather_line(data)
    if w:
        out.append(f"    weather: {w}")
    gd = _log_clean(data.get("general_description"))
    if gd:
        out.append(f"    work: {gd}")
    for a in (data.get("activities") or [])[:6]:
        if not isinstance(a, dict):
            continue
        who = _log_clean(a.get("company"))
        n = _log_clean(a.get("num_workers"))
        what = _log_clean(a.get("work_description"))
        # 'work_locations' on this schema; 'work_location' on an older one.
        where = _log_clean(a.get("work_locations") or a.get("work_location"))
        head = " ".join(x for x in (who, f"({n})" if n else "") if x)
        body = " — ".join(x for x in (what, where) if x)
        if head and body:
            out.append(f"      {head}: {body}")
        elif head or body:
            out.append(f"      {head or body}")
        pics = [p for p in (a.get("photos") or []) if isinstance(p, dict)]
        if pics:
            out.append(f"        {len(pics)} photo(s)")
    failed = [k.replace("_", " ") for k, v in (data.get("checklist_items") or {}).items()
              if isinstance(v, dict)
              and _log_clean(v.get("result")).lower() not in ("pass", "", "na", "n/a")]
    if failed:
        out.append(f"    checklist not passed: {', '.join(failed[:8])}")
    for o in (data.get("observations") or [])[:6]:
        if not isinstance(o, dict):
            continue
        desc = _log_clean(o.get("description") or o.get("note"))
        if not desc:
            continue
        tail = " — ".join(x for x in (_log_clean(o.get("responsible_party")),
                                      _log_clean(o.get("remedy"))) if x)
        out.append(f"    observation: {desc}" + (f" — {tail}" if tail else ""))
    for k, label in (("equipment_on_site", "equipment"),
                     ("visitors_deliveries", "visitors/deliveries"),
                     ("areas_visited", "areas visited")):
        v = _log_field(data.get(k))
        if v:
            out.append(f"    {label}: {v}")
    return out


def _render_superintendent(data: Dict[str, Any]) -> List[str]:
    out: List[str] = []
    pres = data.get("presence") if isinstance(data.get("presence"), dict) else {}
    inout = " to ".join(x for x in (_log_clean(pres.get("arrived_at")),
                                    _log_clean(pres.get("departed_at"))) if x)
    if inout:
        out.append(f"    on site {inout}")
    prog = data.get("progress") if isinstance(data.get("progress"), dict) else {}
    summary = _log_clean(prog.get("summary"))
    if summary:
        out.append(f"    progress: {summary}")
    insp = data.get("daily_inspection") if isinstance(data.get("daily_inspection"), dict) else {}
    loc = _log_clean(insp.get("location"))
    if loc:
        out.append(f"    inspected: {loc}")
    # A section that says "none to report" IS the report, and it is not worth a
    # line. Only the ones carrying something are.
    for key, label in (("unsafe_conditions", "unsafe conditions"),
                       ("orders_given", "orders given"),
                       ("dob_actions", "DOB actions"),
                       ("incidents", "incidents")):
        sec = data.get(key)
        if isinstance(sec, dict) and not sec.get("none_to_report"):
            detail = _log_clean(sec.get("summary") or sec.get("description")
                                or sec.get("note")) or "reported"
            out.append(f"    {label}: {detail}")
    return out


def _render_logbook(book: Dict[str, Any]) -> List[str]:
    kind = book.get("log_type") or "log"
    data = book.get("data") if isinstance(book.get("data"), dict) else {}
    who = _log_clean(book.get("cp_name") or book.get("created_by_name"))
    head = _LOGBOOK_LABEL.get(kind, str(kind).replace("_", " "))
    out = [f"  {head}" + (f" ({who})" if who else "")]
    if kind == "daily_jobsite":
        out += _render_daily_jobsite(data)
    elif kind == "site_superintendent_log":
        out += _render_superintendent(data)
    elif kind == "toolbox_talk":
        att = [a for a in (data.get("attendees") or []) if isinstance(a, dict)]
        bits = [x for x in (_log_clean(data.get("type_of_work")),
                            _log_clean(data.get("meeting_time")),
                            f"{len(att)} attended" if att else "") if x]
        if bits:
            out.append("    " + ", ".join(bits))
    elif kind == "osha_log":
        entries = [e for e in (data.get("entries") or []) if isinstance(e, dict)]
        if entries:
            out.append(f"    {len(entries)} worker card(s) recorded")
    elif kind == "preshift_signin":
        n = _log_clean(data.get("total_count")) or str(len(data.get("workers") or []))
        if n and n != "0":
            out.append(f"    {n} signed in")
    return out


def _render_daily_log_row(log: Dict[str, Any]) -> List[str]:
    """The other collection, and its own fields — none of which were printed."""
    who = _log_clean(log.get("created_by_name"))
    out = ["  daily log" + (f" ({who})" if who else "")]
    w = _weather_line(log)
    if w:
        out.append(f"    weather: {w}")
    n = _log_clean(log.get("worker_count"))
    if n:
        out.append(f"    {n} workers")
    for key, label in (("work_performed", "work"), ("notes", "notes"),
                       ("corrective_actions", "corrective actions"),
                       ("incident_log", "incidents"),
                       ("subcontractor_cards", "subcontractor cards")):
        v = _log_clean(log.get(key))
        if v and v.lower() not in ("none", "n/a", "na", "false"):
            out.append(f"    {label}: {v[:200]}")
    return out


async def _handle_daily_log(project_id: str, date: Optional[str] = None) -> str:
    """Everything filed for one day, from both places a day can be filed.

    ── WHY THIS TOOL EXISTS ───────────────────────────────────────────────
    #
    # Measured: "show me OSHA log" reached query_plan, which searched the
    # DRAWING index for a safety log, found sheets whose text mentions "log",
    # and sent them. The routing was not wrong about the words — it was wrong
    # because the log had no home, and a request with no tool falls to whatever
    # tool will take it.
    #
    # THE DATE ARRIVES RESOLVED. The agent is told to compute "last Thursday"
    # against the NOW line in its context block and pass YYYY-MM-DD; this does
    # not parse English, because two date parsers disagreeing is worse than
    # one."""
    if not project_id:
        return "Could not determine project."
    day = (date or "").strip() or eastern_today()
    books: List[Dict[str, Any]] = []
    legacy = None
    try:
        books = await db.logbooks.find(
            {"project_id": str(project_id), "date": day,
             "is_deleted": {"$ne": True}},
        ).to_list(24)
    except Exception as e:
        logger.warning(f"logbook read failed for {project_id} {day}: {e}")
    try:
        legacy = await db.daily_logs.find_one(
            {"project_id": str(project_id), "date": day,
             "is_deleted": {"$ne": True}},
        )
    except Exception as e:
        logger.warning(f"daily log read failed for {project_id} {day}: {e}")

    if not books and not legacy:
        # NAMED, NOT "no log found". "Nothing filed for 2026-09-11" is
        # checkable; "no daily log found" leaves the reader unsure which day
        # was looked at.
        return f"Nothing filed for {day}."

    order = {k: i for i, k in enumerate(_LOGBOOK_ORDER)}
    books.sort(key=lambda b: order.get(b.get("log_type"), 99))
    lines = [f"Log for {day}:"]
    for b in books:
        lines.extend(_render_logbook(b))
    if legacy:
        lines.extend(_render_daily_log_row(legacy))
    out = "\n".join(lines)
    return out if len(out) <= DAILY_LOG_MAX_CHARS else out[:DAILY_LOG_MAX_CHARS - 3] + "..."


async def _handle_open_items(project_id: str) -> str:
    """Return uncorrected observations from today's daily log."""
    # Eastern: `date` on daily_logs is a New York calendar day, so an evening
    # query on the UTC day looked for tomorrow's log and reported none found.
    today_str = eastern_today()
    log = await db.daily_logs.find_one({"project_id": project_id, "date": today_str})
    if not log:
        return "No daily log found for today."
    observations = log.get("observations", [])
    open_obs = [o for o in observations if not o.get("corrected")]
    if not open_obs:
        return "All observations corrected for today."
    lines = [f"*Open items today ({len(open_obs)}):*"]
    for i, o in enumerate(open_obs, 1):
        desc = o.get("description", o.get("note", "No description"))[:100]
        lines.append(f"  {i}. {desc}")
    return "\n".join(lines)


# ---------- material tracking ----------

async def _detect_material_request(message_body: str, project_id: str, company_id: str) -> Optional[dict]:
    """Use GPT-4o-mini to detect if a message contains a material request."""
    if not message_body or len(message_body.strip()) < 15:
        return None
    if not OPENAI_API_KEY:
        return None

    try:
        async with ServerHttpClient(timeout=15) as client:
            resp = await client.post(
                "https://api.openai.com/v1/chat/completions",
                headers={"Authorization": f"Bearer {OPENAI_API_KEY}"},
                json={
                    "model": "gpt-4o-mini",
                    "temperature": 0,
                    "messages": [
                        {"role": "system", "content": """You analyze construction site WhatsApp messages to detect material requests.
A material request is when someone asks for construction materials to be ordered or delivered.
Examples: "need 200 sheets of drywall", "order 50 bags of concrete", "we're out of 2x4s", "bring 10 boxes of screws tomorrow"
NOT material requests: status updates, questions, greetings, photos, scheduling.

If this is a material request, return JSON:
{"is_request": true, "items": [{"name": "material name", "quantity": number_or_null, "unit": "unit_or_null", "specs": "any specifications"}], "trade": "framing|plumbing|electrical|concrete|drywall|general", "needed_by": "date_mentioned_or_null"}

If NOT a material request, return: {"is_request": false}"""},
                        {"role": "user", "content": message_body}
                    ],
                    "response_format": {"type": "json_object"}
                }
            )
            if resp.status_code == 200:
                content = resp.json()["choices"][0]["message"]["content"]
                result = json.loads(content)
                if result.get("is_request"):
                    return result
    except Exception as e:
        logger.error(f"Material detection error: {e}")
    return None


async def _create_material_request(project_id: str, company_id: str, group_id: str,
                                     message_id: str, sender_phone: str, detection: dict) -> dict:
    """Create a material request document from detected request."""
    now = datetime.now(timezone.utc)

    # Duplicate detection: check for similar request from same group in last 24h
    recent = await db.material_requests.find_one({
        "project_id": project_id,
        "group_id": group_id,
        "status": {"$in": ["open", "partial"]},
        "created_at": {"$gte": now - timedelta(hours=24)}
    })
    if recent:
        # Check item overlap
        existing_names = {i["name"].lower() for i in recent.get("items", [])}
        new_names = {i["name"].lower() for i in detection.get("items", [])}
        overlap = len(existing_names & new_names)
        if overlap > 0 and overlap >= len(new_names) * 0.5:
            logger.info(f"Duplicate material request detected for project {project_id}, skipping")
            return recent

    items = []
    for item in detection.get("items", []):
        items.append({
            "name": item.get("name", "Unknown"),
            "quantity_requested": item.get("quantity"),
            "quantity_received": 0,
            "unit": item.get("unit"),
            "specs": item.get("specs"),
            "status": "pending",
        })

    doc = {
        "project_id": project_id,
        "company_id": company_id,
        "group_id": group_id,
        "message_id": message_id,
        "requested_by": sender_phone,
        "requested_by_trade": detection.get("trade", "general"),
        "needed_by_date": detection.get("needed_by"),
        "items": items,
        "status": "open",
        "delivery_receipts": [],
        "created_at": now,
        "updated_at": now,
        "is_deleted": False,
    }

    result = await db.material_requests.insert_one(doc)
    doc["_id"] = result.inserted_id
    return doc


async def _send_material_confirmation(group_id: str, request_doc: dict):
    """Send formatted confirmation to WhatsApp group."""
    items = request_doc.get("items", [])
    trade = request_doc.get("requested_by_trade", "general").title()
    needed_by = request_doc.get("needed_by_date")

    lines = [f"\U0001f4cb *Material Request Logged* ({trade})"]
    if needed_by:
        lines.append(f"\U0001f4c5 Needed by: {needed_by}")
    lines.append("")
    for i, item in enumerate(items, 1):
        qty = f"{item['quantity_requested']} {item.get('unit') or 'units'}" if item.get('quantity_requested') else "TBD"
        specs = f" \u2014 {item['specs']}" if item.get('specs') else ""
        lines.append(f"{i}. {item['name']}: {qty}{specs}")
    lines.append("")
    lines.append("_Reply with delivery info when materials arrive._")

    message = "\n".join(lines)
    await send_whatsapp_message(group_id, message)


async def _handle_material_receipt(project_id: str, message_body: str, sender_phone: str) -> str:
    """Reconcile a delivery receipt against open material requests."""
    if not project_id or not OPENAI_API_KEY:
        return "I couldn't process this delivery receipt. Please log it manually."

    # Get open/partial requests
    requests = await db.material_requests.find({
        "project_id": project_id,
        "status": {"$in": ["open", "partial"]},
        "is_deleted": {"$ne": True}
    }).to_list(20)

    if not requests:
        return "No open material requests found for this project."

    # Build outstanding items summary
    outstanding = []
    for req in requests:
        for item in req.get("items", []):
            if item["status"] in ("pending", "partial"):
                remaining = (item.get("quantity_requested") or 0) - (item.get("quantity_received") or 0)
                outstanding.append({
                    "request_id": str(req["_id"]),
                    "item_name": item["name"],
                    "quantity_remaining": remaining,
                    "unit": item.get("unit"),
                })

    if not outstanding:
        return "All material requests are fulfilled. No outstanding items."

    try:
        async with ServerHttpClient(timeout=15) as client:
            resp = await client.post(
                "https://api.openai.com/v1/chat/completions",
                headers={"Authorization": f"Bearer {OPENAI_API_KEY}"},
                json={
                    "model": "gpt-4o",
                    "temperature": 0,
                    "messages": [
                        {"role": "system", "content": f"""Match the delivery receipt against outstanding material requests.
Outstanding items: {json.dumps(outstanding)}
Return JSON: {{"matches": [{{"request_id": "id", "item_name": "name", "quantity_received": number}}], "unmatched": ["items not on any request"]}}"""},
                        {"role": "user", "content": message_body}
                    ],
                    "response_format": {"type": "json_object"}
                }
            )
            if resp.status_code != 200:
                return "Could not process delivery receipt. Please log manually."

            result = json.loads(resp.json()["choices"][0]["message"]["content"])
    except Exception as e:
        logger.error(f"Delivery reconciliation error: {e}")
        return "Error processing delivery receipt. Please log manually."

    # Update MongoDB
    report_lines = ["\U0001f4e6 *Delivery Reconciliation*", ""]
    for match in result.get("matches", []):
        req_id = match.get("request_id")
        item_name = match.get("item_name")
        qty_received = match.get("quantity_received", 0)

        # Find and update the request
        for req in requests:
            if str(req["_id"]) == req_id:
                for item in req.get("items", []):
                    if item["name"].lower() == item_name.lower():
                        item["quantity_received"] = (item.get("quantity_received") or 0) + qty_received
                        if item.get("quantity_requested") and item["quantity_received"] >= item["quantity_requested"]:
                            item["status"] = "received"
                            report_lines.append(f"\u2705 {item_name}: {qty_received} received \u2014 *Complete*")
                        else:
                            remaining = (item.get("quantity_requested") or 0) - item["quantity_received"]
                            item["status"] = "partial"
                            report_lines.append(f"\u26a0\ufe0f {item_name}: {qty_received} received \u2014 {remaining} still needed")
                        break

                # Update overall request status
                statuses = [i["status"] for i in req.get("items", [])]
                if all(s == "received" for s in statuses):
                    req_status = "fulfilled"
                elif any(s in ("received", "partial") for s in statuses):
                    req_status = "partial"
                else:
                    req_status = "open"

                await db.material_requests.update_one(
                    {"_id": req["_id"]},
                    {"$set": {"items": req["items"], "status": req_status, "updated_at": datetime.now(timezone.utc)},
                     "$push": {"delivery_receipts": {"received_by": sender_phone, "message": message_body, "timestamp": datetime.now(timezone.utc), "matches": result.get("matches", [])}}}
                )
                break

    for unmatched in result.get("unmatched", []):
        report_lines.append(f"\u2753 {unmatched} \u2014 not on any open request")

    return "\n".join(report_lines)


async def _handle_project_info(project_id: str) -> str:
    """Return a short, human-readable summary of the project bound to this group."""
    if not project_id:
        return "Could not determine which project this group is linked to."
    try:
        project = await db.projects.find_one({"_id": to_query_id(project_id)})
    except Exception:
        project = None
    if not project:
        return "Project not found."

    name = project.get("name") or "(unnamed project)"
    address = project.get("address") or project.get("formatted_address") or "—"
    bin_ = project.get("nyc_bin") or project.get("bin") or ""
    bbl = project.get("bbl") or project.get("nyc_bbl") or ""
    # GC name: same canonical fallback chain as api_check_eligibility,
    # via _resolve_gc_legal_name in permit_renewal.py. Adds one
    # companies.find_one round-trip but matches semantics across
    # display (here) and eligibility-check input. Falls back to the
    # legacy project.gc_name field if the chain produces nothing,
    # preserving the prior display behavior on old project docs that
    # only carry that field.
    gc = ""
    try:
        from permit_renewal import _resolve_gc_legal_name
        company_for_gc = None
        company_id = project.get("company_id")
        if company_id:
            try:
                company_for_gc = await db.companies.find_one(
                    {"_id": to_query_id(company_id)}
                )
            except Exception:
                company_for_gc = None
        gc = _resolve_gc_legal_name(project, company_for_gc)
    except Exception:
        # Defensive — chat handler should never crash on a name lookup.
        gc = ""
    if not gc:
        gc = project.get("gc_name") or ""  # legacy field
    status = project.get("status") or "active"

    lines = [f"📍 *{name}*", address]
    if bin_:
        lines.append(f"BIN: {bin_}")
    if bbl:
        lines.append(f"BBL: {bbl}")
    if gc:
        lines.append(f"GC: {gc}")
    lines.append(f"Status: {status}")
    return "\n".join(lines)


from lib.app_urls import APP_BASE_URL  # single definition; see lib/app_urls.py


def _permit_renewal_deep_link(project_id: str, permit_id: str) -> str:
    """Deep link to the mobile/web renewal screen with the permit preselected.

    The frontend reads ?permit=<id> and auto-selects. If the user isn't
    signed in, the login screen preserves the return URL so they land
    back on renewal after auth.
    """
    return (
        f"{APP_BASE_URL.rstrip('/')}/project/{project_id}/permit-renewal"
        f"?permit={permit_id}"
    )


def _permit_matches_hint(permit: dict, hint: str) -> int:
    """Score a permit 0-N against a free-text hint. Higher = better match."""
    if not hint:
        return 0
    h = hint.lower()
    score = 0
    for field, weight in (
        ("permit_type",    4),
        ("permit_subtype", 3),
        ("job_number",     5),
        ("raw_dob_id",     2),
        ("work_type",      1),
    ):
        v = str(permit.get(field) or "").lower()
        if not v:
            continue
        if h == v:
            score += weight * 3
        elif h in v or v in h:
            score += weight
        else:
            # Token overlap
            htoks = set(re.findall(r"[a-z0-9]+", h))
            vtoks = set(re.findall(r"[a-z0-9]+", v))
            if htoks & vtoks:
                score += max(1, weight // 2)
    # Well-known abbreviation expansions
    aliases = [
        ("pl", "plumbing"), ("me", "mechanical"), ("el", "electrical"),
        ("sp", "sprinkler"), ("mh", "mechanical"), ("gc", "general construction"),
        ("dm", "demolition"), ("eq", "equipment"), ("sh", "sheeting"),
        ("fn", "foundation"), ("nb", "new building"), ("fo", "footing"),
        ("ea", "earthwork"),
    ]
    ptype = str(permit.get("permit_type") or "").lower()
    psub = str(permit.get("permit_subtype") or "").lower()
    for short, long in aliases:
        if (short in h and (long in ptype or long in psub)) or \
           (long in h and (short == ptype or short == psub)):
            score += 5
    # "Soonest" / "expiring" preference handled by caller
    return score


async def _handle_start_permit_renewal(
    project_id: str, group_id: str, sender: str, permit_hint: str
) -> str:
    """Resolve permit → check eligibility → send deep link or blocker list."""
    if not project_id:
        return "Could not determine which project this is."

    # Load the same active-permit set the user sees.
    try:
        permits = await db.dob_logs.find({
            "project_id":  project_id,
            "record_type": "permit",
            "is_deleted":  {"$ne": True},
        }).to_list(200)
    except Exception as e:
        logger.error(f"start_permit_renewal load failed: {e}", exc_info=True)
        return "Couldn't load permits right now — please try again in a minute."

    now = datetime.now(timezone.utc)
    active_status = {"permit issued", "issued", "active", "pre-filed"}

    def _parse_iso(v):
        if not v:
            return None
        if isinstance(v, datetime):
            return v if v.tzinfo else v.replace(tzinfo=timezone.utc)
        try:
            s = str(v).replace("Z", "+00:00")
            dt = datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=timezone.utc)
        except Exception:
            return None

    active = []
    for p in permits:
        stat = str(p.get("permit_status") or "").strip().lower()
        exp = _parse_iso(p.get("expiration_date"))
        if stat in active_status and (exp is None or exp > now):
            active.append((p, exp))

    if not active:
        return "No active permits on file for this project — nothing to renew."

    # "Soonest" / "expiring" shortcut
    hint_low = (permit_hint or "").lower()
    prefer_soonest = any(
        w in hint_low for w in ("soonest", "expiring", "most urgent", "first")
    )

    if prefer_soonest:
        active.sort(key=lambda x: (x[1] or datetime.max.replace(tzinfo=timezone.utc)))
        top = active[0]
        scored = [(100, top[0], top[1])]
    else:
        scored = [
            (_permit_matches_hint(p, permit_hint), p, exp) for p, exp in active
        ]
        scored = [s for s in scored if s[0] > 0]
        scored.sort(key=lambda x: -x[0])

    if not scored:
        # Nothing matched the hint — list the options.
        lines = [f"I don't see a permit matching '{permit_hint}'. Active permits:"]
        active.sort(key=lambda x: (x[1] or datetime.max.replace(tzinfo=timezone.utc)))
        for p, exp in active[:10]:
            label = f"{p.get('permit_type') or 'Permit'}"
            if p.get("permit_subtype"):
                label += f"/{p['permit_subtype']}"
            if p.get("job_number"):
                label += f" — {p['job_number']}"
            if exp:
                label += f" (exp {exp.strftime('%Y-%m-%d')})"
            lines.append(f"  • {label}")
        lines.append("Which one should I renew?")
        return "\n".join(lines)

    # If top two scores are tied or very close, ask for clarification.
    if len(scored) >= 2 and scored[1][0] >= max(scored[0][0] - 1, 1):
        lines = [f"Multiple permits match '{permit_hint}':"]
        for score, p, exp in scored[:5]:
            label = f"{p.get('permit_type') or 'Permit'}"
            if p.get("permit_subtype"):
                label += f"/{p['permit_subtype']}"
            if p.get("job_number"):
                label += f" — {p['job_number']}"
            if exp:
                label += f" (exp {exp.strftime('%Y-%m-%d')})"
            lines.append(f"  • {label}")
        lines.append("Which one? Reply with the job number or full type.")
        return "\n".join(lines)

    target, target_exp = scored[0][1], scored[0][2]
    permit_id = str(target["_id"])

    # Eligibility — call the existing engine. Needs company name.
    project = await db.projects.find_one({"_id": to_query_id(project_id)})
    company_doc = None
    if project and project.get("company_id"):
        company_doc = await db.companies.find_one(
            {"_id": to_query_id(project["company_id"])}
        )
    company_name = (company_doc or {}).get("name") or ""

    try:
        from backend.permit_renewal import check_renewal_eligibility
        elig = await check_renewal_eligibility(
            db, permit_id, project_id, company_name,
            company_id=str(project["company_id"]) if project else None,
        )
    except Exception as e:
        logger.error(f"eligibility check failed: {e}", exc_info=True)
        deep = _permit_renewal_deep_link(project_id, permit_id)
        return (
            f"Couldn't run the automatic eligibility check, but I can take you "
            f"straight to the renewal screen:\n{deep}"
        )

    ptype = target.get("permit_type") or "Permit"
    sub = target.get("permit_subtype")
    label = f"{ptype}" + (f"/{sub}" if sub else "")
    job = target.get("job_number") or ""
    exp_str = target_exp.strftime("%Y-%m-%d") if target_exp else "unknown"
    days_left = elig.days_until_expiry if elig and elig.days_until_expiry is not None else None

    deep = _permit_renewal_deep_link(project_id, permit_id)

    header = f"*Renewal — {label}*"
    if job:
        header += f" (Job {job})"
    header += f"\nExpires {exp_str}" + (f" ({days_left}d left)" if days_left is not None else "")

    if not elig.eligible and elig.blocking_reasons:
        bullets = "\n".join(f"  • {r}" for r in elig.blocking_reasons[:6])
        extra = ""
        if elig.insurance_flags:
            extra = "\n\nInsurance to update first:\n" + "\n".join(
                f"  • {f}" for f in elig.insurance_flags[:5]
            )
        return (
            f"{header}\n\n"
            f"Not ready to auto-renew yet:\n{bullets}{extra}\n\n"
            f"Open the renewal screen anyway to review and file manually:\n{deep}"
        )

    if elig.insurance_not_entered:
        return (
            f"{header}\n\n"
            f"Ready to renew, but I don't have insurance on file for this company yet.\n"
            f"Add General Liability, Workers Comp, and Disability in Settings, "
            f"then tap here:\n{deep}"
        )

    return (
        f"{header}\n\n"
        f"Eligible to renew — all checks pass. Open the renewal form:\n{deep}"
    )


async def _handle_active_permits(project_id: str) -> str:
    """Return currently-active DOB permits for this project.

    Reads from db.dob_logs where record_type='permit' and the permit is
    issued/active and not expired. Groups by permit type/subtype.
    """
    if not project_id:
        return "Could not determine project."
    try:
        permits = await db.dob_logs.find({
            "project_id":  project_id,
            "record_type": "permit",
            "is_deleted":  {"$ne": True},
        }).sort("expiration_date", -1).to_list(100)
    except Exception as e:
        logger.error(f"active_permits query failed: {e}", exc_info=True)
        return "Couldn't load permit data right now — please try again in a minute."

    if not permits:
        return (
            "No permits on file for this project in our DB. "
            "If you expect permits, run a DOB sync from the project page."
        )

    # Classify: active if status is issued-like and not past expiration.
    now = datetime.now(timezone.utc)
    active_status = {"permit issued", "issued", "active", "pre-filed"}

    def _parse_iso(v):
        if not v:
            return None
        if isinstance(v, datetime):
            return v if v.tzinfo else v.replace(tzinfo=timezone.utc)
        try:
            s = str(v).replace("Z", "+00:00")
            dt = datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=timezone.utc)
        except Exception:
            return None

    active = []
    for p in permits:
        stat = str(p.get("permit_status") or "").strip().lower()
        exp = _parse_iso(p.get("expiration_date"))
        if stat in active_status and (exp is None or exp > now):
            active.append((p, exp))

    if not active:
        total = len(permits)
        return f"No active permits right now (found {total} on file, all expired or closed)."

    # Sort active by expiration (soonest first)
    active.sort(key=lambda x: (x[1] or datetime.max.replace(tzinfo=timezone.utc)))

    # Pre-compute days-to-expiry so the LLM composing the final reply
    # can't hallucinate "no permits expiring soon" when one clearly is.
    # Bucket: <=30 days = URGENT, <=90 = soon, >90 = ok.
    expiring_30 = [a for a in active if a[1] and (a[1] - now).days <= 30]
    expiring_90 = [a for a in active if a[1] and 30 < (a[1] - now).days <= 90]

    header_bits = [f"*Active permits ({len(active)}):*"]
    if expiring_30:
        header_bits.append(
            f"⚠️ {len(expiring_30)} permit(s) expiring within 30 days — renewal needed now."
        )
    if expiring_90:
        header_bits.append(
            f"🟡 {len(expiring_90)} permit(s) expiring within 31–90 days."
        )
    lines = header_bits
    for p, exp in active[:15]:
        ptype = p.get("permit_type") or "Permit"
        sub = p.get("permit_subtype") or ""
        job = p.get("job_number") or p.get("raw_dob_id") or ""
        label = f"{ptype}" + (f"/{sub}" if sub else "")
        if job:
            label += f" — Job {job}"
        if exp:
            days = (exp - now).days
            if days <= 30:
                flag = f" ⚠️ *{days}d left*"
            elif days <= 90:
                flag = f" 🟡 {days}d left"
            else:
                flag = ""
            label += f" (exp {exp.strftime('%Y-%m-%d')}{flag})"
        lines.append(f"  • {label}")
    if len(active) > 15:
        lines.append(f"…and {len(active) - 15} more.")
    return "\n".join(lines)


async def _handle_material_status(project_id: str) -> str:
    """Return formatted status of open/partial material requests."""
    if not project_id:
        return "Could not determine project."

    requests = await db.material_requests.find({
        "project_id": project_id,
        "status": {"$in": ["open", "partial"]},
        "is_deleted": {"$ne": True}
    }).to_list(20)

    if not requests:
        return "\u2705 No outstanding material requests."

    lines = ["\U0001f4ca *Outstanding Materials*", ""]
    for req in requests:
        trade = req.get("requested_by_trade", "general").title()
        lines.append(f"*{trade}* (requested {req.get('created_at', '').strftime('%m/%d') if isinstance(req.get('created_at'), datetime) else 'N/A'}):")
        for item in req.get("items", []):
            if item["status"] in ("pending", "partial"):
                remaining = (item.get("quantity_requested") or 0) - (item.get("quantity_received") or 0)
                unit = item.get("unit") or "units"
                if item["status"] == "pending":
                    lines.append(f"  \u23f3 {item['name']}: {remaining} {unit} needed")
                else:
                    lines.append(f"  \u26a0\ufe0f {item['name']}: {remaining} {unit} still needed")
        lines.append("")

    return "\n".join(lines)


async def _find_project_for_contact(contact: dict) -> Optional[str]:
    """Return first assigned project ID for a contact, or None."""
    user_id = contact.get("user_id")
    if not user_id:
        return None
    user = await db.users.find_one({"_id": to_query_id(user_id)})
    if not user:
        return None
    assigned = user.get("assigned_projects", [])
    if assigned:
        return str(assigned[0])
    # Fallback: first active project in company
    company_id = user.get("company_id")
    if company_id:
        proj = await db.projects.find_one({"company_id": company_id, "is_deleted": {"$ne": True}})
        if proj:
            return str(proj["_id"])
    return None


# ---------- inbound processing ----------

# ==================== WHATSAPP BOT CONFIG ====================

def _default_bot_config() -> dict:
    """Default bot_config assigned to newly linked or migrated groups.

    IMPORTANT: daily_summary_enabled defaults to False everywhere. Old groups
    without a config pick up these defaults via the startup migration so they
    do NOT start receiving unsolicited summaries on first deploy of this code.
    Admins must explicitly opt in per group.
    """
    return {
        "bot_enabled": True,  # master kill switch — False short-circuits everything
        "daily_summary_enabled": False,
        "daily_summary_time": "17:00",       # 24h EST HH:MM
        "daily_summary_days": [1, 2, 3, 4, 5],  # ISO weekday Mon=1 Sun=7
        # ── ON, BECAUSE NOBODY SWITCHES ON A FEATURE THEY DO NOT KNOW EXISTS ─
        #
        # This defaulted False and the reasoning was sound in isolation: do not
        # surprise an existing group with behaviour it did not ask for. What it
        # missed is that there is no screen that advertises the feature either,
        # so "off by default" and "does not exist" are the same thing to every
        # user who has not read the source.
        #
        # The surprise argument still holds for anything the bot sends
        # UNPROMPTED, which is why daily_summary_enabled stays False: a digest
        # arriving at 17:00 in a group that never asked for one is spam. A
        # checklist only appears when somebody asks for one.
        "checklist_extraction_enabled": True,
        "checklist_frequency": "daily",       # "daily" | "on_demand"
        "checklist_time": "16:00",
        "features": {
            "who_on_site": True,
            "dob_status": True,
            "open_items": True,
            "material_detection": True,
            # Default ON — the tool is the bot's whole reason to know the
            # plans, and it's gated behind the indexing pipeline anyway.
            "plan_queries": True,
            # ── LOOSE, AND THE DEFAULT FLIPPED ON MEASUREMENT ──────────────
            #
            # This was "strict" and strict was measured losing about a third of
            # the real questions put to it: eleven of thirty-four unaddressed
            # messages in the only live group were questions the bot could have
            # answered. Not one was malformed. People were talking normally.
            #
            # Strict is the right default for a bot in a group of strangers.
            # This is a bot in a crew's own group, on a site, where the people
            # typing have hard hats on and will not learn a syntax.
            #
            # WHAT MAKES LOOSE SAFE IS NOT THE TRIGGER LIST, IT IS NOREPLY. A
            # message that trips a trigger without being meant for the bot
            # reaches the agent, which answers NOREPLY and stays silent. So the
            # cost of a false trigger is one gpt-4o-mini call, not an
            # interruption — and the cap in _vision_budget_exceeded is what
            # keeps that from being unbounded.
            #
            # "strict" is still there and still works, per group, for anyone
            # who wants it.
            "address_mode": "loose",
            # Group voicenotes. See _process_whatsapp_message for why this was
            # off, and why it is worth another try before the trial.
            "voice_notes": True,
        },
        "cross_project_summary": False,
    }


_WHATSAPP_CONFIG_KEYS = {
    "bot_enabled", "daily_summary_enabled", "daily_summary_time",
    "daily_summary_days", "checklist_extraction_enabled",
    "checklist_frequency", "checklist_time", "features",
    "cross_project_summary",
}
_WHATSAPP_FEATURE_KEYS = {
    "who_on_site", "dob_status", "open_items", "material_detection", "plan_queries",
    "address_mode", "voice_notes",
}
_HHMM_RE = re.compile(r"^([01]\d|2[0-3]):[0-5]\d$")


async def _whatsapp_send_log_try_mark(
    group_id: str, job_type: str, sent_date_est: str
) -> bool:
    """Attempt to record that a scheduled send happened for this group/job/date.

    Returns True if the caller should proceed with the send (first attempt today).
    Returns False if a duplicate key error fires (already sent) -- caller must skip.

    Backed by a MongoDB unique compound index. Survives server restarts. No
    in-memory state anywhere.
    """
    from pymongo.errors import DuplicateKeyError
    try:
        await db.whatsapp_send_log.insert_one({
            "group_id": group_id,
            "job_type": job_type,
            "sent_date_est": sent_date_est,
            "created_at": datetime.now(timezone.utc),
        })
        return True
    except DuplicateKeyError:
        return False


async def ensure_dropbox_sync_indexes():
    """Indexes for the Dropbox sync run record. Idempotent; safe every boot.

    ITS OWN FUNCTION AND ITS OWN try/except, and that is the whole point of the
    change that moved it here. These two lines were inside
    run_whatsapp_startup_migrations() -- one try covering four unrelated
    migrations with a single except that logs and moves on -- so an unrelated
    WhatsApp failure would have silently skipped them.

    That is not a tidiness argument. The TTL is the only thing bounding this
    collection: the Dropbox webhook fans out across EVERY project a company has
    linked, so one person editing one file writes a run record per project, and
    a company with forty projects writes forty rows for one save. Losing the
    index loses the bound, silently, for a reason having nothing to do with
    Dropbox.

    14 days: long enough to answer "why was that CP missing drawings last week",
    short enough that the fan-out cannot accumulate. What the CLIENT reads is
    mirrored onto the project document and is NOT subject to this expiry, so a
    run ageing out ends the diagnostic trail and never changes app behaviour.
    """
    try:
        await db[DROPBOX_SYNC_RUNS].create_index(
            "created_at",
            expireAfterSeconds=60 * 60 * 24 * 14,
            name="dropbox_sync_runs_ttl",
        )
        await db[DROPBOX_SYNC_RUNS].create_index(
            [("project_id", 1), ("created_at", -1)],
            name="dropbox_sync_runs_by_project",
        )
    except Exception as e:
        logger.warning(f"ensure_dropbox_sync_indexes: {e}")


async def ensure_document_page_indexes():
    """Indexes for the plan-query page index. Idempotent; safe every boot.

    ITS OWN FUNCTION AND ITS OWN try/except, for exactly the reason
    ensure_dropbox_sync_indexes gives — and these four had even less business
    being where they were. `document_page_index` is the Sprint 3 PLAN QUERY
    pipeline. It has NOTHING TO DO WITH WHATSAPP. It sat inside
    run_whatsapp_startup_migrations under a shared `except` with four unrelated
    WhatsApp migrations, so a failure in the bot_config backfill — a collection
    the plan pipeline has never heard of — silently skipped every index the
    plan search reads through.

    `document_page_unique` is a UNIQUE build, so it goes through
    _ensure_index_resilient like every other one: duplicate (file_id,
    page_number) rows from a re-index would otherwise be a silent no-index, and
    now they are a named finding in the health payload.
    """
    try:
        await _ensure_index_resilient(
            db.document_page_index,
            keys=[("file_id", 1), ("page_number", 1)],
            name="document_page_unique",
            unique=True,
        )
        await _ensure_index_resilient(
            db.document_page_index,
            keys=[("project_id", 1), ("discipline", 1)],
            name="document_page_by_project_discipline",
        )
        # Plan-query v2: fast exact-match lookup on sheet number per project.
        # Alphanumeric sheet IDs ('A-301', 'ME-401') are poorly served by
        # vector search; regex / exact match on this field always takes
        # priority over semantic retrieval.
        await _ensure_index_resilient(
            db.document_page_index,
            keys=[("project_id", 1), ("sheet_number", 1)],
            name="document_page_by_sheet_number",
        )
        await _ensure_index_resilient(
            db.document_page_index,
            keys=[("project_id", 1), ("file_hash", 1), ("page_number", 1)],
            name="document_page_by_project_hash_page",
        )
        # Index version 3: one row per schedule, note block, legend, element
        # list. Replaced per page, deleted with the page, read by project.
        await _ensure_index_resilient(
            db.document_page_chunks,
            keys=[("project_id", 1), ("page_id", 1)],
            name="page_chunks_by_project_page",
        )
        await _ensure_index_resilient(
            db.document_page_chunks,
            keys=[("file_id", 1), ("page_number", 1)],
            name="page_chunks_by_file_page",
        )
        # The plan index queue: the worker's claim, and per-project status.
        await _ensure_index_resilient(
            db[PLAN_INDEX_JOBS],
            keys=[("status", 1), ("not_before", 1), ("enqueued_at", 1)],
            name="plan_index_jobs_claim",
        )
        await _ensure_index_resilient(
            db[PLAN_INDEX_JOBS],
            keys=[("project_id", 1), ("status", 1)],
            name="plan_index_jobs_by_project",
        )
    except Exception as e:
        logger.warning(f"ensure_document_page_indexes: {e}")


async def run_whatsapp_startup_migrations():
    """Idempotent startup migrations for the WhatsApp feature set.

    Safe to call on every server boot. Runs:
    - Set default bot_config on any existing whatsapp_groups without one.
    - Create whatsapp_send_log collection + unique compound + TTL index.
    - Create whatsapp_checklists compound index (used in Sprint 2).
    - Create whatsapp_conversation_state unique + TTL (Sprint 6).

    ── ONE try PER MIGRATION, AND THAT IS THE CHANGE ─────────────────────────

    All of this was under ONE try with ONE `except` that logged and moved on.
    A throw in migration 2 silently skipped 3, 4 and 5 — and the log line said
    "run_whatsapp_startup_migrations: <error>", which reads like ONE thing
    failed. Nothing anywhere said the other three never ran.

    This is the shape ensure_dropbox_sync_indexes was extracted OUT of. That
    extraction fixed two lines and left five; this finishes it. The
    document_page_index block, which was never a WhatsApp migration at all, is
    now ensure_document_page_indexes() above.

    Each stage is independent and each names ITSELF in its log line, so a
    failure says which migration failed and the rest still run.
    """
    # Migration 1 — backfill bot_config on legacy group docs
    try:
        result = await db.whatsapp_groups.update_many(
            {"bot_config": {"$exists": False}},
            {"$set": {"bot_config": _default_bot_config()}},
        )
        if result.modified_count:
            logger.info(
                f"WhatsApp migration: backfilled bot_config on "
                f"{result.modified_count} existing group doc(s)"
            )
    except Exception as e:
        logger.warning(f"whatsapp migration 1 (bot_config backfill): {e}")

    # Migration 2 — send_log dedup collection
    try:
        await _ensure_index_resilient(
            db.whatsapp_send_log,
            keys=[("group_id", 1), ("job_type", 1), ("sent_date_est", 1)],
            unique=True,
            name="whatsapp_send_log_unique",
        )
        # 45-day TTL so the collection doesn't grow forever
        await _ensure_index_resilient(
            db.whatsapp_send_log,
            keys=[("created_at", 1)],
            expireAfterSeconds=60 * 60 * 24 * 45,
            name="whatsapp_send_log_ttl",
        )
    except Exception as e:
        logger.warning(f"whatsapp migration 2 (send_log indexes): {e}")

    # Migration 3 — whatsapp_checklists indexes (Sprint 2 consumer)
    try:
        await _ensure_index_resilient(
            db.whatsapp_checklists,
            keys=[("project_id", 1), ("generated_at", -1)],
            name="checklists_by_project_recent",
        )
        await _ensure_index_resilient(
            db.whatsapp_checklists,
            keys=[("group_id", 1), ("generated_at", -1)],
            name="checklists_by_group_recent",
        )
    except Exception as e:
        logger.warning(f"whatsapp migration 3 (checklist indexes): {e}")

    # Migration 5 — whatsapp_conversation_state (Sprint 6 consumer).
    # One active draft per group; auto-expire via TTL on expires_at.
    # (Migration 4 was document_page_index — see ensure_document_page_indexes.)
    # ── ONE ROW PER GROUP WAS ONE ROW TOO FEW ──────────────────────────────
    #
    # `convo_state_by_group` was unique on group_id ALONE, and this collection
    # now holds three kinds of row keyed by the same group: a checklist draft,
    # a bot session, and a nudge cooldown.
    #
    # THE SECOND WRITER ALWAYS LOST, SILENTLY. Its upsert filter did not match
    # the existing row, so it fell through to an insert and hit E11000, which
    # _mark_bot_session caught and logged at DEBUG. Measured against the live
    # test of 2026-09-14: the first untagged question wrote a nudge row, every
    # subsequent _mark_bot_session in that group failed, and an untagged
    # follow-up twenty seconds after a tagged message was judged unaddressed
    # because the window it should have ridden had never been written.
    #
    # It also meant two people in one group could never both hold a session,
    # and a live checklist draft blocked sessions outright — both true long
    # before the nudge existed, which is why this is a fix and not a revert.
    #
    # THE KEY IS NOW WHAT ACTUALLY IDENTIFIES A ROW. One draft per group still
    # holds: a checklist row carries kind="checklist" and no sender, so (kind,
    # group_id, sender) admits exactly one of them per group.
    #
    # The old index is dropped BY NAME. _ensure_index_resilient only rebuilds
    # an index whose name it is given, so leaving the old one in place would
    # keep rejecting every write this change exists to allow.
    try:
        try:
            await db.whatsapp_conversation_state.drop_index("convo_state_by_group")
            # WARNING, not info. This runs once per deploy and the question
            # "did the old index actually go?" was asked of production and
            # could not be answered from the log — an info line in a service
            # nobody raised the level for is a fact that was never recorded.
            logger.warning(
                "dropped convo_state_by_group (was unique on group_id alone) — "
                "bot sessions, nudges and checklist drafts can now coexist")
        except Exception as e:
            # Never created, already gone, or a real failure. The first two are
            # the normal case on every deploy after the first, so this is not
            # an error — but it IS the difference between "the fix is live" and
            # "the fix silently did not apply", so it is said out loud.
            logger.warning(f"convo_state_by_group not dropped: {e}")

        await _ensure_index_resilient(
            db.whatsapp_conversation_state,
            keys=[("kind", 1), ("group_id", 1), ("sender", 1)],
            unique=True,
            name="convo_state_by_kind_group_sender",
        )
        await _ensure_index_resilient(
            db.whatsapp_conversation_state,
            keys=[("expires_at", 1)],
            expireAfterSeconds=0,
            name="convo_state_ttl",
        )
    except Exception as e:
        logger.warning(f"whatsapp migration 5 (conversation state): {e}")


# ==================== SPRINT 3 — PLAN QUERY PIPELINE ====================

# Module-level concurrency guard so a first-sync of a project with 500 PDFs
# doesn't spawn 500 simultaneous indexers. Combined with the per-file page
# semaphore (size 5) the worst case is 3 files * 5 pages = 15 in-flight Qwen
# requests.
_PDF_INDEX_FILE_SEMAPHORE = asyncio.Semaphore(1)
# One page's text layout and render at a time, inside that one file.
_PLAN_PAGE_PREP_SEMAPHORE = asyncio.Semaphore(1)


_DISCIPLINE_PATTERNS = [
    ("AR", re.compile(r"\b(?:ar|arch|architectural)\b", re.I)),
    ("ME", re.compile(r"\b(?:me|mech|mechanical|hvac|mh)\b", re.I)),
    ("EL", re.compile(r"\b(?:el|elec|electrical)\b", re.I)),
    ("PL", re.compile(r"\b(?:pl|plmb|plumbing)\b", re.I)),
    ("SP", re.compile(r"\b(?:sp|sprk|sprinkler|fp|fire\s*protection)\b", re.I)),
    ("ST", re.compile(r"\b(?:st|str|strl|structural)\b", re.I)),
    ("GN", re.compile(r"\b(?:gn|gen|general|site|civil|cv)\b", re.I)),
]


def detect_discipline(filename: str) -> str:
    """Classify a drawing file name into an AEC discipline code.

    Checks the full filename + any path components. Case-insensitive.
    Returns 'other' when no pattern matches.
    """
    if not filename:
        return "other"
    # Split path components and filename into words to match
    raw = filename.replace("\\", "/")
    parts = [p for p in raw.split("/") if p]
    joined = " ".join(parts)
    for code, pat in _DISCIPLINE_PATTERNS:
        if pat.search(joined):
            return code
    return "other"


# ------------- Plan-query index prompts -------------
#
# The indexing prompt is intentionally verbose. Its output is the ONLY basis
# for the downstream embedding + semantic search, so anything missing here is
# permanently invisible to the query pipeline. Qwen-VL handles multi-section
# structured extraction well; keep the section headers stable so the parser
# fallback and human reviewers can grep it.
_PLAN_INDEX_PROMPT = (
    "You are indexing a NYC construction drawing for a searchable database "
    "used by field workers and general contractors. Your output will be the "
    "sole basis for answering technical questions about this sheet.\n\n"
    "Extract and return every piece of the following information exactly as "
    "it appears in the drawing. Do not paraphrase. Do not summarize. Quote "
    "all text verbatim. If a field is not present on this sheet, write NONE "
    "for that field. Be exhaustive — a field worker's safety depends on this "
    "data being complete.\n\n"
    "Return the answer with these exact labeled sections, one per line or "
    "bulleted beneath the label:\n"
    "SHEET_ID: the sheet number exactly as printed (examples: A-301, ME-401, S-102, PL-201)\n"
    "SHEET_TITLE: the full title as printed on the title block\n"
    "DISCIPLINE: Architectural | Structural | Mechanical | Electrical | Plumbing | Sprinkler | Civil | General\n"
    "FLOOR: every floor, level, or zone this sheet covers\n"
    "SPACES_AND_ROOMS: all room names, unit types, corridor labels, space identifiers\n"
    "DIMENSIONS: every explicit dimension callout, ceiling height, clear width, slab thickness, structural depth shown\n"
    "MATERIALS_AND_SPECS: every material, product name, gauge, thickness, fire rating, R-value, performance spec, keynote text verbatim "
    "(examples: 5/8\" Type X GWB, 3-5/8\" 20GA metal stud at 16\" OC, DensGlass Gold sheathing, R-19 batt insulation, 2-hour fire-rated assembly)\n"
    "CODE_REFS: Local Law citations, NYC Building Code sections, IBC refs, special inspection flags, fire-rating assembly numbers\n"
    "DETAIL_AND_SECTION_REFS: all detail bubbles, section cut markers, enlarged plan callouts with their reference numbers\n"
    "NOTES: all general notes, keynotes, and sheet-specific notes in full\n"
)


def _parse_plan_summary(text: str) -> dict:
    """Extract structured fields from a Qwen indexing summary.

    Section labels come from _PLAN_INDEX_PROMPT. Tolerant to minor label
    drift ('SHEET ID', 'Sheet_Id', 'Sheet ID:'). Unmatched sections get None.
    """
    out = {
        "sheet_number":  None,
        "sheet_title":   None,
        "discipline":    None,
        "floor":         None,
        "spaces":        None,
        "dimensions":    None,
        "materials":     None,
        "code_refs":     None,
        "detail_refs":   None,
        "notes":         None,
    }
    if not text:
        return out
    label_map = {
        "SHEET_ID":                  "sheet_number",
        "SHEETID":                   "sheet_number",
        "SHEET_TITLE":               "sheet_title",
        "SHEETTITLE":                "sheet_title",
        "DISCIPLINE":                "discipline",
        "FLOOR":                     "floor",
        "FLOOR_OR_LEVEL":            "floor",
        "SPACES_AND_ROOMS":          "spaces",
        "SPACES":                    "spaces",
        "DIMENSIONS":                "dimensions",
        "MATERIALS_AND_SPECS":       "materials",
        "MATERIALS":                 "materials",
        "CODE_REFS":                 "code_refs",
        "CODE_REFERENCES":           "code_refs",
        "DETAIL_AND_SECTION_REFS":   "detail_refs",
        "DETAIL_REFS":               "detail_refs",
        "DETAILS":                   "detail_refs",
        "NOTES":                     "notes",
    }
    # Split on label: at start of line. Use a tolerant regex that accepts
    # "Sheet ID:", "SHEET_ID:", "Sheet_Id -", etc.
    # Strategy: find all (label_norm, value) pairs by scanning for labeled
    # sections anchored at line starts.
    lines = text.splitlines()
    current_key = None
    current_buf: list = []
    def _flush():
        nonlocal current_key, current_buf
        if current_key and current_buf:
            val = "\n".join(current_buf).strip(" \t:-\n")
            if val and val.upper() != "NONE":
                out[current_key] = val
        current_key = None
        current_buf = []
    for raw in lines:
        line = raw.strip()
        if not line:
            if current_key:
                current_buf.append("")
            continue
        m = re.match(r"^[*_\-\s]*([A-Za-z][A-Za-z _\-]+?)\s*[:\-–]\s*(.*)$", line)
        if m:
            label_raw = re.sub(r"[^A-Za-z]", "_", m.group(1).strip().upper()).strip("_")
            label_norm = re.sub(r"__+", "_", label_raw)
            if label_norm in label_map:
                _flush()
                current_key = label_map[label_norm]
                rest = m.group(2).strip(" -:\t")
                current_buf = [rest] if rest else []
                continue
        if current_key:
            current_buf.append(line)
    _flush()
    return out


async def _generate_embedding(text: str) -> Optional[list]:
    """Generate an OpenAI embedding (text-embedding-3-small, 1536 dim).

    Returns None on any failure — callers must tolerate missing embeddings.
    """
    if not OPENAI_API_KEY or not text:
        return None
    # OpenAI caps at 8192 tokens per input; truncate aggressively at char level.
    text = text.strip()[:20000]
    try:
        async with ServerHttpClient(timeout=30.0) as client_http:
            resp = await client_http.post(
                "https://api.openai.com/v1/embeddings",
                headers={
                    "Authorization": f"Bearer {OPENAI_API_KEY}",
                    "Content-Type": "application/json",
                },
                json={"model": "text-embedding-3-small", "input": text},
            )
            if resp.status_code != 200:
                logger.warning(f"embedding API {resp.status_code}: {resp.text[:200]}")
                return None
            data = resp.json()
            return data["data"][0]["embedding"]
    except Exception as e:
        logger.warning(f"embedding failed: {e}")
        return None


async def _upload_page_jpeg_to_r2(project_id: str, file_id: str,
                                    page_number: int, jpeg_bytes: bytes) -> str:
    """Store a per-page rendered JPEG to R2 at
    `plans/{project_id}/{file_id}/page_{N}.jpg` and return the key."""
    r2_key = f"plans/{project_id}/{file_id}/page_{page_number}.jpg"
    try:
        await asyncio.to_thread(
            _upload_to_r2, jpeg_bytes, r2_key, "image/jpeg"
        )
        return r2_key
    except Exception as e:
        logger.warning(f"page jpeg upload failed {r2_key}: {e}")
        return ""


# ── THE SHEET, SMALL ENOUGH TO PUT IN A LIST ────────────────────────────────
#
# THE PLAN LIST SHOWS A BLANK DOCUMENT ICON, so the only way to find out which
# sheet a row is is to open it — and opening costs the CP 20-30 seconds. A
# thumbnail is the cheapest possible fix for that, and the pixels for it have
# existed all along: the indexer already renders every page at 250 DPI and
# stores it in R2 for the VLM. Nothing has ever served one to a phone.
#
# 400px LONG EDGE / QUALITY 80, taken from lib/photo_enhance (THUMB_MAX_EDGE,
# THUMB_QUALITY) rather than picked afresh. The app already renders 400px
# thumbnails for logbook photos through that path; a second, slightly different
# thumbnail convention is two conventions to keep in step.
#
# THIS IS NOT THE VIEWER'S BASE LAYER. A two-layer viewer wants roughly
# viewport width (1200-3000px), not 400 — same 250 DPI original, a different
# derivative. That size is deliberately NOT decided here: it depends on whether
# the viewer keeps rendering PDFs on-device at all, which is an open ruling.
_PLAN_THUMB_MAX_EDGE = 400
_PLAN_THUMB_QUALITY = 80

# ── THE VIEWER'S BASE LAYER ─────────────────────────────────────────────────
#
# THE SECOND DERIVATIVE OF THE SAME ORIGINAL, and the reason the two are
# defined together: one pipeline, two outputs, and a change to the 250 DPI
# source moves both.
#
# 2048 ON THE LONG EDGE, ruled by the operator. At fit-to-width on a ~1000 CSS
# px tablet the sheet occupies roughly 2000 device pixels, so 2048 is sharp
# rather than soft — and that matters more than it sounds, because if pdf.js
# takes twenty seconds this is not a flash before the real render. It IS what
# the CP is looking at for twenty seconds.
#
# EVERY PAGE, unlike the thumbnail. The thumbnail identifies a FILE in a list,
# so page one is the whole job. The base layer is what sits under the sharp
# render of whatever page he is on, so a set is only covered if every sheet has
# one. ~150-250 KB per sheet, ~25 MB for a hundred-sheet set.
_PLAN_BASE_MAX_EDGE = 2048
_PLAN_BASE_QUALITY = 80


def _downscale_page_jpeg(jpeg_bytes: bytes, max_edge: int,
                         quality: int) -> Optional[bytes]:
    """Downscale an already-rendered page JPEG.

    FROM THE RENDERED PAGE, NOT FROM THE PDF. The expensive step — poppler
    rasterising a 36x48 sheet at 250 DPI — has already happened by the time
    this is called, and re-rendering to get a smaller copy would pay it twice.
    This is a resize of bytes already in hand.

    Returns None on any failure. Both callers treat a missing derivative as
    "fall back to what the screen already does", so this must never be able to
    fail an import.
    """
    if not jpeg_bytes:
        return None
    try:
        from PIL import Image
        import io as _io
        img = Image.open(_io.BytesIO(jpeg_bytes))
        # DECODE SMALL. draft() lets the JPEG decoder scale by 1/2, 1/4 or 1/8
        # while decoding, so a 400px thumbnail of a 9000px page never builds
        # the full 162 MB raster first.
        try:
            img.draft("RGB", (max_edge, max_edge))
        except Exception:
            pass
        img.load()
        if img.mode not in ("RGB", "L"):
            img = img.convert("RGB")
        w, h = img.size
        longest = max(w, h)
        if longest > max_edge:
            ratio = max_edge / float(longest)
            img = img.resize(
                (max(1, int(w * ratio)), max(1, int(h * ratio))),
                Image.LANCZOS,
            )
        buf = _io.BytesIO()
        img.save(buf, format="JPEG", quality=quality, optimize=True)
        return buf.getvalue()
    except Exception as e:
        logger.warning(f"page downscale to {max_edge}px failed: {e}")
        return None


def _make_page_thumb_jpeg(jpeg_bytes: bytes) -> Optional[bytes]:
    """The list thumbnail: 400px long edge."""
    return _downscale_page_jpeg(
        jpeg_bytes, _PLAN_THUMB_MAX_EDGE, _PLAN_THUMB_QUALITY)


def _make_page_base_jpeg(jpeg_bytes: bytes) -> Optional[bytes]:
    """The viewer's base layer: 2048px long edge."""
    return _downscale_page_jpeg(
        jpeg_bytes, _PLAN_BASE_MAX_EDGE, _PLAN_BASE_QUALITY)


async def _upload_page_thumb_to_r2(project_id: str, file_id: str,
                                   page_number: int, jpeg_bytes: bytes) -> str:
    """Store the list thumbnail at `plans/{project_id}/{file_id}/page_{N}_thumb.jpg`.

    Same prefix as the full page deliberately: one plan's derivatives live
    together, so a project purge that sweeps `plans/{project_id}/` takes the
    thumbnails with it rather than orphaning them in a second location.
    """
    thumb = await asyncio.to_thread(_make_page_thumb_jpeg, jpeg_bytes)
    if not thumb:
        return ""
    r2_key = f"plans/{project_id}/{file_id}/page_{page_number}_thumb.jpg"
    try:
        await asyncio.to_thread(_upload_to_r2, thumb, r2_key, "image/jpeg")
        return r2_key
    except Exception as e:
        logger.warning(f"page thumb upload failed {r2_key}: {e}")
        return ""


async def _upload_page_base_to_r2(project_id: str, file_id: str,
                                  page_number: int, jpeg_bytes: bytes) -> str:
    """Store the viewer base layer at `plans/{project}/{file}/page_{N}_base.jpg`.

    Same prefix as the full page and the thumbnail, for the same reason: one
    plan's derivatives live together, so a project purge that sweeps
    `plans/{project_id}/` takes all three rather than orphaning two of them.
    """
    base = await asyncio.to_thread(_make_page_base_jpeg, jpeg_bytes)
    if not base:
        return ""
    r2_key = f"plans/{project_id}/{file_id}/page_{page_number}_base.jpg"
    try:
        await asyncio.to_thread(_upload_to_r2, base, r2_key, "image/jpeg")
        return r2_key
    except Exception as e:
        logger.warning(f"page base upload failed {r2_key}: {e}")
        return ""


def _is_sheet_number_query(s: str) -> bool:
    """Heuristic: does this token look like a sheet id (A-301, ME-401)?"""
    if not s:
        return False
    s = s.strip().upper()
    return bool(re.match(r"^[A-Z]{1,3}-?\d{1,4}[A-Z]?$", s))


# ── INDEX VERSION 3, AND WHY THE SKIP THRESHOLD DID NOT MOVE WITH IT ──────
#
# Version 2 made one Qwen call per page with a 1500-token cap, and on
# 6a5f63bc147407d3261df2c7 the model looped on DIMENSIONS until the cap and
# every section after it came back null. Version 3 reads the PDF text layer as
# the authority, runs four bounded section calls, and stores the structure
# (lib/plan_extract.py).
#
# The writer is version 3. The "already indexed, skip" check still accepts 2.
# Raising it would re-index every customer's every plan on their next Dropbox
# sync — four vision calls a page, unasked. A project moves to 3 when a file is
# uploaded, or when someone runs reindex-document / reindex-all on it, and the
# re-index of 6a5f63bc147407d3261df2c7 is exactly that explicit call.
PLAN_INDEX_VERSION = plan_extract.EXTRACTION_VERSION
PLAN_INDEX_SKIP_MIN_VERSION = 2

# Textract's synchronous call refuses an image over 10,000 px on a side or
# 10 MB. A 36-inch sheet at 300 DPI is 10,800 px, so every page is brought
# under both before it is sent.
_OCR_MAX_EDGE = 9500
_OCR_MAX_BYTES = 9_500_000


def _ocr_configured() -> bool:
    """Textract needs AWS credentials, which are not R2's. Absent them the page
    is indexed from the image alone and flagged — it is never an error."""
    return bool(_BOTO3_AVAILABLE and os.environ.get("AWS_ACCESS_KEY_ID")
                and os.environ.get("AWS_SECRET_ACCESS_KEY"))


def _textract_lines(jpeg_bytes: bytes) -> str:
    img = _downscale_page_jpeg(jpeg_bytes, _OCR_MAX_EDGE, 80) or jpeg_bytes
    if len(img) > _OCR_MAX_BYTES:
        img = _downscale_page_jpeg(jpeg_bytes, 6000, 75) or img
    client = boto3.client(
        "textract", region_name=os.environ.get("AWS_REGION") or "us-east-1")
    resp = client.detect_document_text(Document={"Bytes": img})
    return "\n".join(b.get("Text", "") for b in resp.get("Blocks", [])
                     if b.get("BlockType") == "LINE")


async def _ocr_page_text(project_id: str, jpeg_bytes: bytes) -> Tuple[str, Optional[str]]:
    """(text, flag). Called only for a page whose text layer is too thin to be
    a CAD export — a scan. Metered before the call, like every paid call."""
    if not _ocr_configured():
        return "", "ocr_not_configured"
    await record_vision_call(db, endpoint=VISION_PLAN_INDEX_OCR, project_id=project_id)
    try:
        return (await asyncio.to_thread(_textract_lines, jpeg_bytes)) or "", None
    except Exception as e:
        logger.warning(f"textract failed for project {project_id}: {e!r}")
        return "", f"ocr_failed:{type(e).__name__}"


PLAN_RECORDS = "plan_records"


async def _write_page_records(*, project_id: str, company_id: str, file_id: str,
                              file_hash: str, page_number: int, fields: dict,
                              boilerplate, page_id: str, discipline=None,
                              file_name=None, raw_text: str = "",
                              title_text: str = "") -> int:
    """Replace this page's typed records.

    ── WHY THESE EXIST BESIDE THE CHUNKS, FOR NOW ─────────────────────────
    #
    # document_page_chunks stores strings, and every fix for "the letters did
    # not line up" has widened the match. Records store what the sheet says
    # with HOW WE CAME TO KNOW IT, so retrieval can rank evidence before
    # similarity and an answer can point at the region it came from.
    #
    # The chunk writer stays until search_plans reads records and the eval
    # says the records answer better. Two writers is the transition, not the
    # destination: the chunks go when the reader does.
    """
    await db[PLAN_RECORDS].delete_many({"file_id": file_id, "page_number": page_number})
    authority = plan_records.page_authority(raw_text, title_text, file_name or "")
    page_ctx = {
        "project_id": project_id, "company_id": company_id,
        "file_id": file_id, "file_hash": file_hash, "file_name": file_name,
        "page_id": page_id, "page_number": page_number,
        "sheet_number": fields.get("sheet_number"),
        "sheet_title": fields.get("sheet_title"),
        "discipline": discipline or fields.get("discipline"),
        "floors": fields.get("floors") or [],
        # Read off the title block. approval_status is deliberately absent:
        # it changes without the drawing changing, so dob_logs is the join.
        **authority,
        "index_version": PLAN_INDEX_VERSION,
    }
    try:
        records = plan_records.build_records(
            fields, page=page_ctx, raw_text=raw_text, boilerplate=boilerplate)
    except Exception as e:
        logger.exception("record build failed %s p%s: %r", file_name, page_number, e)
        return 0
    if not records:
        return 0
    now = datetime.now(timezone.utc)
    for r in records:
        r["created_at"] = now
    try:
        await db[PLAN_RECORDS].insert_many(records)
    except Exception as e:
        logger.exception("record write failed %s p%s: %r", file_name, page_number, e)
        return 0
    return len(records)


async def _write_page_chunks(*, project_id: str, company_id: str, file_id: str,
                             file_hash: str, page_number: int, fields: dict,
                             boilerplate, discipline: Optional[str] = None,
                             file_name: Optional[str] = None) -> int:
    """Replace this page's chunks AND its typed records.

    One call site, deliberately: records and chunks describe the same page and
    must not be able to disagree about which pages exist."""
    page = await db.document_page_index.find_one(
        {"file_id": file_id, "page_number": page_number}, {"_id": 1, "raw_text": 1})
    await db.document_page_chunks.delete_many(
        {"file_id": file_id, "page_number": page_number})
    if not page:
        return 0
    try:
        await _write_page_records(
            project_id=project_id, company_id=company_id, file_id=file_id,
            file_hash=file_hash, page_number=page_number, fields=fields,
            boilerplate=boilerplate, page_id=str(page["_id"]),
            discipline=discipline, file_name=file_name,
            raw_text=page.get("raw_text") or "")
    except Exception as e:
        # Never fail the page over the new writer while the old one is what
        # answers questions.
        logger.exception("typed records failed %s p%s: %r", file_name, page_number, e)
    chunks = plan_extract.build_chunks(fields, boilerplate)
    if not chunks:
        return 0
    embeddings = await asyncio.gather(
        *[_generate_embedding(c["text"][:8000]) for c in chunks],
        return_exceptions=True)
    now = datetime.now(timezone.utc)
    docs = []
    for c, emb in zip(chunks, embeddings):
        docs.append({
            "project_id": project_id, "company_id": company_id,
            "file_id": file_id, "file_hash": file_hash,
            "page_id": str(page["_id"]), "page_number": page_number,
            "sheet_number": fields.get("sheet_number"),
            "sheet_title": fields.get("sheet_title"),
            # SO A RECORD CAN ALWAYS SAY WHERE IT IS. A page whose sheet number
            # could not be read still has a file and a page, and an answer that
            # cites "? (text): CONC. WALL" names nothing anyone can open.
            "file_name": file_name,
            # THE SAME MARK MEANS DIFFERENT THINGS IN DIFFERENT SETS. On 588
            # Boyland 'S' is the sanitary stack on five plumbing sheets, the
            # storm stack on two, and a smoke detector on one architectural
            # sheet. All three readings are correct. A record carries the
            # discipline it was read in so nothing downstream can merge them
            # into one project-wide meaning.
            "discipline": discipline or fields.get("discipline"),
            "chunk_type": c["chunk_type"], "ordinal": c["ordinal"],
            "text": c["text"], "payload": c["payload"],
            "embedding": emb if isinstance(emb, list) else None,
            "index_version": PLAN_INDEX_VERSION, "created_at": now,
        })
    await db.document_page_chunks.insert_many(docs)
    return len(docs)


# ── THE PLAN INDEX'S TIME CEILING ─────────────────────────────────────────
# See the block above `_section_call` for why a per-call timeout was never a
# page budget and what the unbounded worst case was.
PLAN_INDEX_CALL_TIMEOUT = 180.0       # one section, unchanged
PLAN_INDEX_PAGE_BUDGET = 300.0        # every call on one page, together
PLAN_INDEX_MIN_CALL_SECONDS = 20.0    # below this, refuse rather than send


class BudgetExhausted(RuntimeError):
    """The page ran out of time before this section was sent.

    ITS OWN TYPE BECAUSE plan_extract RECORDS THE TYPE NAME. The section's flag
    reads `call_failed:BudgetExhausted`, which says we stopped — distinct from
    `call_failed:ReadTimeout`, which says the provider did.
    """


# At most this many grids per page get OCR'd. M-200.00, the densest schedule
# sheet in the corpus, has seven. A page claiming twenty is a page where grid
# detection has gone wrong, and the cost of finding out is a render each.
PLAN_OCR_MAX_GRIDS = 12


async def _ocr_blind_grids(pdf_path: Optional[str], page_number: int,
                           layout: Optional[dict], file_name: str
                           ) -> Tuple[List[dict], List[str]]:
    """(schedules, flags) for the ruled grids this page's text layer cannot read.

    ── WHY THIS RUNS ON SOME GRIDS AND NOT EVERY PAGE ─────────────────────
    #
    # Measured 2026-09-16 on the 588 Boyland sets: 15 of 56 schedule-shaped
    # grids hand the text layer zero characters, because the mechanical
    # engineer exports with text converted to curves. OCR of those 15 grids is
    # about two minutes for the whole corpus. OCR of every page, tiled, is
    # 112 seconds PER PAGE — three and a half hours per re-index to re-read
    # text we already have exactly.
    #
    # `layout["ocr_grids"]` is already only the grids with zero characters
    # inside them, and that test is deterministic: ruling lines and a character
    # count, no model and no threshold on how confident anything feels.
    """
    grids = (layout or {}).get("ocr_grids") or []
    if not grids:
        return [], []
    if not plan_ocr.available():
        return [], [f"ocr_engine_absent:{plan_ocr.why_unavailable()[:60]}"]
    if not pdf_path:
        return [], ["ocr_no_pdf_path"]
    out: List[dict] = []
    flags: List[str] = []
    for g in grids[:PLAN_OCR_MAX_GRIDS]:
        ok, why = plan_ocr.grid_is_readable(g)
        if not ok:
            flags.append(f"ocr_grid_skipped:{why}")
            continue
        png = await asyncio.to_thread(
            _render_pdf_crop, pdf_path, page_number, g["bbox"], plan_ocr.OCR_DPI)
        if not png:
            flags.append("ocr_render_failed")
            continue
        sched = await asyncio.to_thread(plan_ocr.read_grid, png, g)
        if sched:
            out.append(sched)
    if len(grids) > PLAN_OCR_MAX_GRIDS:
        flags.append(f"ocr_grids_capped:{len(grids)}")
    if out:
        logger.info(
            f"plan OCR {file_name} p{page_number}: {len(out)} of {len(grids)} "
            f"blind grids read, rows={[len(s.get('rows') or []) for s in out]}")
    return out, flags


async def _index_single_page(
    *,
    project_id: str,
    company_id: str,
    file_id: str,
    file_name: str,
    file_hash: str,
    page_number: int,
    discipline: str,
    page_text: str,
    page_image_bytes: Optional[bytes],
    boilerplate=frozenset(),
    layout: Optional[dict] = None,
    tag_vocab=None,
    drawing_index: Optional[dict] = None,
    pdf_path: Optional[str] = None,
):
    """Index one page: text layer + sectioned Qwen extraction + chunks + R2 JPEG.

    Extractable-text length is used as a rough gate for SPEC-only pages
    (walls-of-text with no drawing). Architectural drawings have long
    title blocks + keynote lists that can push text past 1000 chars
    while still being primarily VISUAL, so the threshold has to be set
    high enough to let those through. We also require the text to look
    paragraph-style (long lines) rather than labels-and-dimensions-style
    (short fragments).
    """
    now = datetime.now(timezone.utc)
    base_doc = {
        "project_id":    project_id,
        "company_id":    company_id,
        "file_id":       file_id,
        "file_name":     file_name,
        "file_hash":     file_hash,
        "discipline":    discipline,
        "page_number":   page_number,
        "indexed_at":    now,
        "index_version": PLAN_INDEX_VERSION,
        # Set by _supersede_plan_pages after the whole file is in. Cleared on
        # every write so a re-index never inherits a stale verdict.
        "superseded_by": None,
        # True only once the row AND its chunks are written. The resume guard
        # in _index_pdf_file redoes any page without it.
        "page_complete": False,
    }

    # Spec-sheet detection: must be BOTH long (>5000 chars — a drawing with
    # annotations rarely gets that high) AND paragraph-style (avg non-empty
    # line length ≥40 chars). Architectural drawings have many short labels
    # and fail the second check even when they have lots of keynote text.
    stripped = (page_text or "").strip()
    is_spec = False
    if len(stripped) > 5000:
        lines = [ln.strip() for ln in stripped.splitlines() if ln.strip()]
        if lines:
            avg_len = sum(len(ln) for ln in lines) / len(lines)
            is_spec = avg_len >= 40
    if is_spec:
        doc = dict(base_doc)
        doc.update({
            "sheet_number":       None,
            "sheet_title":        "[SPECIFICATION PAGE]",
            "floor":              None,
            "keywords":           [],
            "summary":            "",
            "spaces":             None,
            "dimensions":         None,
            "materials":          None,
            "code_refs":          None,
            "detail_refs":        None,
            "notes":              None,
            "embedding":          None,
            "page_jpeg_r2_key":   "",
            "page_thumb_r2_key":  "",
            "page_base_r2_key":   "",
            "is_spec_page":       True,
            "page_complete":      True,
        })
        # A SPEC PAGE IS STILL A SHEET. S-001.00 — 25,000 characters of general
        # notes — is exactly this shape, and "HELICAL PILES" is on it. From the
        # text layer it gets, with no model call:
        #   its chunks, for count / existence / attribute answers
        #   the searchable fields, so the debug view and the literal element
        #     search see its notes instead of "[SPECIFICATION PAGE]"
        #   its page image, so "show me S-001" can send the sheet
        # The broad candidate search still skips it (is_spec_page); lookup by
        # sheet number does not.
        spec_fields = None
        if layout:
            spec_fields = dict(plan_extract.EMPTY_FIELDS)
            spec_fields.update(plan_text.fields_from_layout(
                layout, boilerplate, tag_vocab or plan_text.SEED_TAGS))
            _spec_title = plan_text.title_region(layout)
            spec_fields["sheet_number"], _ = plan_text.validate_sheet_number(
                None, plan_text.sheet_ids(_spec_title),
                plan_text.sheet_ids(layout.get("text") or ""),
                drawing_index, plan_text.sheet_position(_spec_title), _spec_title)
            spec_fields["sheet_position"] = list(
                plan_text.sheet_position(_spec_title) or ()) or None
            heading_text = plan_text.headings(layout)
            spec_fields["sheet_type"] = "notes"
            spec_fields["contents_summary"] = (
                "Notes and specification sheet: " + "; ".join(heading_text.split("\n")[:20])
                if heading_text else None)
            spec_legacy = plan_extract.legacy_fields(spec_fields)
            spec_jpeg = spec_thumb = spec_base = ""
            if page_image_bytes:
                spec_jpeg = await _upload_page_jpeg_to_r2(
                    project_id, file_id, page_number, page_image_bytes)
                # Page one only, like the main path's thumbnail — written as an
                # expression so the main path's `if page_number == 1:` guard stays
                # the one test_plan_thumbnails reads.
                spec_thumb = (await _upload_page_thumb_to_r2(
                    project_id, file_id, page_number, page_image_bytes)
                    if page_number == 1 else "")
                spec_base = await _upload_page_base_to_r2(
                    project_id, file_id, page_number, page_image_bytes)
            doc.update({
                "sheet_number":     spec_fields["sheet_number"],
                "sheet_position":   spec_fields["sheet_position"],
                "is_document":      bool(spec_fields["sheet_number"]) and not
                                    plan_text.looks_like_a_sheet_number(
                                        spec_fields["sheet_number"]),
                "sheet_title":      None,
                "sheet_type":       "notes",
                "keywords":         spec_legacy["keywords"],
                "summary":          spec_legacy["summary"],
                "dimensions":       spec_legacy["dimensions"],
                "materials":        spec_legacy["materials"],
                "code_refs":        spec_legacy["code_refs"],
                "detail_refs":      spec_legacy["detail_refs"],
                "notes":            spec_legacy["notes"],
                "page_jpeg_r2_key": spec_jpeg,
                "page_thumb_r2_key": spec_thumb,
                "page_base_r2_key": spec_base,
                "extraction":       spec_fields,
                "tag_counts":       spec_fields["tag_counts"],
                "text_source":      "vector",
                "raw_text":         (layout.get("text") or "")[:plan_extract.RAW_CAP],
                "vlm_calls":        0,
            })
        await db.document_page_index.update_one(
            {"file_id": file_id, "page_number": page_number},
            {"$set": doc},
            upsert=True,
        )
        if spec_fields:
            try:
                await _write_page_chunks(
                    project_id=project_id, company_id=company_id, file_id=file_id,
                    file_hash=file_hash, page_number=page_number, fields=spec_fields,
                    boilerplate=boilerplate, discipline=discipline, file_name=file_name,
                )
            except Exception as e:
                logger.exception("spec page chunks failed %s p%s: %r", file_name, page_number, e)
                await db.document_page_index.update_one(
                    {"file_id": file_id, "page_number": page_number},
                    {"$set": {"page_complete": False}})
        return

    if not page_image_bytes:
        doc = dict(base_doc)
        doc.update({
            "sheet_number":       None,
            "sheet_title":        None,
            "floor":              None,
            "keywords":           [],
            "summary":            "",
            "embedding":          None,
            "page_jpeg_r2_key":   "",
            "page_thumb_r2_key":  "",
            "page_base_r2_key":   "",
            "is_spec_page":       False,
            # NOT complete. No image means the render failed; a page written
            # complete here would be skipped by every resume and never sent
            # to the vision model at all.
            "page_complete":      False,
            "render_failed":      True,
        })
        await db.document_page_index.update_one(
            {"file_id": file_id, "page_number": page_number},
            {"$set": doc},
            upsert=True,
        )
        return

    # 1. Upload per-page JPEG to R2 (used at query time so we don't re-render).
    page_jpeg_r2_key = await _upload_page_jpeg_to_r2(
        project_id, file_id, page_number, page_image_bytes
    )

    # 1b. PAGE ONE ONLY. The list needs one image per FILE, not per page, and
    # a thumbnail for sheet 147 of a 200-sheet set is storage nobody reads.
    # Written here because this is the one moment the rendered pixels exist in
    # memory — anywhere later and it is a second 250 DPI rasterise.
    page_thumb_r2_key = ""
    if page_number == 1:
        page_thumb_r2_key = await _upload_page_thumb_to_r2(
            project_id, file_id, page_number, page_image_bytes
        )

    # 1c. THE VIEWER'S BASE LAYER — EVERY PAGE, not just the first. It sits
    # under the sharp render of whatever sheet the CP is on, so a set is only
    # covered when every sheet has one. Written here for the same reason as the
    # thumbnail: this is the one moment the 250 DPI pixels exist in memory.
    page_base_r2_key = await _upload_page_base_to_r2(
        project_id, file_id, page_number, page_image_bytes
    )

    # 2. The words on the page. A CAD export carries them exactly in its text
    # layer; a scan carries next to none, and only then is the page OCR'd.
    text_flags = []
    # A VECTOR PAGE READS ITS OWN TEXT LAYER, rebuilt at span level so stacked
    # fractions survive. Scanned pages (no layer worth the name) keep OCR and
    # the full vision path below.
    vector_layout = None
    if layout and plan_extract.classify_text_source(layout.get("text")) == "vector":
        vector_layout = layout
        page_text = layout.get("text") or ""
    text_source = "vector" if vector_layout else plan_extract.classify_text_source(page_text)
    if text_source == "sparse":
        ocr_text, ocr_flag = await _ocr_page_text(project_id, page_image_bytes)
        if ocr_flag:
            text_flags.append(ocr_flag)
        if ocr_text.strip():
            page_text, text_source = ocr_text, "ocr"
        else:
            text_source = "none" if not (page_text or "").strip() else "sparse"

    # 3. Four section calls — title block, schedules, notes, elements — each
    # with its own token budget, so a loop in one cannot null the others.
    #
    # COUNTED PER CALL, WHICH IS THE UNIT THAT SPENDS. Four per page now, and
    # a per-upload count would report a forty-sheet set as 1. Counted before the
    # post for the reason the meter's own docstring gives: a call that errors
    # after the provider has billed it is still spend.
    # ── THE 180 s WAS A PAGE BUDGET APPLIED PER CALL ───────────────────────
    #
    # The comment below this line has always read "180s: measured 165-225s for
    # a FOUR-CALL PAGE" — a budget for the whole page. It is passed as the
    # timeout of EACH call, so the page's real ceiling is 180 s x the number of
    # calls the extractor decides to make, and nothing anywhere bounded that:
    #
    #   raster path (extract_page)          5 sections  -> 900 s per page
    #   vector path (extract_vector_page)   1 call           180 s per page
    #     + PR #547's notes fallback        +1 call     -> 360 s per page
    #
    # A 44-sheet set on the vector path is a 4.4-hour worst case, and #547 did
    # not introduce that — it doubled an exposure that had no ceiling to begin
    # with. On the unbounded-tail model that ran 09-11 to 09-15, every one of
    # those windows would have been spent in full.
    #
    # PLAN_INDEX_PAGE_BUDGET IS THE CEILING THE COMMENT ALREADY CLAIMED: 300 s
    # for the whole page, generous against the measured 165-225 s four-call
    # page, shared by every call the extractor makes. Each call still gets up
    # to 180 s, clamped to what the page has left. When the budget is gone the
    # call is refused rather than sent doomed — plan_extract records that as
    # `call_failed:BudgetExhausted` on the section and keeps the rest of the
    # page, which is the same degrade path a provider error already takes.
    _page_deadline = _time.monotonic() + PLAN_INDEX_PAGE_BUDGET

    async def _section_call(image_b64: str, prompt: str, max_tokens: int):
        remaining = _page_deadline - _time.monotonic()
        if remaining < PLAN_INDEX_MIN_CALL_SECONDS:
            logger.warning(
                "[plan-index] page budget exhausted for %s p%s "
                "(%.0fs spent, %.1fs left) — section refused",
                file_name, page_number, PLAN_INDEX_PAGE_BUDGET, remaining,
            )
            raise BudgetExhausted(
                f"plan index page budget of {PLAN_INDEX_PAGE_BUDGET:.0f}s exhausted"
            )
        call_timeout = min(PLAN_INDEX_CALL_TIMEOUT, remaining)

        await record_vision_call(
            db, endpoint=VISION_PLAN_INDEX_PAGE, project_id=project_id,
        )
        # 180s: measured 165-225s for a four-call page on the production model,
        # and a 90s cap timed out the schedules call on S-001.00. Now a cap on
        # the call AND on the page, per the block above.
        try:
            async with ServerHttpClient(timeout=call_timeout) as client_http:
                resp = await client_http.post(
                    f"{QWEN_API_BASE}/chat/completions",
                    headers={
                        "Authorization": f"Bearer {QWEN_API_KEY}",
                        "Content-Type": "application/json",
                    },
                    json={
                        "model":       QWEN_MODEL,
                        "max_tokens":  max_tokens,
                        "temperature": 0,
                        "messages": [{
                            "role": "user",
                            "content": [
                                {"type": "image_url",
                                 "image_url": {"url": f"data:image/jpeg;base64,{image_b64}"}},
                                {"type": "text", "text": prompt},
                            ],
                        }],
                    },
                )
        except Exception as call_exc:
            # SITE 2 OF 5. plan_extract catches this and records
            # `call_failed:<TypeName>` on the section — a flag, not a log, and
            # a flag cannot carry a traceback or the model id. On a ReadTimeout
            # the row said `call_failed:ReadTimeout` and the log said nothing
            # at all, so a page that quietly indexed with no notes looked
            # identical to one the model had nothing to say about.
            logger.exception(
                "[plan-index] vision call failed for %s p%s: %r "
                "(model=%s timeout=%.0fs)",
                file_name, page_number, call_exc, QWEN_MODEL, call_timeout,
            )
            raise
        if resp.status_code != 200:
            logger.warning(
                f"Qwen index returned {resp.status_code} for "
                f"{file_name} page {page_number} [model={QWEN_MODEL}]"
            )
            raise RuntimeError(f"qwen status {resp.status_code}")
        choice = resp.json()["choices"][0]
        return (choice["message"].get("content") or ""), choice.get("finish_reason")

    if vector_layout is not None:
        # One call: title block, sheet type, summary. Everything else is text.
        result = await plan_extract.extract_vector_page(
            image_b64=base64.b64encode(page_image_bytes).decode("ascii"),
            layout=vector_layout,
            vlm_call=_section_call,
            boilerplate=boilerplate,
            tag_vocab=tag_vocab,
            drawing_index=drawing_index,
        )
    else:
        result = await plan_extract.extract_page(
            image_b64=base64.b64encode(page_image_bytes).decode("ascii"),
            page_text=page_text or "",
            vlm_call=_section_call,
            boilerplate=boilerplate,
        )
    fields = result["fields"]

    # 3b. THE SCHEDULES THE TEXT LAYER CANNOT READ. A grid whose ruling lines
    # are printed and whose cells contain no characters is a schedule drawn as
    # artwork — not a scan, a CAD export with text converted to curves. It is
    # read here, tiered as ocr_grid_cell, and never mistaken for a cell the
    # text layer handed over.
    # A legend row whose glyph could not be lifted unambiguously says so here
    # rather than nowhere: a refused template is a real gap in what this sheet
    # can be asked, and it is the recall cost of never guessing one.
    text_flags.extend((fields.get("glyph_flags") or [])[:6])
    try:
        ocr_scheds, ocr_flags = await _ocr_blind_grids(
            pdf_path, page_number, layout, file_name)
        text_flags.extend(ocr_flags)
        if ocr_scheds:
            fields["schedules"] = list(fields.get("schedules") or []) + ocr_scheds
            # Elements are derived FROM the schedules, so they are rebuilt
            # rather than appended to: an OCR'd quantity has to reach the
            # element list with `ocr_schedule_qty` as its basis, and a mark
            # that now has a quantity must stop saying "not stated".
            #
            # The glyph counts are NOT derived from schedules and survive the
            # rebuild. Dropping them here would silently undo the whole
            # symbol pass on exactly the sheets that also carry schedules.
            drawn = [e for e in (fields.get("elements") or [])
                     if e.get("count_basis") == "glyph_match"]
            fields["elements"] = plan_text.elements_from_evidence(
                fields.get("legend") or [], fields["schedules"],
                fields.get("tag_counts") or []) + drawn
    except Exception as e:
        # Never fail a page over the new reader.
        logger.warning(f"plan OCR failed {file_name} p{page_number}: {e!r}")

    legacy = plan_extract.legacy_fields(fields)
    bad = {k: v for k, v in result["flags"].items() if v}
    if bad or result["number_flags"]:
        logger.warning(
            f"plan extract flags {file_name} p{page_number} "
            f"sheet={fields.get('sheet_number')} {bad} {result['number_flags']}"
        )

    # 4. Embedding of what the sheet is ABOUT, not of every dimension on it.
    emb_text = plan_extract.embedding_text(fields)
    embedding = await _generate_embedding(emb_text) if emb_text else None

    doc = dict(base_doc)
    doc.update({
        # The version 2 string fields, filled from the structure, so the
        # thirteen readers of this collection keep working unchanged.
        "sheet_number":       legacy["sheet_number"],
        # '16 OF 31' — corroborates two numbers being one sheet. See
        # _supersede_plan_pages.
        "sheet_position":     fields.get("sheet_position"),
        # A DOB form numbered 'Page 2 of 2' and a survey numbered '0' are in
        # the project's files and are not drawings. Their text stays
        # searchable; they are kept out of sheet lookup and out of the sheet
        # index the agent is given, where they read as sheets that exist.
        "is_document":        bool(legacy["sheet_number"]) and not
                              plan_text.looks_like_a_sheet_number(legacy["sheet_number"]),
        "sheet_title":        legacy["sheet_title"],
        "floor":              legacy["floor"],
        "keywords":           legacy["keywords"],
        "summary":            legacy["summary"],
        "spaces":             legacy["spaces"],
        "dimensions":         legacy["dimensions"],
        "materials":          legacy["materials"],
        "code_refs":          legacy["code_refs"],
        "detail_refs":        legacy["detail_refs"],
        "notes":              legacy["notes"],
        # Version 3.
        "sheet_type":         fields.get("sheet_type"),
        "floors":             fields.get("floors") or [],
        "revision":           fields.get("revision"),
        "revision_date":      fields.get("revision_date"),
        "extraction":         fields,
        "extraction_flags":   result["flags"],
        "number_flags":       result["number_flags"],
        "text_source":        text_source,
        "text_flags":         text_flags,
        "text_layer_chars":   len(page_text or ""),
        "raw_text":           (page_text or "")[:plan_extract.RAW_CAP],
        "raw_vlm":            result["raw_vlm"],
        "vlm_calls":          result.get("vlm_calls", len(plan_extract.SECTIONS)),
        # Label counts from the text layer — never a schedule total.
        "tag_counts":         fields.get("tag_counts") or [],
        "embedding":          embedding,
        "page_jpeg_r2_key":   page_jpeg_r2_key,
        "page_thumb_r2_key":  page_thumb_r2_key,
        "page_base_r2_key":   page_base_r2_key,
        "is_spec_page":       False,
    })
    await db.document_page_index.update_one(
        {"file_id": file_id, "page_number": page_number},
        {"$set": doc},
        upsert=True,
    )
    try:
        await _write_page_chunks(
            project_id=project_id, company_id=company_id, file_id=file_id,
            file_hash=file_hash, page_number=page_number, fields=fields,
            boilerplate=boilerplate, discipline=discipline, file_name=file_name,
        )
        await db.document_page_index.update_one(
            {"file_id": file_id, "page_number": page_number},
            {"$set": {"page_complete": True}},
        )
    except Exception as e:
        # The page row stands without its chunks: retrieval falls back to the
        # version 2 path for it. Logged, because a count cannot be answered.
        logger.exception("page chunks failed %s p%s: %r", file_name, page_number, e)


# Minimum rendering DPI for the plan-query pipeline. Construction drawings
# carry dimension callouts and material specs in tiny type; anything lower
# than 250 becomes unreadable by Qwen-VL. 300 for enlarged-detail sheets.
_PLAN_RENDER_DPI = 250
_PLAN_RENDER_DPI_DETAIL = 300


def _render_dpi_for(file_name: str, page_number: int) -> int:
    """Pick the DPI for rendering this page. Detail sheets get a bump."""
    low = (file_name or "").lower()
    if any(tok in low for tok in ("detail", "enlarged", "schedule", "d-")):
        return _PLAN_RENDER_DPI_DETAIL
    return _PLAN_RENDER_DPI


def _pdf_source(pdf) -> Any:
    """A path stays a path; bytes become a stream. Indexing now passes a path
    to a temp file, so a 30 MB set is not held in memory for its whole run."""
    import io as _io
    if isinstance(pdf, (bytes, bytearray)):
        return _io.BytesIO(pdf)
    return str(pdf)


def _pdf_total_pages(pdf) -> int:
    try:
        from pypdf import PdfReader
        return len(PdfReader(_pdf_source(pdf)).pages)
    except Exception:
        try:
            from PyPDF2 import PdfReader as LegacyReader  # type: ignore
            return len(LegacyReader(_pdf_source(pdf)).pages)
        except Exception:
            try:
                from pdf2image.pdf2image import pdfinfo_from_bytes, pdfinfo_from_path
                if isinstance(pdf, (bytes, bytearray)):
                    info = pdfinfo_from_bytes(pdf)
                else:
                    info = pdfinfo_from_path(str(pdf))
                return int(info.get("Pages") or 0)
            except Exception:
                return 0


def _pdf_page_texts(pdf) -> List[str]:
    """Extract text per page. Returns [] if extraction unavailable."""
    try:
        from pypdf import PdfReader
        reader = PdfReader(_pdf_source(pdf))
        return [(p.extract_text() or "") for p in reader.pages]
    except Exception:
        try:
            from PyPDF2 import PdfReader as LegacyReader  # type: ignore
            reader = LegacyReader(_pdf_source(pdf))
            return [(p.extract_text() or "") for p in reader.pages]
        except Exception:
            return []


def _render_pdf_crop(pdf_path: str, page_number: int, bbox, dpi: int) -> Optional[bytes]:
    """One RECTANGLE of one page, as PNG bytes, at high resolution.

    ── WHY A CROP AND NOT THE PAGE ────────────────────────────────────────
    #
    # A schedule has to be read at about 400 dpi before a comma stops being
    # read as a period. The same sheet at 400 dpi whole is 14,400 x 9,600 —
    # over 400 MB of RGB, on the container that already restarted mid-reindex
    # over 250 dpi full pages. The PTAC schedule is 12 x 2 inches.
    #
    # pdf2image cannot crop, so this calls pdftoppm directly with -x -y -W -H.
    # Same binary the rest of the indexer already depends on (poppler_utils is
    # in nixpacks.toml), same doctrine: poppler writes the file, Python reads
    # a few hundred KB back.
    #
    # -x/-y/-W/-H are DEVICE pixels at -r, and the page origin for pdftoppm is
    # the TOP-LEFT — the same origin pdfplumber reports `top` in, which is why
    # the bbox needs no flip.
    """
    import os as _os
    import shutil as _shutil
    import subprocess as _subprocess
    import tempfile as _tempfile
    exe = _shutil.which("pdftoppm")
    if not exe or not pdf_path:
        return None
    try:
        x0, y0, x1, y1 = [float(v) for v in bbox]
    except (TypeError, ValueError):
        return None
    s = dpi / 72.0
    x, y = int(x0 * s), int(y0 * s)
    w, h = int((x1 - x0) * s) + 2, int((y1 - y0) * s) + 2
    if w <= 0 or h <= 0:
        return None
    try:
        with _tempfile.TemporaryDirectory(prefix="plancrop-") as tmp:
            out = _os.path.join(tmp, "crop")
            _subprocess.run(
                [exe, "-r", str(dpi), "-f", str(page_number), "-l", str(page_number),
                 "-x", str(x), "-y", str(y), "-W", str(w), "-H", str(h),
                 "-png", "-singlefile", str(pdf_path), out],
                check=True, capture_output=True, timeout=120)
            with open(out + ".png", "rb") as fh:
                return fh.read()
    except Exception as e:
        logger.warning(f"crop render p{page_number} {bbox} @{dpi} failed: {e}")
        return None


def _render_pdf_page(pdf, page_number: int, dpi: int) -> Optional[bytes]:
    """Render a single PDF page to JPEG bytes.

    ── POPPLER WRITES THE JPEG, PYTHON NEVER HOLDS THE RASTER ──────────────
    #
    # This used to return the page as a PIL image and encode it here. A 36x24
    # sheet at 250 DPI is 9000x6000 pixels: 162 MB of RGB per page, and with
    # three files indexing three pages each that was well over a gigabyte of
    # rasters alive at once on a container that restarted mid-reindex with no
    # crash line. pdftoppm now writes the JPEG straight to a temp directory
    # and only the file's bytes — a few MB — come back.
    """
    import tempfile as _tempfile
    try:
        from pdf2image import convert_from_bytes, convert_from_path
        with _tempfile.TemporaryDirectory(prefix="planpage-") as tmp:
            kw = dict(
                dpi=dpi, first_page=page_number, last_page=page_number,
                fmt="jpeg", jpegopt={"quality": 85, "progressive": False, "optimize": False},
                output_folder=tmp, single_file=True, output_file="page",
                paths_only=True, timeout=300,
            )
            if isinstance(pdf, (bytes, bytearray)):
                paths = convert_from_bytes(pdf, **kw)
            else:
                paths = convert_from_path(str(pdf), **kw)
            if not paths:
                return None
            with open(paths[0], "rb") as fh:
                return fh.read()
    except Exception as e:
        logger.warning(f"render page {page_number} at {dpi} dpi failed: {e}")
        return None


POPPLER_OK = False
POPPLER_DETAIL = "not checked yet"


def _check_poppler() -> Tuple[bool, str]:
    """(ok, detail). Both binaries on PATH, their version, and a valid PDF
    actually rendered."""
    import io as _io
    import shutil as _shutil
    import subprocess as _subprocess
    pdftoppm = _shutil.which("pdftoppm")
    pdfinfo = _shutil.which("pdfinfo")
    if not pdftoppm or not pdfinfo:
        return False, f"not on PATH (pdftoppm={pdftoppm}, pdfinfo={pdfinfo})"
    try:
        out = _subprocess.run([pdftoppm, "-v"], capture_output=True, text=True, timeout=10)
        version = ((out.stderr or out.stdout or "").strip().splitlines() or ["version unknown"])[0]
    except Exception as e:
        version = f"version unknown ({type(e).__name__})"
    try:
        from pypdf import PdfWriter
        from pdf2image import convert_from_bytes
        writer = PdfWriter()
        writer.add_blank_page(width=72, height=72)
        buf = _io.BytesIO()
        writer.write(buf)
        imgs = convert_from_bytes(buf.getvalue(), dpi=10, first_page=1, last_page=1)
        if len(imgs) != 1:
            return False, f"{pdftoppm} ({version}): self-test rendered {len(imgs)} images, expected 1"
    except Exception as e:
        return False, f"{pdftoppm} ({version}): render self-test failed: {e!r}"[:400]
    return True, f"{pdftoppm} ({version}), render self-test passed"


def _pdf_pages_render_and_text(pdf_bytes: bytes, dpi: int = _PLAN_RENDER_DPI,
                                 file_name: str = ""):
    """Generator yielding (page_number, page_text, jpeg_bytes_or_None).

    Renders each page separately to bound memory. DPI may be overridden
    per-page by _render_dpi_for() based on filename heuristics.
    """
    total = _pdf_total_pages(pdf_bytes)
    if total <= 0:
        return
    texts = _pdf_page_texts(pdf_bytes)
    for page_num in range(1, total + 1):
        page_dpi = _render_dpi_for(file_name, page_num)
        jpeg_bytes = _render_pdf_page(pdf_bytes, page_num, page_dpi)
        text = texts[page_num - 1] if page_num - 1 < len(texts) else ""
        yield page_num, text, jpeg_bytes


async def _auto_aggregate_project_model(project_id: str) -> None:
    """Fire-and-forget rebuild of the project's ProjectModel after a file's plan
    indexing completes. Defensive by contract: an aggregation failure is logged
    and swallowed so it can never fail or roll back the upload/indexing that
    triggered it. The aggregator's merge (PR #74) preserves operator-confirmed
    fields and never downgrades confirmed->proposed, so this is safe to fire on
    every upload/re-sync. Deferred import keeps the indexing path independent of
    the app.scheduling package at module load."""
    try:
        from app.scheduling.aggregator import aggregate_project_model
        await aggregate_project_model(db, project_id)
        logger.info(f"Auto-aggregated ProjectModel for project {project_id}")
    except Exception as e:
        logger.warning(
            f"Auto-aggregate ProjectModel failed for project {project_id}: {e!r}"
        )


# ── A COMBINED SET IS NOT INDEXED ─────────────────────────────────────────
#
# See plan_text.combined_set_decision. The status is stored on the file so
# Plans & Files can say why a PDF has no index, instead of looking broken.
COMBINED_SET_SKIPPED = "skipped_combined_set"

# ── A REPORT WE WROTE IS NOT A DRAWING SET ────────────────────────────────
#
# We generate Blueview reports as PDFs. A customer saves one into the Dropbox
# folder their project is synced from, the sync copies it into Plans & Files
# like any other PDF, and the plan indexer reads our own report as if it were
# a drawing set. Measured on 852 East 176th: Blueview_Report_3846_Bailey_Ave_
# 2026-03-10.pdf, two pages, indexed, no sheet number on either — sitting in
# the corpus the concept vocabulary is derived from, and about a different
# building than the project it is filed on.
#
# Skipped by NAME, before the download, because nothing about the file's
# contents would tell us: it is a construction document, and a good one. What
# disqualifies it is that we wrote it.
#
# NOT is_document. That flag says "this page is a form, not a drawing" and
# keeps it searchable, which is right for a DOB filing a superintendent may
# ask about. This is a round trip of our own output, and indexing it teaches
# the index nothing it did not already have.
GENERATED_REPORT_SKIPPED = "skipped_generated_report"
# `\b` would not fire before the underscore in "Blueview_Report_3846":
# both sides are word characters. The test is that "report" is not the start
# of a longer word, so "Reporting" is somebody else's file.
_GENERATED_REPORT_RE = re.compile(r"^\s*blueview[\s_\-]*report(?![A-Za-z])", re.I)


def is_generated_report(name: Optional[str]) -> bool:
    """True for a PDF this system produced, whatever folder it came back in."""
    return bool(_GENERATED_REPORT_RE.match(str(name or "").strip()))
# The queue can reach a combined set before the discipline sets it duplicates
# are indexed. Its job is then put back with a not_before, and the worker moves
# on to the project's other files; the check runs again with the profile the
# job saved. The cap is a runaway guard only — the wait ends when the project
# has no other queued or running jobs.
COMBINED_DEFER_SECONDS = 120
COMBINED_MAX_DEFERRALS = 360


async def _discipline_sets(project_id: str, file_id: str) -> Tuple[Dict[str, List[str]], bool]:
    """({file name: sheet prefixes}, other PDFs still unindexed).

    A discipline set is another live PDF whose index rows mostly carry a real
    sheet number."""
    files = await db.project_files.find(
        {"project_id": project_id, "is_deleted": {"$ne": True},
         "index_status.state": {"$ne": COMBINED_SET_SKIPPED},
         "name": {"$regex": r"\.pdf$", "$options": "i"}},
        {"_id": 1, "name": 1},
    ).to_list(2000)
    others = {str(f["_id"]): (f.get("name") or str(f["_id"])) for f in files
              if str(f["_id"]) != file_id}
    if not others:
        return {}, False
    rows = await db.document_page_index.find(
        {"project_id": project_id, "file_id": {"$in": list(others)}},
        {"file_id": 1, "sheet_number": 1},
    ).to_list(50000)
    by_file: Dict[str, list] = {}
    for r in rows:
        by_file.setdefault(r.get("file_id"), []).append(r.get("sheet_number"))
    sets: Dict[str, List[str]] = {}
    pending = False
    for fid, name in others.items():
        numbers = by_file.get(fid)
        if not numbers:
            pending = True
            continue
        ids = [str(n).upper() for n in numbers
               if n and plan_text.SHEET_ID_RE.fullmatch(str(n).upper())]
        if ids and len(ids) >= 0.5 * len(numbers):
            sets[name] = sorted({i.split("-")[0] for i in ids})
    return sets, pending


async def _combined_set_gate(project_id: str, file_record: dict, file_id: str,
                             profile: dict, deferrals: int = 0,
                             can_defer: bool = False) -> str:
    """"index" | "skipped" | "deferred"."""
    if not plan_text.looks_combined(profile):
        return "index"
    if not (profile.get("text_prefixes") or []):
        # NOTHING TO BE A DUPLICATE OF. A file whose text shows no discipline
        # cannot be proven a copy of anything, however long it waits — its
        # disciplines come from its own pages, not from the other files. On 588
        # Boyland cross connection waited an hour for that proof and then died
        # with the container.
        return "index"
    try:
        sets, _unindexed = await _discipline_sets(project_id, file_id)
        pending = 0
        if can_defer:
            # NOT counted: a job that has itself been deferred. Two combined-
            # looking files that each waited for "the project's other files"
            # waited for each other — the deadlock that left three Boyland
            # files unindexed. Only work that will actually finish counts.
            pending = await db[PLAN_INDEX_JOBS].count_documents({
                "project_id": project_id, "_id": {"$ne": file_id},
                "$or": [{"status": "running"},
                        {"status": "queued", "deferrals": {"$in": [0, None]}}],
            })
    except Exception as e:
        logger.warning(f"combined-set check failed for {file_id}: {e!r} — indexing it")
        return "index"
    decision = plan_text.combined_set_decision(profile, sets)
    name = file_record.get("name") or file_id
    if decision:
        status = dict(decision, state=COMBINED_SET_SKIPPED, at=datetime.now(timezone.utc))
        await db.project_files.update_one(
            {"_id": to_query_id(file_id), "project_id": project_id},
            {"$set": {"index_status": status}},
        )
        logger.info(f"Plan index: {name} skipped as a combined set — {decision['reason']}")
        return "skipped"
    if pending and can_defer and deferrals < COMBINED_MAX_DEFERRALS:
        logger.info(f"Plan index: {name} looks like a combined set; {pending} other file(s) on "
                    f"the project still queued — checking again after them")
        return "deferred"
    return "index"


# ══════════════════════════════════════════════════════════════════════════
# THE PLAN INDEX QUEUE
# ══════════════════════════════════════════════════════════════════════════
#
# Re-indexing 588 Thomas S Boyland St queued 16 files as asyncio tasks. Two
# minutes later the container restarted — no crash line, so most likely out of
# memory — and every one of those tasks went with it. Nothing on disk said
# they had been asked for.
#
# Now a request writes one row per file to plan_index_jobs, and a single worker
# started at boot drains it: one file at a time, three pages at a time. A
# claimed job holds a lease the worker renews while it works; after a restart
# the lease runs out, the new container's worker claims the job again, and the
# page-level resume in _index_pdf_file skips every page already complete.
#
# A file that takes the container down every time it runs must not become a
# restart loop: after PLAN_INDEX_MAX_ATTEMPTS claims it is marked failed.
PLAN_INDEX_JOBS = "plan_index_jobs"
PLAN_INDEX_ACTIVE = ("queued", "running")
PLAN_INDEX_BATCH = 3
PLAN_INDEX_LEASE_SECONDS = 180
PLAN_INDEX_HEARTBEAT_SECONDS = 45
PLAN_INDEX_IDLE_SECONDS = 15
PLAN_INDEX_MAX_ATTEMPTS = 3
_PLAN_INDEX_WORKER_TASK = None


def _as_utc(ts):
    if isinstance(ts, datetime) and ts.tzinfo is None:
        return ts.replace(tzinfo=timezone.utc)
    return ts


async def _enqueue_plan_index(project_id: str, company_id: str, file_record: dict, *,
                              source: str, resume: bool = True) -> str:
    """Queue one file. Idempotent per file. Returns what happened."""
    file_id = str(file_record.get("_id") or file_record.get("id") or "")
    if not file_id:
        return "no_file_id"
    now = datetime.now(timezone.utc)
    jobs = db[PLAN_INDEX_JOBS]
    current = await jobs.find_one({"_id": file_id, "project_id": project_id},
                                  {"status": 1, "lease_until": 1})
    lease = _as_utc((current or {}).get("lease_until"))
    if current and current.get("status") == "running" and lease and lease > now:
        # Already being indexed. Run it again when this pass finishes rather
        # than letting two passes over one file race.
        await jobs.update_one({"_id": file_id, "project_id": project_id},
                              {"$set": {"rerun": True, "rerun_resume": bool(resume),
                                        "updated_at": now}})
        return "rerun_after_current"
    fields = {
        "project_id": project_id, "company_id": company_id,
        "file_name": file_record.get("name"), "status": "queued", "source": source,
        "resume": bool(resume), "not_before": None, "enqueued_at": now, "updated_at": now,
        "error": None, "attempts": 0, "deferrals": 0, "profile": None, "rerun": False,
        "worker": None, "lease_until": None,
    }
    on_insert = {"created_at": now, "pages_total": None}
    if resume:
        on_insert["pages_done"] = 0
    else:
        fields["pages_done"] = 0
    await jobs.update_one({"_id": file_id, "project_id": project_id},
                          {"$set": fields, "$setOnInsert": on_insert}, upsert=True)
    return "queued"


async def _claim_plan_index_job(worker: str) -> Optional[dict]:
    """The oldest runnable job, atomically: queued and due, or running on a
    lease nobody renewed (its worker died with the container)."""
    now = datetime.now(timezone.utc)
    return await db[PLAN_INDEX_JOBS].find_one_and_update(
        {"$or": [
            {"status": "queued", "$or": [{"not_before": None}, {"not_before": {"$lte": now}}]},
            {"status": "running", "lease_until": {"$lt": now}},
        ]},
        {"$set": {"status": "running", "worker": worker, "started_at": now, "updated_at": now,
                  "lease_until": now + timedelta(seconds=PLAN_INDEX_LEASE_SECONDS)},
         "$inc": {"attempts": 1}},
        sort=[("enqueued_at", 1)],
        return_document=_ReturnDocument.AFTER,
    )


async def _plan_job_progress(job: Optional[dict], project_id: str, file_id: str, *,
                             pages_done: Optional[int] = None,
                             pages_total: Optional[int] = None) -> None:
    """Record progress on the job (and the page count on the file). No job —
    a direct call — records nothing."""
    if not job:
        return
    now = datetime.now(timezone.utc)
    fields: Dict[str, Any] = {"updated_at": now}
    if pages_done is not None:
        fields["pages_done"] = int(pages_done)
    if pages_total is not None:
        fields["pages_total"] = int(pages_total)
    try:
        await db[PLAN_INDEX_JOBS].update_one({"_id": file_id, "project_id": project_id},
                                             {"$set": fields})
        if pages_total is not None:
            await db.project_files.update_one(
                {"_id": to_query_id(file_id), "project_id": project_id},
                {"$set": {"page_count": int(pages_total)}})
    except Exception as e:
        logger.warning(f"plan index progress write failed for {file_id}: {e!r}")


async def _plan_index_heartbeat(file_id: str, project_id: str, worker: str) -> None:
    while True:
        await asyncio.sleep(PLAN_INDEX_HEARTBEAT_SECONDS)
        now = datetime.now(timezone.utc)
        try:
            await db[PLAN_INDEX_JOBS].update_one(
                {"_id": file_id, "project_id": project_id, "worker": worker},
                {"$set": {"lease_until": now + timedelta(seconds=PLAN_INDEX_LEASE_SECONDS),
                          "updated_at": now}})
        except Exception as e:
            logger.warning(f"plan index lease renewal failed for {file_id}: {e!r}")


async def _run_plan_index_job(job: dict, worker: str) -> str:
    """Index one claimed file and record how it ended. Returns the status."""
    file_id = str(job["_id"])
    project_id = job["project_id"]
    jobs = db[PLAN_INDEX_JOBS]
    now = datetime.now(timezone.utc)
    key = {"_id": file_id, "project_id": project_id}

    if int(job.get("attempts") or 0) > PLAN_INDEX_MAX_ATTEMPTS:
        await jobs.update_one(key, {"$set": {
            "status": "failed", "finished_at": now, "updated_at": now,
            "worker": None, "lease_until": None,
            "error": (f"stopped after {PLAN_INDEX_MAX_ATTEMPTS} attempts — the container "
                      f"restarted while this file was indexing each time"),
        }})
        logger.error(f"Plan index: {job.get('file_name')} failed after "
                     f"{PLAN_INDEX_MAX_ATTEMPTS} attempts")
        return "failed"

    rec = await db.project_files.find_one({"_id": to_query_id(file_id), "project_id": project_id})
    if not rec or rec.get("is_deleted"):
        await jobs.update_one(key, {"$set": {
            "status": "cancelled", "finished_at": now, "updated_at": now,
            "worker": None, "lease_until": None, "error": "the file no longer exists"}})
        return "cancelled"

    heartbeat = asyncio.create_task(_plan_index_heartbeat(file_id, project_id, worker))
    try:
        result = await _index_pdf_file(
            project_id, job.get("company_id") or rec.get("company_id") or "", rec, job=job)
    except Exception as e:
        logger.error(f"Plan index: {job.get('file_name')} raised {e!r}")
        result = {"outcome": "failed", "error": repr(e)[:300]}
    finally:
        heartbeat.cancel()

    result = result or {"outcome": "done"}
    now = datetime.now(timezone.utc)
    outcome = result.get("outcome", "done")
    if outcome == "deferred":
        await jobs.update_one(key, {
            "$set": {"status": "queued", "worker": None, "lease_until": None, "updated_at": now,
                     "not_before": now + timedelta(seconds=COMBINED_DEFER_SECONDS),
                     "profile": result.get("profile")},
            "$inc": {"deferrals": 1, "attempts": -1},
        })
        return "queued"

    status = outcome if outcome in ("done", "skipped", "failed") else "done"
    fields = {"status": status, "finished_at": now, "updated_at": now, "worker": None,
              "lease_until": None, "error": result.get("error")}
    latest = await jobs.find_one(key, {"rerun": 1, "rerun_resume": 1})
    if latest and latest.get("rerun"):
        fields.update({"status": "queued", "rerun": False, "attempts": 0, "enqueued_at": now,
                       "not_before": None, "resume": bool(latest.get("rerun_resume", True))})
    await jobs.update_one(key, {"$set": fields})
    return fields["status"]


def _plan_index_ready() -> Tuple[bool, str]:
    missing = []
    if not QWEN_API_KEY:
        missing.append("QWEN_API_KEY not set")
    if not _r2_client:
        missing.append("R2 not configured")
    if not POPPLER_OK:
        missing.append(f"poppler check failed ({POPPLER_DETAIL})")
    return (not missing), "; ".join(missing)


async def _plan_index_worker() -> None:
    import socket as _socket
    import uuid as _uuid
    worker = f"{_socket.gethostname()}:{os.getpid()}:{_uuid.uuid4().hex[:6]}"
    logger.warning(f"Plan index worker started ({worker})")
    loop = asyncio.get_event_loop()
    last_pause_log = -1e9
    while True:
        try:
            ready, why = _plan_index_ready()
            if not ready:
                if loop.time() - last_pause_log > 600:
                    waiting = await db[PLAN_INDEX_JOBS].count_documents(
                        {"status": {"$in": list(PLAN_INDEX_ACTIVE)}})
                    logger.error(f"Plan index worker PAUSED: {why}. {waiting} file(s) waiting.")
                    last_pause_log = loop.time()
                await asyncio.sleep(60)
                continue
            job = await _claim_plan_index_job(worker)
            if not job:
                await asyncio.sleep(PLAN_INDEX_IDLE_SECONDS)
                continue
            logger.info(f"Plan index: claimed {job.get('file_name')} "
                        f"(attempt {job.get('attempts')}, {job.get('pages_done') or 0} pages done)")
            await _run_plan_index_job(job, worker)
        except asyncio.CancelledError:
            raise
        except Exception as e:
            logger.error(f"Plan index worker error: {e!r}")
            await asyncio.sleep(PLAN_INDEX_IDLE_SECONDS)


async def _index_pdf_file(project_id: str, company_id: str, file_record: dict,
                          job: Optional[dict] = None) -> dict:
    """Download a PDF from R2 and index each page into document_page_index.

    Called by the plan index worker with its claimed `job`; progress is written
    to the job as pages finish. Returns {"outcome": "done" | "skipped" |
    "deferred" | "failed", ...}.

    MEMORY IS BOUNDED BY THE PAGE, NOT THE FILE. The PDF goes to a temp file
    and is read from disk. The whole-file pass keeps only each page's text and
    a few small facts; a page's full layout is parsed again when that page is
    indexed, three at a time, and poppler writes each page's JPEG to disk.

    File-hash cache: pages already complete for this file and hash are skipped,
    so a restart or a repeat sync costs only the pages that are left.
    """
    import shutil as _shutil
    import tempfile as _tempfile

    if not QWEN_API_KEY:
        logger.info("Plan index skipped — QWEN_API_KEY not configured")
        return {"outcome": "failed", "error": "QWEN_API_KEY not configured"}
    # Before the download: a report of ours costs nothing to refuse and
    # everything to index.
    file_name_early = file_record.get("name") or ""
    if is_generated_report(file_name_early):
        logger.info(f"Plan index: {file_name_early} is a report we generated — not indexed")
        try:
            await db.project_files.update_one(
                {"_id": to_query_id(str(file_record.get("_id") or "")),
                 "project_id": project_id},
                {"$set": {"index_status": {
                    "state": GENERATED_REPORT_SKIPPED,
                    "reason": "a Blueview report, not a drawing set",
                    "at": datetime.now(timezone.utc)}}})
        except Exception as e:
            logger.warning(f"could not record the generated-report skip: {e!r}")
        return {"outcome": "skipped", "reason": GENERATED_REPORT_SKIPPED}
    if not _r2_client or not file_record.get("r2_key"):
        logger.info(
            f"Plan index skipped (no R2 object) for "
            f"{file_record.get('name')}"
        )
        return {"outcome": "failed", "error": "no R2 object for this file"}

    file_id = str(file_record.get("_id") or file_record.get("id") or "")
    file_name = file_record.get("name") or "unknown.pdf"
    job = job or {}
    deferrals = int(job.get("deferrals") or 0)
    can_defer = bool(job)

    # A deferred combined-set check runs here, with the profile its job saved,
    # before anything is downloaded.
    if job.get("profile"):
        verdict = await _combined_set_gate(project_id, file_record, file_id,
                                           job["profile"], deferrals, can_defer)
        if verdict != "index":
            return {"outcome": verdict, "profile": job["profile"]}

    async with _PDF_INDEX_FILE_SEMAPHORE:
        r2_key = file_record["r2_key"]
        discipline = detect_discipline(file_name)
        tmpdir = _tempfile.mkdtemp(prefix="planidx-")
        try:
            # Download to disk. The bytes are dropped as soon as they are written.
            try:
                obj = await asyncio.to_thread(
                    _r2_client.get_object, Bucket=R2_BUCKET_NAME, Key=r2_key
                )
                pdf_bytes = obj["Body"].read()
            except Exception as e:
                logger.error(f"Plan index: R2 download failed for {r2_key}: {e}")
                return {"outcome": "failed", "error": f"R2 download failed: {e!r}"[:300]}

            # Compute MD5 for hash-cache
            import hashlib
            file_hash = hashlib.md5(pdf_bytes).hexdigest()
            pdf_path = os.path.join(tmpdir, "source.pdf")
            with open(pdf_path, "wb") as fh:
                fh.write(pdf_bytes)
            del pdf_bytes

            # Skip only if an existing entry has the same hash AND was produced by
            # index_version 2 or later. Version 1 used a minimal prompt and no
            # embedding and must be reprocessed. Version 2 is NOT forced up to 3
            # here — see PLAN_INDEX_SKIP_MIN_VERSION.
            existing = await db.document_page_index.find_one({
                "file_id":      file_id,
                "file_hash":    file_hash,
                "index_version": {"$gte": PLAN_INDEX_SKIP_MIN_VERSION},
            })
            # Total page count up front so we can log progress.
            total = _pdf_total_pages(pdf_path)
            if total <= 0:
                logger.error(f"Plan index: page count = 0 for {file_name}")
                return {"outcome": "failed", "error": "page count is 0"}

            # ── RESUME, DON'T RESTART, AND DON'T SKIP A HALF-DONE FILE ─────
            #
            # Only pages that are done are skipped: a version 2 row, or a
            # version 3 row marked page_complete (row and chunks written).
            todo = list(range(1, total + 1))
            if existing:
                done = await _pages_already_indexed(file_id, file_hash)
                if done is None or len(done) >= total:
                    logger.info(
                        f"Plan index: {file_name} already indexed at current hash + "
                        f"version — skipping"
                    )
                    await _plan_job_progress(job, project_id, file_id,
                                             pages_done=total, pages_total=total)
                    return {"outcome": "done"}
                todo = [p for p in todo if p not in done]
                logger.info(f"Plan index: {file_name} resuming — {len(todo)} of {total} pages left")

            # The whole-file pass: each page's text and the facts the whole file
            # decides, one page parsed at a time. Falls back to pypdf's flat
            # text when the PDF library cannot read the file.
            ctx = None
            try:
                ctx = await asyncio.to_thread(plan_text.file_context, pdf_path)
                if ctx.get("page_count") != total:
                    ctx = None
            except Exception as e:
                logger.warning(f"Plan index: text layer failed for {file_name}: {e!r}")
                ctx = None
            if ctx:
                texts = ctx["texts"]
            else:
                texts = _pdf_page_texts(pdf_path) or ["" for _ in range(total)]
            # Lines on most pages of this file — the firm, the address, the stamp.
            # Stripped before extraction so the model reads the sheet, not the
            # title block it has already seen forty times.
            boilerplate = plan_extract.boilerplate_lines(texts)
            tag_vocab = ctx["tag_vocab"] if ctx else plan_text.SEED_TAGS
            drawing_index = ctx["drawing_index"] if ctx else {}

            # Before any page goes to the vision model.
            if ctx and not job.get("profile"):
                verdict = await _combined_set_gate(project_id, file_record, file_id,
                                                   ctx["profile"], deferrals, can_defer)
                if verdict != "index":
                    return {"outcome": verdict, "profile": ctx["profile"]}
            if ctx and file_record.get("index_status"):
                # Indexed after all — a stale "skipped" must not stay on screen.
                try:
                    await db.project_files.update_one(
                        {"_id": to_query_id(file_id), "project_id": project_id},
                        {"$unset": {"index_status": ""}},
                    )
                except Exception as e:
                    logger.warning(f"could not clear index_status on {file_id}: {e!r}")

            pages_done = total - len(todo)
            await _plan_job_progress(job, project_id, file_id,
                                     pages_done=pages_done, pages_total=total)

            async def _process_page(page_num: int):
                dpi = _render_dpi_for(file_name, page_num)
                layout = None
                # PREPARED ONE PAGE AT A TIME; the vision calls still run three
                # at a time. Measured: a page's layout with tables is up to
                # ~100 MB, and pdftoppm builds a ~160 MB raster for a 36x24
                # sheet at 250 DPI in its own process. Three of each at once is
                # most of a gigabyte for work that takes seconds per page.
                async with _PLAN_PAGE_PREP_SEMAPHORE:
                    if ctx:
                        try:
                            layout = await asyncio.to_thread(plan_text.page_layout_at, pdf_path, page_num)
                        except Exception as e:
                            logger.warning(f"Plan index: page {page_num} layout failed: {e!r}")
                    jpeg = await asyncio.to_thread(
                        _render_pdf_page, pdf_path, page_num, dpi
                    )
                text = (layout or {}).get("text") or (
                    texts[page_num - 1] if page_num - 1 < len(texts) else "")
                await _index_single_page(
                    project_id=project_id,
                    company_id=company_id,
                    file_id=file_id,
                    file_name=file_name,
                    file_hash=file_hash,
                    page_number=page_num,
                    discipline=discipline,
                    page_text=text,
                    page_image_bytes=jpeg,
                    boilerplate=boilerplate,
                    layout=layout,
                    tag_vocab=tag_vocab,
                    drawing_index=drawing_index,
                    pdf_path=pdf_path,
                )

            # Three pages at a time, progress written after each batch.
            for i in range(0, len(todo), PLAN_INDEX_BATCH):
                batch = todo[i:i + PLAN_INDEX_BATCH]
                await asyncio.gather(*[_process_page(n) for n in batch])
                pages_done += len(batch)
                await _plan_job_progress(job, project_id, file_id,
                                         pages_done=pages_done, pages_total=total)
                logger.info(f"Plan index: {file_name}: {pages_done}/{total}")
        finally:
            _shutil.rmtree(tmpdir, ignore_errors=True)

        logger.info(f"Plan index complete: {file_name} ({total} pages)")

        try:
            await _supersede_plan_pages(project_id)
        except Exception as e:
            logger.warning(f"plan supersession failed for {project_id}: {e!r}")

        # Auto-rebuild the project's ProjectModel now that this file's pages are
        # fully indexed. Shared completion point for ALL indexing entry points
        # (upload, Dropbox sync, single re-index, reindex-all — they all enqueue,
        # and the worker runs _index_pdf_file). Fire-and-forget so indexing
        # never waits on, or fails because of, aggregation.
        asyncio.create_task(_auto_aggregate_project_model(project_id))
        return {"outcome": "done"}


async def _pages_already_indexed(file_id: str, file_hash: str) -> Optional[set]:
    """Page numbers that need no work. None when the lookup failed — the caller
    then skips the file, which is what it did before resume existed."""
    try:
        rows = await db.document_page_index.find(
            {"file_id": file_id, "file_hash": file_hash},
            {"page_number": 1, "index_version": 1, "page_complete": 1},
        ).to_list(5000)
    except Exception as e:
        logger.warning(f"resume lookup failed for file {file_id}: {e!r}")
        return None
    return {r.get("page_number") for r in rows
            if (r.get("index_version") or 0) < PLAN_INDEX_VERSION or r.get("page_complete")}


def _file_upload_order(fr: dict) -> tuple:
    ts = fr.get("created_at")
    if isinstance(ts, str):
        try:
            ts = datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except ValueError:
            ts = None
    if isinstance(ts, datetime) and ts.tzinfo is None:
        ts = ts.replace(tzinfo=timezone.utc)
    return (ts or datetime.min.replace(tzinfo=timezone.utc), str(fr.get("_id")))


# Sheets every discipline set carries its own copy of. A T-001.00 cover on the
# architectural set is not a newer version of the structural set's T-001.00,
# and EN-001.00 energy sheets and GN general sheets repeat the same way.
_NEVER_SUPERSEDE_ACROSS_SETS = frozenset({"T", "EN", "GN"})

# The '.01' of a partial reissue. Standard drafting: same sheet, revised.
_SHEET_SUFFIX_RE = re.compile(r"\.\d{1,2}$")
_SHEET_DATE_RE = re.compile(r"(?<!\d)(\d{1,4})[./\-_](\d{1,2})[./\-_](\d{2,4})(?!\d)")


def _parse_sheet_date(text: Any):
    """The last date in a title-block revision field or a file name:
    '03/28/2025', '07-29-26', 'AR - 3.28.25.pdf', '...AS BUILT 08-24-26.pdf'.
    None when there is none."""
    from datetime import date as _date
    found = None
    for m in _SHEET_DATE_RE.finditer(str(text or "")):
        a, b, c = m.groups()
        try:
            if len(a) == 4:
                found = _date(int(a), int(b), int(c))
                continue
            if len(c) == 2:
                year = 2000 + int(c)
            elif len(c) == 4:
                year = int(c)
            else:
                continue
            found = _date(year, int(a), int(b))
        except ValueError:
            continue
    return found


def _sheet_prefix(sheet_number: str) -> str:
    return sheet_number.split("-")[0] if "-" in sheet_number else ""


async def _supersede_plan_pages(project_id: str) -> dict:
    """One current row per sheet, within each discipline set.

    ── THE DUPLICATES ────────────────────────────────────────────────────
    #
    # Page rows are keyed (file_id, page_number), and every re-upload of a
    # drawing set mints a new file id. Two ways a page is someone else's copy:
    #   same file_hash + page_number in another file — the identical PDF again
    #   same sheet_number in another file of the SAME discipline set — a revision
    # The losing row gets `superseded_by` = the winning file id.
    #
    # ── WHICH COPY WINS: THE DRAWING'S DATE, NOT THE UPLOAD'S ──────────────
    #
    # This used to be "the newest upload wins", and on 588 Boyland that hid
    # the June 2026 owners set behind the March 2025 architectural set, because
    # the March set had been re-synced most recently. Now, in order:
    #   1. the date in the file name ('Owners set - 6.9.26.pdf')
    #   2. the revision date read from the title block
    #   3. upload time
    # See _order for why the title-block date is the tie-break and not the
    # lead: it is the date of a revision cloud, and the sheet that supersedes
    # another frequently carries none.
    #
    # ── WITHIN A SET, AND NEVER FOR COVER / ENERGY / GENERAL SHEETS ────────
    #
    # A file's discipline is its most common sheet prefix. Sheet numbers are
    # matched only between files of the same discipline: the structural set's
    # T-001.00 cover was being hidden by the architectural set's, and MH's
    # EN-001.00 by PL's. T-, EN- and GN- sheets are never superseded across
    # files at all.
    #
    # NOTHING IS DELETED. Readers exclude a row only while the file that
    # superseded it is still live, so deleting the newer file brings the older
    # sheet straight back. A sheet that appears twice INSIDE one file is not a
    # duplicate and both pages stay.
    """
    from collections import Counter as _Counter
    from datetime import date as _date

    files = await db.project_files.find(
        {"project_id": project_id, "is_deleted": {"$ne": True}},
        {"_id": 1, "created_at": 1, "name": 1},
    ).to_list(2000)
    uploaded = {str(f["_id"]): _file_upload_order(f) for f in files}
    name_date = {str(f["_id"]): _parse_sheet_date(f.get("name")) for f in files}
    if not uploaded:
        return {"superseded": 0}
    rows = await db.document_page_index.find(
        {"project_id": project_id, "file_id": {"$in": list(uploaded)}},
        {"_id": 1, "file_id": 1, "file_hash": 1, "page_number": 1,
         "sheet_number": 1, "superseded_by": 1, "revision_date": 1,
         "sheet_position": 1},
    ).to_list(20000)

    def _norm(sn):
        return re.sub(r"\s+", "", str(sn or "")).upper()

    # ── A .01 IS THE SAME SHEET, REVISED ───────────────────────────────────
    #
    # 'AR - 8.18.26.pdf' reissues ten sheets of the March architectural set and
    # bumps every suffix: A-105.00 becomes A-105.01, keeping its place in the
    # set ('16 OF 31' on both). Matching on the exact string left both current,
    # and the project carried nine duplicated sheets — three roof plans among
    # them — until 2026-09-16.
    #
    # The stem goes in its OWN key space. Stemming into the ordinary sheet key
    # would let a number with no suffix collide with one that has it: on this
    # project a roof plan misfiled as 'A-300' would have hidden the real
    # A-300.00, LONGITUDINAL SECTIONS, which is the opposite of the point.
    def _stem_key(sn):
        return _SHEET_SUFFIX_RE.sub("", sn)

    prefixes: Dict[str, _Counter] = {}
    for r in rows:
        p = _sheet_prefix(_norm(r.get("sheet_number")))
        if p and p not in _NEVER_SUPERSEDE_ACROSS_SETS:
            prefixes.setdefault(r.get("file_id"), _Counter())[p] += 1
    family = {fid: c.most_common(1)[0][0] for fid, c in prefixes.items() if c}

    def _keys(r):
        out = []
        if r.get("file_hash"):
            out.append(("hash", r["file_hash"], r.get("page_number")))
        sn = _norm(r.get("sheet_number"))
        fam = family.get(r.get("file_id"))
        if not sn or not fam:
            return out
        # T-, EN- and GN- stay out of the exact-number key: that is the one
        # that hid the structural set's T-001.00 behind the architectural
        # set's, and MH's EN-001.00 behind PL's. They DO get a stem key, and
        # the pass below keeps only the ones that are a genuine reissue —
        # AR - 8.18.26's T-001.01 for AR - 3.28.25's T-001.00. Two files of the
        # same discipline that both print GN-001.00 are not a reissue of each
        # other and neither is hidden.
        if _SHEET_SUFFIX_RE.search(sn):
            out.append(("stem", fam, _stem_key(sn)))
        elif _sheet_prefix(sn) not in _NEVER_SUPERSEDE_ACROSS_SETS:
            out.append(("sheet", fam, sn))
        return out

    members: Dict[tuple, Dict[str, list]] = {}
    for r in rows:
        for k in _keys(r):
            members.setdefault(k, {}).setdefault(r.get("file_id"), []).append(r)

    # ── THE FILE'S DATE LEADS ──────────────────────────────────────────────
    #
    # A title-block revision date is the date of the last revision CLOUD on
    # that sheet. It is not the date the set was issued, and the sheet that
    # replaces another often carries none at all: AR - 3.28.25's Z-001.00
    # carries 2/27/2025 and AR - 8.18.26's Z-001.01 carries nothing, so
    # reading the revision date first put the March sheet above the August one
    # and the reissue superseded itself backwards.
    #
    # The failure is not particular to a reissue. Any pair where only the older
    # sheet was ever clouded picks the wrong winner the same way, and the
    # revision date is only evidence about the newer drawing when the newer
    # drawing actually carries one. The file is the issue; the date on the file
    # is the date of the issue; the revision date breaks ties between two
    # issues of the same day.
    def _order(fid, file_rows):
        revs = [d for d in (_parse_sheet_date(x.get("revision_date")) for x in file_rows) if d]
        return (name_date.get(fid) or _date.min,
                max(revs) if revs else _date.min,
                uploaded[fid])

    # A COVER SHEET IS REISSUED, NOT DUPLICATED. T-, EN- and GN- reach the
    # stem key so that T-001.00 and T-001.01 of one architectural set resolve
    # to one cover. Where every row under the stem carries the SAME number,
    # nothing was reissued — it is the same general sheet bound into two
    # issues — and the old exclusion still applies.
    for k in [k for k in members
              if k[0] == "stem" and _sheet_prefix(k[2]) in _NEVER_SUPERSEDE_ACROSS_SETS]:
        numbers = {_norm(r.get("sheet_number")) for rs in members[k].values() for r in rs}
        if len(numbers) < 2:
            del members[k]

    # THE SET'S OWN INDEX GETS A VETO. Two sheets whose title blocks claim
    # DIFFERENT places in the set are different sheets, whatever their numbers
    # stem to. Corroboration only: a page whose title block does not print its
    # place says nothing either way, and most do not.
    for k in [k for k in members if k[0] == "stem"]:
        places = {tuple(r["sheet_position"]) for rs in members[k].values() for r in rs
                  if r.get("sheet_position")}
        if len(places) > 1:
            logger.info(f"plan supersession {project_id}: {k[2]} left alone, "
                        f"title blocks claim {sorted(places)}")
            del members[k]

    winners: Dict[tuple, Tuple[str, tuple]] = {}
    for k, by_file in members.items():
        if len(by_file) > 1:
            best = max(by_file, key=lambda f: _order(f, by_file[f]))
            winners[k] = (best, _order(best, by_file[best]))

    by_winner: Dict[str, list] = {}
    keep_ids = []
    for r in rows:
        loser_to, loser_order = None, None
        for k in _keys(r):
            w = winners.get(k)
            if w and w[0] != r.get("file_id") and (loser_order is None or w[1] > loser_order):
                loser_to, loser_order = w
        if loser_to:
            if r.get("superseded_by") != loser_to:
                by_winner.setdefault(loser_to, []).append(r["_id"])
        elif r.get("superseded_by"):
            keep_ids.append(r["_id"])

    n = 0
    for w, ids in by_winner.items():
        res = await db.document_page_index.update_many(
            {"project_id": project_id, "_id": {"$in": ids}},
            {"$set": {"superseded_by": w}})
        n += getattr(res, "modified_count", 0) or 0
    if keep_ids:
        await db.document_page_index.update_many(
            {"project_id": project_id, "_id": {"$in": keep_ids}},
            {"$set": {"superseded_by": None}})
    logger.info(f"plan supersession {project_id}: {n} newly superseded, "
                f"{len(keep_ids)} restored")
    return {"superseded": n, "restored": len(keep_ids)}


def _current_page_filter(live_ids: Optional[list]) -> dict:
    """Live file AND not superseded by a live file. None → no filter, which is
    the documented degradation of _live_plan_file_ids."""
    if live_ids is None:
        return {}
    return {"file_id": {"$in": live_ids}, "superseded_by": {"$nin": live_ids}}


async def _project_has_full_index(project_id: str) -> bool:
    """Return True when every PDF in the project's files has at least one
    document_page_index entry with a matching file_hash — used to skip
    re-sync indexing entirely when nothing has changed.
    """
    pdf_files = await db.project_files.find({
        "project_id": project_id,
        "name": {"$regex": r"\.pdf$", "$options": "i"},
    }).to_list(200)
    if not pdf_files:
        return True
    for fr in pdf_files:
        file_id = str(fr.get("_id"))
        if not fr.get("r2_key"):
            return False
        hit = await db.document_page_index.find_one({"file_id": file_id})
        if not hit:
            return False
    return True


# ==================== PLAN QUERY HANDLER ====================

PLAN_TRIGGER_VERBS = [
    "show me", "find the", "pull up", "send me",
    "where is", "what does", "which sheet", "get me", "open",
]
PLAN_DRAWING_NOUNS = [
    "plan", "elevation", "section", "detail", "schedule",
    "sheet", "drawing", "blueprint",
]


def _has_plan_query_trigger(text: str) -> bool:
    """Two-condition match: trigger verb AND drawing noun both present."""
    if not text:
        return False
    low = text.lower()
    has_verb = any(v in low for v in PLAN_TRIGGER_VERBS)
    if not has_verb:
        return False
    has_noun = any(n in low for n in PLAN_DRAWING_NOUNS)
    return has_noun


_PLAN_QUERY_PARSER_PROMPT = (
    "You are parsing a construction worker's WhatsApp message into a structured "
    "drawing search query for a NYC residential project.\n\n"
    "Return a JSON object with exactly these fields:\n"
    "  sheet_number: exact sheet ID if mentioned (A-301, ME-401, S-102), else null\n"
    "  discipline: one of AR, ST, ME, EL, PL, SP, GN — inferred from context, else null\n"
    "  floor: floor number or name if mentioned (3, roof, cellar, penthouse), else null\n"
    "  sheet_type: one of plan, elevation, section, detail, schedule, riser, diagram, else null\n"
    "  keywords: array of 2-4 key construction terms that would appear on a drawing\n"
    "  question: the verbatim question to answer from the drawing, or null if the user "
    "wants the image ('show me', 'pull up', 'send me', 'find the')\n"
    "  dob_route: true if the message is about permits, violations, or DOB status and "
    "should NOT be treated as a plan query; else false\n\n"
    "Spatial → floor/discipline inference (always apply before returning):\n"
    "- 'backyard', 'yard', 'rear yard', 'courtyard', 'garden' → floor='1', "
    "  likely discipline='PL' if drainage/sewer/water, else 'GN' for site/landscape.\n"
    "- 'front yard', 'front walk', 'sidewalk', 'street', 'curb' → floor='1', "
    "  discipline='GN'.\n"
    "- 'basement', 'cellar', 'sub-basement' → floor='cellar' or 'basement'.\n"
    "- 'rooftop', 'roof' → floor='roof'.\n"
    "- 'penthouse', 'PH' → floor='penthouse'.\n"
    "- 'ground floor', 'first floor', '1st floor', 'lobby' → floor='1'.\n"
    "- 'mezzanine' → floor='mezzanine'.\n\n"
    "Topic → discipline inference:\n"
    "- drain / drainage / sewer / trap / cleanout / waste line / water line / "
    "  hose bib / floor drain / roof drain → discipline='PL'.\n"
    "- HVAC / ductwork / AHU / VAV / boiler / chiller / supply grille / "
    "  return grille / diffuser → discipline='ME'.\n"
    "- outlet / receptacle / panel / feeder / circuit / switch / lighting / "
    "  riser (electrical) → discipline='EL'.\n"
    "- standpipe / fire pump / sprinkler head / zone valve → discipline='SP'.\n"
    "- beam / column / footing / slab / rebar / girder / shear wall → 'ST'.\n"
    "- partition / door / ceiling / finish / stair / elevator → 'AR'.\n"
    "- site work / landscape / retaining wall / fence / pavers → 'GN'.\n\n"
    "Keywords should always include the spatial noun (e.g. BACKYARD, ROOF, "
    "BASEMENT) AND the topic noun (DRAIN, DUCT, OUTLET) so keyword retrieval "
    "can match even if discipline inference is wrong.\n\n"
    "Routing rules:\n"
    "- 'show me / pull up / send me / find the' → question=null (image send).\n"
    "- 'what is / how thick / how many / where / any / is there / required / "
    "  what size / how far' or any '?' → extract as question.\n"
    "- Permit / violation / DOB keyword → set dob_route=true and leave other fields null.\n"
    "- Return ONLY valid JSON, no explanation."
)


async def _parse_plan_query(query: str) -> dict:
    """Parse a natural-language plan request into a structured search spec.

    Returns dict with keys: sheet_number, discipline, floor, sheet_type,
    keywords (list), question (str|None), dob_route (bool).
    """
    if not OPENAI_API_KEY or not query:
        return {}
    try:
        async with ServerHttpClient(timeout=20.0) as client_http:
            resp = await client_http.post(
                "https://api.openai.com/v1/chat/completions",
                headers={
                    "Authorization": f"Bearer {OPENAI_API_KEY}",
                    "Content-Type": "application/json",
                },
                json={
                    "model": "gpt-4o-mini",
                    "temperature": 0,
                    "max_tokens": 250,
                    "response_format": {"type": "json_object"},
                    "messages": [
                        {"role": "system", "content": _PLAN_QUERY_PARSER_PROMPT},
                        {"role": "user",   "content": query},
                    ],
                },
            )
            if resp.status_code != 200:
                return {}
            import json as _json
            parsed = _json.loads(resp.json()["choices"][0]["message"]["content"])
            if not isinstance(parsed, dict):
                return {}
            # Normalize types
            if "keywords" in parsed and not isinstance(parsed["keywords"], list):
                parsed["keywords"] = []
            parsed["dob_route"] = bool(parsed.get("dob_route"))
            return parsed
    except Exception as e:
        logger.warning(f"plan query parse failed: {e}")
        return {}


def _cosine_similarity(a: list, b: list) -> float:
    """Cosine similarity over two equal-length embedding vectors. 0 if malformed."""
    if not a or not b or len(a) != len(b):
        return 0.0
    dot = 0.0
    na = 0.0
    nb = 0.0
    for x, y in zip(a, b):
        dot += x * y
        na += x * x
        nb += y * y
    if na <= 0 or nb <= 0:
        return 0.0
    import math
    return dot / (math.sqrt(na) * math.sqrt(nb))


async def _live_plan_file_ids(project_id: str) -> list:
    """The `project_files` ids this project still has, as index `file_id`s.

    ── WHY A SEARCH HAS TO ASK THIS ───────────────────────────────────────
    DELETING A FILE DOES NOT DELETE ITS INDEX ROWS.
    `DELETE /projects/{id}/files/{file_id}` removes the R2 source object and
    hard-deletes the `project_files` row, and touches `document_page_index`
    not at all. Production carries 44 such rows across 8 files today.
    They are not inert: this retriever searches the index, so a WhatsApp
    answer can name a sheet, offer its image, and tell a superintendent to
    "open it in the Levelog app under Plans & Files" — where it does not
    exist. A well-formed answer with nothing behind it, which is the same
    failure as an attestation over a roster nobody read.

    SILENTLY OMITTED, NOT REPORTED AS UNAVAILABLE. A result he cannot open is
    worse than no result: "no matching sheet" sends him to look properly,
    while "A-301, unavailable" reads as a system fault and invites a retry
    that cannot succeed. The retriever already answers "couldn't find a
    matching sheet" when the pool is empty, and that sentence is true here.

    THIS IS THE READ-SIDE HALF ONLY. It does not delete anything and does not
    stop new orphans arriving — the delete endpoint still leaves rows behind,
    which is a separate change with a separate owner. This one holds even if
    that sweep never runs.

    CHEAP, AND MEASURED RATHER THAN ASSUMED: 26 live `project_files` rows
    across the whole database against 287 index rows. One projected query per
    plan question, on a path that already runs a vector search and a VLM call.
    Not cached deliberately — a stale allow-list would either resurrect a
    deleted sheet or hide a freshly uploaded one, and both are worse than the
    query.

    RETURNS None WHEN IT COULD NOT LOOK, and the caller then does not filter.
    Neither of the other two options is acceptable: an empty list would read as
    "every sheet in this project is deleted" and answer "couldn't find a
    matching sheet" for a project whose drawings are all present, and RAISING
    would be worse still — `_handle_plan_query` is launched with
    `asyncio.create_task` and nothing awaits it, so an exception becomes an
    unhandled task exception and the man who asked gets SILENCE. Falling back
    to unfiltered is exactly today's behaviour, which is the one degradation
    that cannot be worse than what shipped before this.
    """
    try:
        rows = await db.project_files.find(
            {"project_id": project_id, "is_deleted": {"$ne": True}, "index_status.state": {"$ne": COMBINED_SET_SKIPPED}},
            {"_id": 1},
        ).to_list(2000)
        return [str(r["_id"]) for r in rows]
    except Exception as e:
        logger.warning(f"live plan file ids lookup failed for {project_id}: {e!r}")
        return None


# Everything the ranking, fusion and answer paths read off a page row. The
# `embedding` field is deliberately ABSENT: it is fetched separately for the
# cosine pass and dropped, so 1536 floats per page stop travelling through
# four stages that never look at them.
# TAKEN FROM WHAT _index_single_page ACTUALLY WRITES, not from the prompt that
# produced it. The indexing prompt asks the model for MATERIALS_AND_SPECS and
# SPACES_AND_ROOMS; the fields it stores are `materials` and `spaces`. Guessing
# the names from the prompt gave a projection that silently dropped the two
# fields the keyword rank leans on hardest — a projection typo does not raise,
# it just makes matching quietly worse.
_PAGE_FIELDS = {
    "_id": 1, "project_id": 1, "company_id": 1,
    "file_id": 1, "file_name": 1, "file_hash": 1,
    "page_number": 1, "sheet_number": 1, "sheet_title": 1,
    "discipline": 1, "floor": 1, "keywords": 1,
    "materials": 1, "spaces": 1, "summary": 1, "notes": 1,
    "dimensions": 1, "code_refs": 1, "detail_refs": 1,
    "index_version": 1, "indexed_at": 1,
    # Written by later passes than the one above, and read by the image path.
    "page_jpeg_r2_key": 1, "page_base_r2_key": 1, "is_spec_page": 1,
}


async def _retrieve_plan_candidates(
    project_id: str,
    parsed: dict,
    original_query: str,
    limit: int = 3,
) -> list:
    """Retrieve top plan-page candidates for a query.

    Priority order:
      1. If parser returned a sheet_number, do an exact (case-insensitive)
         match on the sheet_number field and return it directly.
      2. Otherwise, run two parallel searches:
           a. Vector similarity against the summary embedding.
           b. Keyword match on sheet_title + keywords + materials.
         Merge via Reciprocal Rank Fusion and return top `limit`.

    Hard filters: discipline + floor (if extracted), and always exclude
    spec pages (is_spec_page=True or sheet_title='[SPECIFICATION PAGE]').

    AND ALWAYS EXCLUDE A PAGE WHOSE FILE NO LONGER EXISTS. See
    `_live_plan_file_ids` below — a citation to a deleted drawing is a
    well-formed answer with nothing behind it.
    """
    base_filter: Dict[str, Any] = {
        "project_id":   project_id,
        "is_spec_page": {"$ne": True},
        "sheet_title":  {"$ne": "[SPECIFICATION PAGE]"},
    }
    # None means the lookup failed; filtering on it would answer "no matching
    # sheet" for a healthy project. Absent filter == today's behaviour.
    live_ids = await _live_plan_file_ids(project_id)
    # And not an older copy of a sheet a newer upload carries.
    base_filter.update(_current_page_filter(live_ids))

    # Hard filters — normalize discipline to the 2-letter code stored in the
    # index ('ME', 'AR', 'ST', etc). The agent sometimes passes the full
    # word ('Mechanical') or alternate casing; match tolerantly.
    _DISC_ALIASES = {
        "AR": "AR", "A": "AR", "ARCH": "AR", "ARCHITECTURAL": "AR",
        "ST": "ST", "S": "ST", "STR": "ST", "STRUCTURAL": "ST",
        "ME": "ME", "M": "ME", "MECH": "ME", "MECHANICAL": "ME", "HVAC": "ME", "MH": "ME",
        "EL": "EL", "E": "EL", "ELEC": "EL", "ELECTRICAL": "EL",
        "PL": "PL", "P": "PL", "PLMB": "PL", "PLUMBING": "PL",
        "SP": "SP", "SPRK": "SP", "SPRINKLER": "SP", "FP": "SP",
        "GN": "GN", "GEN": "GN", "GENERAL": "GN", "CIVIL": "GN", "SITE": "GN",
    }
    raw_disc = (parsed.get("discipline") or "").strip().upper()
    disc = _DISC_ALIASES.get(raw_disc) or (raw_disc if len(raw_disc) == 2 else None)
    if disc:
        base_filter["discipline"] = disc
    floor = parsed.get("floor")
    if isinstance(floor, (int, float)):
        floor = str(int(floor))

    # ── 1. Sheet-number exact match ───────────────────────────────────────
    # Sheet numbers are often stamped with decimal subsheet suffixes
    # (M-200, M-200.00, A-301.1). If the user types the base id we want
    # all variants to hit. Pattern: start ^, optional trailing .digits, end.
    sheet_q = (parsed.get("sheet_number") or "").strip()
    if not sheet_q:
        for tok in re.findall(r"[A-Za-z]{1,3}-?\d{1,4}[A-Za-z]?", original_query or ""):
            if _is_sheet_number_query(tok):
                sheet_q = tok
                break
    if sheet_q:
        q_upper = sheet_q.upper()
        # Build up the set of prefixes to accept
        prefixes = {q_upper}
        m = re.match(r"^([A-Z]{1,3})-?(\d{1,4}[A-Z]?)(\.\d+)?$", q_upper)
        if m:
            prefixes.add(f"{m.group(1)}-{m.group(2)}")
            prefixes.add(f"{m.group(1)}{m.group(2)}")
            # Also accept the exact decimal form the user gave us
            if m.group(3):
                prefixes.add(f"{m.group(1)}-{m.group(2)}{m.group(3)}")
        # Regex: ^(PFX1|PFX2)(\.\d+)?$  — tolerate decimal subsheet
        pattern = (
            f"^({'|'.join(re.escape(p) for p in prefixes)})"
            r"(\.\d+)?$"
        )
        fq = dict(base_filter)
        # A NAMED SHEET IS FOUND EVEN WHEN IT IS A NOTES SHEET. The spec-page
        # exclusion keeps a wall of notes out of a broad "which sheet is like
        # this" search; it must not make "show me S-001" answer that S-001
        # does not exist.
        fq.pop("is_spec_page", None)
        fq.pop("sheet_title", None)
        fq["sheet_number"] = {"$regex": pattern, "$options": "i"}
        # Multiple hits possible when a family shares a base (M-200, M-200.1…);
        # prefer the shortest — it's the "most canonical" base sheet.
        hits = await db.document_page_index.find(fq).to_list(10)
        if hits:
            hits.sort(key=lambda p: len(p.get("sheet_number") or ""))
            return [hits[0]]
        # Fall through to full search if no exact match

    # ── 2. Load candidate pool + parallel search ──────────────────────────
    # ── THE EMBEDDING RODE ALONG WITH EVERY DOCUMENT ───────────────────────
    #
    # This find carried NO projection, so all 400 pages shipped their full
    # `embedding` field — 1536 floats each, roughly 2.4 MB of vectors per
    # question — and then carried them through the keyword rank, the fusion,
    # the sort and the candidate slice, none of which look at a vector.
    #
    # The cosine pass genuinely needs them, so this is not a saving of bytes
    # off the wire: it is the same vectors fetched once, used, and dropped,
    # instead of held on 400 dicts for the rest of the function. What it buys
    # is that the large field is now visible as a cost with a name, next to the
    # timer that will say whether it matters. `_PAGE_FIELDS` also stops a
    # future field from joining the ride silently.
    #
    # NO OTHER LATENCY CHANGE IS MADE HERE. The timers come first; this one is
    # in because the projection is what makes the retrieval timing readable at
    # all — an unprojected find times as one number covering both.
    pool = await db.document_page_index.find(
        base_filter, _PAGE_FIELDS,
    ).limit(400).to_list(400)
    if not pool and base_filter.get("discipline"):
        # Discipline filter was too strict (e.g. user asked about "drains in
        # backyard" — parser tagged it PL, but the drainage is actually on
        # a site/GN sheet). Retry without discipline; floor/spec filters
        # stay in place.
        logger.info(
            f"plan retrieval: discipline={base_filter['discipline']} filter "
            f"returned empty pool, retrying without discipline filter"
        )
        relaxed = {k: v for k, v in base_filter.items() if k != "discipline"}
        pool = await db.document_page_index.find(
            relaxed, _PAGE_FIELDS,
        ).limit(400).to_list(400)
    if not pool:
        return []

    # Optional floor filter (soft — use regex on floor field + sheet_title)
    if floor:
        fr = _floor_regex(str(floor))
        if fr:
            pat = re.compile(fr, re.I)
            filtered = [
                p for p in pool
                if pat.search(str(p.get("floor") or ""))
                or pat.search(str(p.get("sheet_title") or ""))
            ]
            if filtered:
                pool = filtered

    # 2a. Vector similarity
    query_embedding = await _generate_embedding(original_query)
    vector_ranked = []
    if query_embedding:
        # Vectors are fetched HERE, for the pass that needs them, keyed by id
        # and dropped when it ends. Nothing downstream sees them.
        vec_by_id = {}
        try:
            async for row in db.document_page_index.find(
                {"_id": {"$in": [p["_id"] for p in pool]}},
                {"embedding": 1},
            ):
                vec_by_id[row["_id"]] = row.get("embedding") or []
        except Exception as e:
            # A failed vector fetch costs the cosine rank, not the answer: the
            # keyword rank below still runs and RRF still fuses what it has.
            logger.warning(f"plan retrieval: embedding fetch failed: {e}")
        scored = []
        for p in pool:
            emb = vec_by_id.get(p["_id"]) or []
            sim = _cosine_similarity(query_embedding, emb)
            scored.append((sim, p))
        scored.sort(key=lambda x: -x[0])
        vector_ranked = [p for _s, p in scored if _s > 0.05]

    # 2b. Keyword match
    keywords = [str(k).upper() for k in (parsed.get("keywords") or []) if k]
    # Also split the raw query into keywords as a safety net
    extra_kws = re.findall(r"[A-Z][A-Z0-9\-]{2,}", (original_query or "").upper())
    keywords = list({*keywords, *extra_kws})
    keyword_ranked = []
    if keywords:
        scored_kw = []
        for p in pool:
            bag = " ".join(filter(None, [
                (p.get("sheet_number") or "").upper(),
                (p.get("sheet_title") or "").upper(),
                " ".join(p.get("keywords") or []).upper(),
                (p.get("materials") or "").upper(),
                (p.get("spaces") or "").upper(),
            ]))
            score = sum(1 for k in keywords if k in bag)
            if score > 0:
                scored_kw.append((score, p))
        scored_kw.sort(key=lambda x: -x[0])
        keyword_ranked = [p for _s, p in scored_kw]

    # ── 3. Reciprocal Rank Fusion ─────────────────────────────────────────
    # RRF constant k=60 (standard choice). Score = sum(1 / (k + rank)).
    K = 60
    rrf: Dict[str, dict] = {}
    scores: Dict[str, float] = {}
    for rank, p in enumerate(vector_ranked[:50], start=1):
        pid = str(p["_id"])
        rrf[pid] = p
        scores[pid] = scores.get(pid, 0) + 1.0 / (K + rank)
    for rank, p in enumerate(keyword_ranked[:50], start=1):
        pid = str(p["_id"])
        rrf[pid] = p
        scores[pid] = scores.get(pid, 0) + 1.0 / (K + rank)
    ordered = sorted(rrf.values(), key=lambda p: -scores[str(p["_id"])])
    return ordered[:limit]


def _floor_regex(val: str) -> str:
    """Build a safe regex for floor matching. Numeric floors require a word
    boundary + FLOOR context so '4' doesn't match '14TH FLOOR' or 'BASEMENT 4'.
    """
    v = (val or "").strip()
    if not v:
        return ""
    if v.isdigit():
        return rf"\b{v}(?:ST|ND|RD|TH)?\s+FLOOR\b"
    return rf"\b{re.escape(v)}\b"


SHOW_VERBS = ("show me", "pull up", "send me", "find the", "open", "get me", "display")

# NYC sheet ids: one to three letters, a separator, digits, optionally .1 for a
# revision. A-301, ME-401, S102, SP-1.2. Anchored on word boundaries so a
# permit number or a date cannot pass for one.
_SHEET_ID_RE = re.compile(r"\b([A-Za-z]{1,3})[-\s]?(\d{1,4}(?:\.\d+)?)\b")

# Letters that actually begin a sheet id on these drawings. Without this,
# "on 4" and "by 12" match the pattern and every message looks like a sheet
# request. Taken from the discipline prefixes the agent prompt already names.
_SHEET_PREFIXES = frozenset({
    "a", "ar", "s", "st", "m", "me", "e", "el", "p", "pl", "sp", "gn", "g",
    "c", "fa", "fp", "t", "id", "ls", "q",
    # On 588 Boyland: the site safety plan, reflected ceiling plans, energy
    # sheets and zoning sheets. "show me SSP-013" named nothing without these.
    "ssp", "rcp", "en", "z",
})


def _requested_sheet_id(text: str) -> Optional[str]:
    """The sheet id a message names, normalised ('s-001' -> 'S-001'), or None.

    A bare letter and a short number ('a 4 story') is not a sheet: without a
    hyphen the number must be three digits or more."""
    for m in _SHEET_ID_RE.finditer(text or ""):
        prefix, num = m.group(1), m.group(2)
        if prefix.lower() not in _SHEET_PREFIXES:
            continue
        hyphenated = "-" in m.group(0)
        if not hyphenated and len(num.split(".")[0]) < 3:
            continue
        return f"{prefix.upper()}-{num}"
    return None


# "Show me", "@levelog show me that", "pull it up" — a show verb with nothing to
# show. Live test 2026-09-15: after a not-found, a bare "Show me" reached the
# plan pipeline with a sheet the agent made up (S-402.00) and that sheet was
# sent.
_SHOW_FILLER = frozenset({
    "me", "it", "that", "this", "them", "those", "these", "the", "a", "please", "pls",
    "again", "up", "now", "here", "one", "sheet", "sheets", "drawing", "drawings",
    "plan", "plans", "levelog",
})


def _is_bare_show_request(body: Optional[str]) -> bool:
    s = re.sub(r"@\S+", " ", body or "").lower()
    s = " ".join(re.sub(r"[^\w\s/-]", " ", s).split())
    verb = next((v for v in SHOW_VERBS if s == v or s.startswith(v + " ")), None)
    if not verb:
        return False
    return not [w for w in s[len(verb):].split() if w not in _SHOW_FILLER]


async def _find_named_sheet(project_id: str, sheet_q: str) -> list:
    """EXACTLY the sheet asked for, or nothing. Spec pages included.

    Live test 2026-09-15: "show me s-001" sent S-002 and M-001. The exact match
    skipped S-001.00 because it is a notes (spec) page, and the search then fell
    through to its closest neighbours. A sheet id is not a search: the named
    sheet is sent, or the reply says it is not there."""
    q_upper = re.sub(r"\s+", "", (sheet_q or "")).upper()
    m = re.match(r"^([A-Z]{1,4})-?(\d{1,4}[A-Z]?)(\.\d+)?$", q_upper)
    if not m:
        return []
    base = rf"{re.escape(m.group(1))}-?{re.escape(m.group(2))}"
    pattern = (rf"^{base}{re.escape(m.group(3))}$" if m.group(3) else rf"^{base}(\.\d+)?$")
    live_ids = await _live_plan_file_ids(project_id)
    q = {"project_id": project_id,
         "sheet_number": {"$regex": pattern, "$options": "i"},
         # A permit form numbered '0' or 'F' is not a sheet anyone can be sent.
         "is_document": {"$ne": True},
         **_current_page_filter(live_ids)}
    try:
        rows = await db.document_page_index.find(q, _PAGE_FIELDS).to_list(10)
    except Exception as e:
        logger.warning(f"named sheet lookup failed for {sheet_q}: {e!r}")
        return []
    rows.sort(key=lambda r: (len(r.get("sheet_number") or ""), not r.get("page_jpeg_r2_key")))
    return rows[:1]


def _names_a_sheet(text: str) -> bool:
    """True when the text contains something shaped like a sheet id.

    ── WHY THIS EXISTS ────────────────────────────────────────────────────
    #
    # Reported from the live test of 2026-09-14: "show me <element>" came back
    # as two drawings picked by keyword rank. The branch that sends an image
    # was gated on the VERB alone, so "show me the sprinkler riser" and "show
    # me ST-201" took the same path — and for the first of them the top two RRF
    # candidates are a guess dressed as an answer. The reader cannot tell that
    # nobody checked whether the riser is on either sheet.
    #
    # A person asking for a SHEET names the sheet. A person asking about a
    # THING names the thing. That is the distinction the image path needs, and
    # it is a property of the text rather than of the verb in front of it."""
    if not text:
        return False
    for m in _SHEET_ID_RE.finditer(text):
        if m.group(1).lower() in _SHEET_PREFIXES:
            return True
    return False


# A question whose answer is a number or a yes. These beat the show-verbs,
# which is the whole fix — see the note in _classify_plan_question.
_COUNT_PHRASING = re.compile(
    r"\b(how many|how much|number of|count (of |the )?|total (number )?of)\b", re.I)
# Existence words, which mean the same wherever they sit in the sentence.
_YES_NO_ANYWHERE = re.compile(
    r"\b(is there|are there|anywhere|do any|does any|any of)\b", re.I)

# Bare auxiliaries, which only make a yes/no question when they OPEN it.
#
# "is the" ANYWHERE was the first draft and it was wrong. It fires inside
# "what is the ceiling height on 2" — an open question whose answer is a
# measurement, and the one kind of question the reference drawing most helps
# with — so it suppressed exactly the image it should have sent. An auxiliary
# in the middle of a sentence is grammar; at the front it is a yes/no.
_YES_NO_LEADING = re.compile(
    r"^(is|are|was|were|does|do|did|has|have|can|could|should|will|any)\b", re.I)


def _is_count_or_yes_no(query: str) -> bool:
    """True when the answer is a number or a yes/no, wherever it sits."""
    if not query:
        return False
    low = re.sub(r"^@?levelog\s*[:,-]?\s*", "", query.strip().lower())
    return bool(
        _COUNT_PHRASING.search(low)
        or _YES_NO_ANYWHERE.search(low)
        or _YES_NO_LEADING.match(low)
    )


def _classify_plan_question(query: str) -> bool:
    """Return True if the user is asking a visual question about a drawing
    (VQA), False if they just want the image sent.

    ── THE SHOW-VERB USED TO WIN, AND IT SHOULD NEVER WIN OVER A COUNT ──────
    #
    Live test, 2026-09-14: "show me how many outlets are on the roof plan"
    came back as a drawing. So did "count the risers on ST-201". The first
    lost because the show-verb check ran first and returned before the
    question words were ever looked at; the second lost because "count" was
    not in the starter list and the sentence carried no question mark.
    Both are questions with a one-word answer, and a sheet is not an answer
    to either.
    #
    "Show me" in front of a count is not a request for a picture. It is how
    people ask for anything — "show me how many guys are on site" is not a
    request for a photograph of the crew. So count and yes/no phrasing is
    tested FIRST and anywhere in the sentence, not only at the front.
    #
    A bare show-verb with no question in it still sends the image, which is
    the behaviour that was right all along: "show me A-101" wants A-101.
    """
    if not query:
        return False
    low = query.strip().lower()

    # FIRST, and deliberately before the show-verbs.
    if _is_count_or_yes_no(low):
        return True

    # Explicit show-me requests with no question in them → image send
    for v in SHOW_VERBS:
        if low.startswith(v):
            return False
    # Question words at start or after "@levelog"
    stripped = re.sub(r"^@?levelog\s*[:,-]?\s*", "", low)
    question_starters = (
        "what", "how", "where", "why", "which", "when",
        "is ", "are ", "does ", "do ", "can ", "could ", "would ",
    )
    for q in question_starters:
        if stripped.startswith(q):
            return True
    if "?" in low:
        return True
    return False


async def _fetch_page_base(page_rec: dict) -> Optional[bytes]:
    """The viewer's base layer for a page, down the same three rungs the
    thumbnail uses: the stored 2048px derivative; else the full page JPEG
    downscaled here; else `_fetch_page_jpeg`'s own re-render from the source
    PDF.

    THE LADDER IS WHAT MAKES THIS SHIP WITHOUT A BACKFILL. Every v2-indexed
    plan already has a full page JPEG in R2, so rung two covers the entire
    existing plan set from the day this deploys, at the cost of one downscale
    per request until the next reindex writes rung one.
    """
    key = page_rec.get("page_base_r2_key")
    if key and _r2_client and R2_BUCKET_NAME:
        try:
            obj = await asyncio.to_thread(
                _r2_client.get_object, Bucket=R2_BUCKET_NAME, Key=key
            )
            return obj["Body"].read()
        except Exception as e:
            logger.warning(f"R2 get page base {key} failed: {e}")

    full = await _fetch_page_jpeg(page_rec)
    if not full:
        return None
    return await asyncio.to_thread(_make_page_base_jpeg, full)


async def _fetch_page_thumb(page_rec: dict) -> Optional[bytes]:
    """The list thumbnail for a page, down three rungs.

    A LADDER, NOT A LOOKUP, because the plan set on the live project predates
    this field and a blank icon is the thing being fixed:

      1. `page_thumb_r2_key`  — written at import since this change
      2. the full `page_jpeg_r2_key`, resized here — every v2-indexed page has
         one, so every plan indexed before this change still gets a thumbnail
         without a backfill, at the cost of one resize per request
      3. `_fetch_page_jpeg`'s own fallback, which re-renders from the source
         PDF — the only rung that touches poppler, and the only one a plan that
         was never indexed at all can reach

    Rung 2 is deliberately not cached back into R2 here. A GET that writes is a
    GET that can fail in a new way, and the same bytes are one `reindex` away
    from being written by the path that owns them.
    """
    key = page_rec.get("page_thumb_r2_key")
    if key and _r2_client and R2_BUCKET_NAME:
        try:
            obj = await asyncio.to_thread(
                _r2_client.get_object, Bucket=R2_BUCKET_NAME, Key=key
            )
            return obj["Body"].read()
        except Exception as e:
            logger.warning(f"R2 get page thumb {key} failed: {e}")

    full = await _fetch_page_jpeg(page_rec)
    if not full:
        return None
    return await asyncio.to_thread(_make_page_thumb_jpeg, full)


async def _fetch_page_jpeg(page_rec: dict) -> Optional[bytes]:
    """Fetch the pre-rendered JPEG for a page from R2.

    Indexed pages (v2+) store the R2 key at `page_jpeg_r2_key`. If missing
    (legacy index), fall back to on-the-fly render of the source PDF —
    slower, but keeps the query path working during the migration.
    """
    key = page_rec.get("page_jpeg_r2_key")
    if key and _r2_client and R2_BUCKET_NAME:
        try:
            obj = await asyncio.to_thread(
                _r2_client.get_object, Bucket=R2_BUCKET_NAME, Key=key
            )
            return obj["Body"].read()
        except Exception as e:
            logger.warning(f"R2 get page jpeg {key} failed: {e}")

    # Fallback: render live from the source PDF.
    file_id = page_rec.get("file_id")
    page_num = page_rec.get("page_number") or 1
    file_rec = None
    try:
        file_rec = await db.project_files.find_one({"_id": ObjectId(file_id)}) if file_id else None
    except Exception:
        file_rec = None
    if not file_rec or not file_rec.get("r2_key"):
        return None
    try:
        obj = await asyncio.to_thread(
            _r2_client.get_object, Bucket=R2_BUCKET_NAME, Key=file_rec["r2_key"]
        )
        pdf_bytes = obj["Body"].read()
    except Exception as e:
        logger.warning(f"source pdf fetch failed: {e}")
        return None
    dpi = _render_dpi_for(file_rec.get("name", ""), page_num)
    return await asyncio.to_thread(_render_pdf_page, pdf_bytes, page_num, dpi)


_VQA_PROMPT = (
    "You are answering a field question about a NYC construction drawing for "
    "a crew member on site with a phone in hand. They need a fast, specific answer.\n\n"
    "Sheet: {sheet_number} — {sheet_title}\n\n"
    "Question: {user_question}\n\n"
    "Answer format — follow exactly:\n"
    "- If the question is yes/no, START with 'Yes.' or 'No.' then the specifics.\n"
    "- If the question is 'how many / where / what size / how far', START with "
    "the count or value, THEN the dimension/location quoted from the drawing.\n"
    "- Quote dimensions, pipe sizes, materials, note numbers EXACTLY as shown "
    "(e.g. '2 floor drains, 4\\\" trap, 2'-10\\\" from building line', "
    "'3/4\\\" CW line per Note 4').\n"
    "- Maximum 40 words. No preamble. No 'based on the drawing' or 'according "
    "to this sheet'. Just the answer.\n"
    "- If multiple instances exist in different rooms/zones, list each with a "
    "1-word location tag (e.g. 'Kitchen: FD-1 at 3'-2\\\". Bath: FD-2 at wall.').\n"
    "- NEVER invent dimensions. Only quote what is literally printed on the sheet.\n"
    "- If this specific information is not shown on this sheet, reply with "
    "exactly this single word and nothing else: NOT_SHOWN_ON_SHEET"
)


# ── THE CEILING THE METER WAS BUILT TO MAKE POSSIBLE ───────────────────────
#
# lib/vision_meter.py shipped the count first and attached no limit, on the
# stated grounds that a ceiling reads a number and there was no number. There is
# one now, and turning plan queries on by default is what makes the limit
# necessary rather than theoretical: an unbounded inbound channel is now wired
# to a paid vision model with nothing between them.
#
# PER PROJECT PER DAY, BECAUSE THAT IS THE UNIT THE ROWS ALREADY HAVE.
# vision_calls is keyed (day, project_id, endpoint), and a WhatsApp group maps
# to exactly one project, so "per group" and "per project" are the same cap with
# no new bookkeeping.
#
# THE NUMBER IS A CIRCUIT BREAKER, NOT A BUDGET. A plan question costs one call
# per candidate sheet until one answers, so a handful of real questions is tens
# of calls and a loop is thousands. 300 sits far above a day of genuine use by a
# crew and far below anything that would show up on an invoice as a surprise.
# Revisit it from real rows after the trial rather than from this comment.
#
# AND IT REFUSES OUT LOUD. A silent cap would read as the bot being broken,
# which is the failure this whole change set exists to stop.
VISION_DAILY_CAP_PER_PROJECT = 300


async def _vision_budget_exceeded(project_id: Optional[str]) -> bool:
    """True when this project has already spent its day's vision calls.

    Reads the meter's own rows — there is no second counter to drift. Never
    raises: a budget check that fails open costs money, and a budget check that
    fails closed costs a superintendent his answer. Money is the cheaper one to
    be wrong about here, and the meter still records every call either way."""
    try:
        from lib.vision_meter import eastern_day, COLLECTION
        day = eastern_day()
        total = 0
        cursor = db[COLLECTION].find({
            "date": day,
            "project_id": str(project_id) if project_id else None,
            # WHATSAPP QUESTIONS ONLY. Indexing used to count here too, and at
            # four section calls a page a single re-index of an 80-sheet set
            # would spend the day's cap and refuse every plan question the
            # crew asked afterwards. Indexing is still metered, under its own
            # endpoint names; it just no longer locks the group out.
            "endpoint": {"$in": [VISION_WHATSAPP_VQA]},
        })
        async for row in cursor:
            total += int(row.get("calls") or 0)
        return total >= VISION_DAILY_CAP_PER_PROJECT
    except Exception as e:
        logger.warning(f"vision budget check failed (allowing): {e}")
        return False


# WHAT A PERSON WILL WAIT FOR, STANDING ON A SITE. The budget was 90 seconds,
# and on 2026-09-16 two questions spent all of it and returned nothing: 98 s
# and 92 s end to end, for "Not found on the indexed drawings." The model
# either reads a plan page well inside this or it is not going to, and the
# candidate loop in _handle_plan_query moves to the next sheet when it does
# not — so a slow sheet now costs a retry rather than the whole reply.
PLAN_VQA_TIMEOUT_SECONDS = 30.0


async def _qwen_visual_qa(jpeg_bytes: bytes, question: str,
                           sheet_number: str, sheet_title: str,
                           project_id: Optional[str] = None) -> Optional[str]:
    """Ask Qwen2.5-VL a question about a single rendered plan page.
    Returns plain-text answer (possibly 'NOT_SHOWN_ON_SHEET'), or None on failure.

    `project_id` is metering only — it never reaches the model. It is optional
    so an existing caller cannot break by omitting it; those calls count under
    "unknown" rather than not at all."""
    if not QWEN_API_KEY or not jpeg_bytes:
        return None

    # COUNTED PER SHEET, NOT PER QUESTION. _handle_plan_query walks its
    # candidate list and calls this once for each until one answers, so a
    # question about something the set does not show costs the length of the
    # list. A per-question count would hide exactly that case.
    #
    # After the QWEN_API_KEY guard, because a call that was never made is not
    # spend; before the post, because a call that 500s has still been billed.
    await record_vision_call(
        db, endpoint=VISION_WHATSAPP_VQA, project_id=project_id,
    )
    b64 = base64.b64encode(jpeg_bytes).decode("ascii")
    prompt = _VQA_PROMPT.format(
        sheet_number=sheet_number or "(unknown)",
        sheet_title=sheet_title or "(unknown)",
        user_question=question.strip(),
    )
    try:
        async with ServerHttpClient(timeout=PLAN_VQA_TIMEOUT_SECONDS) as client_http:
            resp = await client_http.post(
                f"{QWEN_API_BASE}/chat/completions",
                headers={
                    "Authorization": f"Bearer {QWEN_API_KEY}",
                    "Content-Type": "application/json",
                },
                json={
                    "model": QWEN_MODEL,
                    "max_tokens": 300,
                    "temperature": 0,
                    "messages": [{
                        "role": "user",
                        "content": [
                            {"type": "image_url",
                             "image_url": {"url": f"data:image/jpeg;base64,{b64}"}},
                            {"type": "text", "text": prompt},
                        ],
                    }],
                },
            )
            if resp.status_code != 200:
                logger.warning(f"Qwen VQA returned {resp.status_code}")
                return None
            return (resp.json()["choices"][0]["message"]["content"] or "").strip()
    except Exception as e:
        # SITE 3 OF 5, AND IT CARRIED THE EXACT DEFECT THE GATE DID. `{e}` is
        # `str(e)`, and `str(httpx.ReadTimeout())` is the empty string — this
        # line logged `Qwen VQA failed: ` for every timeout, on a 90 s budget,
        # against the same unbounded-tail model. WhatsApp plan QA had no live
        # traffic during the 09-11 -> 09-15 window, so it cost nothing; it was
        # the same trap, unsprung.
        if isinstance(e, (httpx.TimeoutException, asyncio.TimeoutError)):
            # Not worth a stack trace: it is the budget doing its job, and the
            # caller has another candidate to try. Named explicitly because
            # str(httpx.ReadTimeout()) is the empty string.
            logger.warning("Qwen VQA timed out after %ss sheet=%s (model=%s)",
                           PLAN_VQA_TIMEOUT_SECONDS, sheet_number, QWEN_MODEL)
            return None
        logger.exception("Qwen VQA failed: %r (model=%s)", e, QWEN_MODEL)
        return None


def _compress_jpeg_for_whatsapp(src_bytes: bytes, max_dim: int = 4800,
                                  max_size_bytes: int = 15 * 1024 * 1024,
                                  min_quality: int = 55) -> bytes:
    """Resize + re-encode a JPEG so it fits WaAPI's media delivery limits.

    Resolution doubled vs. the previous pass — max_dim 2400 → 4800,
    ceiling 4 MB → 15 MB (WaAPI's stated limit is ~16 MB; we leave
    a ~1 MB safety margin for multipart overhead). Quality ladder
    starts at 90 so the first-try encoding is noticeably sharper on
    construction drawings where dimension text was borderline
    legible at q=85.

    The iterative step-down preserves the original "best-effort,
    never block the send" behavior: we try q=90 → 85 → 80 → 75 → 70
    → 65 → min_quality and return the first encoding under the
    ceiling. If even the lowest quality is oversized, we still ship
    it (WaAPI may downscale further but at least the crew gets
    SOMETHING).
    """
    try:
        from PIL import Image
        import io as _io
        img = Image.open(_io.BytesIO(src_bytes))
        if img.mode not in ("RGB", "L"):
            img = img.convert("RGB")
        # Downscale if the larger side exceeds max_dim
        w, h = img.size
        longest = max(w, h)
        if longest > max_dim:
            scale = max_dim / longest
            img = img.resize((int(w * scale), int(h * scale)), Image.LANCZOS)
        # Iteratively lower quality until we fit.
        for q in (90, 85, 80, 75, 70, 65, min_quality):
            buf = _io.BytesIO()
            img.save(buf, format="JPEG", quality=q, optimize=True)
            data = buf.getvalue()
            if len(data) <= max_size_bytes:
                return data
        return data  # best-effort — even if over, ship it
    except Exception as e:
        logger.warning(f"jpeg compress failed: {e}")
        return src_bytes


async def _send_plan_image(
    group_id: str, page_rec: dict, caption: str,
) -> bool:
    """Fetch a page's pre-rendered JPEG from R2, downscale to WhatsApp-safe
    size, upload to R2 via presigned URL, and send-image to the group.
    Returns True on success."""
    sheet_ref = page_rec.get("sheet_number") or page_rec.get("_id")
    jpeg_src = await _fetch_page_jpeg(page_rec)
    if not jpeg_src:
        logger.warning(
            f"plan send: jpeg fetch returned empty for sheet={sheet_ref} "
            f"key={page_rec.get('page_jpeg_r2_key')}"
        )
        return False
    jpeg = await asyncio.to_thread(_compress_jpeg_for_whatsapp, jpeg_src)
    logger.info(
        f"plan send: jpeg ok for sheet={sheet_ref} "
        f"src_size={len(jpeg_src)} compressed_size={len(jpeg)}"
    )
    import uuid as _uuid
    temp_key = f"temp/whatsapp/{group_id}/{_uuid.uuid4()}.jpg"
    try:
        await asyncio.to_thread(_upload_to_r2, jpeg, temp_key, "image/jpeg")
        # WaAPI does a HEAD preflight. R2 presigned URLs are method-scoped
        # (signed GET returns 403 on HEAD), so we hand WaAPI a URL that
        # points to our own backend proxy — it handles HEAD+GET cleanly.
        tok = await _mint_temp_media_token(temp_key, "image/jpeg", ttl_seconds=3600)
        media_url = _public_temp_media_url(tok)
    except Exception as e:
        logger.warning(f"plan send: temp upload failed sheet={sheet_ref}: {e}")
        return False
    # WaAPI endpoint is `send-media` with a `mediaUrl` field (NOT send-image
    # with `image`, which returns 404). Discovered via probe-waapi-endpoints.
    try:
        async with ServerHttpClient(timeout=40.0) as client_http:
            resp = await client_http.post(
                f"{WAAPI_BASE_URL}/instances/{WAAPI_INSTANCE_ID}/client/action/send-media",
                headers={
                    "Authorization": f"Bearer {WAAPI_TOKEN}",
                    "Content-Type": "application/json",
                },
                json={
                    "chatId":   group_id,
                    "mediaUrl": media_url,
                    "caption":  caption,
                },
            )
            ok = 200 <= resp.status_code < 300
            body_preview = ""
            try:
                body_preview = resp.text[:400]
            except Exception:
                pass
            logger.info(
                f"plan send: WaAPI send-media status={resp.status_code} ok={ok} "
                f"sheet={sheet_ref} body={body_preview!r}"
            )
            if ok:
                # WaAPI sometimes returns 200 with {data: {status: 'error'}}.
                try:
                    j = resp.json()
                    if isinstance(j, dict):
                        inner = j.get("data") or {}
                        if isinstance(inner, dict) and inner.get("status") == "error":
                            logger.warning(
                                f"plan send: WaAPI data.status=error: {inner}"
                            )
                            return False
                except Exception:
                    pass
            return ok
    except Exception as e:
        logger.warning(f"WaAPI send-media exception sheet={sheet_ref}: {e}")
        return False


# Words that carry no element. Stripped before a literal text search, because
# "the" appears on every page ever indexed and would make every sheet a match.
_ELEMENT_STOPWORDS = frozenset({
    "show", "me", "the", "a", "an", "of", "on", "in", "at", "for", "to",
    "please", "pull", "up", "send", "find", "get", "display", "open",
    "levelog", "plan", "plans", "drawing", "drawings", "sheet", "sheets",
    "where", "is", "are", "what", "which", "any",
})


def _element_terms(query: str, parsed: dict) -> list:
    """The thing being asked about, as words to look for in a page's text.

    The parser's `keywords` are preferred — it has already read the sentence
    and pulled out the subject. The raw query minus stopwords is the fallback
    for when it returns nothing, which it does on short requests."""
    kws = parsed.get("keywords") or []
    terms = [str(k).strip().lower() for k in kws if str(k).strip()]
    if not terms:
        terms = [w for w in re.findall(r"[a-z0-9]+", (query or "").lower())
                 if w not in _ELEMENT_STOPWORDS and len(w) > 2]
    # Two terms is enough to be specific and few enough that an AND over them
    # still matches a page that phrases it differently.
    return terms[:2]


# The fields the indexer fills from what it read off the page. A literal search
# runs over THESE and nothing else: `embedding` is a guess by construction and
# file_name is about the upload, not the drawing.
_ELEMENT_TEXT_FIELDS = (
    "keywords", "summary", "materials", "spaces", "notes",
    "sheet_title", "detail_refs", "dimensions",
)


async def _pages_with_element(project_id: str, terms: list, limit: int = 8) -> list:
    """Pages whose EXTRACTED TEXT actually mentions the element.

    ── WHY THIS IS NOT THE RETRIEVAL ABOVE ────────────────────────────────
    #
    # _retrieve_plan_candidates fuses a vector rank and a keyword rank and
    # returns its top three. That is the right instrument for "which sheet is
    # most like this question" and the wrong one for "which sheets mention
    # roof drains", because its top three are ALWAYS populated — it cannot
    # return nothing, so it can never say the thing is not there.
    #
    # This asks the literal question. Every term has to appear, somewhere in
    # what the indexer extracted from that page. No match is a real answer.
    #
    # ORDERING PUTS THE STRONGEST EVIDENCE FIRST. A page whose `keywords` name
    # the element is a page the indexer thought the element was ABOUT; a page
    # that merely mentions it in a note is weaker. The primary sheet sent to
    # the group is the first of these, so the ordering is the difference
    # between sending the riser diagram and sending a page that says "see
    # riser diagram"."""
    if not (project_id and terms):
        return []
    clauses = []
    for t in terms:
        # ── A PLURAL MUST FIND THE SINGULAR ────────────────────────────────
        #
        # Measured against a stubbed index: "show me the roof drains" found the
        # roof plan and MISSED the riser diagram, whose summary reads "roof
        # drain leaders to riser". A literal search is the right instrument
        # here and a literal search that cannot see past an "s" answers "on one
        # sheet" when the truth is two.
        #
        # The stem, not a stemmer. Dropping a trailing s (and the e of "es")
        # covers how these words actually differ on a drawing — drain/drains,
        # riser/risers, box/boxes — and a real stemmer would turn "gas" into
        # "ga" and match everything.
        needle = t
        if len(needle) > 3 and needle.endswith("es"):
            needle = needle[:-2]
        elif len(needle) > 3 and needle.endswith("s"):
            needle = needle[:-1]
        rx = {"$regex": re.escape(needle), "$options": "i"}
        clauses.append({"$or": [{f: rx} for f in _ELEMENT_TEXT_FIELDS]})
    live_ids = await _live_plan_file_ids(project_id)
    q = {"project_id": str(project_id), "$and": clauses}
    q.update(_current_page_filter(live_ids))
    try:
        rows = await db.document_page_index.find(
            q, _PAGE_FIELDS,
        ).limit(max(limit * 4, 32)).to_list(max(limit * 4, 32))
    except Exception as e:
        logger.warning(f"element lookup failed for {terms}: {e}")
        return []

    def _rank(rec):
        kws = " ".join(str(k).lower() for k in (rec.get("keywords") or []))
        in_keywords = sum(1 for t in terms if t in kws)
        title = (rec.get("sheet_title") or "").lower()
        in_title = sum(1 for t in terms if t in title)
        # Negated so a plain ascending sort puts the strongest first.
        return (-in_keywords, -in_title, str(rec.get("sheet_number") or "~"))

    rows.sort(key=_rank)
    return rows[:limit]


async def _current_v3_chunks(project_id: str) -> list:
    """Every chunk on a current (live, not superseded) version 3 page. Empty
    for a project that has not been indexed at version 3 — the caller then
    keeps the version 2 path, unchanged."""
    live_ids = await _live_plan_file_ids(str(project_id))
    pages = await db.document_page_index.find(
        # Spec pages included: their notes are chunks too (S-001.00).
        {"project_id": str(project_id), "index_version": {"$gte": 3},
         **_current_page_filter(live_ids)},
        {"_id": 1},
    ).to_list(5000)
    if not pages:
        return []
    return await db.document_page_chunks.find(
        {"project_id": str(project_id),
         "page_id": {"$in": [str(p["_id"]) for p in pages]}},
        {"embedding": 0},
    ).to_list(20000)


async def _answer_plan_from_chunks(project_id: str, route_text: str,
                                   parsed: dict) -> Tuple[bool, Optional[dict]]:
    """(project_has_v3, answer). Answer is {"text", "outcome"} or None.

    ── A NUMBER IS READ, NEVER LOOKED AT ──────────────────────────────────
    #
    # "how many piles" used to go to a vision model with a picture of a sheet,
    # and a vision model asked to count symbols on a 36-inch drawing produces a
    # number with nothing behind it. On a version 3 project the answer comes
    # from what is PRINTED: a quantity in a schedule, or a tag the page text
    # confirms. No printed quantity is "not stated", with the sheets that
    # mention the thing — never an estimate.
    #
    # Existence ("are there chase walls") and attributes ("stucco thickness",
    # "post gauge", "pile type") are answered from the note, legend, schedule
    # and spec lines, quoting the line. An attribute with no line carrying a
    # value is answered by a schedule named for the thing if the set has one,
    # then by naming the sheets that mention it; only a subject the drawings
    # never name at all falls through to the vision model.
    """
    # THE TEXT IS READ BEFORE ANY PICTURE IS LOOKED AT. This used to ask
    # question_kind() first and skip the chunk lookup entirely when it came
    # back None — so "Whats the helical piles" and "What piles used on site?"
    # never touched the index and went to the vision model, which spent 90
    # seconds and answered nothing, while S-001.00 had HELICAL PILES printed
    # on it. Classification chooses the SHAPE of the answer, never whether to
    # look at all. A question that reaches the vision model without the
    # drawings' own text having been searched is a bug;
    # tests/test_plan_chunks_first.py asserts the order.
    chunks = await _current_v3_chunks(project_id)
    if not chunks:
        # Cheap existence probe for the caller's top-1 decision.
        has_v3 = bool(await db.document_page_chunks.find_one(
            {"project_id": str(project_id)}, {"_id": 1}))
        return has_v3, None
    # The same function the local harness calls, so a before-merge run answers
    # exactly what WhatsApp would.
    return True, plan_extract.answer_question(chunks, route_text, parsed.get("keywords"))


# ══════════════════════════════════════════════════════════════════════════
# search_plans — the agent asks, the records answer, the gate checks
# ══════════════════════════════════════════════════════════════════════════
#
# The DB half lives here and the ranking half lives in lib/plan_search.py, so
# the ordering that decides what an answer may cite is testable without Mongo.
#
# Supersession is resolved the same way _current_v3_chunks resolves it — via
# document_page_index — because `superseded_by` is a property of a PAGE and
# putting a second copy of it on every record is how the two drift apart.

SEARCH_PLANS_MAX = 12
# Candidates fetched before ranking. Measured on 588 Boyland: the commonest
# single word ('floor') matches 578 records of 15,369. Ranking a few thousand
# dicts in Python costs milliseconds; ranking an arbitrary subset costs answers.
SEARCH_PLANS_CANDIDATES = 3000


async def _current_record_page_ids(project_id: str, *, discipline: str = "",
                                   floor: str = "", sheet_number: str = "") -> list:
    """The page ids a search may read from: live file, not superseded."""
    live_ids = await _live_plan_file_ids(str(project_id))
    q = {"project_id": str(project_id), **_current_page_filter(live_ids)}
    if sheet_number:
        q["sheet_number"] = {"$regex": f"^{re.escape(sheet_number)}",
                             "$options": "i"}
    if discipline:
        q["discipline"] = {"$regex": f"^{re.escape(discipline)}$", "$options": "i"}
    if floor:
        q["floors"] = {"$regex": re.escape(floor), "$options": "i"}
    pages = await db.document_page_index.find(q, {"_id": 1}).to_list(5000)
    return [str(p["_id"]) for p in pages]


async def search_plans(project_id: str, subject: str, *, intent: str = "",
                       discipline: str = "", floor: str = "",
                       sheet_number: str = "", limit: int = 8) -> List[dict]:
    """The records on this project's current sheets that speak to `subject`.

    Returns RECORDS, not prose. The agent composes; `answer_is_grounded` then
    decides whether what it composed may be sent."""
    terms = plan_search.search_terms(subject)
    if not (project_id and terms):
        return []
    page_ids = await _current_record_page_ids(
        project_id, discipline=discipline, floor=floor, sheet_number=sheet_number)
    if not page_ids:
        return []
    # ── MATCHED IN THE DATABASE, RANKED IN PYTHON ──────────────────────────
    #
    # Mongo narrows to the rows that contain ANY term — a cheap OR over the
    # three matchable fields, including `label`, which is how a vision-read
    # word widens the search without ever becoming an answer. Ranking is the
    # part that decides what may be cited, so it happens where it is tested.
    #
    # THE SAME WORD PATTERN THE RANKER USES. This narrowed with an unanchored
    # regex, so 'air' fetched every row that prints STAIRS — and with the
    # unsorted cap below, a flood of those could push the real matches out of
    # the candidate set before ranking ever saw them.
    per_term = []
    for t in terms:
        rx = {"$regex": plan_search.term_pattern(t), "$options": "i"}
        per_term.append([{"quote": rx}, {"label": rx}, {"subject_terms": rx}])
    scope = {"project_id": str(project_id), "page_id": {"$in": page_ids}}
    proj = {"_id": 0, "embedding": 0}
    # ── THE CAP MUST NOT DECIDE WHAT GETS RANKED ───────────────────────────
    #
    # This was one `$or` query with `.limit(400)` and no sort. On 588 Boyland
    # the single word 'floor' matches 578 records, so which 400 reached the
    # ranker was whatever order the collection returned them in — and a record
    # that answered the WHOLE question could be among the 178 left behind.
    #
    # So the records that contain every term are fetched first, in full; the
    # ones that contain any term fill the rest; and a query that still hits
    # the ceiling says so in the log rather than ranking a silent sample.
    rows: List[dict] = []
    seen = set()

    def _take(batch):
        for r in batch:
            k = (r.get("page_id"), r.get("record_type"), r.get("ordinal"))
            if k not in seen:
                seen.add(k)
                rows.append(r)

    try:
        if len(per_term) > 1:
            _take(await db[PLAN_RECORDS].find(
                {**scope, "$and": [{"$or": ors} for ors in per_term]}, proj,
            ).limit(SEARCH_PLANS_CANDIDATES).to_list(SEARCH_PLANS_CANDIDATES))
        room = SEARCH_PLANS_CANDIDATES - len(rows)
        if room > 0:
            anyof = await db[PLAN_RECORDS].find(
                {**scope, "$or": [c for ors in per_term for c in ors]}, proj,
            ).limit(room + len(rows)).to_list(room + len(rows))
            _take(anyof)
            if len(anyof) >= room + len(rows):
                logger.warning(
                    f"search_plans candidate cap {SEARCH_PLANS_CANDIDATES} reached "
                    f"for {subject!r}; records matching only some terms were cut")
    except Exception as e:
        logger.warning(f"search_plans lookup failed for {subject!r}: {e}")
        return []
    ranked = plan_search.rank(rows, terms, intent)
    # ── A LABEL MAY FIND A RECORD; IT MAY NOT MAKE ONE AN ANSWER ───────────
    #
    # Measured by the plan eval, 2026-09-17: 'what is a kicker' returned the
    # two legend entries on M-104.00 whose quotes are 'KE 1' and 'KE 2' and
    # whose only tie to the question is the vision label 'KICKER EXHAUST'.
    # The agent is never shown a label, but it is shown the question and the
    # marks, and 'KE 1 is a kicker' follows from nothing else. contains_label
    # cannot catch that — the answer need not contain the label string.
    #
    # There is no way to offer a label-only match as an answer without
    # asserting what the label says, so none is offered, on either path. The
    # label still widens retrieval for a record that ALSO matches on words the
    # sheet prints; that is the only use #568 needed it for.
    ranked = [r for r in ranked
              if not plan_search.matched_only_through_label(r, terms)]
    return plan_search.best_per_attribute(ranked)[:max(1, min(limit, SEARCH_PLANS_MAX))]


def _render_records_for_model(records: List[dict], subject: str) -> str:
    """What the agent is shown. Every line carries where it came from and how
    strong it is, because those are the two things the model must not have to
    guess at — and the numbers it is allowed to use are the ones printed
    here."""
    if not records:
        return (f"(No record on the current drawings mentions {subject!r}. "
                f"Say it is not on the indexed drawings; do not estimate.)")
    lines = [f"{len(records)} record(s) for {subject!r}. "
             f"Use ONLY numbers that appear below; an answer containing any "
             f"other number will be discarded and replaced."]
    for r in records:
        where = r.get("sheet_number") or f"p{r.get('page_number')}"
        quote = re.sub(r"\s+", " ", (r.get("quote") or "")).strip()[:400]
        line = f"- [{where} | {r.get('record_type')} | {r.get('tier')}] {quote}"
        if r.get("tier") == plan_extract.TIER_VISION:
            line += " (read off the image — say so if you use it)"
        elif r.get("tier") == plan_extract.TIER_OCR_GRID:
            # A real printed cell, in the cell the ruling lines define. It is
            # still a transcription, and the sheet is the authority.
            line += " (transcribed from the printed schedule)"
        elif (r.get("payload") or {}).get("glyph_scope") == "family":
            # The shape matched; nothing was printed inside it to say WHICH
            # member. Saying 'two W1 windows' here would be the 41 again.
            line += " (a count of the symbol, not of any one marked type)"
        lines.append(line)
    return "\n".join(lines)


def gate_plan_answer(text: str, records: List[dict], subject: str = ""
                     ) -> Tuple[str, str]:
    """(text_to_send, outcome). THE HARD GATE.

    Every number and dimension in a composed answer must appear in a record
    that was actually returned. One that does not means the model supplied it,
    and a supplied number on a jobsite reads exactly like a measured one. The
    answer is not edited or warned about — it is replaced by a render of the
    records themselves, which can only say what the sheets say.

    A vision-read label is checked the same way and for the same reason: those
    words came from a model looking at a picture, and KICKER and PACKAGE
    TERMINAL AIR CONDITIONER arrived by the identical path."""
    if not records:
        return text, "no_records"
    grounded, unsupported = plan_search.answer_is_grounded(text, records)
    leaked = plan_search.contains_label(text, records)
    if grounded and not leaked:
        return text, "grounded"
    logger.warning(
        "plan answer failed the gate: unsupported=%s labels=%s subject=%r text=%r",
        unsupported[:6], leaked[:3], subject[:40], (text or "")[:200])
    return plan_search.render_records(records, subject), (
        "ungrounded" if not grounded else "label_leak")


def _log_plan_timing(group_id: str, query: str, stage: dict, outcome: str) -> None:
    """One line per plan question, every stage named.

    Read it with: grep 'plan timing' on the app log. The shape is deliberately
    flat and greppable rather than JSON — this exists to survive one live test,
    not to feed a dashboard."""
    total = round(sum(v for k, v in stage.items() if k != "candidates"), 2)
    parts = " ".join(f"{k}={v}" for k, v in stage.items())
    logger.warning(
        f"plan timing outcome={outcome} total={total}s {parts} "
        f"group={group_id[-10:] if group_id else '?'} q={query[:60]!r}"
    )


async def _handle_plan_query(project_id: str, group_id: str, query: str,
                              question: Optional[str] = None,
                              parsed_override: Optional[dict] = None,
                              reply_to: Optional[str] = None,
                              user_body: Optional[str] = None) -> None:
    """End-to-end plan-query pipeline (spec-compliant v2).

    Flow:
      1. Immediate ack.
      2. Parse → structured spec (sheet_number, discipline, floor, keywords,
         question, dob_route). Bail to DOB handler if dob_route.
      3. Retrieve: sheet-number exact match first; else vector + keyword
         with Reciprocal Rank Fusion. Top 3 candidates.
      4. If parser says no question (show-me verb) → send top 1 or 2 images.
      5. If parser extracted a question → VQA loop through candidates.
    """
    if not QWEN_API_KEY:
        await send_whatsapp_message(group_id, "Plan queries are not configured.",
                                    reply_to=reply_to)
        return

    # THE CEILING, CHECKED BEFORE THE ACK. Checking it after would promise to go
    # look and then refuse, which reads worse than a straight no. See
    # VISION_DAILY_CAP_PER_PROJECT for why the cap exists and why it speaks.
    if await _vision_budget_exceeded(project_id):
        await send_whatsapp_message(
            group_id,
            "I've hit today's limit on drawing lookups for this project. "
            "Open the sheet in the app, or ask me again tomorrow.",
            reply_to=reply_to,
        )
        logger.warning(f"vision daily cap hit for project {project_id}")
        return

    # NOTHING TO SHOW. Checked on the user's own words, before the "checking
    # the drawings" ack — there is nothing to check — and before anything the
    # agent put in the query, because for a bare "show me" that is a guess.
    if _is_bare_show_request(user_body):
        await send_whatsapp_message(group_id, "Nothing to show for that — which sheet?",
                                    reply_to=reply_to)
        logger.info(f"plan route group={group_id[-10:] if group_id else '?'} bare show request")
        return

    # ── THE NUMBERS THE LATENCY FIX WILL BE BUILT FROM ─────────────────────
    #
    # Reported: plan Q&A takes about sixty seconds. There is no instrumentation
    # anywhere on this path, so every explanation available today is arithmetic
    # off the call chain rather than a measurement, and optimising against
    # arithmetic is how the wrong stage gets cut.
    #
    # One log line per answered question, with each stage named. Deliberately
    # not a metrics backend: this has to survive one live test in one group
    # next week, and a log line does that with nothing to stand up.
    #
    # NOTHING BELOW CHANGES BEHAVIOUR. The stages are timed where they already
    # happen, in the order they already happen.
    _t0 = perf_counter()
    _stage = {}

    def _mark(name):
        nonlocal _t0
        now = perf_counter()
        _stage[name] = round(now - _t0, 2)
        _t0 = now

    # 1. Immediate ack (needs to be fast — construction sites have poor signal)
    try:
        await send_whatsapp_message(group_id, "🔎 Checking the drawings…",
                                    reply_to=reply_to)
    except Exception:
        pass

    # 2. Parse — prefer the structured spec from the agent router if it's
    # available (avoids a second gpt-4o-mini call and a lossy re-parse of
    # the synth string).
    if isinstance(parsed_override, dict) and parsed_override:
        parsed = dict(parsed_override)
    else:
        parsed = await _parse_plan_query(query)
    _mark("parse")
    if parsed.get("dob_route"):
        # Parser flagged this as a DOB/permits question — route to dob_status.
        txt = await _handle_dob_status(project_id)
        await send_whatsapp_message(group_id, txt, reply_to=reply_to)
        return

    # `question` param from the agent-router overrides parser's question —
    # except the agent often hallucinates a question for "show me" phrases
    # where the user clearly wants the image, not an answer. Check for
    # show-verb prefix in BOTH the synth query AND the agent's question
    # (agent frequently echoes the user's full "show me..." utterance into
    # the question slot). If either looks like a show-verb request, force
    # image-send mode.
    def _looks_like_show_verb(s: str) -> bool:
        s = (s or "").strip().lower()
        return any(s.startswith(v) for v in SHOW_VERBS)

    # ── THE DECISION IS MADE ON WHAT THE USER TYPED ────────────────────────
    #
    # Live test, 2026-09-14 23:33: "how many piles" came back as two drawings
    # and "show me roof drains" came back with no text at all. Same cause.
    #
    # `query` here is NOT the user's message. _dispatch_agent_tool builds it
    # from the agent's STRUCTURED arguments —
    #
    #     bits = [discipline, floor, sheet_type, sheet_number, *keywords]
    #     synth = " ".join(bits) or question or "plan"
    #
    # — so it arrives as something like "structural pile". No show verb, no
    # question mark, no question word. Every routing test below was therefore
    # being run against a bag of keywords rather than a sentence:
    #
    #   _looks_like_show_verb("structural pile")     -> False, always
    #   _classify_plan_question("structural pile")   -> False, always
    #
    # With `question` empty — which the agent leaves empty whenever it reads
    # the request as a search — effective_question stayed None and control fell
    # into the image-send branch, which ships up to two sheets with captions
    # and NO TEXT LINE. That is both reported symptoms, from one fault.
    #
    # It also made the element path unreachable: offer_only can only be set
    # when wants_image is true, and wants_image needed a show verb that the
    # synth can never contain.
    #
    # `user_body` is the message as sent. The synth stays as the RETRIEVAL
    # input, which is what it is good at — structured bits make a better
    # search than a sentence — and the routing now reads the sentence.
    route_text = (user_body or "").strip() or query
    offer_only = False

    # A count or a yes/no beats a show verb, exactly as _classify_plan_question
    # already orders them. "show me how many piles" is a question with a
    # one-word answer, not a request for a picture.
    asks_for_a_value = _is_count_or_yes_no(route_text)
    wants_image = (not asks_for_a_value) and (
        _looks_like_show_verb(route_text) or _looks_like_show_verb(question or "")
    )

    if wants_image:
        effective_question = None
        if not (parsed.get("sheet_number") or _names_a_sheet(route_text)
                or _names_a_sheet(question or "")):
            offer_only = True
    else:
        effective_question = (question or "").strip() or parsed.get("question")
        if effective_question and effective_question.strip().lower() in ("null", "none", ""):
            effective_question = None
        # The user's own sentence is the fallback question, not the synth. A
        # bag of keywords put to a vision model is a worse prompt than the
        # thing the person actually asked.
        if not effective_question and _classify_plan_question(route_text):
            effective_question = route_text
        # A show-verb request with no sheet named is an ELEMENT request even
        # when the agent supplied no question, which is the case that fell
        # through to images.
        if (not effective_question
                and _looks_like_show_verb(route_text)
                and not (parsed.get("sheet_number") or _names_a_sheet(route_text))):
            offer_only = True

    logger.info(
        f"plan route group={group_id[-10:] if group_id else '?'} "
        f"offer_only={offer_only} vqa={bool(effective_question)} "
        f"synth={query[:40]!r} body={route_text[:60]!r}"
    )

    # 2b. Version 3: counts, existence and attributes from the extracted text,
    # with no vision call. A request for a picture keeps the paths below.
    has_v3 = False
    if not wants_image and not offer_only:
        try:
            has_v3, chunk_answer = await _answer_plan_from_chunks(
                project_id, route_text, parsed)
        except Exception as e:
            logger.warning(f"chunk answer failed, using v2 path: {e!r}")
            chunk_answer = None
        _mark("chunks")
        if chunk_answer:
            await send_whatsapp_message(group_id, chunk_answer["text"],
                                        reply_to=reply_to)
            _log_plan_timing(group_id, query, _stage, chunk_answer["outcome"])
            return

    # 3. Retrieve. A NAMED SHEET IS AN EXACT LOOKUP, NEVER A SEARCH: the sheet
    # the person typed, or the one the agent mapped their words to. See
    # _find_named_sheet — neighbours are never sent in its place.
    named_sheet = (_requested_sheet_id(route_text) or _requested_sheet_id(question or "")
                   or (parsed.get("sheet_number") or "").strip() or None)
    if named_sheet:
        candidates = await _find_named_sheet(project_id, named_sheet)
        _mark("retrieval")
        _stage["candidates"] = len(candidates)
        if not candidates:
            await send_whatsapp_message(
                group_id, f"{named_sheet.upper()} isn't in the indexed drawings.",
                reply_to=reply_to)
            _log_plan_timing(group_id, query, _stage, "named_sheet_not_found")
            return
        if not candidates[0].get("page_jpeg_r2_key"):
            label = candidates[0].get("sheet_number") or named_sheet.upper()
            await send_whatsapp_message(
                group_id,
                (f"{label} is a notes sheet — indexed, can't render yet."
                 if candidates[0].get("is_spec_page")
                 else f"{label} is indexed, but its image isn't available yet."),
                reply_to=reply_to)
            _log_plan_timing(group_id, query, _stage, "named_sheet_no_image")
            return
    else:
        candidates = await _retrieve_plan_candidates(
            project_id, parsed, query, limit=3
        )
        _mark("retrieval")
        _stage["candidates"] = len(candidates)
    # A version 3 project sends a spatial question to the vision model on the
    # two best sheets. Three tripled the latency and the spend for an answer
    # the first sheet either has or does not; one left nothing to fall back on
    # when the first call timed out, which is what "Whats the helical piles"
    # did on 2026-09-16 — candidates=1, one 90-second timeout, 98 seconds to
    # "not found". At PLAN_VQA_TIMEOUT_SECONDS the pair still costs less than
    # the single call used to.
    if has_v3 and effective_question:
        candidates = candidates[:2]
    if not candidates:
        await send_whatsapp_message(
            group_id,
            # "Try a sheet number (A-301, ME-401)" was the old copy, and it is
            # the exact thing the stance forbids: it hands the problem back to
            # a superintendent who does not carry the drawing list in his head.
            # The agent now has the full sheet index in its context, so it can
            # map a description onto a sheet itself — and when retrieval finds
            # nothing, the honest report is that nothing matched, not homework.
            "Nothing in the indexed drawings matched that. If the plans were "
            "uploaded recently, they may still be indexing.",
            reply_to=reply_to,
        )
        return

    # 4a-offer. A show-verb with no sheet named: say where it is, do not
    # assert that it is there by sending the page.
    if offer_only:
        # ── AN ANSWER, NOT A QUESTION BACK ─────────────────────────────────
        #
        # The first version of this named the sheets and asked "Want them?".
        # That is still a round trip: a superintendent who typed "show me the
        # roof drains" has already said what he wants, and answering a request
        # with a request is the thing the sixty-second latency makes
        # unbearable. He gets the answer and the sheet, in one turn.
        #
        # AND THE SHEETS ARE FOUND BY TEXT, NOT BY RANK. The retrieval above
        # is a fused vector-plus-keyword guess, which is the right instrument
        # for "which sheet is most like this question" and the wrong one for
        # "which sheets actually mention roof drains" — its top three are
        # always populated, so it can never say no. `_pages_with_element` asks
        # the second question literally: the element's words have to appear in
        # what the indexer extracted from that page. A sheet that does not
        # mention the thing is not sent, and when nothing mentions it the
        # answer is that nothing does.
        terms = _element_terms(query, parsed)
        matches = await _pages_with_element(project_id, terms)
        _mark("element_lookup")
        _stage["matches"] = len(matches)
        if not matches:
            _log_plan_timing(group_id, query, _stage, "element_not_found")
            await send_whatsapp_message(
                group_id, "Not found on indexed drawings.", reply_to=reply_to,
            )
            return

        subject = " ".join(terms).strip() or "That"
        where = []
        for rec in matches[:4]:
            sn = rec.get("sheet_number") or "?"
            title = (rec.get("sheet_title") or "").strip()
            where.append(f"{sn} ({title})" if title else sn)
        await send_whatsapp_message(
            group_id,
            f"{subject[:1].upper()}{subject[1:]}: {', '.join(where)}.",
            reply_to=reply_to,
        )

        # The primary sheet, in the same turn. First is the best-matching one
        # that actually mentions the element — see _pages_with_element for the
        # ordering — so this is never a guess dressed as an answer.
        primary = matches[0]
        caption = (f"{primary.get('sheet_number') or 'Sheet'} — "
                   f"{primary.get('sheet_title') or ''}").strip(" —")
        try:
            await _send_plan_image(group_id, primary, caption)
        except Exception as e:
            logger.warning(f"primary sheet send failed for {caption}: {e}")
        _log_plan_timing(group_id, query, _stage, "element_answered")
        return

    # 4a. Image-send path (parser said user wants the image, no question)
    if not effective_question:
        # Send top 1-2 candidates.
        sent_any = False
        for i, rec in enumerate(candidates[:2]):
            sheet_number = rec.get("sheet_number") or "Sheet"
            sheet_title  = rec.get("sheet_title")  or "Construction Drawing"
            caption = f"{sheet_number} — {sheet_title}"
            ok = await _send_plan_image(group_id, rec, caption)
            if ok:
                sent_any = True
            else:
                # Text fallback if image send fails
                await send_whatsapp_message(
                    group_id,
                    f"Found: {caption}. Open it in the Levelog app under Plans & Files.",
                    reply_to=reply_to,
                )
            if i + 1 < min(2, len(candidates)):
                await asyncio.sleep(1.2)
        if not sent_any:
            logger.info(
                f"plan query image send: all {len(candidates[:2])} candidates failed"
            )
        # THE EXIT THAT LOGGED NOTHING. Both reported failures ended here and
        # left no line in the log, so "which path handled it" could not be
        # answered from production at all.
        _log_plan_timing(group_id, query, _stage, "image_sent")
        return

    _vqa_n = 1

    # 4b. VQA path — iterate candidates, stop on first real answer.
    # On success we send BOTH the short text answer AND the sheet image so
    # the crew can verify the answer against the drawing in one message.
    for rec in candidates:
        try:
            sheet_number = rec.get("sheet_number") or "Sheet"
            sheet_title  = rec.get("sheet_title")  or "Construction Drawing"
            jpeg = await _fetch_page_jpeg(rec)
            _mark(f"fetch{_vqa_n}")
            if not jpeg:
                continue
            answer = await _qwen_visual_qa(
                jpeg, effective_question, sheet_number, sheet_title,
                project_id=project_id,
            )
            _mark(f"vqa{_vqa_n}")
            _vqa_n += 1
            if not answer or "NOT_SHOWN_ON_SHEET" in answer.upper():
                continue
            # Got an answer — format with sheet citation per spec.
            reply_text = f"*{sheet_number}* — {sheet_title}\n\n{answer}"
            await send_whatsapp_message(group_id, reply_text,
                                        reply_to=reply_to)
            # A DRAWING AFTER A NUMBER IS NOISE. The follow-up image is real
            # help for an open question — "what is the ceiling height here"
            # is better with the section in front of you. It is the opposite
            # for "how many outlets" and "is there a skylight": the answer is
            # one word, it has already been sent, and a full sheet after it is
            # a scroll the superintendent did not ask for.
            _log_plan_timing(group_id, query, _stage, "answered")
            if not _is_count_or_yes_no(effective_question):
                try:
                    await asyncio.sleep(0.6)
                    await _send_plan_image(
                        group_id, rec, f"{sheet_number} — {sheet_title}",
                    )
                except Exception as e:
                    logger.warning(
                        f"plan image send after VQA failed sheet={sheet_number}: {e}"
                    )
            return
        except Exception as e:
            logger.warning(f"VQA attempt failed for {rec.get('sheet_number')}: {e}")
            continue

    # ── NO IMAGE FALLBACK FOR A QUESTION ───────────────────────────────────
    #
    # This used to send the top sheet as a picture. Every candidate had just
    # answered NOT_SHOWN_ON_SHEET — the model looked at that exact drawing and
    # said the thing is not on it — and the handler sent it anyway.
    #
    # For a yes/no or a count that is worse than saying nothing. The user asked
    # "are there sprinklers on 4", the drawings do not show sprinklers on 4, and
    # what arrives is a drawing of floor 4. It reads as an answer. It is not
    # one, and the reader has no way to tell.
    #
    # The sheet NUMBERS are still worth sending: they say where we looked, which
    # is what turns "I don't know" into something a person can act on — open
    # those three in the app, or tell us the set is missing a sheet.
    top_sheets = [
        (r.get("sheet_number") or "?") for r in candidates[:3]
    ]
    checked = ", ".join(dict.fromkeys(s for s in top_sheets if s != "?"))
    _log_plan_timing(group_id, query, _stage, "not_found")
    msg = "Not found on the indexed drawings."
    if checked:
        msg += f"\nClosest sheets: {checked}."
    await send_whatsapp_message(group_id, msg, reply_to=reply_to)


# ==================== SPRINT 4 — AGENTIC INTENT ROUTER ====================

_BOT_ADDRESS_SOFT_TRIGGERS = [
    "who", "show", "how many", "how much", "what", "where", "find", "pull", "open",
    "dob", "violation", "punch", "open items", "material", "delivery",
    "create checklist", "make checklist", "new checklist", "add checklist",
    "assign", "done ",
]


def _jid_digits(jid: str) -> str:
    """Return just the digits from a WhatsApp JID like '15165494475@c.us' or
    '153906327875707@lid'. Empty string for unknown/empty input."""
    if not jid:
        return ""
    # Drop the @domain suffix, then strip anything non-digit.
    head = jid.split("@", 1)[0]
    return re.sub(r"\D", "", head)


_LEARNED_BOT_LIDS: set = set()


def _learn_bot_lid(lid_digits: str) -> None:
    """Remember a LID we've seen WhatsApp route to/from our bot.

    Call this when we observe a webhook with fromMe=true whose author
    is a @lid JID — that author IS the bot's LID. Cached in-process so
    subsequent webhooks get matched even if WAAPI_BOT_LID isn't set.
    Survives restarts only if WAAPI_BOT_LID is configured.
    """
    if lid_digits and len(lid_digits) >= 10:
        _LEARNED_BOT_LIDS.add(lid_digits)


def _bot_identifier_digits() -> list:
    """All digit-strings we recognize as the bot.

    WhatsApp gives the bot two separate IDs:
      - its E.164 phone number (what you'd dial) — WAAPI_DISPLAY_NUMBER
      - its LID (a random ~15-digit identifier used in mentions and some
        group events) — WAAPI_BOT_LID

    Native @mentions in modern WhatsApp Web reference the LID, NOT the
    phone number, so matching by phone alone misses real @mentions.
    Also accepts LIDs we've auto-learned from outbound (fromMe=true)
    webhooks at runtime — saves having to reconfigure if WhatsApp ever
    rotates the LID.
    """
    out = []
    phone = re.sub(r"\D", "", os.environ.get("WAAPI_DISPLAY_NUMBER", "") or "")
    if phone:
        out.append(phone)
    lid = re.sub(r"\D", "", os.environ.get("WAAPI_BOT_LID", "") or "")
    if lid:
        out.append(lid)
    out.extend(_LEARNED_BOT_LIDS)
    return out


def _digits_match_bot(digits: str, bot_ids: Optional[list] = None) -> bool:
    """Case-insensitive digit-suffix match against any configured bot id."""
    if not digits:
        return False
    ids = bot_ids if bot_ids is not None else _bot_identifier_digits()
    for bot_id in ids:
        if not bot_id:
            continue
        # Exact equality first (ideal for LID which is opaque),
        # then last-10 suffix to tolerate country-code variants on phone numbers.
        if digits == bot_id:
            return True
        if len(bot_id) >= 10 and len(digits) >= 10 and digits[-10:] == bot_id[-10:]:
            return True
    return False


# The product's own name, as a whole word. Matched case-insensitively against
# the lowered body, so one pattern covers "Levelog", "LEVELOG" and "@levelog"
# — the @ is not a word character, so \b sits between it and the L.
_LEVELOG_NAME_RE = re.compile(r"\blevelog\b")


def _has_explicit_bot_mention(
    body: str,
    bot_phone_digits: str,  # kept for backwards compat; prefer _bot_identifier_digits()
    mentioned_jids: Optional[list] = None,
) -> bool:
    """Returns True iff the bot was explicitly addressed.

    Matches (any of):
      - WhatsApp native @mention: the bot's JID (phone or LID) appears in
        mentioned_jids. Modern clients use @lid here.
      - Bare '@<digits>' token in the body that matches bot phone or LID.
        (some vendors don't populate mentionedJidList.)
      - Literal text '@levelog' or 'levelog ' prefix (typed fallback).
    """
    # Build the set of bot identifiers — union of phone + LID + the legacy
    # `bot_phone_digits` arg the call site passed in.
    bot_ids = _bot_identifier_digits()
    if bot_phone_digits and bot_phone_digits not in bot_ids:
        bot_ids.append(bot_phone_digits)

    # 1. Native @-mention via JID list (the primary, correct path)
    if mentioned_jids:
        for jid in mentioned_jids:
            if _digits_match_bot(_jid_digits(str(jid)), bot_ids):
                return True

    if not body:
        return False
    low = body.strip().lower()

    # 2. Bare @<digits> token in the body text (WhatsApp renders the
    #    mention as a styled pill, but the raw body carries '@<digits>').
    for token in re.findall(r"@[\w\d]+", low):
        digits = re.sub(r"\D", "", token)
        if _digits_match_bot(digits, bot_ids):
            return True

    # 3. The NAME, anywhere in the message — not only the handle, and not only
    # at the front.
    #
    # THIS USED TO REQUIRE A PREFIX. The test was `startswith("@levelog")` or
    # `startswith("levelog ")`, which accepts "levelog who is on site" and
    # rejects "ask levelog who is on site", "levelog, who is on site" and
    # "who is on site levelog". Nobody on a site says "at levelog"; they say
    # the name, in the middle of a sentence, with a comma after it.
    #
    # A word boundary rather than a substring, so "levelogging" does not match
    # and neither does a URL with the name in it.
    if _LEVELOG_NAME_RE.search(low):
        return True

    return False


# Key for the short-lived "sender just addressed the bot" session. When the
# sender tags @levelog with text, we mark them active for BOT_SESSION_TTL
# seconds — follow-up voice notes / short text replies from the same sender
# within that window are also routed to the agent without requiring another
# explicit mention. This matches how people naturally interact with the bot:
# "@levelog who's on site" → (bot replies) → voice note "also show me the roof"
BOT_SESSION_TTL_SECONDS = 180  # 3 minutes



async def _mark_bot_session(group_id: str, sender: str) -> None:
    """Record that `sender` just explicitly addressed the bot in this group.

    Subsequent messages from the same sender within BOT_SESSION_TTL_SECONDS
    are treated as bot-addressed. Uses whatsapp_conversation_state with a
    TTL index so rows auto-expire.
    """
    try:
        exp = datetime.now(timezone.utc) + timedelta(seconds=BOT_SESSION_TTL_SECONDS)
        await db.whatsapp_conversation_state.update_one(
            {"kind": "bot_session", "group_id": group_id, "sender": sender},
            {"$set": {
                "kind":       "bot_session",
                "group_id":   group_id,
                "sender":     sender,
                "expires_at": exp,
                "updated_at": datetime.now(timezone.utc),
            }},
            upsert=True,
        )
    except Exception as e:
        # ── THIS LINE USED TO BE logger.debug ──────────────────────────────
        #
        # A session that fails to write is a bot that stops answering a
        # conversation it is in the middle of, and for months the only trace
        # was a debug line nobody reads. E11000 in particular is never
        # transient and never benign here: it means the key does not describe
        # the row, which is a schema fault that will keep happening on every
        # message until somebody changes an index.
        #
        # The FILTER is logged, not just the message, because "duplicate key"
        # without it does not say which of the three row kinds collided.
        _filter = {"kind": "bot_session", "group_id": group_id, "sender": sender}
        if "E11000" in str(e) or "duplicate key" in str(e).lower():
            logger.warning(
                f"mark_bot_session DUPLICATE KEY — the session was NOT "
                f"written and this group's follow-ups will be ignored. "
                f"filter={_filter} err={e}"
            )
        else:
            logger.warning(f"mark_bot_session failed: filter={_filter} err={e}")


async def _is_in_bot_session(group_id: str, sender: str) -> bool:
    """True if the sender has an active session with the bot in this group."""
    try:
        row = await db.whatsapp_conversation_state.find_one({
            "kind":     "bot_session",
            "group_id": group_id,
            "sender":   sender,
        })
        if not row:
            return False
        exp = row.get("expires_at")
        if not exp:
            return False
        exp_aware = exp if exp.tzinfo is not None else exp.replace(tzinfo=timezone.utc)
        return exp_aware > datetime.now(timezone.utc)
    except Exception:
        return False


# ── THE ONE-TIME NUDGE ─────────────────────────────────────────────────────
#
# Kept next to the session helpers because it uses the same collection and the
# same TTL mechanism, and because both exist for the same reason: the bot has
# to behave like something that is listening even when it decides not to speak.

NUDGE_COOLDOWN_SECONDS = 60 * 60 * 24  # once a day per group

NUDGE_TEXT = (
    "I'm here — say \"levelog\" or reply to one of my messages and I'll answer."
)

_QUESTION_WORDS = (
    "who", "what", "when", "where", "why", "how", "which",
    "can ", "could ", "do ", "does ", "did ", "is ", "are ", "any ",
)


def _looks_like_a_question(body: str) -> bool:
    """Shaped like a question, cheaply and without a model.

    A question mark is the strong signal. The word list is for the people who
    do not type one, which on a phone is most of them — and it is anchored to
    the START of the message, because "what" in the middle of a sentence is
    usually a statement ("that's what I said")."""
    if not body:
        return False
    text = body.strip()
    if len(text) < 4:
        return False
    if text.endswith("?"):
        return True
    low = text.lower()
    return any(low.startswith(w) for w in _QUESTION_WORDS)


async def _nudge_once(group_id: str) -> None:
    """Tell a group how to reach the bot, at most once a day.

    Never raises: a nudge that fails is a missed hint, and turning that into
    an exception would take down the message-processing path behind it."""
    if not group_id:
        return
    try:
        now = datetime.now(timezone.utc)
        existing = await db.whatsapp_conversation_state.find_one({
            "kind": "nudge", "group_id": group_id,
        })
        if existing:
            exp = existing.get("expires_at")
            if exp is not None:
                exp = exp if exp.tzinfo is not None else exp.replace(tzinfo=timezone.utc)
                if exp > now:
                    return
        await db.whatsapp_conversation_state.update_one(
            {"kind": "nudge", "group_id": group_id},
            {"$set": {
                "kind":       "nudge",
                "group_id":   group_id,
                "expires_at": now + timedelta(seconds=NUDGE_COOLDOWN_SECONDS),
                "updated_at": now,
            }},
            upsert=True,
        )
        await send_whatsapp_message(group_id, NUDGE_TEXT)
    except Exception as e:
        logger.debug(f"nudge skipped for {group_id}: {e}")


async def _is_bot_addressed(
    body: str,
    bot_phone_digits: str,
    is_voice: bool,
    *,
    group_id: str = "",
    sender: str = "",
    mode: str = "strict",
    quoted_body: str = "",
    mentioned_jids: Optional[list] = None,
    quoted_mentioned_jids: Optional[list] = None,
    quoted_from_bot: bool = False,
) -> bool:
    """Decide whether this message should route through the agent.

    Modes:
      Both modes:
        - the name "levelog" as a whole word anywhere in the message, the
          handle, or a native @mention matching the bot's phone or LID
        - a reply to a message that mentioned the bot
        - a reply to one of the BOT'S OWN messages
        - any message from a sender with a live session (180s, and it rolls
          forward on every exchange, not only on an explicit mention)

      loose (the default for new groups) adds:
        - any voice note
        - any message containing a soft-trigger word

    Loose is the default because strict was measured losing about a third of
    the real questions put to it. What keeps loose from being noisy is the
    agent's NOREPLY hatch: a message that trips a trigger without being for
    the bot is answered with silence, so the cost is a model call rather than
    an interruption.
    """
    # ── WHY THIS WAS REBUILT ───────────────────────────────────────────────
    #
    # Measured against the only real traffic this bot has ever had: eleven of
    # thirty-four unaddressed group messages were questions the bot could have
    # answered and never saw. "Who's on site?", "Permit status?", "Done 2".
    # Not one of them was malformed. They were people talking normally to
    # something they believed was listening.
    #
    # Three separate rules were each dropping a share of them, and all three
    # are fixed below rather than traded off against each other:
    #
    #   1. The soft-trigger list was unreachable outside loose mode, and loose
    #      was not the default.
    #   2. A reply to one of the bot's own messages did not count, because the
    #      only thing known about a quoted message was its text.
    #   3. The session window ran from the last EXPLICIT mention rather than
    #      the last exchange, so a live conversation died at 180 seconds.
    #
    # The decision is now computed once and the session is marked once, at the
    # bottom, for every route in. That ordering is the fix for (3): it used to
    # be marked only on the two explicit branches, so riding the window never
    # renewed it.
    reason = ""

    # Explicit mention — the name, the handle, or a native @mention JID.
    if _has_explicit_bot_mention(body, bot_phone_digits, mentioned_jids):
        reason = "mention"

    # The message being replied to mentioned the bot.
    elif _has_explicit_bot_mention(quoted_body, bot_phone_digits, quoted_mentioned_jids):
        reason = "quoted_mention"

    # ── REPLYING TO THE BOT IS ADDRESSING THE BOT ──────────────────────────
    #
    # This is what the docstring above has always promised and the code never
    # did. It holds in BOTH modes, because it is not a heuristic: tapping
    # reply on a message is the most explicit thing a person can do short of
    # typing the name, and on this number the only other writer is the bot.
    elif quoted_from_bot:
        reason = "reply_to_bot"

    # An open conversation. Checked before the soft triggers so a follow-up
    # inside the window routes on the window rather than on a chance word,
    # and checked in BOTH modes — loose used to return before reaching it.
    elif group_id and sender and await _is_in_bot_session(group_id, sender):
        reason = "session"

    elif mode == "loose":
        # Any voice note, or any soft-trigger word. The NOREPLY escape hatch
        # is what makes this safe to leave on: a message that trips a trigger
        # but is not for the bot reaches the agent, which answers NOREPLY and
        # says nothing. Loose mode costs model calls, not interruptions.
        if is_voice:
            reason = "voice"
        elif body:
            low = body.strip().lower()
            for t in _BOT_ADDRESS_SOFT_TRIGGERS:
                if t in low:
                    reason = f"trigger:{t.strip()}"
                    break

    if not reason:
        # ── A REFUSAL LEFT NO TRACE, WHICH IS WHY THE MISSES WERE INVISIBLE ─
        #
        # The success path below has logged `addressed via <reason>` since it
        # was written. The refusal path logged nothing, so "why did the bot
        # ignore that?" — asked twice now about real messages — could not be
        # answered from production at all.
        #
        # The reason is NAMED rather than "not addressed", because the four
        # causes want four different fixes: a message nobody tagged is a
        # product decision, a session that expired is a TTL question, and a
        # session that was never written is the duplicate-key fault that ate
        # the first miss.
        why = "no_mention"
        if group_id and sender:
            try:
                row = await db.whatsapp_conversation_state.find_one(
                    {"kind": "bot_session", "group_id": group_id, "sender": sender})
                if row is None:
                    why = "session_missing"
                else:
                    why = "session_expired"
            except Exception:
                why = "session_unreadable"
        if mode != "loose":
            why += "+strict"
        logger.info(
            f"NOT addressed ({why}) group={group_id[-10:] if group_id else '?'} "
            f"sender={sender[-4:] if sender else '?'} mode={mode} "
            f"body={(body or '')[:60]!r}"
        )
        return False

    # ── ONE MARK, EVERY ROUTE IN, WHICH IS THE POINT ───────────────────────
    #
    # Marking here rather than on the explicit branches is what makes the
    # window roll forward. A person who tags the bot, gets an answer, and asks
    # two follow-ups now has a live window three exchanges later; before, the
    # clock started on the tag and ran out mid-conversation.
    if group_id and sender:
        await _mark_bot_session(group_id, sender)
    logger.info(
        f"addressed via {reason} group={group_id[-10:] if group_id else '?'} "
        f"sender={sender[-4:] if sender else '?'} mode={mode}"
    )
    return True


