@api_router.get("/whatsapp/debug/bot-identifiers")
async def whatsapp_debug_bot_ids(current_user=Depends(get_current_user)):
    """Dump the digit-strings the addressing matcher recognizes as 'the bot'.

    If your native @mention isn't being detected, compare the LID the
    webhook payloads carry (see /whatsapp/debug/webhook-log) against the
    list this returns. A missing LID here = env var isn't loaded, or has
    whitespace/quote corruption.
    """
    if not is_company_admin(current_user):
        raise HTTPException(status_code=403, detail="Admin access required")
    env_phone_raw = os.environ.get("WAAPI_DISPLAY_NUMBER", "")
    env_lid_raw = os.environ.get("WAAPI_BOT_LID", "")
    return {
        "env_waapi_display_number": {
            "raw_repr": repr(env_phone_raw),
            "digits_only": re.sub(r"\D", "", env_phone_raw),
        },
        "env_waapi_bot_lid": {
            "raw_repr": repr(env_lid_raw),
            "digits_only": re.sub(r"\D", "", env_lid_raw),
        },
        "learned_lids_since_restart": sorted(_LEARNED_BOT_LIDS),
        "full_matcher_set": _bot_identifier_digits(),
        "note": (
            "If native @mentions still fail, look at "
            "/whatsapp/debug/webhook-log and find the @<digits> token in a "
            "recent inbound body. It must be exactly equal to one of "
            "full_matcher_set entries, or share the last 10 digits with a "
            "phone entry."
        ),
    }


@api_router.get("/whatsapp/debug/page-index")
async def whatsapp_debug_page_index(
    project_id: str, sheet: str = "", limit: int = 5, list_sheets: bool = False,
    current_user=Depends(get_current_user),
):
    """The RAW stored extraction for a sheet. Owner/admin only.

    `list_sheets=true` returns every page row's identity instead — sheet
    number, file, hash, version, supersession, extraction flags — because
    "S-001 returned nothing" cannot be told apart from "S-001 is stored as
    S-001.00" or "S-001's title block was never read" without it.

    ── WHY THIS EXISTS ────────────────────────────────────────────────────
    #
    # Live test, 2026-09-14: stucco, posts, gauge and piles all came back "not
    # found" on a drawing set that contains every one of them. Two explanations
    # fit — retrieval is looking in the wrong place, or the indexer never
    # extracted the words in the first place — and they want opposite fixes.
    # Nothing in the product could tell them apart, because what the indexer
    # wrote has never been visible anywhere.
    #
    # So this returns the stored fields verbatim, unranked and unsummarised.
    # If `summary` and `keywords` come back thin or generic, no retrieval
    # change helps and the work is in the indexing prompt. That is the decision
    # this endpoint exists to make, and it is not one to make by guessing.
    #
    # NO EMBEDDING. It is 1536 floats that no human reads, and it would bury
    # the text this is here to show.
    """
    if not is_company_admin(current_user):
        raise HTTPException(status_code=403, detail="Admin access required")

    # SCOPED TO THE CALLER'S COMPANY. A project id in a query string is the
    # client's input, and a debug endpoint is still an endpoint.
    project = await db.projects.find_one({"_id": to_query_id(project_id)})
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")
    _same_company_or_403(project, current_user)

    live_ids = await _live_plan_file_ids(str(project_id)) or []
    live = set(live_ids)

    if list_sheets:
        rows = await db.document_page_index.find(
            {"project_id": str(project_id)},
            {"sheet_number": 1, "sheet_title": 1, "file_id": 1, "file_name": 1,
             "file_hash": 1, "page_number": 1, "index_version": 1,
             "superseded_by": 1, "is_spec_page": 1, "text_source": 1,
             "text_layer_chars": 1, "extraction_flags": 1, "number_flags": 1},
        ).to_list(5000)
        sheets = []
        for r in rows:
            flags = {k: v for k, v in (r.get("extraction_flags") or {}).items() if v}
            sheets.append({
                "sheet_number": r.get("sheet_number"),
                "sheet_title": r.get("sheet_title"),
                "file_id": r.get("file_id"), "file_name": r.get("file_name"),
                "file_hash": r.get("file_hash"), "page_number": r.get("page_number"),
                "index_version": r.get("index_version"),
                "file_live": r.get("file_id") in live,
                "superseded_by": r.get("superseded_by"),
                "current": (r.get("file_id") in live
                            and r.get("superseded_by") not in live),
                "is_spec_page": bool(r.get("is_spec_page")),
                "text_source": r.get("text_source"),
                "text_layer_chars": r.get("text_layer_chars"),
                "extraction_flags": flags, "number_flags": r.get("number_flags") or [],
            })
        sheets.sort(key=lambda s: (str(s["file_name"] or ""), s["page_number"] or 0))
        chunk_count = await db.document_page_chunks.count_documents(
            {"project_id": str(project_id)})
        return {
            "project_id": str(project_id),
            "rows": len(sheets),
            "rows_without_sheet_number": sum(1 for s in sheets if not s["sheet_number"]),
            "current_rows": sum(1 for s in sheets if s["current"]),
            "chunks": chunk_count,
            "sheets": sheets,
        }

    q: Dict[str, Any] = {"project_id": str(project_id)}
    if sheet:
        q["sheet_number"] = {
            "$regex": f"^{re.escape(sheet)}(\\.\\d+)?$", "$options": "i"}

    rows = await db.document_page_index.find(
        q, {"embedding": 0},
    ).limit(min(max(limit, 1), 25)).to_list(min(max(limit, 1), 25))

    out = []
    for r in rows:
        page_id = str(r.get("_id"))
        r["_current"] = (r.get("file_id") in live
                         and r.get("superseded_by") not in live)
        r["_chunks"] = await db.document_page_chunks.find(
            {"project_id": str(project_id), "page_id": page_id},
            {"_id": 0, "chunk_type": 1, "ordinal": 1, "text": 1},
        ).to_list(200)
        r.pop("_id", None)
        for k, v in list(r.items()):
            if isinstance(v, datetime):
                r[k] = v.isoformat()
        # What a literal element search would actually see for this page —
        # the same fields _pages_with_element looks in, concatenated. This is
        # the string that decides whether "stucco" is findable.
        searchable = []
        for f in _ELEMENT_TEXT_FIELDS:
            v = r.get(f)
            if isinstance(v, list):
                searchable.extend(str(x) for x in v)
            elif v:
                searchable.append(str(v))
        r["_searchable_text"] = " | ".join(searchable)
        r["_searchable_chars"] = len(r["_searchable_text"])
        out.append(r)

    return {
        "project_id": str(project_id),
        "sheet_filter": sheet or "(all)",
        "count": len(out),
        "searched_fields": list(_ELEMENT_TEXT_FIELDS),
        "pages": out,
    }


