@api_router.post("/whatsapp/group-link/verify", dependencies=[Depends(require_approved)])
async def whatsapp_group_link_verify(
    body: dict,
    current_user=Depends(get_current_user),
):
    """Verify a link code and create the group-project association."""
    code = body.get("code", "").strip()
    project_id = body.get("project_id")
    if not code or not project_id:
        raise HTTPException(status_code=400, detail="code and project_id required")
    company_id = get_user_company_id(current_user)
    code_doc = await db.whatsapp_link_codes.find_one({
        "code": code,
        "project_id": project_id,
        "company_id": company_id,
        "verified": False,
    })
    if not code_doc:
        raise HTTPException(status_code=404, detail="Invalid or expired code")
    group_id = code_doc.get("group_id")
    if not group_id and not code_doc.get("group_verified"):
        raise HTTPException(status_code=400, detail="Code not yet verified by group. Send the code in the WhatsApp group first.")
    # Create group link. Seed bot_config on first insert only ($setOnInsert)
    # so re-linking an existing group doesn't clobber the admin's config.
    now = datetime.now(timezone.utc)
    linker_id = str(current_user.get("id") or current_user.get("_id") or "")
    await db.whatsapp_groups.update_one(
        {"company_id": company_id, "wa_group_id": group_id},
        {
            "$set": {
                "project_id": project_id,
                "company_id": company_id,
                "wa_group_id": group_id,
                "linked_by": linker_id,
                "linked_at": now,
                "active": True,
            },
            "$setOnInsert": {
                "bot_config": _default_bot_config(),
            },
        },
        upsert=True,
    )
    # Mark code as used
    await db.whatsapp_link_codes.update_one(
        {"_id": code_doc["_id"]},
        {"$set": {"verified": True}},
    )

    # ── THE FIRST SIXTY SECONDS DECIDE WHETHER ANYONE ASKS A SECOND TIME ────
    #
    # Until now the group's entire introduction to the bot was a six-digit
    # number that nothing responded to. Everyone in the chat watched something
    # get added, watched it say nothing, and had no reason to believe it did
    # anything at all — and the one measured group went quiet after eleven
    # unanswered questions, which is what that silence buys.
    #
    # WHAT THIS MESSAGE HAS TO DO IS NAME THE FOUR THINGS IT KNOWS AND GET OUT
    # OF THE WAY. No syntax to learn, because there is no longer a syntax: the
    # name works anywhere in a sentence, a reply to the bot works, and in loose
    # mode an ordinary question usually works on its own. Promising a format
    # would teach a rule the crew does not need and would then have to unlearn.
    #
    # Best-effort. A group that is linked but did not get a greeting is a worse
    # first impression, not a failed link, so this must never turn a successful
    # 200 into an error.
    try:
        await send_whatsapp_message(
            group_id,
            "Levelog here. I can tell you who's on site, permit and DOB "
            "status, what's still open, and where materials are.\n"
            "Just ask — no special format. Voice notes work too.",
        )
    except Exception as e:
        logger.warning(f"welcome message failed for {group_id}: {e}")

    return {"status": "linked", "group_id": group_id, "project_id": project_id}


# ---------- WhatsApp management endpoints (auth required) ----------

@api_router.get("/whatsapp/groups/{project_id}")
async def whatsapp_get_groups(project_id: str, current_user=Depends(get_current_user)):
    """List linked WhatsApp groups for a project, with message counts + bot_config."""
    company_id = get_user_company_id(current_user)
    if not company_id and not is_platform_operator(current_user):
        # `company_id: None` IS NOT A TENANT FILTER -- it matches
        # precisely the rows with no company, i.e. every OTHER
        # un-onboarded signup, so a company-less caller was
        # cross-linked to strangers rather than scoped to nobody.
        raise HTTPException(
            status_code=403,
            detail="This account is not linked to a company yet.",
        )
    groups = await db.whatsapp_groups.find({
        "project_id": project_id,
        "company_id": company_id,
        "active": True,
    }).to_list(50)
    results = []
    for g in groups:
        msg_count = await db.whatsapp_messages.count_documents({"group_id": g["wa_group_id"]})
        # Merge stored config over defaults so legacy docs without one still
        # return a complete object — frontend never has to handle missing fields.
        cfg = _default_bot_config()
        stored = g.get("bot_config") or {}
        cfg.update({k: v for k, v in stored.items() if k in _WHATSAPP_CONFIG_KEYS})
        # Merge features subdoc specifically so partial feature dicts work too.
        if "features" in stored and isinstance(stored["features"], dict):
            merged_features = dict(cfg["features"])
            merged_features.update({
                k: v for k, v in stored["features"].items() if k in _WHATSAPP_FEATURE_KEYS
            })
            cfg["features"] = merged_features
        results.append({
            "id": str(g["_id"]),
            "wa_group_id": g["wa_group_id"],
            "project_id": g["project_id"],
            "linked_at": g.get("linked_at"),
            "message_count": msg_count,
            "group_name": g.get("group_name"),
            "bot_config": cfg,
        })
    return results


@api_router.put("/whatsapp/groups/{group_doc_id}/config")
async def whatsapp_update_group_config(
    group_doc_id: str,
    body: dict,
    current_user=Depends(get_current_user),
):
    """Update bot_config for a linked WhatsApp group.

    Admin/owner only, must belong to the group's company. Accepts a partial
    or full config object. Unknown keys rejected. Time fields validated HH:MM.
    Days list validated 1-7.
    """
    # Rank gate — company admins only, and the platform operator.
    if not is_company_admin(current_user):
        raise HTTPException(status_code=403, detail="Admin access required")

    group = await db.whatsapp_groups.find_one({"_id": to_query_id(group_doc_id)})
    if not group:
        raise HTTPException(status_code=404, detail="Group not found")

    # _same_company_or_403 did not exist when this was first surveyed. A group
    # carries its own company_id and no project to scope through, so this is
    # the company-level twin of project_access_ok -- and it treats an absent,
    # null or empty company_id on the GROUP as unowned rather than as a match.
    _same_company_or_403(group, current_user)

    # ---- Validate payload ----
    if not isinstance(body, dict) or not body:
        raise HTTPException(status_code=422, detail="Request body must be a non-empty object")

    unknown = set(body.keys()) - _WHATSAPP_CONFIG_KEYS
    if unknown:
        raise HTTPException(
            status_code=422,
            detail=f"Unknown config keys: {sorted(unknown)}",
        )

    set_ops: Dict[str, Any] = {}

    if "bot_enabled" in body:
        if not isinstance(body["bot_enabled"], bool):
            raise HTTPException(status_code=422, detail="bot_enabled must be a boolean")
        set_ops["bot_config.bot_enabled"] = body["bot_enabled"]

    if "daily_summary_enabled" in body:
        if not isinstance(body["daily_summary_enabled"], bool):
            raise HTTPException(status_code=422, detail="daily_summary_enabled must be a boolean")
        set_ops["bot_config.daily_summary_enabled"] = body["daily_summary_enabled"]

    if "daily_summary_time" in body:
        t = body["daily_summary_time"]
        if not isinstance(t, str) or not _HHMM_RE.match(t):
            raise HTTPException(status_code=422, detail="daily_summary_time must be HH:MM (24h)")
        set_ops["bot_config.daily_summary_time"] = t

    if "daily_summary_days" in body:
        d = body["daily_summary_days"]
        if not isinstance(d, list) or not all(isinstance(x, int) and 1 <= x <= 7 for x in d):
            raise HTTPException(
                status_code=422,
                detail="daily_summary_days must be a list of ints 1-7 (Mon=1 Sun=7)",
            )
        set_ops["bot_config.daily_summary_days"] = d

    if "checklist_extraction_enabled" in body:
        if not isinstance(body["checklist_extraction_enabled"], bool):
            raise HTTPException(
                status_code=422, detail="checklist_extraction_enabled must be a boolean"
            )
        set_ops["bot_config.checklist_extraction_enabled"] = body["checklist_extraction_enabled"]

    if "checklist_frequency" in body:
        f = body["checklist_frequency"]
        if f not in ("daily", "on_demand"):
            raise HTTPException(
                status_code=422, detail="checklist_frequency must be 'daily' or 'on_demand'"
            )
        set_ops["bot_config.checklist_frequency"] = f

    if "checklist_time" in body:
        t = body["checklist_time"]
        if not isinstance(t, str) or not _HHMM_RE.match(t):
            raise HTTPException(status_code=422, detail="checklist_time must be HH:MM (24h)")
        set_ops["bot_config.checklist_time"] = t

    if "cross_project_summary" in body:
        if not isinstance(body["cross_project_summary"], bool):
            raise HTTPException(status_code=422, detail="cross_project_summary must be a boolean")
        set_ops["bot_config.cross_project_summary"] = body["cross_project_summary"]

    if "features" in body:
        f = body["features"]
        if not isinstance(f, dict):
            raise HTTPException(status_code=422, detail="features must be an object")
        unknown_features = set(f.keys()) - _WHATSAPP_FEATURE_KEYS
        if unknown_features:
            raise HTTPException(
                status_code=422,
                detail=f"Unknown feature keys: {sorted(unknown_features)}",
            )
        for k, v in f.items():
            # address_mode is the one non-boolean feature — it's a string enum,
            # so it skips the isinstance(v, bool) check below.
            #
            # ── AND IT USED TO SKIP THE WRITE WITH IT ──────────────────────
            #
            # The `continue` that ended this branch jumped past the set_ops
            # line at the bottom of the loop. So a request carrying
            # features.address_mode was validated, accepted, answered 200, and
            # DISCARDED. The value never reached the document.
            #
            # That made the setting unreachable by any supported means:
            # GroupConfigPanel does not render a control for it, and the API
            # that does accept it silently dropped it, which left a direct
            # database write as the only way to put a group into loose mode.
            #
            # A 200 on a write that did not happen is the worst shape this can
            # take. Nothing in the response, the logs or the config panel
            # distinguishes it from success, and the symptom shows up somewhere
            # else entirely — as a bot that keeps ignoring the crew after
            # somebody already turned the setting off.
            if k == "address_mode":
                if v not in ("strict", "loose"):
                    raise HTTPException(
                        status_code=422,
                        detail="features.address_mode must be 'strict' or 'loose'",
                    )
                set_ops[f"bot_config.features.{k}"] = v
                continue
            if not isinstance(v, bool):
                raise HTTPException(
                    status_code=422,
                    detail=f"features.{k} must be a boolean",
                )
            set_ops[f"bot_config.features.{k}"] = v

    # Cross-field validation — days list required non-empty if daily summary enabled
    # Handles either the effective new state OR combo of request + stored state.
    merged_enabled = set_ops.get("bot_config.daily_summary_enabled")
    if merged_enabled is None:
        merged_enabled = (group.get("bot_config") or {}).get("daily_summary_enabled", False)
    merged_days = set_ops.get("bot_config.daily_summary_days")
    if merged_days is None:
        merged_days = (group.get("bot_config") or {}).get("daily_summary_days", [1, 2, 3, 4, 5])
    if merged_enabled and not merged_days:
        raise HTTPException(
            status_code=422,
            detail="daily_summary_days cannot be empty when daily_summary_enabled is true",
        )

    set_ops["updated_at"] = datetime.now(timezone.utc)

    await db.whatsapp_groups.update_one(
        {"_id": to_query_id(group_doc_id)},
        {"$set": set_ops},
    )

    updated = await db.whatsapp_groups.find_one({"_id": to_query_id(group_doc_id)})

    # Return the same shape as the list endpoint entry for this group
    cfg = _default_bot_config()
    stored = updated.get("bot_config") or {}
    cfg.update({k: v for k, v in stored.items() if k in _WHATSAPP_CONFIG_KEYS})
    if "features" in stored and isinstance(stored["features"], dict):
        merged_features = dict(cfg["features"])
        merged_features.update({
            k: v for k, v in stored["features"].items() if k in _WHATSAPP_FEATURE_KEYS
        })
        cfg["features"] = merged_features

    return {
        "id": str(updated["_id"]),
        "wa_group_id": updated.get("wa_group_id"),
        "project_id": updated.get("project_id"),
        "group_name": updated.get("group_name"),
        "linked_at": updated.get("linked_at"),
        "bot_config": cfg,
    }


@api_router.delete("/whatsapp/groups/{group_doc_id}")
async def whatsapp_unlink_group(group_doc_id: str, current_user=Depends(get_current_user)):
    """Unlink (deactivate) a WhatsApp group."""
    company_id = get_user_company_id(current_user)
    result = await db.whatsapp_groups.update_one(
        {"_id": to_query_id(group_doc_id), "company_id": company_id},
        {"$set": {"active": False, "unlinked_at": datetime.now(timezone.utc)}},
    )
    if result.matched_count == 0:
        raise HTTPException(status_code=404, detail="Group not found")
    return {"status": "unlinked"}


# ── LINKING IS A TENANT DECISION, SO EVERY ROUTE BELOW ASSERTS TENANCY ─────
#
# A group binds to exactly ONE project; many groups may bind to one project.
# Getting this wrong does not produce a 500 — it produces a crew's daily log,
# their roster and their permit data appearing in another customer's chat, and
# nothing anywhere goes red. So the checks are stated once, here, and every
# route calls them rather than each re-deriving the rule.
_PENDING_LINK_ROLES = ("owner", "admin", "cp")


def _require_link_role(current_user) -> str:
    """Caller must be able to bind a group to a job. Returns their company."""
    role = (current_user.get("role") or "").lower()
    if role not in _PENDING_LINK_ROLES:
        raise HTTPException(
            status_code=403,
            detail="Owner, admin or CP access required to connect a group",
        )
    company_id = get_user_company_id(current_user)
    if not company_id:
        # A caller with no company has no projects to link TO. Returning an
        # empty list would be a lie of omission; refusing says why.
        raise HTTPException(status_code=400, detail="No company associated")
    return company_id


def _caller_phone_digits(current_user) -> str:
    return re.sub(r"\D", "", str(current_user.get("phone") or ""))


def _pending_visible_query(company_id: str, phone_digits: str) -> dict:
    """Which pending groups this caller may see.

    Two kinds. Groups whose company we resolved — because the person who added
    the bot is a known contact — belong to that company and only that company.
    Groups we could NOT resolve have no owner yet, and the only person with a
    claim on them is whoever added the bot, matched by phone. Without that
    second clause an unresolved group would be invisible to everyone and the
    bot would sit in it forever; with it widened to "everyone", one customer
    would see another's group names."""
    clauses: List[Dict[str, Any]] = [{"company_id": company_id}]
    if phone_digits:
        clauses.append({
            "company_id": None,
            "added_by_phone": {"$in": _contact_phone_variants(phone_digits)},
        })
    return {"status": "pending", "$or": clauses}


@api_router.get("/whatsapp/pending-groups",
                dependencies=[Depends(require_approved)])
async def whatsapp_pending_groups(current_user=Depends(get_current_user)):
    """Groups the bot is in that are not connected to a project yet.

    Each row carries a SUGGESTION when the group's name points at exactly one
    of this company's projects. The suggestion pre-fills a dropdown and links
    nothing — see lib/group_match.py for why one clear winner or nothing."""
    company_id = _require_link_role(current_user)
    phone = _caller_phone_digits(current_user)

    rows = await db[PENDING_GROUPS].find(
        _pending_visible_query(company_id, phone)
    ).sort("first_seen", -1).to_list(200)

    projects = await db.projects.find(
        {"company_id": company_id, "is_deleted": {"$ne": True}},
        {"name": 1, "address": 1, "location": 1, "nickname": 1,
         "nyc_bin": 1, "bbl": 1},
    ).to_list(500)
    for p in projects:
        p["id"] = str(p.pop("_id"))

    out = []
    for r in rows:
        suggestion = suggest_project_for_group(projects, r.get("group_name"))
        out.append({
            "group_id":       r.get("group_id"),
            "group_name":     r.get("group_name") or "",
            "added_by_phone": r.get("added_by_phone") or "",
            "first_seen":     (r.get("first_seen").isoformat()
                               if isinstance(r.get("first_seen"), datetime)
                               else None),
            "last_seen":      (r.get("last_seen").isoformat()
                               if isinstance(r.get("last_seen"), datetime)
                               else None),
            "suggested_project_id": (suggestion or {}).get("project_id"),
            "suggested_confidence": (suggestion or {}).get("confidence"),
        })
    return {
        "pending": out,
        "projects": [
            {"id": p["id"], "name": p.get("name") or "",
             "address": p.get("address") or p.get("location") or "",
             "nickname": p.get("nickname") or ""}
            for p in projects
        ],
    }


@api_router.post("/whatsapp/pending-groups/{group_id}/link",
                 dependencies=[Depends(require_approved)])
async def whatsapp_pending_group_link(
    group_id: str, body: dict, current_user=Depends(get_current_user),
):
    """Bind a pending group to a project. Never automatic; always this call."""
    company_id = _require_link_role(current_user)
    project_id = (body or {}).get("project_id")
    if not project_id:
        raise HTTPException(status_code=422, detail="project_id required")

    pending = await db[PENDING_GROUPS].find_one({"group_id": group_id})
    if not pending:
        raise HTTPException(status_code=404, detail="Group not found")
    # The caller must be able to SEE it before they may bind it — same rule as
    # the list, so a group id guessed from elsewhere is not a way in.
    visible = await db[PENDING_GROUPS].find_one({
        "group_id": group_id,
        **_pending_visible_query(company_id, _caller_phone_digits(current_user)),
    })
    if not visible:
        raise HTTPException(status_code=403, detail="Access denied")

    # THE PROJECT MUST BE THEIRS. Checked against the database rather than
    # against anything the client sent, because the project id IS the client's
    # input and the whole tenancy decision rests on it.
    project = await db.projects.find_one({"_id": to_query_id(project_id)})
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")
    _same_company_or_403(project, current_user,
                         detail="That project belongs to another company")

    now = datetime.now(timezone.utc)
    linker_id = str(current_user.get("id") or current_user.get("_id") or "")

    # ── RE-LINKING CLEARS THE CONVERSATION ─────────────────────────────────
    #
    # whatsapp_conversation_state is keyed by group_id alone and holds a
    # half-finished checklist and its candidate assignees. Moved to another
    # project, that draft names people from the OLD job — and if the move
    # crosses companies it names another customer's staff. Deleted, not
    # migrated: a draft that survives a re-link is worse than one that is lost.
    existing = await db.whatsapp_groups.find_one({"wa_group_id": group_id})
    if existing and str(existing.get("project_id") or "") != str(project_id):
        try:
            await db.whatsapp_conversation_state.delete_one(
            {"kind": "checklist", "group_id": group_id})
        except Exception as e:
            logger.warning(f"conversation state clear failed for {group_id}: {e}")

    await db.whatsapp_groups.update_one(
        {"company_id": company_id, "wa_group_id": group_id},
        {
            "$set": {
                "project_id":  str(project_id),
                "company_id":  company_id,
                "wa_group_id": group_id,
                "group_name":  pending.get("group_name") or "",
                "linked_by":   linker_id,
                "linked_at":   now,
                "active":      True,
            },
            "$setOnInsert": {"bot_config": _default_bot_config()},
        },
        upsert=True,
    )
    await db[PENDING_GROUPS].update_one(
        {"group_id": group_id},
        {"$set": {"status": "linked", "linked_at": now,
                  "linked_project_id": str(project_id)}},
    )

    # ── THE CONFIRMATION IS ALSO HOW @MENTIONS START WORKING ───────────────
    #
    # This message is not only manners. WhatsApp routes group @mentions by LID,
    # a random identifier that is NOT the bot's phone number, and the only way
    # this server learns its own LID is by observing a webhook for a message it
    # sent (_learn_bot_lid, in the parser). Until the bot has spoken in a group,
    # a native @mention of it arrives as digits that match nothing and the
    # message reads as unaddressed.
    #
    # So the first thing a freshly linked group gets is the bot speaking. From
    # the next message on, tapping @Levelog works.
    address = (project.get("address") or project.get("location")
               or project.get("name") or "the project")
    try:
        await send_whatsapp_message(
            group_id,
            f"Connected to {address}.\n\n"
            f"Conectado a {address}.",
        )
    except Exception as e:
        logger.warning(f"link confirmation failed for {group_id}: {e}")

    return {"status": "linked", "group_id": group_id,
            "project_id": str(project_id)}


@api_router.post("/whatsapp/pending-groups/{group_id}/ignore",
                 dependencies=[Depends(require_approved)])
async def whatsapp_pending_group_ignore(
    group_id: str, current_user=Depends(get_current_user),
):
    """Take a group off the list without connecting it.

    Ignored rather than deleted, so the next message from that group does not
    put it straight back on the list — which is what a delete would do, and the
    reason a person ignored it was to stop seeing it."""
    company_id = _require_link_role(current_user)
    visible = await db[PENDING_GROUPS].find_one({
        "group_id": group_id,
        **_pending_visible_query(company_id, _caller_phone_digits(current_user)),
    })
    if not visible:
        raise HTTPException(status_code=404, detail="Group not found")
    await db[PENDING_GROUPS].update_one(
        {"group_id": group_id},
        {"$set": {"status": "ignored",
                  "ignored_at": datetime.now(timezone.utc)}},
    )
    return {"status": "ignored", "group_id": group_id}


# ── THE IN-CHAT FRONT DOOR ─────────────────────────────────────────────────
#
# A tappable link posted in the group, for the case where the person who added
# the bot is holding a phone and will not go hunting through an admin screen.
#
# THE TOKEN CARRIES THE GROUP ID SO THE URL DOES NOT. A raw @g.us id in a link
# is an identifier for a real conversation, pasted into browser history, server
# logs and anywhere the link is forwarded. Signed with the app's own secret and
# expiring in 24 hours, the token is meaningless anywhere else and stale by the
# next day.
#
# IT IS NOT A CREDENTIAL. /wa/link requires a normal login and the link route
# re-runs every tenancy check. The token names WHICH group to show; it grants
# nothing.
WA_LINK_TOKEN_TTL_HOURS = 24


def _mint_group_link_token(group_id: str) -> str:
    return jwt.encode(
        {
            "group_id": group_id,
            "kind":     "wa_group_link",
            "exp":      datetime.now(timezone.utc)
                        + timedelta(hours=WA_LINK_TOKEN_TTL_HOURS),
        },
        JWT_SECRET,
        algorithm=JWT_ALGORITHM,
    )


def _read_group_link_token(token: str) -> str:
    """The group id inside a valid token, or '' for anything else.

    `kind` is checked as well as the signature: every token this app issues is
    signed with the same secret, and without that check a login token would be
    accepted here as a group link."""
    try:
        payload = jwt.decode(token, JWT_SECRET, algorithms=[JWT_ALGORITHM])
    except Exception:
        return ""
    if payload.get("kind") != "wa_group_link":
        return ""
    return str(payload.get("group_id") or "")


@api_router.get("/whatsapp/pending-groups/by-token",
                dependencies=[Depends(require_approved)])
async def whatsapp_pending_group_by_token(
    t: str, current_user=Depends(get_current_user),
):
    """One pending row, named by a token from an in-chat link.

    Same visibility rule as the list. An expired or forged token and a group
    the caller may not see return the same 404, because distinguishing them
    would confirm that a group exists to someone who may not know it."""
    company_id = _require_link_role(current_user)
    group_id = _read_group_link_token(t or "")
    if not group_id:
        raise HTTPException(status_code=404, detail="Link expired or invalid")

    row = await db[PENDING_GROUPS].find_one({
        "group_id": group_id,
        **_pending_visible_query(company_id, _caller_phone_digits(current_user)),
    })
    if not row:
        raise HTTPException(status_code=404, detail="Link expired or invalid")

    projects = await db.projects.find(
        {"company_id": company_id, "is_deleted": {"$ne": True}},
        {"name": 1, "address": 1, "location": 1, "nickname": 1,
         "nyc_bin": 1, "bbl": 1},
    ).to_list(500)
    for p in projects:
        p["id"] = str(p.pop("_id"))
    suggestion = suggest_project_for_group(projects, row.get("group_name"))
    return {
        "pending": [{
            "group_id":   row.get("group_id"),
            "group_name": row.get("group_name") or "",
            "added_by_phone": row.get("added_by_phone") or "",
            "suggested_project_id": (suggestion or {}).get("project_id"),
            "suggested_confidence": (suggestion or {}).get("confidence"),
        }],
        "projects": [
            {"id": p["id"], "name": p.get("name") or "",
             "address": p.get("address") or p.get("location") or "",
             "nickname": p.get("nickname") or ""}
            for p in projects
        ],
    }


@api_router.post("/whatsapp/activate", dependencies=[Depends(require_approved)])
async def whatsapp_activate(current_user=Depends(get_current_user)):
    """Activate WhatsApp for the company. Auto-populate contacts from users."""
    company_id = get_user_company_id(current_user)
    if not company_id:
        raise HTTPException(status_code=400, detail="No company associated")

    # Check if already active
    existing = await db.whatsapp_config.find_one({"company_id": company_id})
    if existing:
        return {"status": "already_active", "whatsapp_number": os.environ.get("WAAPI_DISPLAY_NUMBER", "")}

    # Create config
    await db.whatsapp_config.insert_one({
        "company_id": company_id,
        "is_active": True,
        "activated_at": datetime.now(timezone.utc),
        "activated_by": str(current_user.get("_id", current_user.get("id", "")))
    })
    # Auto-populate contacts from existing users with phone numbers
    users = await db.users.find({
        "company_id": company_id,
        "is_deleted": {"$ne": True},
        "phone": {"$exists": True, "$ne": ""},
    }).to_list(500)
    created = 0
    for user in users:
        phone = re.sub(r"[^\d]", "", user.get("phone", ""))
        if not phone:
            continue
        try:
            await db.whatsapp_contacts.update_one(
                {"company_id": company_id, "phone": phone},
                {"$setOnInsert": {
                    "company_id": company_id,
                    "phone": phone,
                    "user_id": str(user["_id"]),
                    "name": user.get("name", ""),
                    "created_at": datetime.now(timezone.utc),
                }},
                upsert=True,
            )
            created += 1
        except Exception:
            pass  # duplicate
    return {"status": "activated", "contacts_synced": created, "whatsapp_number": os.environ.get("WAAPI_DISPLAY_NUMBER", "")}


@api_router.get("/whatsapp/status")
async def whatsapp_status(current_user=Depends(get_current_user)):
    """Check if WhatsApp is configured at platform level and active for company."""
    company_id = get_user_company_id(current_user)
    platform_configured = bool(WAAPI_INSTANCE_ID and WAAPI_TOKEN)
    company_active = False
    whatsapp_number = ""
    if company_id:
        config = await db.whatsapp_config.find_one({"company_id": company_id})
        company_active = bool(config and config.get("is_active"))
    if company_active:
        whatsapp_number = os.environ.get("WAAPI_DISPLAY_NUMBER", "")
    return {
        "platform_configured": platform_configured,
        "company_active": company_active,
        "whatsapp_number": whatsapp_number,
        "vendor": WHATSAPP_VENDOR,
    }


@api_router.post(
    "/projects/{project_id}/repair-file-names",
    dependencies=[Depends(require_approved), Depends(require_project_access)],
)
async def repair_file_names(project_id: str, current_user=Depends(get_admin_user)):
    """Fix existing project_files rows whose `name` / `r2_key` contain URL-encoded
    sequences (%20, %2F, etc.). Renames the R2 object and updates the DB record.
    Safe to run repeatedly.

    ── THE PREMISE THAT MADE THIS A CROSS-TENANT WRITE ─────────────────────

    The comment below used to end "the caller already matched project_id which
    is scope enough", and NOTHING MATCHED IT. This route carried only
    `Depends(get_admin_user)`, which admits any role in ("admin", "owner") --
    and `register` gives every self-serve signup `role = "owner"`. There was no
    `require_project_access` on the decorator and no `_assert_project_access`
    in the body, so the path `project_id` went straight into the query and any
    account that had registered could name ANOTHER TENANT'S project and drive
    R2 `copy_object` + `delete_object` against its files.

    A LEAKED READ IS RECOVERABLE. This was a WRITE to object storage, and the
    delete half is not.

    THE FIX IS THE DEPENDENCY THE NEXT ROUTE IN THIS FILE ALREADY CARRIES --
    `POST /projects/{project_id}/reindex-document`, forty lines below, is
    declared `dependencies=[Depends(require_approved), Depends(require_project_access)]`.
    The correct pattern was adjacent the whole time. That is the ported-fix
    shape again: applied to the route someone was reading.

    THE company_id COMMENT'S OTHER HALF IS STILL TRUE and is kept: legacy rows
    may carry no `company_id`, so filtering the ROWS by it would skip exactly
    the ones needing repair. Scoping belongs on the CALLER, not on the row --
    which is what the dependency now does.
    """
    import urllib.parse as _urlparse
    # Row-level company filtering is deliberately absent: legacy rows may have
    # been written without a company_id, and filtering on it would skip the
    # very rows this repairs. The CALLER is scoped by require_project_access on
    # the decorator above; the rows are scoped by project_id.
    query: Dict[str, Any] = {"project_id": project_id, "is_deleted": {"$ne": True}}
    files = await db.project_files.find(query).to_list(500)
    debug_info = []
    repaired = []
    for f in files:
        raw = f.get("name") or ""
        decoded = _sanitize_upload_filename(raw)
        debug_info.append({
            "raw": raw, "decoded": decoded, "changed": decoded != raw,
            "has_r2_key": bool(f.get("r2_key")),
            "company_id": f.get("company_id"),
        })
        if decoded == raw:
            continue
        if not _r2_client:
            continue
        old_key = f.get("r2_key") or f"{f.get('company_id', '')}/{project_id}/{raw}"
        new_key = f"{f.get('company_id', '')}/{project_id}/{decoded}"
        try:
            # Copy to new key (R2 is S3-compatible)
            await asyncio.to_thread(
                _r2_client.copy_object,
                Bucket=R2_BUCKET_NAME,
                CopySource={"Bucket": R2_BUCKET_NAME, "Key": old_key},
                Key=new_key,
                ContentType="application/pdf",
            )
            # Delete old
            await asyncio.to_thread(
                _r2_client.delete_object, Bucket=R2_BUCKET_NAME, Key=old_key
            )
        except Exception as e:
            err_msg = f"copy/delete failed: old_key={old_key!r} new_key={new_key!r} error={str(e)[:300]}"
            logger.warning(f"repair_file_names: {err_msg}")
            debug_info[-1]["r2_error"] = err_msg
            continue

        new_url = f"{R2_PUBLIC_URL.rstrip('/')}/{new_key}" if R2_PUBLIC_URL else f"{R2_ENDPOINT_URL}/{R2_BUCKET_NAME}/{new_key}"
        await db.project_files.update_one(
            {"_id": f["_id"]},
            {"$set": {
                "name":    decoded,
                "r2_key":  new_key,
                "r2_url":  new_url,
                "updated_at": datetime.now(timezone.utc),
            }},
        )
        repaired.append({"old_name": raw, "new_name": decoded})

    return {"repaired_count": len(repaired), "repaired": repaired, "debug": debug_info}


@api_router.post("/projects/{project_id}/reindex-document", dependencies=[Depends(require_approved), Depends(require_project_access)])
async def reindex_project_document(
    project_id: str,
    body: dict,
    resume: bool = False,
    current_user=Depends(get_admin_user),
):
    """Admin-only: re-index a single PDF. Clears existing page entries first
    so the file_hash cache can't block the re-run.

    `?resume=true` keeps the rows and indexes only pages not marked complete —
    for a re-index a deploy interrupted."""
    file_id = (body or {}).get("file_id")
    if not file_id:
        raise HTTPException(status_code=422, detail="file_id is required")

    # Verify company match
    file_rec = await db.project_files.find_one({"_id": to_query_id(file_id)})
    if not file_rec:
        raise HTTPException(status_code=404, detail="File not found")
    if file_rec.get("project_id") != project_id:
        raise HTTPException(status_code=400, detail="File is not part of this project")
    company_id = get_user_company_id(current_user)
    if company_id and file_rec.get("company_id") != company_id:
        raise HTTPException(status_code=403, detail="Access denied")
    if not QWEN_API_KEY:
        raise HTTPException(status_code=503, detail="Plan indexing is not configured")
    if not file_rec.get("r2_key"):
        raise HTTPException(status_code=400, detail="File has no R2 storage key")

    # Wipe existing entries for this file — unless resuming.
    if not resume:
        await db.document_page_index.delete_many({"file_id": str(file_rec["_id"])})
        await db.document_page_chunks.delete_many({"file_id": str(file_rec["_id"])})

    # Count pages for the response (best-effort)
    total_pages = 0
    try:
        obj = await asyncio.to_thread(
            _r2_client.get_object, Bucket=R2_BUCKET_NAME, Key=file_rec["r2_key"]
        )
        pdf_bytes = obj["Body"].read()
        try:
            from pypdf import PdfReader
            import io as _io
            total_pages = len(PdfReader(_io.BytesIO(pdf_bytes)).pages)
        except Exception:
            total_pages = 0
    except Exception:
        pass

    # Queued, not spawned: the queue survives a restart.
    await _enqueue_plan_index(project_id, file_rec.get("company_id") or company_id or "",
                              dict(file_rec), source="reindex_document", resume=resume)
    return {
        "status": "queued",
        "file_name": file_rec.get("name"),
        "total_pages": total_pages,
    }


@api_router.post("/projects/{project_id}/reindex-all", dependencies=[Depends(require_approved), Depends(require_project_access)])
async def reindex_all_project_files(
    project_id: str,
    resume: bool = False,
    current_user=Depends(get_admin_user),
):
    """Admin-only: queue a full re-index of every PDF on this project.

    `?resume=true` keeps existing rows: pages marked complete are skipped and
    only the rest are indexed. Use it after a deploy interrupted a re-index.

    Useful after a prompt/DPI upgrade — the per-file hash cache is scoped
    by index_version, so v1-indexed pages will get reprocessed automatically
    by _index_pdf_file once spawned.
    """
    if not QWEN_API_KEY:
        raise HTTPException(status_code=503, detail="Plan indexing is not configured")
    company_id = get_user_company_id(current_user)

    q: Dict[str, Any] = {
        "project_id": project_id,
        "name":       {"$regex": r"\.pdf$", "$options": "i"},
        "r2_key":     {"$exists": True, "$ne": ""},
    }
    if company_id:
        q["company_id"] = company_id
    files = await db.project_files.find(q).to_list(500)
    if not files:
        return {"queued": 0, "files": []}

    queued = []
    for fr in files:
        # Wipe existing index entries so stale v1 pages don't linger — unless
        # resuming an interrupted run.
        if not resume:
            await db.document_page_index.delete_many({"file_id": str(fr["_id"])})
            await db.document_page_chunks.delete_many({"file_id": str(fr["_id"])})
        # Queued, not spawned. Sixteen asyncio tasks died with the container on
        # the first Boyland re-index; a queue row does not.
        await _enqueue_plan_index(project_id, fr.get("company_id") or company_id or "",
                                  dict(fr), source="reindex_all", resume=resume)
        queued.append(fr.get("name"))
    return {"queued": len(queued), "files": queued}


# ==================== TEMP-MEDIA PROXY (for WaAPI preflight) ====================
#
# WaAPI's send-media does a HEAD preflight on the supplied URL before fetching
# the body. R2 presigned URLs are method-scoped (a signed GET returns 403 on
# HEAD), so WaAPI rejects them. We side-step by handing WaAPI a URL that
# points to OUR backend — it accepts both HEAD and GET and proxies the bytes
# from R2. Token is opaque and rows TTL-auto-expire via whatsapp_conversation_state.


# -- A VIEW URL CARRIES A GRANT, NEVER A SESSION -----------------------------
#
# An <iframe> and a system browser cannot set an Authorization header, so a
# document URL has to carry its own credential in the query string. What it
# carried was the SESSION JWT, and JWT_EXPIRATION_HOURS is 720 -- a thirty-day
# credential for the whole account, in a string that is logged verbatim.
#
# MEASURED, NOT INFERRED: a request with a marker in its query string was sent
# to production and the marker read back out of the platform log as
# `/api/version?probe=<marker>`. So every document open wrote a live 30-day
# bearer token into a month of log retention, plus the browser history of
# whoever opened it and any link they copied.
#
# -- THE CREDENTIAL HALF OF A LESSON THIS REPO ALREADY LEARNED ---------------
#
# frontend/src/utils/pdfSrc.js exists because Android used to url-encode a
# token-bearing URL into `mozilla.github.io/pdf.js/web/viewer.html?file=...`,
# putting the same 30-day token into a THIRD PARTY's request log. That fix
# changed the DESTINATION -- token only for our own origin, Android never gets
# a remote URL -- and left the credential exactly as it was. It was the right
# fix for the incident and only half the lesson.
#
# DO NOT READ pdfSrc.js AND CONCLUDE THIS WAS SOLVED. It bounds where the URL
# goes. This bounds what the URL is worth.
#
# A GRANT IS SINGLE-PURPOSE AND SHORT-LIVED. It names one R2 object or one
# rendered report, it expires in seconds, and it confers nothing else. The
# token is opaque and random, never derived from the thing it names.
VIEW_GRANTS = "view_grants"
VIEW_GRANT_TTL_SECONDS = 120


async def _mint_view_grant(kind: str, ttl_seconds: int = VIEW_GRANT_TTL_SECONDS,
                           **payload) -> Optional[str]:
    """An opaque token naming ONE thing to serve. None if it cannot be stored.

    RETURNS None RATHER THAN RAISING, and every caller treats that as "no
    link": a document that cannot be granted must not take down the screen
    that lists it.
    """
    import secrets as _secrets
    token = _secrets.token_urlsafe(24)
    now = datetime.now(timezone.utc)
    try:
        await db[VIEW_GRANTS].insert_one({
            "token": token, "kind": kind, "payload": payload,
            "created_at": now,
            "expires_at": now + timedelta(seconds=int(ttl_seconds)),
        })
        try:
            await db[VIEW_GRANTS].create_index(
                "expires_at", expireAfterSeconds=0, name="view_grant_ttl")
            await db[VIEW_GRANTS].create_index("token", name="view_grant_token")
        except Exception:
            pass
    except Exception as e:
        logger.warning(f"view grant insert failed: {e}")
        return None
    return token


async def _resolve_view_grant(token: str) -> Optional[dict]:
    """The row, or None. EXPIRY IS CHECKED HERE AS WELL AS BY THE INDEX.

    A TTL index is a background sweep, not a guarantee: mongod runs it about
    once a minute, so a row can outlive its own expiry by up to that long. On
    a credential measured in seconds that is the difference between the stated
    lifetime and the real one.
    """
    try:
        row = await db[VIEW_GRANTS].find_one({"token": token})
    except Exception:
        return None
    if not row:
        return None
    exp = row.get("expires_at")
    if isinstance(exp, datetime):
        if exp.tzinfo is None:
            exp = exp.replace(tzinfo=timezone.utc)
        if exp <= datetime.now(timezone.utc):
            return None
    return row


def _public_view_url(token: str) -> str:
    # SAME BASE AS _public_temp_media_url, read the same way. Two spellings of
    # one host is how a link starts pointing at the wrong deployment.
    base = os.environ.get("PUBLIC_BASE_URL", "https://api.levelog.com").rstrip("/")
    return f"{base}/api/public/view/{token}"


@app.get("/api/public/view/{token}")
async def public_view_grant(token: str):
    """Serve exactly what one grant names, and nothing else.

    STREAMED IN CHUNKS, NOT BUFFERED. `public_temp_media_get` reads its whole
    object into memory, which is right for a thumbnail and wrong here: the
    largest project file in production is 37.9MB and there are 171MB across 26
    of them, so a buffered read is that spike per concurrent viewer.

    NOT `Cache-Control: public`. The token is opaque and short-lived, but the
    BYTES are a private project document and a shared cache must not keep
    them. `private, no-store` costs nothing on a URL that dies in two minutes.
    """
    from fastapi.responses import HTMLResponse

    row = await _resolve_view_grant(token)
    if not row:
        raise HTTPException(status_code=404, detail="Not found or expired")
    kind = row.get("kind")
    data = row.get("payload") or {}
    _no_store = {"Cache-Control": "private, no-store"}

    if kind == "r2_object":
        r2_key = data.get("r2_key") or ""
        if not r2_key or not _r2_client or not R2_BUCKET_NAME:
            raise HTTPException(status_code=404, detail="File not stored in R2")
        try:
            obj = await asyncio.to_thread(
                _r2_client.get_object, Bucket=R2_BUCKET_NAME, Key=r2_key)
        except Exception as e:
            logger.error(f"view grant R2 get failed {r2_key}: {e}")
            raise HTTPException(status_code=502, detail="Storage fetch failed")
        body = obj["Body"]

        def _iter():
            try:
                for chunk in iter(lambda: body.read(65536), b""):
                    yield chunk
            finally:
                try:
                    body.close()
                except Exception:
                    pass

        fname = str(data.get("filename") or "file").replace('"', "")
        return StreamingResponse(
            _iter(),
            media_type=(obj.get("ContentType")
                        or data.get("content_type")
                        or "application/octet-stream"),
            headers={**_no_store,
                     "Content-Disposition": f'inline; filename="{fname}"'},
        )

    if kind in ("report_html", "report_pdf"):
        html = await generate_combined_report(
            str(data.get("project_id") or ""), str(data.get("date") or ""))
        if kind == "report_html":
            return HTMLResponse(content=html, headers=_no_store)

        def _render_pdf(h: str) -> bytes:
            from weasyprint import HTML
            return HTML(string=h).write_pdf()

        try:
            pdf_bytes = await asyncio.to_thread(_render_pdf, html)
        except Exception as e:
            logger.error(f"view grant PDF render failed: {e}")
            raise HTTPException(status_code=500, detail="PDF generation failed")
        return Response(
            content=pdf_bytes, media_type="application/pdf",
            headers={**_no_store,
                     "Content-Disposition": 'inline; filename="report.pdf"'},
        )

    raise HTTPException(status_code=404, detail="Not found or expired")


async def _mint_temp_media_token(r2_key: str, content_type: str = "image/jpeg",
                                   ttl_seconds: int = 3600) -> str:
    """Store an R2 key under an opaque token; return the token string."""
    import secrets as _secrets
    token = _secrets.token_urlsafe(24)
    now = datetime.now(timezone.utc)
    exp = now + timedelta(seconds=ttl_seconds)
    try:
        await db.temp_media_tokens.insert_one({
            "token":        token,
            "r2_key":       r2_key,
            "content_type": content_type,
            "created_at":   now,
            "expires_at":   exp,
        })
        # Ensure TTL index exists (idempotent).
        try:
            await db.temp_media_tokens.create_index(
                "expires_at", expireAfterSeconds=0, name="temp_media_ttl"
            )
        except Exception:
            pass
    except Exception as e:
        logger.warning(f"temp_media_tokens insert failed: {e}")
    return token


async def _resolve_temp_media_token(token: str) -> Optional[dict]:
    try:
        row = await db.temp_media_tokens.find_one({"token": token})
    except Exception:
        return None
    if not row:
        return None
    exp = row.get("expires_at")
    if isinstance(exp, datetime):
        exp_aware = exp if exp.tzinfo is not None else exp.replace(tzinfo=timezone.utc)
        if exp_aware < datetime.now(timezone.utc):
            return None
    return row


# Both routes are mounted on the unauth'd app (not api_router with its
# Depends(get_current_user) on other endpoints) because WaAPI doesn't
# forward auth headers. Token IS the auth.
@app.head("/api/public/temp-media/{token}")
async def public_temp_media_head(token: str):
    row = await _resolve_temp_media_token(token)
    if not row:
        return Response(status_code=404)
    # HEAD must mirror GET headers but have no body.
    return Response(
        status_code=200,
        headers={
            "Content-Type":  row.get("content_type") or "image/jpeg",
            "Cache-Control": "public, max-age=300",
        },
    )


@app.get("/api/public/temp-media/{token}")
async def public_temp_media_get(token: str):
    row = await _resolve_temp_media_token(token)
    if not row:
        raise HTTPException(status_code=404, detail="Not found or expired")
    r2_key = row.get("r2_key") or ""
    if not r2_key or not _r2_client or not R2_BUCKET_NAME:
        raise HTTPException(status_code=404, detail="Storage miss")
    try:
        obj = await asyncio.to_thread(
            _r2_client.get_object, Bucket=R2_BUCKET_NAME, Key=r2_key
        )
        data = obj["Body"].read()
    except Exception as e:
        logger.error(f"temp-media R2 get failed {r2_key}: {e}")
        raise HTTPException(status_code=502, detail="Storage fetch failed")
    return Response(
        content=data,
        media_type=row.get("content_type") or "image/jpeg",
        headers={"Cache-Control": "public, max-age=300"},
    )


def _public_temp_media_url(token: str) -> str:
    """Build the fully-qualified URL WaAPI will HEAD+GET."""
    base = os.environ.get("PUBLIC_BASE_URL", "https://api.levelog.com").rstrip("/")
    return f"{base}/api/public/temp-media/{token}"


# ── A FILED RECORD OPENS FOR SOMEBODY WITH NO LOGIN ─────────────────────────
#
# WHY THIS EXISTS. The investor report is getting a PROJECT RECORD page: eight
# cards, each naming one filed logbook, each with a View Document button. Today
# the report EMBEDS every logbook in full, so a lender reading the attachment
# already has the content. The button is a MECHANISM CHANGE, not an access
# change -- it replaces twenty pages of embedded record with eight links.
#
# `get_single_logbook_pdf` is `Depends(get_current_user)`, and its `token`
# query parameter is a JWT for that same authenticated user. An investor
# opening the emailed PDF and clicking a card gets a 401. That is what this
# closes.
#
# ── IT REUSES temp-media's PATTERN AND NOT ITS RESOLVER ─────────────────────
#
# `_mint_temp_media_token` maps a token to an R2 KEY and streams that object.
# A per-logbook PDF is not an R2 object -- it is RENDERED ON DEMAND from the
# stored document. Putting one in R2 per report would be eight renders and
# eight uploads a day per project, storing a second copy of something that
# regenerates deterministically from the record.
#
# So the payload differs and everything else is the same, deliberately: the
# opaque `token_urlsafe(24)`, the `expires_at` TTL index that DELETES the row,
# the mount on `app` rather than `api_router` so no auth dependency runs, and
# the rule that made those safe -- THE TOKEN IS THE AUTH.
#
# ── NINETY DAYS, AND WHY IT IS NOT PERMANENT ────────────────────────────────
#
# temp-media defaults to 3600 seconds because WaAPI HEADs and GETs a URL within
# seconds of being handed it. A report is read weeks later, so that default is
# wrong here by orders of magnitude -- and "then make it permanent" is the
# wrong correction.
#
# AN EMBEDDED PDF AND A LINK DIFFER IN ONE RESPECT: THE LINK KEEPS WORKING AND
# IT FORWARDS. A PDF in an inbox is a copy of what the recipient was sent. A
# URL is a live door into a statutory record, it survives being pasted into a
# group chat, and nothing about it decays. Ninety days is what bounds that
# difference: it covers a quarterly reading cycle with margin, and a leaked
# link dies.
#
# EXPIRY IS ENFORCED BY DELETION, NOT BY A CHECK. The TTL index removes the row
# and the route 404s on a token it cannot find. There is no predicate anybody
# has to remember to write, and no code path that can forget to consult one --
# which is the property that makes this an access control rather than a
# convention.
#
# If a recipient needs a record after ninety days they ask, and that is the
# right amount of friction on a compliance document: it produces a conversation
# instead of silent indefinite access.
SHARED_LOGBOOK_TTL_SECONDS = 90 * 24 * 3600


async def _mint_logbook_share_token(
    logbook_id: str, ttl_seconds: int = SHARED_LOGBOOK_TTL_SECONDS,
) -> Optional[str]:
    """Store a logbook id under an opaque token; return the token, or None.

    RETURNS None RATHER THAN RAISING. This is called while rendering a report
    that is about to be emailed. A failed insert must cost the reader one
    button, not the whole document -- the caller omits the link and the card
    still names the record.
    """
    import secrets as _secrets
    token = _secrets.token_urlsafe(24)
    now = datetime.now(timezone.utc)
    try:
        await db.logbook_share_tokens.insert_one({
            "token":      token,
            "logbook_id": str(logbook_id),
            "created_at": now,
            "expires_at": now + timedelta(seconds=ttl_seconds),
        })
        try:
            await db.logbook_share_tokens.create_index(
                "expires_at", expireAfterSeconds=0, name="logbook_share_ttl"
            )
        except Exception:
            pass
    except Exception as e:
        logger.warning(f"logbook_share_tokens insert failed: {e}")
        return None
    return token


async def _resolve_logbook_share_token(token: str) -> Optional[dict]:
    """The row, or None for unknown AND for expired.

    THE EXPIRY IS CHECKED HERE AS WELL AS BY THE INDEX. MongoDB's TTL monitor
    runs about once a minute, so a row is readable for up to a minute after it
    expires. One minute is nothing against ninety days -- but a resolver that
    trusts the sweep is a resolver that returns a stale grant, and the whole
    point of the index is that nothing has to remember. This is the same
    belt-and-braces `_resolve_temp_media_token` already applies.
    """
    try:
        row = await db.logbook_share_tokens.find_one({"token": token})
    except Exception:
        return None
    if not row:
        return None
    exp = row.get("expires_at")
    if isinstance(exp, datetime):
        exp_aware = exp if exp.tzinfo is not None else exp.replace(tzinfo=timezone.utc)
        if exp_aware < datetime.now(timezone.utc):
            return None
    return row


# ── A CARD'S THUMBNAIL IS RENDERED ONCE, EVER ───────────────────────────────
#
# The project record page shows each filed logbook as a card with a picture of
# its first page. Rendering that on every report would be SEVEN WeasyPrint
# renders plus seven rasterisations per project per day, each fetching its
# photographs over HTTP -- roughly eight times the current cost, daily, for a
# document that cannot change.
#
# A FILED LOG IS FROZEN, so the thumbnail is a pure function of it. The cache
# key is (logbook_id, updated_at): `updated_at` moves when a photograph is
# appended -- the only write `append_activity_photo` is allowed outside
# photos[] -- so an appended photograph produces a new key and a new picture,
# and nothing else does.
#
# STORED IN R2 AND SERVED BY TOKEN. WeasyPrint fetches images over HTTP like a
# mail client, so the bytes need a URL. `_mint_temp_media_token` maps a token
# to an R2 key and streams it from a route with no auth dependency, which is
# exactly this: a public URL to an R2 object. The default one-hour TTL is
# right here and wrong for a document link -- the fetch happens DURING the
# render, seconds after the mint, not weeks later by a reader.
#
# ── FIRST LIVE USE OF POPPLER IN THIS CODEBASE ──────────────────────────────
#
# `pdf2image` is in requirements.txt and `poppler-utils` is in both the
# Dockerfile and nixpacks.toml, but the only existing caller is the annotation
# screenshot behind `SCREENSHOT_ENABLED = False`. Nothing exercises it in
# production today. So every failure path below returns None rather than
# raising, and the card renders without a picture: A MISSING THUMBNAIL COSTS AN
# IMAGE, NEVER THE CARD.
THUMBNAIL_DPI = 72
THUMBNAIL_WIDTH = 240


def _logbook_thumb_r2_key(logbook_id: str, cache_version: str) -> str:
    # `cache_version` CARRIES THE RENDERER, not just the record -- see
    # LEGAL_RENDERER_VERSION. A key on the record alone would serve the old
    # picture for ever after a restyle, because a filed log never changes.
    return f"report-thumbs/{logbook_id}/{cache_version}.png"


def _render_logbook_thumbnail(pdf_bytes: bytes) -> Optional[bytes]:
    """Page one of a PDF as a small PNG, or None. NEVER raises.

    OFF THE EVENT LOOP BY ITS CALLER -- poppler forks a process and Pillow is
    CPU-bound, so this is run through asyncio.to_thread like every other
    rasterisation in this file.
    """
    try:
        from pdf2image import convert_from_bytes
        from PIL import Image
    except Exception as e:
        logger.warning(f"thumbnail: pdf2image/Pillow unavailable: {e}")
        return None
    try:
        pages = convert_from_bytes(
            pdf_bytes, first_page=1, last_page=1, dpi=THUMBNAIL_DPI)
        if not pages:
            return None
        img = pages[0]
        if img.width > THUMBNAIL_WIDTH:
            h = max(1, int(img.height * THUMBNAIL_WIDTH / img.width))
            img = img.resize((THUMBNAIL_WIDTH, h), Image.LANCZOS)
        buf = io.BytesIO()
        img.save(buf, format="PNG", optimize=True)
        return buf.getvalue()
    except Exception as e:
        # POPPLER MISSING FROM THE CONTAINER LANDS HERE, and so does a PDF it
        # cannot parse. Both are "no picture", and neither may reach the caller
        # as an exception.
        logger.warning(f"thumbnail: raster failed: {e}")
        return None


async def _logbook_thumbnail_url(logbook: dict) -> Optional[str]:
    """A public URL for this logbook's first page, or None.

    THE CACHE IS CHECKED BEFORE ANYTHING IS RENDERED, which is the whole point:
    on every day after the first, this is one indexed read and one token mint.
    """
    lb_id = str(logbook.get("_id") or "")
    if not lb_id or not _r2_client or not R2_BUCKET_NAME:
        return None
    key = _logbook_thumb_r2_key(lb_id, _logbook_cache_version(logbook))

    try:
        cached = await db.logbook_thumbnails.find_one({"_id": key})
    except Exception:
        cached = None

    if not cached:
        try:
            html = await generate_single_logbook_html(logbook)

            # NAMED `_render_pdf` LIKE THE OTHER THREE, and the name is load
            # bearing: test_close_external_review asserts that every
            # `write_pdf` in this file sits inside a helper called
            # `_render_pdf` or `_default_pdf_renderer`. This call WAS already
            # offloaded -- `asyncio.to_thread` two lines down -- so the check
            # was refusing a convention rather than a defect, which is exactly
            # what it is for: the convention is how the next inline render is
            # caught.
            def _render_pdf(h: str) -> bytes:
                from weasyprint import HTML
                return HTML(string=h).write_pdf()

            pdf_bytes = await asyncio.to_thread(_render_pdf, html)
            png = await asyncio.to_thread(_render_logbook_thumbnail, pdf_bytes)
            if not png:
                return None
            await asyncio.to_thread(
                _upload_to_r2, png, key, "image/png")
            # THE ROW IS WRITTEN AFTER THE OBJECT, never before: a cache entry
            # naming an object R2 does not have would serve a broken image
            # every day thereafter, and nothing would retry it.
            await db.logbook_thumbnails.update_one(
                {"_id": key},
                {"$set": {"r2_key": key, "logbook_id": lb_id,
                          "created_at": datetime.now(timezone.utc)}},
                upsert=True,
            )
        except Exception as e:
            logger.warning(f"thumbnail: build failed for {lb_id}: {e}")
            return None

    try:
        tok = await _mint_temp_media_token(key, "image/png", ttl_seconds=3600)
    except Exception as e:
        logger.warning(f"thumbnail: token mint failed for {lb_id}: {e}")
        return None
    return _public_temp_media_url(tok) if tok else None


def _public_logbook_url(token: str) -> str:
    """The URL a View Document button points at."""
    base = os.environ.get("PUBLIC_BASE_URL", "https://api.levelog.com").rstrip("/")
    return f"{base}/api/public/logbook/{token}"


# ON `app`, NOT `api_router`. Same reason temp-media's two routes are: the
# router carries an auth dependency, and a recipient of the report has no
# account to authenticate as.
@app.get("/api/public/logbook/{token}")
async def public_logbook_pdf(token: str):
    """Render one filed logbook as a PDF for a holder of a valid token.

    NOTHING IS TRUSTED FROM THE URL EXCEPT THE TOKEN. The logbook id comes from
    the stored row, so a token cannot be pointed at a different record by
    editing the link -- which is the failure a `?logbook_id=` parameter beside
    a token would invite.
    """
    row = await _resolve_logbook_share_token(token)
    if not row:
        # ONE ANSWER FOR UNKNOWN AND EXPIRED. Distinguishing them tells a
        # holder of a guessed token that it was once real.
        raise HTTPException(status_code=404, detail="Not found or expired")

    logbook = await db.logbooks.find_one({
        "_id": to_query_id(row.get("logbook_id") or ""),
        "is_deleted": {"$ne": True},
    })
    if not logbook:
        raise HTTPException(status_code=404, detail="Not found or expired")

    # ── EVERY FETCH IS RECORDED ─────────────────────────────────────────────
    #
    # Nothing else in this system would show that a statutory record was read
    # by somebody with no account. The authenticated readers leave a session;
    # this route leaves nothing unless it writes something.
    #
    # BEFORE THE RENDER, so a fetch that fails to render is still recorded as a
    # fetch. What is interesting is that the door was opened, not that the PDF
    # came back.
    #
    # NEVER RAISES. An audit write that can 500 the read turns a logging
    # feature into an availability risk on somebody else's document.
    try:
        await db.logbook_share_reads.insert_one({
            "token":      token,
            "logbook_id": str(row.get("logbook_id") or ""),
            "project_id": str(logbook.get("project_id") or ""),
            "log_type":   logbook.get("log_type"),
            "date":       logbook.get("date"),
            "read_at":    datetime.now(timezone.utc),
            # NO IP, NO USER AGENT. Neither identifies anyone here and both are
            # personal data on a record about a construction site.
        })
    except Exception as e:
        logger.warning(f"logbook_share_reads insert failed: {e}")

    html = await generate_single_logbook_html(logbook)
    try:
        from weasyprint import HTML

        def _render_pdf(h: str) -> bytes:
            return HTML(string=h).write_pdf()

        pdf_bytes = await asyncio.to_thread(_render_pdf, html)
    except Exception as e:
        logger.error(f"public logbook PDF render failed for {row.get('logbook_id')}: {e}")
        raise HTTPException(status_code=500, detail="PDF generation failed")

    project = await db.projects.find_one(
        {"_id": to_query_id(logbook.get("project_id"))})
    project_name = (project.get("name", "report") if project else "report").replace(" ", "_")
    type_label = str(logbook.get("log_type") or "log").replace("_", "-")
    filename = f"Levelog_{type_label}_{project_name}_{logbook.get('date')}.pdf"
    return Response(
        content=pdf_bytes,
        media_type="application/pdf",
        # INLINE, NOT ATTACHMENT. The authenticated route downloads because an
        # admin is filing it; a lender who clicked a button in a report wants
        # to LOOK at the page, and a download that lands in a folder is a
        # worse answer to "show me the record".
        headers={"Content-Disposition": f'inline; filename="{filename}"'},
    )


@api_router.post("/debug/probe-waapi-endpoints")
async def debug_probe_waapi_endpoints(
    body: dict,
    current_user=Depends(get_admin_user),
):
    """Probe multiple WaAPI action paths with the same test payload to see
    which endpoint actually accepts our image sends. Returns {path: status}.

    Body: {"image_url": "<presigned_r2_url>", "group_id": "<wa_group_id>"}
    """
    image_url = (body or {}).get("image_url", "").strip()
    group_id = (body or {}).get("group_id", "").strip()
    if not image_url or not group_id:
        raise HTTPException(status_code=422, detail="image_url and group_id required")
    if not WAAPI_INSTANCE_ID or not WAAPI_TOKEN:
        raise HTTPException(status_code=503, detail="WaAPI not configured")

    paths_to_try = [
        ("client/action/send-image",       {"chatId": group_id, "image":    image_url, "caption": "probe"}),
        ("client/action/send-media",       {"chatId": group_id, "mediaUrl": image_url, "caption": "probe"}),
        ("client/action/send-media",       {"chatId": group_id, "media":    image_url, "caption": "probe"}),
        ("client/action/send-media-url",   {"chatId": group_id, "mediaUrl": image_url, "caption": "probe"}),
        ("client/action/send-file-picture",{"chatId": group_id, "image":    image_url, "caption": "probe"}),
        ("client/action/send-message",     {"chatId": group_id, "mediaUrl": image_url, "message": "probe"}),
    ]
    results = {}
    async with ServerHttpClient(timeout=25.0) as client_http:
        for path, payload in paths_to_try:
            try:
                resp = await client_http.post(
                    f"{WAAPI_BASE_URL}/instances/{WAAPI_INSTANCE_ID}/{path}",
                    headers={
                        "Authorization": f"Bearer {WAAPI_TOKEN}",
                        "Content-Type":  "application/json",
                    },
                    json=payload,
                )
                try:
                    j = resp.json()
                except Exception:
                    j = None
                results[f"{path} fields={list(payload.keys())}"] = {
                    "status": resp.status_code,
                    "body_preview": resp.text[:300],
                    "json": j,
                }
            except Exception as e:
                results[path] = {"error": str(e)[:200]}
    return {"base_url": WAAPI_BASE_URL, "instance": WAAPI_INSTANCE_ID, "results": results}


@api_router.post("/projects/{project_id}/debug/test-plan-image-send", dependencies=[Depends(require_approved), Depends(require_project_access)])
async def debug_test_plan_image_send(
    project_id: str,
    body: dict,
    current_user=Depends(get_admin_user),
):
    """Admin diagnostic — try to send a specific sheet's pre-rendered JPEG
    to a WhatsApp group and return the exact WaAPI response + our internal
    step results. Use this to figure out why image sends fall back to text
    without needing to tail Railway logs.

    Body: {"sheet_number": "Z-101.00", "group_id": "<wa_group_id>"}
    """
    sheet = (body or {}).get("sheet_number", "").strip()
    group_id = (body or {}).get("group_id", "").strip()
    if not sheet or not group_id:
        raise HTTPException(status_code=422, detail="sheet_number and group_id required")

    page = await db.document_page_index.find_one({
        "project_id": project_id,
        "sheet_number": {"$regex": f"^{re.escape(sheet)}(\\.\\d+)?$", "$options": "i"},
    })
    if not page:
        raise HTTPException(status_code=404, detail=f"No indexed page for sheet {sheet}")

    result = {
        "sheet_number":     page.get("sheet_number"),
        "sheet_title":      page.get("sheet_title"),
        "page_jpeg_r2_key": page.get("page_jpeg_r2_key"),
        "steps": {},
    }

    # Step 1 — fetch the jpeg (and compress for WhatsApp delivery)
    jpeg_src = await _fetch_page_jpeg(page)
    if jpeg_src:
        jpeg = await asyncio.to_thread(_compress_jpeg_for_whatsapp, jpeg_src)
    else:
        jpeg = None
    result["steps"]["fetch_jpeg"] = {
        "ok": bool(jpeg),
        "src_size": len(jpeg_src) if jpeg_src else 0,
        "compressed_size": len(jpeg) if jpeg else 0,
    }
    if not jpeg:
        return result

    # Step 2 — upload temp + mint token-based URL
    import uuid as _uuid
    temp_key = f"temp/whatsapp/{group_id}/{_uuid.uuid4()}.jpg"
    try:
        await asyncio.to_thread(_upload_to_r2, jpeg, temp_key, "image/jpeg")
        tok = await _mint_temp_media_token(temp_key, "image/jpeg", ttl_seconds=3600)
        media_url = _public_temp_media_url(tok)
        result["steps"]["upload_temp"] = {"ok": True, "temp_key": temp_key}
        result["steps"]["token_url"] = {"ok": True, "url": media_url}
    except Exception as e:
        result["steps"]["upload_temp"] = {"ok": False, "error": str(e)[:300]}
        return result

    # Step 3 — WaAPI send-media
    try:
        async with ServerHttpClient(timeout=40.0) as client_http:
            resp = await client_http.post(
                f"{WAAPI_BASE_URL}/instances/{WAAPI_INSTANCE_ID}/client/action/send-media",
                headers={
                    "Authorization": f"Bearer {WAAPI_TOKEN}",
                    "Content-Type": "application/json",
                },
                json={
                    "chatId":   group_id,
                    "mediaUrl": media_url,
                    "caption":  f"[diagnostic] {page.get('sheet_number')}",
                },
            )
            try:
                body_json = resp.json()
            except Exception:
                body_json = None
            result["steps"]["waapi_send_media"] = {
                "status":     resp.status_code,
                "ok":         200 <= resp.status_code < 300,
                "body_text":  resp.text[:800],
                "body_json":  body_json,
            }
    except Exception as e:
        result["steps"]["waapi_send_media"] = {"error": str(e)[:300]}
    return result


# A {project_id} IN THE PATH IS NOT AUTHORIZATION. Without this dependency the
# path id went straight into the query and any authenticated caller could name
# another tenant's project and read sheet numbers, titles, disciplines and AI summaries of another tenant's drawings. The company filter below cannot substitute for it:
# a caller with a legitimate company could still name a project outside it.
# Same dependency POST /projects/{project_id}/reindex-document already carries.
@api_router.get("/projects/{project_id}/debug/indexed-pages", dependencies=[Depends(require_project_access)])
async def debug_indexed_pages(
    project_id: str,
    current_user=Depends(get_current_user),
    limit: int = 50,
):
    """Admin diagnostic — show what v2 indexing actually stored for this
    project's pages. Returns the interesting fields only (no raw summaries
    over 400 chars, no full embedding array)."""
    if not is_company_admin(current_user):
        raise HTTPException(status_code=403, detail="Admin access required")
    company_id = get_user_company_id(current_user)
    q: Dict[str, Any] = {"project_id": project_id}
    if company_id:
        q["company_id"] = company_id
    rows = await db.document_page_index.find(q).sort([
        ("file_name", 1), ("page_number", 1),
    ]).limit(limit).to_list(limit)
    out = []
    for r in rows:
        summary = r.get("summary") or ""
        emb = r.get("embedding")
        out.append({
            "file_name":        r.get("file_name"),
            "page":             r.get("page_number"),
            "index_version":    r.get("index_version"),
            "discipline":       r.get("discipline"),
            "sheet_number":     r.get("sheet_number"),
            "sheet_title":      r.get("sheet_title"),
            "floor":            r.get("floor"),
            "is_spec_page":     r.get("is_spec_page"),
            "keywords_count":   len(r.get("keywords") or []),
            "summary_length":   len(summary),
            "summary_preview":  summary[:400],
            "has_embedding":    bool(emb) and isinstance(emb, list) and len(emb) > 0,
            "embedding_dim":    (len(emb) if isinstance(emb, list) else 0),
            "page_jpeg_r2_key": r.get("page_jpeg_r2_key") or "",
            "materials_preview": (r.get("materials") or "")[:200],
        })
    return {"count": len(out), "pages": out}


# A {project_id} IN THE PATH IS NOT AUTHORIZATION. Without this dependency the
# path id went straight into the query and any authenticated caller could name
# another tenant's project and read file names and page counts -- and it FETCHES EVERY MATCHED PDF FROM R2 to count pages, so an unauthorized caller also drove unmetered egress. The company filter below cannot substitute for it:
# a caller with a legitimate company could still name a project outside it.
# Same dependency POST /projects/{project_id}/reindex-document already carries.
@api_router.get("/admin/plan-index/failed", tags=["Admin"],
                dependencies=[Depends(require_approved)])
async def list_failed_plan_index_jobs(current_user=Depends(get_admin_user)):
    """Every plan-index job that gave up, across this admin's projects.

    ── A JOB AT THREE ATTEMPTS IS SILENT ──────────────────────────────────
    #
    # `_run_plan_index_job` marks a file `failed` after PLAN_INDEX_MAX_ATTEMPTS
    # and writes the reason onto the job row. Nothing read that row.
    # document-index-status returns it per file, and the only client that ever
    # called document-index-status was a dead wrapper in the app's api.js — so
    # a drawing set that failed three times disappeared, and the next anyone
    # learned of it was a plan question answering "not on the indexed
    # drawings" about a sheet that is sitting in Plans & Files.
    #
    # Cross-project deliberately: nobody opens sixteen projects to find the one
    # that broke. Scoped to the caller's company unless they are the platform
    # operator, the same rule every other admin surface here follows.
    #
    # STUCK IS REPORTED BESIDE FAILED. A job whose lease expired while it was
    # running is recovered by the worker on its next pass, which is correct and
    # invisible; it is worth seeing when it happens repeatedly, because that is
    # what three attempts looks like on the way to failing.
    """
    # SCOPED BY WHAT THE CALLER IS, NOT BY WHAT THEY LACK. `if company_id:`
    # would have made a companyless account read every tenant's queue — the
    # double-permissive shape the census gates exist to keep out. The platform
    # operator is a role, tested for; everyone else needs a company, and no
    # company is a refusal rather than a wildcard.
    company_id = get_user_company_id(current_user)
    query: Dict[str, Any] = {}
    if not is_platform_operator(current_user):
        if not company_id:
            raise HTTPException(status_code=403,
                                detail="No company on this account")
        query["company_id"] = company_id
    now = datetime.now(timezone.utc)
    try:
        rows = await db[PLAN_INDEX_JOBS].find(query).to_list(500)
    except Exception as e:
        logger.warning(f"failed plan-index list read failed: {e!r}")
        raise HTTPException(status_code=503, detail="Could not read the index queue")

    names: Dict[str, str] = {}
    out = []
    for j in rows:
        status = j.get("status")
        lease = _as_utc(j.get("lease_until"))
        stuck = status == "running" and lease is not None and lease < now
        if status not in ("failed", "cancelled") and not stuck:
            continue
        pid = str(j.get("project_id") or "")
        if pid and pid not in names:
            try:
                p = await db.projects.find_one({"_id": to_query_id(pid)},
                                               {"name": 1, "address": 1})
            except Exception:
                p = None
            names[pid] = ((p or {}).get("address") or (p or {}).get("name") or "")
        out.append({
            "file_id": str(j.get("_id")),
            "file_name": j.get("file_name"),
            "project_id": pid,
            "project_name": names.get(pid) or None,
            # 'stuck' is not a stored status: it is a running job whose lease
            # ran out, which the row cannot say on its own.
            "state": "stuck" if stuck else status,
            "attempts": int(j.get("attempts") or 0),
            "pages_done": j.get("pages_done"),
            "pages_total": j.get("pages_total"),
            "error": j.get("error"),
            "enqueued_at": j.get("enqueued_at"),
            "started_at": j.get("started_at"),
            "finished_at": j.get("finished_at"),
            "updated_at": j.get("updated_at"),
        })
    out.sort(key=lambda r: str(r.get("updated_at") or ""), reverse=True)
    return {"count": len(out), "jobs": out}


@api_router.post("/projects/{project_id}/plan-index/{file_id}/retry",
                 dependencies=[Depends(require_approved), Depends(require_project_access)])
async def retry_plan_index_job(project_id: str, file_id: str,
                               current_user=Depends(get_admin_user)):
    """Put a given-up file back on the queue, keeping the pages it finished.

    RESUME, NOT RESTART. A set that failed on page 90 of 129 has 89 pages that
    cost vision calls; re-running them buys nothing and is charged again.
    `_enqueue_plan_index` already resets attempts, clears the error and
    re-queues, so a retry is that call and not a second code path that could
    drift from it."""
    rec = await db.project_files.find_one(
        {"_id": to_query_id(file_id), "project_id": project_id,
         "is_deleted": {"$ne": True}})
    if not rec:
        raise HTTPException(status_code=404, detail="File not found on this project")
    company_id = get_user_company_id(current_user)
    if not is_platform_operator(current_user):
        if not company_id:
            raise HTTPException(status_code=403, detail="No company on this account")
        if rec.get("company_id") != company_id:
            raise HTTPException(status_code=403, detail="Access denied")
    if not QWEN_API_KEY:
        raise HTTPException(status_code=503, detail="Plan indexing is not configured")

    outcome = await _enqueue_plan_index(
        project_id, rec.get("company_id") or company_id or "", dict(rec),
        source="retry", resume=True)
    logger.info(f"plan index retry {rec.get('name')} on {project_id}: {outcome}")
    return {"queued": outcome in ("queued", "requeued", "rerun_after_current"),
            "outcome": outcome, "file_name": rec.get("name")}


@api_router.get("/projects/{project_id}/document-index-status", dependencies=[Depends(require_project_access)])
async def get_document_index_status(
    project_id: str,
    current_user=Depends(get_current_user),
):
    """Per-file indexing status for a project. Includes a top-level flag
    that tells the frontend whether the server has a Qwen key at all."""
    company_id = get_user_company_id(current_user)
    query: Dict[str, Any] = {"project_id": project_id}
    if company_id:
        query["company_id"] = company_id
    # PDFs only
    query["name"] = {"$regex": r"\.pdf$", "$options": "i"}

    files_out = []

    files = await db.project_files.find(query).to_list(500)

    # A DEVICE IS NOT TOLD ABOUT WHAT IT MAY NOT FETCH. This returned
    # `file_id` and `file_name` for every PDF on the project regardless of the
    # allow-list, which is how a device learned the ids it then streamed. The
    # names alone are a disclosure -- a drawing register is a list of what the
    # job is building -- so the filter is here and not only on the stream.
    if _is_site_device(current_user):
        _project_doc = await db.projects.find_one({"_id": to_query_id(project_id)})
        files = [
            fr for fr in files
            if _site_device_may_retrieve(_project_doc or {}, current_user,
                                         fr.get("dropbox_path") or "")
        ]

    # ── THE QUEUE, NOT THE BUCKET ─────────────────────────────────────────
    #
    # This downloaded EVERY PDF on the project from R2 and parsed it, on every
    # call, to count pages — about 90 MB for 588 Thomas S Boyland St, repeated
    # every 30 seconds by a polling script, on the same container doing the
    # indexing. The job table already knows pages_total and pages_done, and the
    # page count is stored on the file when a job starts.
    jobs: Dict[str, dict] = {}
    file_ids = [str(fr.get("_id")) for fr in files]
    if file_ids:
        for j in await db[PLAN_INDEX_JOBS].find(
            {"project_id": project_id, "_id": {"$in": file_ids}},
        ).to_list(len(file_ids) + 1):
            jobs[str(j["_id"])] = j

    for fr in files:
        file_id = str(fr.get("_id"))
        job = jobs.get(file_id)
        if job:
            indexed = int(job.get("pages_done") or 0)
            total_pages = int(job.get("pages_total") or fr.get("page_count") or 0)
            queue_status = job.get("status")
        else:
            # Spec pages ARE indexed pages. Leaving them out made ST read
            # 13/14 and AR 24/26 on a run where every page was done.
            indexed = await db.document_page_index.count_documents({
                "file_id": file_id,
            })
            total_pages = int(fr.get("page_count") or 0)
            queue_status = "indexed" if indexed else "not_queued"
        most_recent = await db.document_page_index.find_one(
            {"file_id": file_id},
            sort=[("indexed_at", -1)],
        )
        files_out.append({
            "file_id": file_id,
            "file_name": fr.get("name"),
            "total_pages": total_pages,
            "indexed_pages": indexed,
            "last_indexed_at": (most_recent or {}).get("indexed_at"),
            "index_status": _public_index_status(fr.get("index_status")),
            "queue_status": queue_status,
            "queue": ({k: job.get(k) for k in (
                "status", "pages_done", "pages_total", "attempts", "deferrals",
                "error", "not_before", "enqueued_at", "started_at", "finished_at",
                "updated_at")} if job else None),
        })

    return {
        "qwen_configured": bool(QWEN_API_KEY),
        "files": files_out,
    }


# A {project_id} IN THE PATH IS NOT AUTHORIZATION. Without this dependency the
# path id went straight into the query and any authenticated caller could name
# another tenant's project and read extracted checklist items, completions and completed_by names. The company filter below cannot substitute for it:
# a caller with a legitimate company could still name a project outside it.
# Same dependency POST /projects/{project_id}/reindex-document already carries.
@api_router.get("/projects/{project_id}/whatsapp-checklists", dependencies=[Depends(require_project_access)])
async def list_project_whatsapp_checklists(
    project_id: str,
    group_id: Optional[str] = Query(None),
    date: Optional[str] = Query(None, description="YYYY-MM-DD (EST) filter"),
    limit: int = Query(50, ge=1, le=200),
    skip: int = Query(0, ge=0),
    current_user=Depends(get_current_user),
):
    """List WhatsApp-extracted checklists for a project."""
    company_id = get_user_company_id(current_user)
    query: Dict[str, Any] = {
        "project_id": project_id,
        "is_deleted": {"$ne": True},
    }
    if company_id:
        query["company_id"] = company_id
    if group_id:
        query["group_id"] = group_id
    if date:
        try:
            from zoneinfo import ZoneInfo
            eastern = ZoneInfo("America/New_York")
            day_start_est = datetime.strptime(date, "%Y-%m-%d").replace(tzinfo=eastern)
            day_start_utc = day_start_est.astimezone(timezone.utc)
            day_end_utc = day_start_utc + timedelta(hours=24)
            query["generated_at"] = {"$gte": day_start_utc, "$lt": day_end_utc}
        except Exception:
            raise HTTPException(status_code=422, detail="date must be YYYY-MM-DD")

    total = await db.whatsapp_checklists.count_documents(query)
    cursor = (
        db.whatsapp_checklists
        .find(query)
        .sort("generated_at", -1)
        .skip(skip)
        .limit(limit)
    )
    items = []
    async for doc in cursor:
        items.append(serialize_id(doc))
    return {
        "items": items,
        "total": total,
        "limit": limit,
        "skip": skip,
        "has_more": (skip + limit) < total,
    }


@api_router.put("/whatsapp-checklists/{checklist_id}/items/{item_index}")
async def update_whatsapp_checklist_item(
    checklist_id: str,
    item_index: int,
    body: dict,
    current_user=Depends(get_current_user),
):
    """Mark a single item complete/incomplete from the app."""
    if "completed" not in body or not isinstance(body["completed"], bool):
        raise HTTPException(status_code=422, detail="completed (bool) is required")

    doc = await db.whatsapp_checklists.find_one({"_id": to_query_id(checklist_id)})
    if not doc:
        raise HTTPException(status_code=404, detail="Checklist not found")

    # THE ROW'S OWN company_id, and "" counts as absent. Both writers of this
    # collection stamp `company_id or ""`, so an unowned checklist is PRESENT
    # and EMPTY -- an $exists audit would have read clean while every item on
    # every such row was toggleable by any authenticated user.
    _same_company_or_403(doc, current_user)

    items = list(doc.get("items") or [])
    if item_index < 0 or item_index >= len(items):
        raise HTTPException(status_code=404, detail="item_index out of range")

    now = datetime.now(timezone.utc)
    items[item_index] = {
        **items[item_index],
        "completed": body["completed"],
        "completed_at": now if body["completed"] else None,
        "completed_by": current_user.get("name") or current_user.get("email") if body["completed"] else None,
    }

    await db.whatsapp_checklists.update_one(
        {"_id": to_query_id(checklist_id)},
        {"$set": {"items": items, "updated_at": now}},
    )
    updated = await db.whatsapp_checklists.find_one({"_id": to_query_id(checklist_id)})
    return serialize_id(updated)


@api_router.get("/whatsapp/contact.vcf")
async def whatsapp_contact_vcard(current_user=Depends(get_current_user)):
    """
    Return a vCard 3.0 for the Levelog Assistant WhatsApp number so the user
    can save it to their native contacts app and add it to WhatsApp groups.
    Requires the caller's company to have an active whatsapp_config.
    """
    company_id = get_user_company_id(current_user)
    if not company_id:
        raise HTTPException(status_code=400, detail="No company associated with this user.")

    wa_config = await db.whatsapp_config.find_one({"company_id": company_id})
    if not wa_config or not wa_config.get("is_active"):
        raise HTTPException(
            status_code=400,
            detail="WhatsApp integration is not active for this company. Activate it first on the integrations page.",
        )

    # Per-company number first, then fall back to env (forward-compatible)
    raw_number = (wa_config.get("whatsapp_number") or "").strip()
    if not raw_number:
        raw_number = os.environ.get("WAAPI_DISPLAY_NUMBER", "").strip()
    if not raw_number:
        raise HTTPException(status_code=500, detail="WhatsApp number is not configured on the server.")

    # Normalize to E.164 (ensure leading +)
    digits = re.sub(r"\D", "", raw_number)
    if not digits:
        raise HTTPException(status_code=500, detail="Invalid WhatsApp number format.")
    e164 = f"+{digits}"

    # vCard 3.0 — CRLF line endings (iOS strict), escape commas/semicolons in NOTE
    note = (
        "Site intelligence assistant. Ask: who is on site, DOB permit status, "
        "open compliance items, material deliveries, and daily summaries."
    ).replace(";", r"\;").replace(",", r"\,")

    lines = [
        "BEGIN:VCARD",
        "VERSION:3.0",
        "N:Assistant;Levelog;;;",
        "FN:Levelog Assistant",
        "ORG:Levelog",
        "TITLE:Site Intelligence Bot",
        f"TEL;TYPE=CELL,VOICE:{e164}",
        f"X-WHATSAPP:{e164}",
        f"NOTE:{note}",
        "END:VCARD",
    ]
    vcard = "\r\n".join(lines) + "\r\n"

    return Response(
        content=vcard,
        media_type="text/vcard",
        headers={
            "Content-Disposition": 'attachment; filename="levelog-assistant.vcf"',
            "Cache-Control": "no-store",
        },
    )


# ---------- material request endpoints (auth required) ----------

@api_router.get("/projects/{project_id}/material-requests")
async def get_material_requests(project_id: str, status: str = None, current_user=Depends(get_current_user)):
    """Get material requests for a project."""
    query = {"project_id": project_id, "company_id": current_user.get("company_id"), "is_deleted": {"$ne": True}}
    if status:
        query["status"] = status
    requests = await db.material_requests.find(query).sort("created_at", -1).to_list(100)
    for r in requests:
        r["id"] = str(r.pop("_id"))
    return {"requests": requests, "total": len(requests)}


@api_router.put("/material-requests/{request_id}/cancel")
async def cancel_material_request(request_id: str, current_user=Depends(get_current_user)):
    """Cancel a material request (admin only)."""
    if current_user.get("role") not in ("admin", "owner"):
        raise HTTPException(403, "Only admins can cancel material requests")
    result = await db.material_requests.update_one(
        {"_id": to_query_id(request_id), "company_id": current_user.get("company_id")},
        {"$set": {"status": "cancelled", "updated_at": datetime.now(timezone.utc)}}
    )
    if result.modified_count == 0:
        raise HTTPException(404, "Material request not found")
    return {"message": "Material request cancelled"}


# ---------- daily summary scheduler ----------

def _current_est_time_and_date():
    """Return (HH:MM string, ISO weekday 1-7, YYYY-MM-DD date string) in EST/EDT."""
    from zoneinfo import ZoneInfo
    eastern = ZoneInfo("America/New_York")
    now_est = datetime.now(timezone.utc).astimezone(eastern)
    return (
        now_est.strftime("%H:%M"),
        now_est.isoweekday(),  # Mon=1 Sun=7
        now_est.strftime("%Y-%m-%d"),
    )


def _within_30min_window(now_hhmm: str, target_hhmm: str) -> bool:
    """True if now_hhmm is within [target_hhmm, target_hhmm + 30 minutes).

    Computed on whole minutes. A 17:00 target window covers 17:00 through
    17:29 inclusive. A 23:50 target covers 23:50 through 00:19 (wraps).
    """
    try:
        nh, nm = [int(x) for x in now_hhmm.split(":")]
        th, tm = [int(x) for x in target_hhmm.split(":")]
    except Exception:
        return False
    now_minutes = (nh * 60 + nm) % (24 * 60)
    target_minutes = (th * 60 + tm) % (24 * 60)
    diff = (now_minutes - target_minutes) % (24 * 60)
    return 0 <= diff < 30


async def _summarize_and_send_for_group(group_doc: dict) -> None:
    """Build and send a daily summary for one group. Caller handles dedup."""
    project_id = group_doc.get("project_id")
    group_id = group_doc.get("wa_group_id")
    if not project_id or not group_id:
        return

    today_start, today_end = get_today_range_est()
    messages = await db.whatsapp_messages.find({
        "group_id": group_id,
        "created_at": {"$gte": today_start, "$lt": today_end},
    }).sort("created_at", 1).to_list(500)
    if not messages:
        return

    # Build convo text. Skip bot_plan_response messages so the summary
    # doesn't describe the bot's own image sends as if a person said them.
    convo_lines = []
    for m in messages:
        msg_type = m.get("type")
        sender = m.get("sender", "unknown")
        body_text = m.get("body", "")
        if msg_type == "bot_plan_response":
            # Render as a system note, not a human line
            if body_text:
                convo_lines.append(f"[bot sent plan sheet: {body_text}]")
            continue
        if body_text:
            convo_lines.append(f"{sender}: {body_text}")
    if not convo_lines:
        return
    conversation_text = "\n".join(convo_lines[:200])

    project = await db.projects.find_one({"_id": to_query_id(project_id)})
    project_name = project.get("name", "Project") if project else "Project"

    if not OPENAI_API_KEY:
        logger.info(f"Daily summary skipped for {project_name}: no OPENAI_API_KEY")
        return

    try:
        url = "https://api.openai.com/v1/chat/completions"
        headers = {"Authorization": f"Bearer {OPENAI_API_KEY}", "Content-Type": "application/json"}
        gpt_payload = {
            "model": "gpt-4o",
            "temperature": 0.3,
            "max_tokens": 500,
            "messages": [
                {"role": "system", "content": (
                    "You are a construction project assistant. Summarize the day's WhatsApp "
                    "group messages into a concise daily digest. Focus on: key decisions, "
                    "issues raised, action items, and safety concerns. Format with bullet points. "
                    "Keep it under 300 words. Lines wrapped in [brackets] are automated system "
                    "notes, not human messages — treat them as context only."
                )},
                {"role": "user", "content": f"Project: {project_name}\n\nMessages:\n{conversation_text}"},
            ],
        }
        async with ServerHttpClient(timeout=30) as client_http:
            resp = await client_http.post(url, json=gpt_payload, headers=headers)
            resp.raise_for_status()
            summary = resp.json()["choices"][0]["message"]["content"].strip()
        header = f"*Daily Summary - {project_name}*\n_{datetime.now(timezone.utc).strftime('%B %d, %Y')}_\n"
        await send_whatsapp_message(group_id, header + "\n" + summary)
    except Exception as e:
        logger.error(f"Daily summary GPT failed for {project_name}: {e}")


async def _send_whatsapp_daily_summaries():
    """Runs every 30 min. For each active group:
    - skip if bot_enabled == False
    - skip if daily_summary_enabled == False
    - skip if today's ISO weekday not in daily_summary_days
    - skip if current EST time not within [configured_time, +30min)
    - dedup via whatsapp_send_log (MongoDB unique key) so re-fires within
      the window send at most once per day per group.
    """
    try:
        now_hhmm, iso_weekday, today_est = _current_est_time_and_date()
        groups = await db.whatsapp_groups.find({"active": True}).to_list(500)
        for group_doc in groups:
            cfg = group_doc.get("bot_config") or {}
            if not cfg.get("bot_enabled", True):
                continue
            if not cfg.get("daily_summary_enabled", False):
                continue
            days = cfg.get("daily_summary_days", [1, 2, 3, 4, 5])
            if iso_weekday not in (days or []):
                continue
            configured = cfg.get("daily_summary_time", "17:00")
            if not _within_30min_window(now_hhmm, configured):
                continue

            group_id = group_doc.get("wa_group_id")
            if not group_id:
                continue

            # MongoDB-backed dedup — survives restarts.
            first_send = await _whatsapp_send_log_try_mark(
                group_id, "daily_summary", today_est
            )
            if not first_send:
                continue

            try:
                await _summarize_and_send_for_group(group_doc)
            except Exception as e:
                logger.error(f"daily summary send failed for {group_id}: {e}", exc_info=True)
    except Exception as e:
        logger.error(f"WhatsApp daily summary job error: {e}", exc_info=True)


CHECKLIST_SYSTEM_PROMPT = """You are a construction project assistant analyzing WhatsApp group conversations from a NYC construction site.
Extract all action items, commitments, and open issues from the conversation.

For each item found return:
- text: imperative form ("Order 200 sheets of drywall", "Call inspector re: floor 3")
- assigned_to: person name or phone if mentioned, null if unclear
- due_date: specific date or relative term if mentioned, null if none
- category: safety | materials | coordination | inspection | other
- priority: high (safety issues, DOB/inspection, blockers), medium (deliveries, coordination), low (general)

Focus on: explicit requests, commitments made, unresolved issues, safety concerns, inspection prep, material shortages.
Ignore: greetings, already-resolved confirmations, jokes, reactions.

Return ONLY valid JSON: {"items": [...]}
If no action items found return: {"items": []}"""


_CATEGORY_EMOJI = {
    "safety": "⚠️",
    "materials": "📦",
    "coordination": "🤝",
    "inspection": "🔍",
    "other": "•",
}


def _format_checklist_message(project_name: str, items: list) -> str:
    """Produce the WhatsApp-formatted checklist message body."""
    now_est = _current_est_time_and_date()[2]
    high = [i for i in items if (i.get("priority") or "").lower() == "high"]
    med  = [i for i in items if (i.get("priority") or "").lower() == "medium"]
    rest = [i for i in items if (i.get("priority") or "").lower() not in ("high", "medium")]

    lines = [
        f"✅ *Action Items — {project_name}*",
        f"_{now_est}_",
        "",
    ]
    def _render(bucket, header):
        if not bucket:
            return
        lines.append(header)
        for idx_global, it in bucket:
            txt = (it.get("text") or "").strip()
            if not txt:
                continue
            who = (it.get("assigned_to") or "").strip() or "Unassigned"
            lines.append(f"• {idx_global}. {txt} → {who}")
        lines.append("")

    # Assign global 1-based indices matching storage order so "done N"
    # maps to the same slot the user sees.
    indexed = list(enumerate(items, start=1))
    idx_high = [(i, it) for (i, it) in indexed if (it.get("priority") or "").lower() == "high"]
    idx_med  = [(i, it) for (i, it) in indexed if (it.get("priority") or "").lower() == "medium"]
    idx_rest = [(i, it) for (i, it) in indexed if (it.get("priority") or "").lower() not in ("high", "medium")]

    _render(idx_high, "🔴 HIGH PRIORITY")
    _render(idx_med,  "🟡 MEDIUM")
    _render(idx_rest, "⚪ OTHER")

    lines.append(f"_{len(items)} items · Reply \"done 1\" to mark complete_")
    return "\n".join(lines).rstrip()


async def _extract_whatsapp_checklist(project_id: str, group_id: str, conversation_text: str):
    """Call GPT-4o-mini to extract action items from a group conversation,
    persist to whatsapp_checklists, and send a formatted message back to
    the group. No-ops silently if no actionable items are found.
    """
    if not conversation_text or not conversation_text.strip():
        return None
    if not OPENAI_API_KEY:
        logger.info(
            f"checklist extraction skipped (no OPENAI_API_KEY) "
            f"project={project_id} group={group_id}"
        )
        return None

    # Call GPT-4o-mini — structured extraction, forced JSON
    try:
        url = "https://api.openai.com/v1/chat/completions"
        headers = {"Authorization": f"Bearer {OPENAI_API_KEY}", "Content-Type": "application/json"}
        payload = {
            "model": "gpt-4o-mini",
            "temperature": 0.2,
            "max_tokens": 900,
            "response_format": {"type": "json_object"},
            "messages": [
                {"role": "system", "content": CHECKLIST_SYSTEM_PROMPT},
                {"role": "user",   "content": conversation_text[:12000]},
            ],
        }
        async with ServerHttpClient(timeout=40.0) as client_http:
            resp = await client_http.post(url, json=payload, headers=headers)
            resp.raise_for_status()
            content = resp.json()["choices"][0]["message"]["content"]
    except Exception as e:
        logger.error(
            f"checklist GPT call failed (project={project_id}, group={group_id}): {e}"
        )
        return None

    # Parse JSON
    try:
        import json as _json
        data = _json.loads(content)
        raw_items = data.get("items") or []
        if not isinstance(raw_items, list):
            raw_items = []
    except Exception:
        logger.warning(
            f"checklist JSON parse failed for project={project_id} group={group_id}"
        )
        return None

    # Normalize + filter
    VALID_CATEGORY = {"safety", "materials", "coordination", "inspection", "other"}
    VALID_PRIORITY = {"high", "medium", "low"}
    items = []
    for raw in raw_items:
        if not isinstance(raw, dict):
            continue
        text_val = (raw.get("text") or "").strip()
        if not text_val:
            continue
        category = (raw.get("category") or "other").strip().lower()
        if category not in VALID_CATEGORY:
            category = "other"
        priority = (raw.get("priority") or "low").strip().lower()
        if priority not in VALID_PRIORITY:
            priority = "low"
        items.append({
            "text": text_val[:500],
            "assigned_to": (raw.get("assigned_to") or None),
            "due_date": (raw.get("due_date") or None),
            "category": category,
            "priority": priority,
            "completed": False,
            "completed_at": None,
            "completed_by": None,
        })

    # Empty extraction => no DB write, no message
    if not items:
        logger.info(
            f"checklist extraction yielded 0 items (project={project_id}, group={group_id})"
        )
        return None

    # Lookup project + company info
    project = await db.projects.find_one({"_id": to_query_id(project_id)})
    project_name = project.get("name", "Project") if project else "Project"
    company_id = (project.get("company_id") if project else None) or ""

    now_utc = datetime.now(timezone.utc)
    today_start, today_end = get_today_range_est()

    # Count messages in scope for metadata
    source_count = await db.whatsapp_messages.count_documents({
        "group_id": group_id,
        "created_at": {"$gte": today_start, "$lt": today_end},
    })

    doc = {
        "project_id": project_id,
        "company_id": company_id,
        "group_id": group_id,
        "generated_at": now_utc,
        "date_range_start": today_start,
        "date_range_end": today_end,
        "items": items,
        "source_message_count": source_count,
        "is_deleted": False,
    }
    result = await db.whatsapp_checklists.insert_one(doc)

    # Format + send to group
    try:
        message = _format_checklist_message(project_name, items)
        await send_whatsapp_message(group_id, message)
    except Exception as e:
        logger.error(
            f"checklist send failed (project={project_id}, group={group_id}): {e}"
        )

    return str(result.inserted_id)


async def _run_whatsapp_checklist_extractions():
    """Runs every 30 min. Finds groups configured for daily checklist extraction
    whose configured time matches the current EST window, dedups via send_log,
    and calls _extract_whatsapp_checklist."""
    try:
        now_hhmm, _iso_weekday, today_est = _current_est_time_and_date()
        groups = await db.whatsapp_groups.find({"active": True}).to_list(500)
        for group_doc in groups:
            cfg = group_doc.get("bot_config") or {}
            if not cfg.get("bot_enabled", True):
                continue
            if not cfg.get("checklist_extraction_enabled", False):
                continue
            if cfg.get("checklist_frequency", "daily") != "daily":
                continue
            configured = cfg.get("checklist_time", "16:00")
            if not _within_30min_window(now_hhmm, configured):
                continue

            group_id = group_doc.get("wa_group_id")
            project_id = group_doc.get("project_id")
            if not group_id or not project_id:
                continue

            first_send = await _whatsapp_send_log_try_mark(
                group_id, "checklist", today_est
            )
            if not first_send:
                continue

            # Build conversation text for the last 24 hours
            today_start, today_end = get_today_range_est()
            messages = await db.whatsapp_messages.find({
                "group_id": group_id,
                "created_at": {"$gte": today_start, "$lt": today_end},
            }).sort("created_at", 1).to_list(500)
            convo_lines = []
            for m in messages:
                if m.get("type") == "bot_plan_response":
                    continue
                sender = m.get("sender", "unknown")
                body_text = m.get("body", "")
                if body_text:
                    convo_lines.append(f"{sender}: {body_text}")
            if not convo_lines:
                continue
            convo_text = "\n".join(convo_lines[:400])

            try:
                await _extract_whatsapp_checklist(project_id, group_id, convo_text)
            except Exception as e:
                logger.error(f"checklist extraction failed for {group_id}: {e}", exc_info=True)
    except Exception as e:
        logger.error(f"WhatsApp checklist scheduler error: {e}", exc_info=True)


# Card audit VLM adapter. Feeds a raw (jpeg_bytes, prompt) pair into
# the Qwen2.5-VL chat/completions API and returns the assistant's text.
# Kept here rather than in card_audit.py so the module stays free of
# direct httpx + QWEN_API_KEY coupling.
async def _card_audit_vlm_adapter(jpeg_bytes: bytes, prompt: str) -> str:
    """Used by card_audit.enrollment_parse_card to extract card fields."""
    if not QWEN_API_KEY or not jpeg_bytes:
        return ""

    # NOT METERED HERE, AND THAT IS NOT AN OMISSION. This adapter is the
    # transport for card_audit.enrollment_parse_card, which already records
    # VISION_PARSE_CARD itself (card_audit.py) — with the project_id that is
    # not in scope at this level. A count here would double every card parse.
    b64 = base64.b64encode(jpeg_bytes).decode("ascii")
    try:
        async with ServerHttpClient(timeout=60.0) as client_http:
            resp = await client_http.post(
                f"{QWEN_API_BASE}/chat/completions",
                headers={
                    "Authorization": f"Bearer {QWEN_API_KEY}",
                    "Content-Type": "application/json",
                },
                json={
                    "model": QWEN_MODEL,
                    "messages": [{
                        "role": "user",
                        "content": [
                            {"type": "text", "text": prompt},
                            {"type": "image_url",
                             "image_url": {"url": f"data:image/jpeg;base64,{b64}"}},
                        ],
                    }],
                    "temperature": 0.0,
                    "max_tokens": 400,
                },
            )
        if resp.status_code != 200:
            logger.warning(
                f"card_audit VLM {resp.status_code}: {resp.text[:300]!r}"
            )
            return ""
        data = resp.json()
        return (data.get("choices") or [{}])[0].get("message", {}).get("content") or ""
    except Exception as e:
        # SITE 4 OF 5. Already `!r`, so the type survived an empty message —
        # upgraded to .exception for the traceback and given the model id,
        # which is the half that separates "the provider hung" from "the id we
        # send does not exist".
        logger.exception("card_audit VLM adapter failed: %r (model=%s)", e, QWEN_MODEL)
        return ""


# ════════════════════════════════════════════════════════════════════
# MR.14 commit 4a — worker-internal endpoints REMOVED.
#
# v1 monitoring product ships without a local agent container. The
# /api/internal/* endpoints (permit-renewal-claim, job-result,
# agent-heartbeat, filing-jobs/{id}, filing-job-event) plus the
# WORKER_SECRET header validator + the _stale_claim_watchdog +
# _heartbeat_watchdog scheduler crons are gone. Renewal automation
# is deferred to v2.
# ════════════════════════════════════════════════════════════════════


# ── MR.8: DOB approval watcher ─────────────────────────────────────
# Closes the post-filing tracking loop. Once MR.6's worker reports
# status=filed, the renewal sits in AWAITING_DOB_APPROVAL until DOB
# stamps the new expiration on the underlying permit. This watcher
# polls dob_logs (refreshed independently by nightly_dob_scan) and
# transitions the renewal to COMPLETED when dob_log.expiration_date
# advances past renewal.current_expiration.
#
# Cadence: every 30 min. Same interval as nightly_dob_scan but a
# different concern: nightly_dob_scan REFRESHES dob_logs from NYC
# Open Data; this watcher CONSUMES the refreshed data to drive
# renewal state. They're complementary — running both at 30 min
# means worst-case latency from DOB stamping to operator-visible
# completion is ~60 min (one cycle to refresh dob_logs + one cycle
# for the watcher to read it). Acceptable for a renewal that's
# already 5–10 business days into DOB processing.
#
# Idempotency:
#   • Completion transition: only fires when status is currently
#     AWAITING_DOB_APPROVAL. Once flipped to COMPLETED, the renewal
#     is filtered out of subsequent watcher runs by the status query.
#   • Stuck-at-DOB event: the audit_log is scanned for an existing
#     `stuck_at_dob` event before append — re-running the watcher
#     does not duplicate. The event is appended exactly once per
#     stuck renewal.

DOB_APPROVAL_STUCK_THRESHOLD_DAYS = 14


def _safe_parse_date(value) -> Optional[datetime]:
    """Robust date parser used by the watcher. Accepts strings (ISO,
    M/D/YYYY, M-D-YYYY, etc.) and datetime objects. Returns None on
    parse failure rather than raising — the watcher logs and skips."""
    if value is None:
        return None
    if isinstance(value, datetime):
        return value
    try:
        from dateutil import parser as dateparser
        return dateparser.parse(str(value))
    except Exception:
        return None


async def _append_filing_job_audit_event(
    permit_renewal_id: str,
    event: dict,
    *,
    update_status: Optional[str] = None,
    extra_set_fields: Optional[Dict[str, Any]] = None,
) -> Optional[str]:
    """Find the most recent FilingJob for a renewal and $push the event.
    Optionally also set FilingJob.status and other fields atomically.
    Returns the filing_job_id touched, or None if no FilingJob exists
    (e.g. renewal was filed via the legacy MR.1 path before MR.6)."""
    job = await db.filing_jobs.find_one(
        {
            "permit_renewal_id": permit_renewal_id,
            "is_deleted": {"$ne": True},
        },
        sort=[("created_at", -1)],
    )
    if not job:
        return None
    set_fields: Dict[str, Any] = {"updated_at": event["timestamp"]}
    if update_status:
        set_fields["status"] = update_status
    if extra_set_fields:
        set_fields.update(extra_set_fields)
    await db.filing_jobs.update_one(
        {"_id": job["_id"]},
        {
            "$set": set_fields,
            "$push": {"audit_log": event},
        },
    )
    return str(job["_id"])


async def dob_approval_watcher():
    """Every 30 min: detect renewal completion in DOB data and
    transition AWAITING_DOB_APPROVAL → COMPLETED. Also surfaces a
    stuck-at-DOB signal for renewals waiting >14 days.

    Per-renewal exceptions are caught and logged so one bad row
    doesn't kill the cycle. The cycle itself is wrapped in a
    blanket try/except for the same reason — apscheduler should
    never see a raise from this job."""
    try:
        from permit_renewal import RenewalStatus
    except ModuleNotFoundError:
        from backend.permit_renewal import RenewalStatus

    try:
        now = datetime.now(timezone.utc)
        stuck_threshold = now - timedelta(days=DOB_APPROVAL_STUCK_THRESHOLD_DAYS)

        cursor = db.permit_renewals.find({
            "status": RenewalStatus.AWAITING_DOB_APPROVAL.value,
            "is_deleted": {"$ne": True},
        })

        confirmed = 0
        stuck_appended = 0
        skipped = 0

        async for renewal in cursor:
            try:
                renewal_id = renewal.get("_id")
                permit_dob_log_id = renewal.get("permit_dob_log_id")
                if not permit_dob_log_id:
                    logger.warning(
                        "[dob_approval_watcher] renewal %s has no "
                        "permit_dob_log_id; skipping",
                        renewal_id,
                    )
                    skipped += 1
                    continue

                dob_log = await db.dob_logs.find_one(
                    {"_id": to_query_id(permit_dob_log_id)}
                )
                if not dob_log:
                    logger.warning(
                        "[dob_approval_watcher] dob_log %s not found for "
                        "renewal %s; skipping",
                        permit_dob_log_id, renewal_id,
                    )
                    skipped += 1
                    continue

                old_exp_str = renewal.get("current_expiration")
                new_exp_str = dob_log.get("expiration_date")
                old_exp = _safe_parse_date(old_exp_str)
                new_exp = _safe_parse_date(new_exp_str)

                if old_exp is None or new_exp is None:
                    # Can't compare. Don't promote, don't add stuck
                    # (we don't have data for that judgment either).
                    skipped += 1
                    continue

                # Compare as dates only — permit expirations are
                # calendar dates; ignoring time-of-day sidesteps
                # tz-aware-vs-naive comparison errors.
                if new_exp.date() > old_exp.date():
                    # Renewal complete.
                    transition_event = {
                        "event_type": "renewal_confirmed_in_dob",
                        "timestamp": now,
                        "actor": "dob_approval_watcher",
                        "detail": (
                            f"DOB stamped new expiration {new_exp_str} "
                            f"(was {old_exp_str})"
                        ),
                        "metadata": {
                            "old_expiration": old_exp_str,
                            "new_expiration": new_exp_str,
                        },
                    }
                    # Update the renewal first; FilingJob update
                    # follows. If the FilingJob update fails, the
                    # renewal is still correctly transitioned —
                    # operator-visible state is the priority.
                    await db.permit_renewals.update_one(
                        {"_id": renewal_id},
                        {"$set": {
                            "status": RenewalStatus.COMPLETED.value,
                            "completed_at": now,
                            "new_expiration_date": new_exp_str,
                            "updated_at": now,
                        }},
                    )
                    try:
                        from permit_renewal import RenewalStatus as _RS  # local re-bind for closure clarity
                        await _append_filing_job_audit_event(
                            permit_renewal_id=str(renewal_id),
                            event=transition_event,
                            update_status="completed",
                            extra_set_fields={"completed_at": now},
                        )
                    except Exception as fj_err:
                        logger.warning(
                            "[dob_approval_watcher] renewal %s transitioned "
                            "to completed but FilingJob audit append failed: %r",
                            renewal_id, fj_err,
                        )
                    confirmed += 1
                    logger.info(
                        "[dob_approval_watcher] renewal %s completed: "
                        "%s -> %s",
                        renewal_id, old_exp_str, new_exp_str,
                    )
                    # MR.9: fire the completion notification. The hook
                    # is best-effort — a Resend failure or feature-flag
                    # suppression must not crash the watcher cycle.
                    try:
                        await _send_renewal_notification_hook(
                            renewal,
                            trigger_type="renewal_completed",
                            extra_context={
                                "new_expiration": new_exp_str,
                                "old_expiration": old_exp_str,
                            },
                        )
                    except Exception as hook_err:
                        logger.warning(
                            "[dob_approval_watcher] completion hook failed "
                            "for renewal %s: %r",
                            renewal_id, hook_err,
                        )
                    continue

                # Still waiting. Check stuck-at-DOB threshold.
                created_at = renewal.get("created_at")
                if isinstance(created_at, str):
                    created_at = _safe_parse_date(created_at)
                if isinstance(created_at, datetime) and created_at.tzinfo is None:
                    created_at = created_at.replace(tzinfo=timezone.utc)

                if created_at and created_at < stuck_threshold:
                    # Idempotency: only append the stuck event if
                    # the most recent FilingJob's audit_log doesn't
                    # already carry one. Walk back-to-front; first
                    # match short-circuits.
                    fj = await db.filing_jobs.find_one(
                        {
                            "permit_renewal_id": str(renewal_id),
                            "is_deleted": {"$ne": True},
                        },
                        sort=[("created_at", -1)],
                    )
                    if fj is None:
                        # No FilingJob to attach to (legacy renewal).
                        # Skip silently — the renewal-level state on
                        # the `created_at` age is enough for the
                        # operator to see it's stuck.
                        continue
                    already = any(
                        ev.get("event_type") == "stuck_at_dob"
                        for ev in (fj.get("audit_log") or [])
                    )
                    if already:
                        continue
                    days_stuck = int(
                        (now - created_at).total_seconds() // 86400
                    )
                    stuck_event = {
                        "event_type": "stuck_at_dob",
                        "timestamp": now,
                        "actor": "dob_approval_watcher",
                        "detail": (
                            f"Renewal still awaiting DOB approval after "
                            f"{days_stuck} days. Operator should check "
                            f"DOB NOW manually."
                        ),
                        "metadata": {
                            "days_stuck": days_stuck,
                            "old_expiration": old_exp_str,
                            "current_dob_expiration": new_exp_str,
                        },
                    }
                    await db.filing_jobs.update_one(
                        {"_id": fj["_id"]},
                        {
                            "$set": {"updated_at": now},
                            "$push": {"audit_log": stuck_event},
                        },
                    )
                    stuck_appended += 1
                    logger.info(
                        "[dob_approval_watcher] stuck_at_dob appended for "
                        "renewal %s (days_stuck=%d)",
                        renewal_id, days_stuck,
                    )
                    # MR.9: fire the stuck notification. Idempotency
                    # in send_notification + the audit-log dedup above
                    # together ensure exactly-one-email per stuck
                    # renewal per recipient (per 23h window).
                    try:
                        await _send_renewal_notification_hook(
                            renewal,
                            trigger_type="filing_stuck",
                            extra_context={
                                "days_stuck": days_stuck,
                            },
                        )
                    except Exception as hook_err:
                        logger.warning(
                            "[dob_approval_watcher] stuck hook failed "
                            "for renewal %s: %r",
                            renewal_id, hook_err,
                        )
            except Exception as per_err:
                logger.error(
                    "[dob_approval_watcher] error on renewal %s: %r",
                    renewal.get("_id"), per_err,
                )
                continue

        if confirmed or stuck_appended or skipped:
            logger.info(
                "[dob_approval_watcher] cycle: confirmed=%d "
                "stuck_appended=%d skipped=%d",
                confirmed, stuck_appended, skipped,
            )
    except Exception as e:
        logger.error(f"[dob_approval_watcher] cycle error: {e!r}")


# ── MR.9: Notification cron + watcher hooks ────────────────────────
# Daily 7am ET reminder cron walks active renewals and sends T-30,
# T-14, and T-7 reminder emails. The MR.8 watcher hooks (stuck +
# completed) live in the watcher itself; see _maybe_send_notification
# below for the shared adapter.

# Reminder-eligible renewal statuses: those where the OPERATOR still
# needs to act. We exclude statuses where the system has already
# taken over (awaiting_dob_filing, awaiting_dob_approval, in_progress)
# because the stuck-at-DOB notification covers escalation in those
# cases. Also excludes terminal (completed/failed). Sending T-30 to a
# renewal that's already filed just confuses the operator.
REMINDER_ELIGIBLE_STATUSES = {
    "eligible",
    "needs_insurance",
    "ineligible_insurance",
    "ineligible_license",
    "draft_ready",
    "awaiting_gc",
}


# Time windows for the three reminders. Each is (lower_days_inclusive,
# upper_days_exclusive) such that a renewal expiring exactly N days
# from today falls into the window centered on N. The 2-day windows
# are deliberately wider than the 1-day cron cadence so a missed run
# (e.g. backend redeploy) doesn't drop a reminder; idempotency
# (notification_log) prevents duplicate sends across consecutive runs.
REMINDER_WINDOWS = [
    ("renewal_t_minus_30", 29, 31, 30),  # name, low, high, label_days
    ("renewal_t_minus_14", 13, 15, 14),
    ("renewal_t_minus_7",   6,  8,  7),
]


async def _renewal_reminder_context(renewal: dict, days_until: int) -> dict:
    """Build the email context dict for a renewal. Loads the project
    + dob_log so the email shows job_number, work_type, address.
    Best-effort — missing references render as "—" rather than raise."""
    project = None
    dob_log = None
    try:
        if renewal.get("project_id"):
            project = await db.projects.find_one(
                {"_id": to_query_id(renewal.get("project_id"))}
            )
    except Exception:
        project = None
    try:
        if renewal.get("permit_dob_log_id"):
            dob_log = await db.dob_logs.find_one(
                {"_id": to_query_id(renewal.get("permit_dob_log_id"))}
            )
    except Exception:
        dob_log = None

    from lib.notifications import build_action_link

    return {
        "project_name": (project or {}).get("name") or (project or {}).get("address") or "—",
        "project_address": (project or {}).get("address") or "—",
        "permit_job_number": (
            (dob_log or {}).get("job_number")
            or renewal.get("job_number")
            or "—"
        ),
        "permit_work_type": (dob_log or {}).get("work_type") or renewal.get("permit_type") or "—",
        "current_expiration": renewal.get("current_expiration") or "—",
        "days_until_expiry": days_until,
        "action_link": build_action_link(
            project_id=str(renewal.get("project_id") or ""),
            permit_dob_log_id=str(renewal.get("permit_dob_log_id") or "") or None,
        ),
    }


async def _send_reminder_for_renewal(
    renewal: dict,
    *,
    trigger_type: str,
    days_until: int,
):
    """Fire one notification per recipient for a single renewal at a
    single trigger type. Recipients come from filing_reps + admin
    user; see lib.notifications.collect_notification_recipients.

    All sends go through send_notification — feature flag, idempotency,
    and notification_log writes are handled there."""
    from lib.notifications import (
        send_notification,
        collect_notification_recipients,
    )
    from lib.email_templates import render_for_trigger

    company_id = renewal.get("company_id")
    if not company_id:
        logger.warning(
            "[renewal_reminder_cron] renewal %s has no company_id; skipping",
            renewal.get("_id"),
        )
        return

    recipients = await collect_notification_recipients(db, str(company_id))
    if not recipients:
        logger.info(
            "[renewal_reminder_cron] no recipients for renewal %s "
            "(company %s); skipping",
            renewal.get("_id"), company_id,
        )
        return

    permit_renewal_id = str(renewal.get("_id"))

    base_context = await _renewal_reminder_context(renewal, days_until)
    for recipient in recipients:
        ctx = dict(base_context)
        # Recipient-specific name lookup: try to find the matching
        # filing_rep by email. Falls back to the email handle
        # (text before @) so the email feels addressed even when
        # we can't match a name.
        ctx["recipient_name"] = recipient.split("@", 1)[0]
        try:
            company_doc = await db.companies.find_one(
                {"_id": to_query_id(company_id)}
            )
            if company_doc:
                for rep in (company_doc.get("filing_reps") or []):
                    if (rep.get("email") or "").lower() == recipient:
                        ctx["recipient_name"] = rep.get("name") or ctx["recipient_name"]
                        break
        except Exception:
            pass

        try:
            subject, html, text = render_for_trigger(trigger_type, ctx)
        except Exception as render_err:
            logger.error(
                "[renewal_reminder_cron] template render failed "
                "trigger=%s renewal=%s: %r",
                trigger_type, permit_renewal_id, render_err,
            )
            continue

        try:
            await send_notification(
                db,
                permit_renewal_id=permit_renewal_id,
                trigger_type=trigger_type,
                recipient=recipient,
                subject=subject,
                html=html,
                text=text,
                metadata={"days_until_expiry": days_until},
            )
        except Exception as send_err:
            # send_notification handles its own logging + status;
            # this is defensive against unexpected raises.
            logger.error(
                "[renewal_reminder_cron] send_notification raised "
                "trigger=%s renewal=%s recipient=%s: %r",
                trigger_type, permit_renewal_id, recipient, send_err,
            )


async def renewal_reminder_cron():
    """Daily 7am ET. For each non-terminal, operator-actionable
    renewal whose current_expiration falls into one of the three
    reminder windows (T-30, T-14, T-7), fire the matching
    notification to filing_reps + the company admin.

    Date strategy: current_expiration is stored as an Optional[str]
    on permit_renewals (mixed format: ISO and M/D/YYYY both seen in
    production). We can't do a Mongo range query because string
    comparison breaks on mixed formats, so we scan all eligible
    renewals and partition in Python via dateparser. Volume is low
    (single tenant: <100 active renewals) so the scan is cheap.

    Idempotency: send_notification skips when a successful send for
    the same (renewal, trigger, recipient) lands in the last 23h.
    The 23h window leaves slack for cron drift (a 7am run today vs
    7:05am tomorrow still dedups)."""
    try:
        from dateutil import parser as dateparser
        today_utc = datetime.now(timezone.utc).date()

        # Single Mongo scan — eligible-status renewals. We don't filter
        # on current_expiration in Mongo because of the mixed-string
        # format problem documented above.
        cursor = db.permit_renewals.find({
            "status": {"$in": list(REMINDER_ELIGIBLE_STATUSES)},
            "is_deleted": {"$ne": True},
        })

        candidates = []
        async for renewal in cursor:
            exp_str = renewal.get("current_expiration")
            if not exp_str:
                continue
            try:
                exp_date = dateparser.parse(str(exp_str)).date()
            except Exception:
                continue
            days_until = (exp_date - today_utc).days
            candidates.append((renewal, days_until))

        # For each window, dispatch matching candidates.
        sent = 0
        for trigger_type, low, high, label_days in REMINDER_WINDOWS:
            for renewal, days_until in candidates:
                if low <= days_until < high:
                    await _send_reminder_for_renewal(
                        renewal,
                        trigger_type=trigger_type,
                        days_until=days_until,
                    )
                    sent += 1

        if sent:
            logger.info(
                "[renewal_reminder_cron] processed %d renewal/recipient "
                "pairs (idempotency may have suppressed some sends)",
                sent,
            )
    except Exception as e:
        logger.error(f"[renewal_reminder_cron] cycle error: {e!r}")


async def _send_renewal_notification_hook(
    renewal: dict,
    *,
    trigger_type: str,
    extra_context: Optional[dict] = None,
):
    """Watcher-hook adapter. Builds the context, resolves recipients,
    and fires send_notification per recipient. Used by the MR.8
    dob_approval_watcher when it appends a stuck_at_dob or
    renewal_confirmed_in_dob audit event."""
    from lib.notifications import (
        send_notification,
        collect_notification_recipients,
    )
    from lib.email_templates import render_for_trigger

    company_id = renewal.get("company_id")
    if not company_id:
        return
    recipients = await collect_notification_recipients(db, str(company_id))
    if not recipients:
        return

    permit_renewal_id = str(renewal.get("_id"))
    days_until = 0  # unused for stuck/completed; required by template ctx
    base_context = await _renewal_reminder_context(renewal, days_until)
    base_context.update(extra_context or {})

    for recipient in recipients:
        ctx = dict(base_context)
        ctx["recipient_name"] = recipient.split("@", 1)[0]
        try:
            company_doc = await db.companies.find_one(
                {"_id": to_query_id(company_id)}
            )
            if company_doc:
                for rep in (company_doc.get("filing_reps") or []):
                    if (rep.get("email") or "").lower() == recipient:
                        ctx["recipient_name"] = rep.get("name") or ctx["recipient_name"]
                        break
        except Exception:
            pass

        try:
            subject, html, text = render_for_trigger(trigger_type, ctx)
        except Exception as render_err:
            logger.error(
                "[notification_hook] template render failed "
                "trigger=%s renewal=%s: %r",
                trigger_type, permit_renewal_id, render_err,
            )
            continue

        try:
            await send_notification(
                db,
                permit_renewal_id=permit_renewal_id,
                trigger_type=trigger_type,
                recipient=recipient,
                subject=subject,
                html=html,
                text=text,
                metadata=extra_context or {},
            )
        except Exception as send_err:
            logger.error(
                "[notification_hook] send_notification raised "
                "trigger=%s renewal=%s recipient=%s: %r",
                trigger_type, permit_renewal_id, recipient, send_err,
            )


# Card audit routers — gate_router serves public HTML at /checkin/...
# and /enrollment/... (no auth, workers are anonymous), admin_router
# serves JSON at /api/admin/... (admin-gated). The admin gate is a
# small dep wrapper that resolves the admin user AND stashes it on
# request.state so card_audit endpoints can read it without taking
# it as a parameter (mount-time include_router deps don't expose
# their resolved values to downstream endpoint signatures).
async def _card_audit_admin_gate(request: Request, admin_user = Depends(get_admin_user)):
    request.state.current_user = admin_user
    return admin_user

try:
    import card_audit as _card_audit_module  # noqa: E402
    app.include_router(_card_audit_module.gate_router)
    app.include_router(
        _card_audit_module.admin_router,
        dependencies=[Depends(_card_audit_admin_gate)],
    )
except Exception as _card_router_err:
    logger.error(f"card_audit router mount failed: {_card_router_err!r}")


# ── ProjectModel aggregator (app/scheduling) ─────────────────────────
# Produces/persists the typed per-project model the scheduler will consume by
# aggregating already-extracted document_page_index rows. No scheduler, no LLM,
# no WhatsApp here. Imported after sys.path.insert (top of file) so `app.*`
# resolves in both Railway deploy modes.
from app.scheduling.project_model import (  # noqa: E402
    ProjectModel as _ProjectModel,
    ModelConfirmRequest as _ModelConfirmRequest,
)
from app.scheduling import aggregator as _pm_aggregator  # noqa: E402


async def _pm_load_project_or_403(project_id: str, current_user):
    """Load a project and prove the caller may act on it. SIX CALLERS.

    THE BYPASS THIS CLOSES. The check was

        if company_id and project.get("company_id") != company_id:

    and `and` short-circuits: a caller whose company_id is falsy never reaches
    the comparison, so the 403 could not fire. That is not an exotic state --
    /auth/register sets `user_dict["company_id"] = None` on every self-serve
    signup, so it is the DEFAULT until onboarding attaches a company.

    Three of the six callers carry Depends(require_project_access) and were
    therefore already safe. THE OTHER THREE HAD ONLY THIS LINE:

        GET /projects/{project_id}/model
        GET /projects/{project_id}/model/unconfirmed
        GET /projects/{project_id}/schedule

    project_access_ok is the SAME three-branch rule require_project_access
    applies, extracted for exactly this case -- its docstring says so: "a caller
    that must do its OWN project lookup can still reach the same decision
    instead of restating it." It fails closed on a falsy company because the
    company branch requires `user_company` to be truthy before it can return
    True.

    THE LOOKUP IS DELIBERATELY UNCHANGED. This keeps `is_deleted` rather than
    adopting ACTIVE_PROJECT_FILTER, which also excludes marked_for_deletion.
    Switching would newly 404 these reads on a project an admin has just marked
    -- a CP losing his schedule to an admin action. Authorization is what was
    missing; the existence semantics are left exactly as they were. Same choice
    create_logbook made, for the same reason.

    IT ALSO WIDENS ACCESS SLIGHTLY, and that is intended: the three-branch rule
    admits a site device provisioned for this project, and a user with the
    project in assigned_projects. Both are already true of the three sibling
    routes that carry the dependency, so this makes the six agree rather than
    inventing a rule.
    """
    project = await db.projects.find_one(
        {"_id": to_query_id(project_id), "is_deleted": {"$ne": True}}
    )
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")
    if not project_access_ok(project, project_id, current_user):
        raise HTTPException(status_code=403, detail="Access denied to this project")
    return project


@api_router.post("/projects/{project_id}/model/aggregate", response_model=_ProjectModel, dependencies=[Depends(require_approved), Depends(require_project_access)])
async def aggregate_project_model_endpoint(
    project_id: str, current_user = Depends(get_current_user)
):
    await _pm_load_project_or_403(project_id, current_user)
    return await _pm_aggregator.aggregate_project_model(db, project_id)


@api_router.get("/projects/{project_id}/model", response_model=_ProjectModel)
async def get_project_model_endpoint(
    project_id: str, current_user = Depends(get_current_user)
):
    await _pm_load_project_or_403(project_id, current_user)
    model = await _pm_aggregator.load_project_model(db, project_id)
    if model is None:
        raise HTTPException(
            status_code=404, detail="No ProjectModel yet — run aggregate first"
        )
    return model


@api_router.patch("/projects/{project_id}/model/confirm", response_model=_ProjectModel, dependencies=[Depends(require_approved), Depends(require_project_access)])
async def confirm_project_model_endpoint(
    project_id: str, body: _ModelConfirmRequest,
    current_user = Depends(get_current_user),
):
    await _pm_load_project_or_403(project_id, current_user)
    user_id = str(current_user.get("_id") or current_user.get("id") or "")
    try:
        updated = await _pm_aggregator.confirm_project_model(
            db, project_id, body, user_id=user_id
        )
    except ValueError as e:
        raise HTTPException(status_code=422, detail=str(e))
    if updated is None:
        raise HTTPException(
            status_code=404, detail="No ProjectModel yet — run aggregate first"
        )
    return updated


@api_router.get("/projects/{project_id}/model/unconfirmed")
async def unconfirmed_project_model_endpoint(
    project_id: str, current_user = Depends(get_current_user)
):
    await _pm_load_project_or_403(project_id, current_user)
    model = await _pm_aggregator.load_project_model(db, project_id)
    if model is None:
        raise HTTPException(
            status_code=404, detail="No ProjectModel yet — run aggregate first"
        )
    return _pm_aggregator.unconfirmed_view(model)


# ── Scheduling spine (app/scheduling) ────────────────────────────────
# Deterministic construction sequence from the confirmed ProjectModel via the
# graph_v1 seed. No scheduler heuristics/LLM here beyond the engine's layering.
from app.scheduling import engine as _sched_engine  # noqa: E402
from app.scheduling.graph_v1 import build_graph_v1 as _build_graph_v1  # noqa: E402


@api_router.post("/projects/{project_id}/schedule/generate", dependencies=[Depends(require_approved), Depends(require_project_access)])
async def generate_schedule_endpoint(
    project_id: str, current_user = Depends(get_current_user)
):
    await _pm_load_project_or_403(project_id, current_user)
    project = await _pm_aggregator.load_project_model(db, project_id)
    if project is None:
        raise HTTPException(
            status_code=404, detail="No ProjectModel yet — run aggregate first"
        )
    graph = _build_graph_v1()
    await _sched_engine.upsert_seed_graph(db, graph)  # record the seed (upsert)
    try:
        schedule = _sched_engine.generate_schedule(db, project=project, graph=graph)
    except _sched_engine.ScheduleCycleError as e:
        raise HTTPException(
            status_code=422,
            detail={"error": "schedule_cycle", "nodes": e.node_ids},
        )
    await _sched_engine.persist_schedule(db, schedule)
    # Unconfirmed gate-critical input is surfaced, NOT blocked.
    warnings = _sched_engine.schedule_input_warnings(project)
    return {"schedule": schedule.model_dump(mode="json"), "warnings": warnings}


@api_router.get("/projects/{project_id}/schedule")
async def get_schedule_endpoint(
    project_id: str, current_user = Depends(get_current_user)
):
    await _pm_load_project_or_403(project_id, current_user)
    latest = await _sched_engine.load_latest_schedule(db, project_id)
    if latest is None:
        raise HTTPException(
            status_code=404, detail="No schedule yet — run schedule/generate first"
        )
    return latest


# Include the router in the main app
app.include_router(api_router)


@app.get("/a/{annotation_id}")
async def annotation_short_link(annotation_id: str, request: Request):
    """Short link redirect for annotation deep links."""
    from fastapi.responses import HTMLResponse

    web_url = f"https://levelog.com/plans?annotation={annotation_id}"
    deep_link = f"levelog://annotation/{annotation_id}"

    # Return HTML that tries the deep link first, falls back to web
    html = f"""<!DOCTYPE html>
<html><head>
<meta charset="utf-8"/>
<meta name="viewport" content="width=device-width,initial-scale=1"/>
<title>Redirecting…</title>
<script>
  var deep = "{deep_link}";
  var web  = "{web_url}";
  var ua = navigator.userAgent || "";
  if (/iPhone|iPad|Android/i.test(ua)) {{
    window.location = deep;
    setTimeout(function() {{ window.location = web; }}, 1500);
  }} else {{
    window.location = web;
  }}
</script>
</head>
<body style="font-family:sans-serif;text-align:center;padding:60px;">
<p>Redirecting&hellip;</p>
<p><a href="{web_url}">Click here if not redirected</a></p>
</body></html>"""
    return HTMLResponse(content=html)


@app.on_event("shutdown")
async def shutdown_db_client():
    if scheduler.running:
        scheduler.shutdown()
    client.close()

# Startup event to create indexes and seed data
@app.on_event("startup")
async def startup_event():
    logger.info("Starting Levelog API with Sync Support...")

    # ── WHICH VISION MODEL IS THIS BOX ACTUALLY RUNNING ────────────────────
    #
    # QWEN_MODEL is a Railway environment variable, so the model that reads
    # every worker's OSHA/SST card at the gate can change with NO COMMIT and
    # NO DIFF. It did: a four-day registration outage (2026-09-11 to 09-15,
    # zero new worker rows) traced to a model id swapped in the variable panel
    # whose latency tail was unbounded — identical image and prompt, 470 ms or
    # never. Nothing in the deploy log named the model, so there was nothing to
    # correlate the outage against.
    #
    # One line, at boot, naming the value in force. It is printed unconditionally
    # — including the fallback case — because "the variable is unset and we are
    # on the default" is precisely the state that is otherwise invisible.
    from lib import vision_model as _vision_cfg
    _vcfg = _vision_cfg.describe()
    logger.info(
        "Vision model in use: model=%s (%s) base=%s (%s) key=%s",
        _vcfg["model"], _vcfg["model_source"],
        _vcfg["base"], _vcfg["base_source"],
        "set" if _vcfg["key_set"] else "MISSING",
    )
    # EVERY CARD-PATH SETTING AN ENVIRONMENT VARIABLE CAN MOVE, ON ONE LINE.
    # The outage's root cause was a value that changed behaviour with no commit
    # and no diff; anything else with that property belongs in the deploy log
    # beside the model, or it is the same trap waiting.
    logger.info(
        "Card read budget: %d attempts x %.0fs (total %.0fs), downscale max_edge=%d, "
        "canary every %dmin (%s)",
        OSHA_VISION_ATTEMPTS, OSHA_VISION_ATTEMPT_TIMEOUT,
        OSHA_VISION_ATTEMPTS * OSHA_VISION_ATTEMPT_TIMEOUT,
        _osha_vision_max_edge(), CARD_CANARY_INTERVAL_MINUTES,
        "armed" if CARD_CANARY_R2_KEY else "NOT CONFIGURED — set CARD_CANARY_R2_KEY",
    )
    # ASKED, NOT ASSUMED. A boot-time probe so a model id the provider does not
    # have is a line in the deploy log and a flag on /api/health, instead of a
    # 500 at a turnstile four days later. Fire-and-forget: a slow or unreachable
    # provider must never be able to hold up the API coming up.
    try:
        asyncio.create_task(_probe_vision_model_at_boot())
    except Exception as _probe_err:                             # noqa: BLE001
        logger.warning("could not schedule vision model probe: %r", _probe_err)

    # MR.14 commit 4a — ELIGIBILITY_BYPASS_DAYS_REMAINING boot warning
    # removed alongside the bypass helpers. The env var is fully dead
    # post-4a; operator deletes it from Railway as part of cleanup.

    # Initialize R2 storage client
    global _r2_client
    _r2_client = _get_r2_client()
    if _r2_client:
        logger.info(f"R2 storage configured: bucket={R2_BUCKET_NAME}")
        # Ensure CORS lets the web app fetch presigned URLs directly from R2.
        try:
            await asyncio.to_thread(
                _r2_client.put_bucket_cors,
                Bucket=R2_BUCKET_NAME,
                CORSConfiguration={
                    "CORSRules": [{
                        "AllowedOrigins": [
                            "https://www.levelog.com",
                            "https://levelog.com",
                            "https://app.levelog.com",
                            "http://localhost:19006",
                            "http://localhost:8081",
                        ],
                        "AllowedMethods": ["GET", "HEAD"],
                        "AllowedHeaders": ["*"],
                        "ExposeHeaders": ["Content-Length", "Content-Type", "ETag"],
                        "MaxAgeSeconds": 3600,
                    }]
                },
            )
            logger.info("R2 bucket CORS policy applied")
        except Exception as _cors_err:
            logger.error(f"Failed to apply R2 CORS policy: {_cors_err}")
    else:
        logger.warning("R2 storage not configured — file delivery will use Dropbox only")

    # ── POPPLER, CHECKED FOR REAL AND SAID LOUDLY ─────────────────────────
    #
    # The old self-test fed pdf2image a hand-written PDF whose xref offsets were
    # all zero. pdfinfo rejects that file, and pdf2image reports it as "Unable
    # to get page count." — the same first words it uses when poppler is not
    # installed at all. So the log said poppler was missing on an image that
    # installs poppler-utils, and nobody could tell which it was.
    #
    # Now: both binaries looked up on PATH, the version read, and a VALID
    # one-page PDF rendered. One line either way, at a level that shows.
    global SCREENSHOT_ENABLED, POPPLER_OK, POPPLER_DETAIL
    POPPLER_OK, POPPLER_DETAIL = await asyncio.to_thread(_check_poppler)
    SCREENSHOT_ENABLED = POPPLER_OK
    if POPPLER_OK:
        logger.warning(f"POPPLER CHECK: OK — {POPPLER_DETAIL}. Plan page rendering and "
                       f"annotation screenshots enabled.")
    else:
        logger.error(f"POPPLER CHECK: FAILED — {POPPLER_DETAIL}. Plan indexing is PAUSED "
                     f"(queued files wait) and annotation screenshots are disabled.")

    # The plan index queue survives restarts; this drains it.
    global _PLAN_INDEX_WORKER_TASK
    _PLAN_INDEX_WORKER_TASK = asyncio.create_task(_plan_index_worker())

    # ── EVERY UNIQUE BUILD GOES THROUGH THE RESILIENT HELPER ───────────────
    #
    # These five were BARE AWAITS in an @app.on_event("startup") handler. A
    # unique index whose collection already holds a duplicate raises E11000
    # straight out of startup, and the API does not start AT ALL — a total
    # outage, on a data condition, at the next restart, with no deploy having
    # changed anything. Two accounts sharing an email, one phone typed onto two
    # workers, one company name entered twice: every one of those is a thing a
    # person can do through the product today, and any one of them was a
    # company-wide outage waiting for a redeploy.
    #
    # THE NAMES ARE THE ONES MONGO WOULD HAVE GENERATED, and that is not
    # cosmetic. `create_index("email", unique=True)` produces `email_1`. Naming
    # it anything else here does not rename the live index — it asks for a
    # SECOND index beside it, or trips an IndexOptionsConflict that makes the
    # helper drop a live uniqueness constraint and rebuild it. Passing the
    # default name makes this a no-op against every existing deployment.
    await _ensure_index_resilient(
        db.users, keys=[("email", 1)], name="email_1", unique=True,
    )
    await _ensure_index_resilient(
        db.workers, keys=[("phone", 1)], name="phone_1",
        unique=True, sparse=True,
    )
    await _ensure_index_resilient(
        db.nfc_tags, keys=[("tag_id", 1)], name="tag_id_1", unique=True,
    )
    await _ensure_index_resilient(
        db.subcontractors, keys=[("email", 1)], name="email_1", unique=True,
    )
    await _ensure_index_resilient(
        db.companies, keys=[("name", 1)], name="name_1", unique=True,
    )
    await db.checklists.create_index("company_id")
    await db.checklist_assignments.create_index("checklist_id")
    await db.checklist_assignments.create_index("project_id")
    await db.checklist_assignments.create_index("assigned_user_ids")
    await db.checklist_completions.create_index([("assignment_id", 1), ("user_id", 1)])

    # Safety staff indexes
    await db.safety_staff_registrations.create_index([("project_id", 1), ("role", 1)])
    await db.safety_staff_registrations.create_index("company_id")

    # Audit log indexes
    await db.audit_logs.create_index([("resource_type", 1), ("resource_id", 1)])
    await db.audit_logs.create_index("timestamp")

    # Document annotation indexes
    await db.document_annotations.create_index("project_id")
    await db.document_annotations.create_index("created_by")
    await db.document_annotations.create_index("recipients")
    await db.document_annotations.create_index([("project_id", 1), ("document_path", 1)])

    # Project files (R2 cache) indexes
    await db.project_files.create_index("project_id")
    # Uniqueness on (project_id, dropbox_path) must only apply to real Dropbox paths.
    # Direct uploads store dropbox_path="" and would otherwise collide on a sparse index,
    # because sparse skips missing fields but not empty strings.
    try:
        _pf_indexes = await db.project_files.index_information()
        _old_name = "project_id_1_dropbox_path_1"
        if _old_name in _pf_indexes and not _pf_indexes[_old_name].get("partialFilterExpression"):
            await db.project_files.drop_index(_old_name)
    except Exception as _e:
        logger.warning(f"project_files unique index migration skipped: {_e}")
    # Same treatment, same name the migration above drops by — so the
    # drop-then-rebuild pair still refers to one index and not two.
    await _ensure_index_resilient(
        db.project_files,
        keys=[("project_id", 1), ("dropbox_path", 1)],
        name="project_id_1_dropbox_path_1",
        unique=True,
        partialFilterExpression={"dropbox_path": {"$gt": ""}},
    )
    await db.project_files.create_index("dropbox_content_hash")

    # Create compound indexes for sync queries
    await db.workers.create_index([("company_id", 1), ("updated_at", -1)])
    await db.projects.create_index([("company_id", 1), ("updated_at", -1)])
    await db.checkins.create_index([("company_id", 1), ("updated_at", -1)])
    await db.daily_logs.create_index([("company_id", 1), ("updated_at", -1)])
    await _ensure_index_resilient(
        db.daily_logs,
        keys=[("project_id", 1), ("date", 1)],
        name="project_id_1_date_1",
        unique=True, sparse=True,
    )
    await db.nfc_tags.create_index([("company_id", 1), ("updated_at", -1)])
    await db.logbooks.create_index([("project_id", 1), ("log_type", 1), ("date", -1)])
    await db.logbooks.create_index([("company_id", 1), ("date", -1)])
    # THE END-OF-DAY FREEZE SWEEP'S OWN INDEX. It pages
    # {log_type: $in, date: $lt} sorted (date, _id), and `logbooks` holds
    # inline base64 -- a signature, and photos before the finalize purge. An
    # unserved sort there is the 32MB in-memory sort limit, which is an outage
    # this product has already had once. test_sorts_are_indexed catches it.
    #
    # THE SORT KEYS ARE THE PREFIX, and that is forced rather than chosen.
    # This selector pins NOTHING by equality: `log_type` is an $in, `date` is
    # an $lt, and both `is_locked` and `is_deleted` are $ne. find_unserved_sorts
    # counts only `$eq` as a pin -- correctly, because an index leading on an
    # $in would make Mongo merge-sort across one branch per log type, which is
    # not sorted output from one scan. So (date, _id) leads, the $lt becomes a
    # range on the leading key (an index range walked in sort order, which is
    # the cheap case), and `_id` is the unique tie-break that makes skip-free
    # paging correct.
    #
    # The key spec is a LITERAL on purpose: find_unserved_sorts.py resolves
    # index declarations with an AST walk and cannot read a constant, so a
    # named tuple here would drop this index out of the sweep's coverage
    # silently -- the failure that guard exists to prevent.
    await _ensure_index_resilient(
        db.logbooks,
        keys=[("date", 1), ("_id", 1)],
        name="logbooks_eod_sweep_by_type_date",
    )

	# Compound index for check-in duplicate prevention (critical at scale)
    await db.checkins.create_index(
        [("worker_id", 1), ("project_id", 1), ("check_in_time", 1), ("status", 1)],
        name="checkin_dedup_compound"
    )
    # Partial index for active (non-deleted) records — optimizes the is_deleted != True filter
    await db.workers.create_index(
        [("company_id", 1), ("status", 1)],
        partialFilterExpression={"is_deleted": {"$eq": False}},
        name="workers_active_by_company"
    )
    # GET /workers sorts by `name` inside a company. Without an index that is a
    # blocking in-memory sort, which is half of why the endpoint began
    # returning 500 (the other half was loading base64 card images it never
    # needed -- see the projection there).
    #
    # (company_id, name) IN THAT ORDER, by ESR: `company_id` is the equality
    # prefix, `name` satisfies the sort. The query's third clause,
    # `is_deleted: {"$ne": True}`, is deliberately NOT in the key -- a $ne is
    # not selective and placing it before `name` would break the ordering the
    # sort depends on. It is applied to the documents the index scan returns.
    #
    # The existing (company_id, status) and (company_id, updated_at) indexes
    # cannot serve a `name` sort, so this is a new key rather than a duplicate.
    #
    # NOT A COMPLETE FIX ON ITS OWN. The platform-operator path queries with no
    # company_id at all, so this index cannot serve that sort either. THE
    # SENTENCE THAT USED TO FOLLOW WAS FALSE, and it is why the endpoint broke
    # again: it said the projection rescues that path, "with the images gone
    # the sort fits in memory regardless of whether an index is used".
    #
    # THE PLAN SAYS OTHERWISE. Against production, for the operator's query:
    #
    #     stages: ['PROJECTION_SIMPLE', 'SORT', 'COLLSCAN']
    #
    # PROJECTION_SIMPLE sits ABOVE SORT. The sort holds WHOLE DOCUMENTS and the
    # projection is applied to the fifty that survive it, so the images are
    # gone from the RESPONSE and never from the SORT. That path was never
    # fixed; it merely stopped failing, because the collection was under 32MB
    # on the day. It crossed 32MB again on 2026-09-03 11:45 -- 61 workers, 51.7
    # MB, 848KB per document -- and every load by the platform operator has
    # returned 500 since.
    #
    # `workers_by_name` below is what the operator's path actually needed, and
    # is the same mechanism as the compound above with the prefix dropped.
    await _ensure_index_resilient(
        db.workers,
        keys=[("company_id", 1), ("name", 1)],
        name="workers_by_company_name",
    )
    # ── THE SAME SORT, WITHOUT THE COMPANY PREFIX ──────────────────────────
    #
    # The platform operator has no company_id, so GET /workers issues
    # `{is_deleted: {$ne: True}}` sorted on `name` with NO equality prefix --
    # and `(company_id, name)` cannot serve that, because an index only
    # provides ordering on `name` once `company_id` is pinned by equality.
    # The planner has nothing else offering name-order, so it takes a COLLSCAN
    # and a BLOCKING in-memory SORT over every worker document on the
    # platform.
    #
    # A PLAIN `name` KEY, NOT A PARTIAL ONE. `workers_active_by_company` above
    # is partial on `is_deleted: {$eq: False}`, which cannot serve this query:
    # the filter is `$ne: True`, which MATCHES DOCUMENTS WITH NO is_deleted
    # FIELD, and a partial index on `$eq: False` excludes exactly those. An
    # index that silently omits the rows the query wants is worse than none.
    #
    # AND `is_deleted` IS NOT IN THE KEY, for the reason given above: a $ne is
    # not selective, and putting it before `name` would break the ordering the
    # sort depends on.
    #
    # THIS FIXES THE CRASH, NOT THE DISEASE. The documents are 848KB on average
    # because `osha_card_image` (37.8MB) and `selfie_image` (12.9MB) are stored
    # as base64 ON the worker row -- and 26 of the 30 selfies ALSO have a
    # `selfie_r2_url`, so the object is already in R2 and the base64 is a
    # second copy. Moving them out is the real answer and it is a migration,
    # not a hotfix. See docs/audits/followups.md.
    await _ensure_index_resilient(
        db.workers,
        keys=[("name", 1)],
        name="workers_by_name",
    )
    await db.checkins.create_index(
        [("project_id", 1), ("status", 1)],
        partialFilterExpression={"is_deleted": {"$eq": False}},
        name="checkins_active_by_project"
    )

    # ── UNSERVED SORTS ON BASE64-BEARING COLLECTIONS ────────────────────────
    #
    # The same shape as workers_by_company_name above, found by sweeping for it
    # rather than by waiting for the next 500: backend/scripts/
    # find_unserved_sorts.py, ratcheted by tests/test_sorts_are_indexed.py.
    #
    # Every one of these applies the SAME ESR reasoning written out above —
    # equality fields first, then the sort field in the sort's direction — and
    # the SAME exclusion: `is_deleted: {"$ne": True}` is not in any key. A $ne
    # over a two-valued field is a range scan, and a range key sitting between
    # the equality prefix and the sort key destroys the ordering the sort
    # depends on. It is applied to the documents the index scan returns.

    # GET /logbooks/project/{id}/submitted — THE ENDPOINT THAT FAILED IN FRONT
    # OF A DOB INSPECTOR, and GET /logbooks/project/{id}/logs, which filters
    # identically. Both match (project_id, status) by equality and sort `date`
    # descending. The nearest existing index is
    # (project_id, log_type, date) — `log_type` is unpinned by that filter, so
    # it cannot walk `date` in order and Mongo fell back to an in-memory sort
    # over documents carrying photo base64 under data.activities[].photos[].
    #
    # THIS INDEX ALREADY EXISTS ON PRODUCTION. It was created by hand in the
    # Atlas UI to stop the outage, with no deploy — which means it lives on
    # exactly one cluster, in no version control, and would not exist in the
    # next environment anyone builds. Declaring it here is the actual fix;
    # _ensure_index_resilient is idempotent, so the running cluster no-ops.
    await _ensure_index_resilient(
        db.logbooks,
        keys=[("project_id", 1), ("status", 1), ("date", -1)],
        name="logbooks_project_status_date",
    )

    # The same collection, sorted the same way, by the callers that DO NOT pin
    # `status`: GET /logbooks/project/{id} (status is never in that filter) and
    # the stale-unsigned scan in the notifications endpoint, which constrains
    # log_type with `$in` and date with `$lt` — both ranges, neither an
    # equality pin. logbooks_project_status_date above cannot serve them for
    # precisely the reason (project_id, log_type, date) could not serve the
    # endpoint that failed: an unpinned key sits before `date`.
    #
    # So this is a second index, not a duplicate. It is the two-key prefix that
    # covers every project-scoped `date` sort regardless of what else the
    # caller filters on.
    await _ensure_index_resilient(
        db.logbooks,
        keys=[("project_id", 1), ("date", -1)],
        name="logbooks_project_date",
    )

    # GET /annotations/{project_id}/{document_path} matches both of those by
    # equality and sorts `created_at` descending, to_list(500). The existing
    # (project_id, document_path) index stops one key short of the sort.
    #
    # SAME PAYLOAD PROBLEM, DIFFERENT FIELD: _generate_annotation_screenshot
    # writes a full JPEG data URL onto `screenshot` on the annotation document
    # itself, so 500 annotations on a busy drawing is the 32MB budget. This is
    # the third collection with the workers/logbooks shape and it has not
    # failed yet only because no single drawing has enough threads on it.
    #
    # This SUPERSEDES the unnamed (project_id, document_path) index created
    # above — that one is now a strict prefix of this one. Dropping it is a
    # separate change; a redundant prefix index costs write amplification, not
    # correctness.
    await _ensure_index_resilient(
        db.document_annotations,
        keys=[("project_id", 1), ("document_path", 1), ("created_at", -1)],
        name="annotations_project_document_created",
    )

    # GET /admin/users sorts every user by `name`. `company_id` is added to the
    # filter only when the caller is not an owner, so this serves the
    # company-scoped call — the one that grows with the tenant.
    #
    # NOT A COMPLETE FIX, and for the same reason workers_by_company_name is
    # not: the OWNER call carries no company_id at all, so no index led by
    # company_id can serve its sort. What rescued the workers path was the
    # projection, and this endpoint's projection is `{"password": 0}` — an
    # EXCLUSION, so every document it sorts still carries the CP's
    # `cp_signature` base64. An inclusion projection naming the fields the list
    # row actually renders is the fix for that call; it changes a response
    # shape, so it is deliberately not in this change. The gap is recorded as
    # the single allowlist entry in tests/test_sorts_are_indexed.py.
    await _ensure_index_resilient(
        db.users,
        keys=[("company_id", 1), ("name", 1)],
        name="users_by_company_name",
    )

    # COI expiration tracking (Phase 3 prep)
    await db.certificates_of_insurance.create_index(
        [("company_id", 1), ("expiration_date", 1)],
        name="coi_expiry_by_company"
    )
    # Worker certification expiration scanning
    await db.workers.create_index(
        [("certifications.expiration_date", 1)],
        partialFilterExpression={"is_deleted": {"$eq": False}},
        name="worker_cert_expiry",
    )

    # WhatsApp indexes
    await db.whatsapp_groups.create_index([("company_id", 1), ("wa_group_id", 1)])
    await db.whatsapp_groups.create_index("project_id")
    await db.whatsapp_messages.create_index([("project_id", 1), ("timestamp", -1)])
    await db.whatsapp_messages.create_index([("group_id", 1), ("created_at", -1)])
    await _ensure_index_resilient(
        db.whatsapp_contacts,
        keys=[("company_id", 1), ("phone", 1)],
        name="company_id_1_phone_1",
        unique=True,
    )
    await db.whatsapp_link_codes.create_index("expires_at", expireAfterSeconds=0)
    # One row per group, enforced by the database rather than by the two call
    # sites that upsert into it. Two webhooks for one group arrive at once more
    # often than not.
    await _ensure_index_resilient(
        db[PENDING_GROUPS],
        keys=[("group_id", 1)],
        name="whatsapp_pending_groups_group_id",
        unique=True,
    )
    await db[PENDING_GROUPS].create_index([("company_id", 1), ("status", 1)])

    # ── THE OPERATOR'S ACCOUNT, ON A DATABASE THAT HAS NONE ─────────────────
    #
    # A BOOTSTRAP, not a role assignment. It runs only when the account is
    # absent AND OWNER_DEFAULT_PASSWORD is set, which is a fresh database or a
    # restored one.
    #
    # THE ROLE IT WRITES IS "admin" NOW, and the block that used to follow it
    # is GONE. That block read
    #
    #     elif owner and owner.get("role") == "admin":
    #         ... {"$set": {"role": "owner"}}
    #
    # i.e. it rewrote this account's role back to the retired string on EVERY
    # BOOT. It was written when "owner" was believed to be a rank, and left in
    # place it would have silently undone the operator's account migration on
    # the first deploy after it ran — a writer of the role nobody had counted,
    # in the one file the census reads.
    #
    # BEING THE OPERATOR IS NOT WHAT THIS ROLE SAYS. `is_platform_operator`
    # decides that, from the flag on the row or from PLATFORM_OPERATOR_EMAILS,
    # and this code deliberately writes NEITHER: the flag is in no allow-list
    # and is set by a human on purpose, and the email list is an env var that
    # needs a redeploy to change. A seed that granted operator would be an API
    # path to the trust anchor wearing a startup hook's clothes.
