    #   (A) Delete notifications with non-null read_at older than
    #       READ_RETENTION_DAYS (90 days) — bounds long-term
    #       collection growth without losing recent context.
    #   (B) Auto-dismiss notifications whose status="active" AND
    #       expires_at is in the past — cleans expired predictions
    #       from the FE's default status="active" filter without
    #       deleting the audit trail.
    # 03:55 ET sits after the prediction-cleanup tick (03:45 ET)
    # so a prediction that expired overnight is first surfaced as
    # such on the prediction side, then dismissed on the
    # notifications side — predictable order for log archaeology.
    async def _notifications_cleanup_tick():
        try:
            stats = await _notifications_inbox.cleanup_inbox(db)
            logger.info(
                f"[notifications_cleanup] daily: {stats!r}"
            )
        except Exception as e:
            logger.error(
                f"[notifications_cleanup] crashed: {e!r}",
                exc_info=True,
            )
    scheduler.add_job(
        _notifications_cleanup_tick,
        CronTrigger(hour=3, minute=55, timezone="America/New_York"),
        id='notifications_cleanup',
        replace_existing=True,
        max_instances=1,
        coalesce=True,
    )

    # ── Task 8: soft-delete purge (opt-in, allowlist-only) ──
    # Hard-removes rows soft-deleted (is_deleted:true) more than N days ago, but
    # ONLY from an explicit allowlist of operational/replaceable collections.
    # Compliance/audit collections (checkins, logbooks, signatures, dob_logs,
    # compliance_alerts, ...) are NEVER purged — absent from the allowlist AND
    # blocked by the explicit NEVER set. Rows without a `deleted_at` stamp are
    # skipped, which protects any pre-backfill records. A TTL index was NOT used
    # deliberately: TTL keyed on the wrong timestamp deleted DOB compliance
    # history before (see scripts/drop_dob_logs_ttl.py), gives no allowlist, no
    # dry-run, and no audit. Off unless SOFT_DELETE_PURGE_ENABLED=true.
    SOFT_DELETE_RETENTION_DAYS = int(os.environ.get("SOFT_DELETE_RETENTION_DAYS", "90"))
    SOFT_DELETE_PURGE_ENABLED = os.environ.get("SOFT_DELETE_PURGE_ENABLED", "false").lower() == "true"
    SOFT_DELETE_PURGE_COLLECTIONS = [
        "nfc_tags", "site_devices", "dropbox_connections",
        "checklist_assignments", "checklists",
    ]
    SOFT_DELETE_NEVER_PURGE = {
        "checkins", "logbooks", "sign_ins", "signatures", "daily_signatures",
        "signature_events", "audit_logs", "compliance_alerts", "dob_logs",
        "certificates_of_insurance", "safety_staff_registrations",
        "cs_registrations", "workers", "users", "subcontractors",
        # A consent is evidence about a signature, and outlives the signature
        # it authorises. It is never purged for the same reason signature_events
        # is not.
        "esra_consents",
        # AND SO IS A REFUSAL. "He was asked on the 2nd and said no" is
        # evidence about why a statutory log carries no electronic signature —
        # which is exactly the question asked when one is missing. Listed here
        # rather than relying on its absence from the purge allowlist, because
        # that absence is not a decision anyone wrote down.
        "esra_consent_declines",
    }

    async def _soft_delete_purge_tick():
        if not SOFT_DELETE_PURGE_ENABLED:
            logger.info("[soft_delete_purge] disabled (SOFT_DELETE_PURGE_ENABLED off) — skipping")
            return
        cutoff = datetime.now(timezone.utc) - timedelta(days=SOFT_DELETE_RETENTION_DAYS)
        total = 0
        for coll_name in SOFT_DELETE_PURGE_COLLECTIONS:
            if coll_name in SOFT_DELETE_NEVER_PURGE:
                logger.warning(f"[soft_delete_purge] refusing protected collection {coll_name!r}")
                continue
            try:
                res = await db[coll_name].delete_many({
                    "is_deleted": True,
                    "deleted_at": {"$lte": cutoff},
                })
                if res.deleted_count:
                    logger.info(f"[soft_delete_purge] {coll_name}: removed {res.deleted_count} rows deleted >{SOFT_DELETE_RETENTION_DAYS}d ago")
                total += res.deleted_count
            except Exception as e:
                logger.warning(f"[soft_delete_purge] {coll_name} failed (non-fatal): {e!r}")
        logger.info(f"[soft_delete_purge] complete — {total} rows removed (retention={SOFT_DELETE_RETENTION_DAYS}d)")

    scheduler.add_job(
        _soft_delete_purge_tick,
        CronTrigger(hour=4, minute=30, timezone="America/New_York"),
        id='soft_delete_purge',
        replace_existing=True,
        max_instances=1,
        coalesce=True,
    )

    # ── Resend domain health check ──
    # Probe before the digest cron is registered so a verification
    # failure surfaces at deploy time, not at the next 7am ET tick.
    await _verify_resend_domain_at_startup()

    # ── Renewal digest daily cron ──
    # 7am America/New_York every day. One email per company per day,
    # only on days that actually crossed a threshold (per spec §4).
    # Suppression + idempotency live in renewal_alert_sent collection.
    try:
        scheduler.add_job(
            renewal_digest_daily_cron,
            CronTrigger(hour=7, minute=0, timezone="America/New_York"),
            id='renewal_digest_daily',
            replace_existing=True,
            max_instances=1,
            coalesce=True,
        )
        logger.info("📧 Renewal digest scheduled (daily 7am ET)")
    except Exception as _e:
        logger.error(f"renewal_digest_daily scheduler wire failed: {_e!r}")

    # ── ONE LEDGER ROW PER SIGNING ACT, ENFORCED BY THE DATABASE ───────────
    #
    # Two writers now describe the same signature: the signing client's POST
    # /signature-events and the server's derivation from an accepted document.
    # create_signature_event checks before it inserts, but check-then-insert is
    # not atomic and the race is REAL — daily_jobsite fires its ledger write
    # without awaiting it and then calls /finalize, so both can be in flight at
    # once. This is what actually settles it; the pre-check only keeps the
    # common case off the error path.
    #
    # PARTIAL, AND THAT IS LOAD-BEARING. Every row written before this existed
    # has no `signature_key` at all. A plain unique index would read them all
    # as null, collide on the second one, and fail to build — on a collection
    # that must never be rewritten to suit an index. The filter restricts it to
    # rows that carry a key, so it starts empty and only ever governs rows
    # written from here on.
    await _ensure_index_resilient(
        db.signature_events,
        keys=[("document_type", 1), ("document_id", 1), ("signature_key", 1)],
        name="signature_events_one_row_per_signing_act",
        unique=True,
        partialFilterExpression={"signature_key": {"$type": "string"}},
    )

    # ── ONE OPEN AMENDMENT PER PARENT, ENFORCED BY THE DATABASE ────────────
    #
    # The definition, and the argument for every clause of the filter, is at
    # OPEN_AMENDMENT_PARTIAL_FILTER. In short: amend_logbook reads the parent's
    # children and then inserts, with nothing between, so two simultaneous taps
    # both read "no open child" and both insert. That is the fork production
    # carries twice over. The application check stays as the fast path that
    # produces the helpful 409; this is what actually settles it.
    #
    # IT MAY LEGITIMATELY FAIL TO BUILD TODAY, AND THAT IS NOT A BUG HERE.
    # Production HAS the duplicates this index forbids — Aug 10 and Aug 14, two
    # open children on one parent each. A unique build over them is rejected,
    # and _ensure_index_resilient logs and returns rather than raising, which
    # is right: an index must never block app startup. It is also why
    # backend/scripts/create_open_amendment_index.js exists and why it REFUSES
    # to build over duplicates instead of failing quietly — the operator
    # applies indexes by hand, and a silently absent index would leave this
    # race open behind a green suite.
    # THE KEY SPEC IS A LITERAL HERE, AND THAT IS NOT A STYLE CHOICE.
    # find_unserved_sorts.py reads every index declaration in this file with an
    # AST walk and can only resolve a literal `keys=`; handed a constant NAME it
    # reports "key spec not literal" and stops covering the index, which is a
    # sort silently dropping out of the sweep. OPEN_AMENDMENT_INDEX_KEYS stays
    # as the value the tests and the by-hand script agree against, and
    # test_amendment_withdraw asserts this literal still equals it.
    await _ensure_index_resilient(
        db.logbooks,
        keys=[("parent_logbook_id", 1)],
        name=OPEN_AMENDMENT_INDEX_NAME,
        unique=True,
        partialFilterExpression=OPEN_AMENDMENT_PARTIAL_FILTER,
    )

    # Mongo TTL on eligibility_shadow records — 30 days. Idempotent.
    await _ensure_index_resilient(
        db.eligibility_shadow,
        keys=[("ran_at", 1)],
        name="eligibility_shadow_ttl",
        expireAfterSeconds=30 * 24 * 60 * 60,
    )

    # COI OCR drafts: 24h TTL. If admin uploads then walks away without
    # confirming, the draft drops automatically — no orphan accumulation.
    # The PDF + preview in R2 stay (7-year retention) but the in-flight
    # draft state is per-session.
    await _ensure_index_resilient(
        db.coi_ocr_drafts,
        keys=[("created_at", 1)],
        name="coi_ocr_drafts_ttl",
        expireAfterSeconds=24 * 60 * 60,
    )
    # Idempotency lookup index — same (company, sha, type) returns
    # the cached draft instead of creating a duplicate.
    await _ensure_index_resilient(
        db.coi_ocr_drafts,
        keys=[("company_id", 1), ("sha256", 1), ("insurance_type", 1)],
        name="coi_ocr_drafts_idem",
    )

    # Renewal-digest idempotency: one row per (company, kind, expiry,
    # threshold, sent_date). Prevents the cron firing twice on the same
    # day from sending two emails. 90-day TTL — long enough for late
    # debugging, short enough to not accumulate forever.
    await _ensure_index_resilient(
        db.renewal_alert_sent,
        keys=[
            ("company_id", 1),
            ("kind", 1),
            ("expiry_date", 1),
            ("threshold_days", 1),
            ("permit_id", 1),
            ("sent_date", 1),
        ],
        name="renewal_alert_sent_idem",
    )
    await _ensure_index_resilient(
        db.renewal_alert_sent,
        keys=[("sent_at", 1)],
        name="renewal_alert_sent_ttl",
        expireAfterSeconds=90 * 24 * 60 * 60,
    )

    # Phase B1a — notification_preferences. Unique compound on
    # (user_id, project_id) so each (user, project-or-null) pair
    # carries at most one record. Project-scoped reads compose with
    # the user-global fallback in lib.notification_preferences.
    await _ensure_index_resilient(
        db.notification_preferences,
        keys=[("user_id", 1), ("project_id", 1)],
        name="notification_preferences_user_project_unique",
        unique=True,
    )
    # Fast user_id-only lookup for the global fallback path.
    await _ensure_index_resilient(
        db.notification_preferences,
        keys=[("user_id", 1)],
        name="notification_preferences_user",
    )

    # Phase B1a — digest_queue. The dispatcher claims by status +
    # scheduled_send_at; we also support per-user lookups for the
    # "View pending digest items" admin surface that lands in B1b.
    await _ensure_index_resilient(
        db.digest_queue,
        keys=[("status", 1), ("scheduled_send_at", 1)],
        name="digest_queue_status_sched",
    )
    await _ensure_index_resilient(
        db.digest_queue,
        keys=[("user_id", 1), ("scheduled_send_at", 1), ("status", 1)],
        name="digest_queue_user_sched",
    )

    # Phase E1 — feature flags. Unique index on `flag` enforces
    # one document per flag name; the admin POST endpoint relies
    # on this to reject duplicates with a 409.
    await _ensure_index_resilient(
        db.feature_flags,
        keys=[("flag", 1)],
        name="feature_flags_flag_unique",
        unique=True,
    )
    # Audit log lookups by flag (newest first) for the
    # "who changed what when" review query in runbook §13.
    await _ensure_index_resilient(
        db.feature_flag_audit_log,
        keys=[("flag", 1), ("changed_at", -1)],
        name="feature_flag_audit_flag_changed",
    )

    # Phase V2.0 — compliance logbook indexes. Sourced from
    # lib/logbook/schema.py LOGBOOK_ENTRIES_INDEXES so the spec
    # lives in one place. The unique index on
    # (project_id, entry_date, category) enforces the dedupe
    # guarantee the missing/deficiency detectors rely on for
    # idempotent re-runs.
    for _idx_spec in _logbook.LOGBOOK_ENTRIES_INDEXES:
        await _ensure_index_resilient(
            db.logbook_entries,
            keys=_idx_spec["keys"],
            name=_idx_spec["name"],
            **{k: v for k, v in _idx_spec.items() if k not in ("keys", "name")},
        )

    # V2.3 Commit 1: ALL_V22_INDEX_SPECS shrank from 11 collections
    # to 2. The nyc_* mirror collections + statistical_baselines +
    # ingestion_state index specs were removed alongside their
    # deletion in lib/statistical_engine/schema.py. Surviving
    # entries: predicted_events + prediction_outcomes (both
    # untouched in Commit 1; rewritten consumers come in Commit 3).
    for _coll_name, _idx_specs in _stat_engine.ALL_V22_INDEX_SPECS:
        _coll = db[_coll_name]
        for _idx_spec in _idx_specs:
            await _ensure_index_resilient(
                _coll,
                keys=_idx_spec["keys"],
                name=_idx_spec["name"],
                **{
                    k: v for k, v in _idx_spec.items()
                    if k not in ("keys", "name")
                },
            )

    # PR #15A.1 — Daily Panel + Validation Ledger indexes.
    # Mirrors the ALL_V22_INDEX_SPECS loop above; covers the two
    # PR #15A collections (daily_panels + prediction_validation_ledger)
    # via the same resilient helper. 6 indexes total — see
    # lib/statistical_engine/schema.py:DAILY_PANELS_INDEXES +
    # PREDICTION_VALIDATION_LEDGER_INDEXES. The unique compound on
    # (project_id, calendar_date) enforces the T7 canonical-per-day
    # contract at the DB layer; the 7-day TTL on daily_panels.built_at
    # auto-expires stale panels.
    for _coll_name, _idx_specs in _stat_engine.ALL_PR15A_INDEX_SPECS:
        _coll = db[_coll_name]
        for _idx_spec in _idx_specs:
            await _ensure_index_resilient(
                _coll,
                keys=_idx_spec["keys"],
                name=_idx_spec["name"],
                **{
                    k: v for k, v in _idx_spec.items()
                    if k not in ("keys", "name")
                },
            )

    # PR #15B — prediction_models indexes (Stage 3.A — Lock L9).
    # 3 indexes covering: latest-fit-per-project (live mutation hot
    # path), model-hash join key for the validation ledger, and a
    # 60-day TTL for rolling β history.
    for _coll_name, _idx_specs in _stat_engine.ALL_PR15B_INDEX_SPECS:
        _coll = db[_coll_name]
        for _idx_spec in _idx_specs:
            await _ensure_index_resilient(
                _coll,
                keys=_idx_spec["keys"],
                name=_idx_spec["name"],
                **{
                    k: v for k, v in _idx_spec.items()
                    if k not in ("keys", "name")
                },
            )

    # PR #15B Stage 3.B — Predictive Inference Engine crons.
    #
    # Two cron jobs, registered on the existing APScheduler:
    #
    #   • pr15b_nightly_panel_refit (2:45 AM ET) — walks active
    #     projects, fits β per project via sklearn LogisticRegression
    #     on daily_panels rows, writes prediction_models +
    #     prediction_cache + prediction_validation_ledger entries.
    #     Cold-start branch (sample_size<30) writes borough actuarial
    #     baselines instead of fitting β.
    #
    #   • pr15b_validation_audit_sweep (4:15 AM ET) — walks the
    #     prediction_validation_ledger entries whose target_horizon_at
    #     has passed, scores observed_outcome from severe ECB
    #     violations, computes brier_score_delta.
    #
    # L12 lock: both crons isolate failures to the 4 new collection
    # surfaces (daily_panels, prediction_models, validation_ledger,
    # projects.prediction_cache). They NEVER mutate peer_stats_cache
    # or risk_score_log even on per-project exceptions.
    #
    # PR #15B.1 B1 — third cron: pr15a_nightly_panel_build (1:30 AM
    # ET). Registered BEFORE the refit so source order reads
    # build (1:30) → refit (2:45) → audit (4:15) top-to-bottom.
    # Without this cron, daily_panels stays empty and every project
    # falls through to cold-start (the bug Stage 1 Probe D confirmed).
    async def _pr15a_nightly_panel_build_tick():
        try:
            from lib.statistical_engine.socrata_client import (
                SocrataClient,
            )
            from lib.server_http import ServerHttpClient
            async with ServerHttpClient(timeout=10.0) as _http:
                _socrata = SocrataClient(_http)
                stats = await _stat_engine.nightly_panel_build_for_all_projects(
                    db, _socrata,
                )
            logger.info(
                f"[pr15a_panel_build] tick complete: {stats!r}"
            )
        except Exception as e:
            logger.error(
                f"[pr15a_panel_build] tick crashed: {e!r}",
                exc_info=True,
            )

    scheduler.add_job(
        _pr15a_nightly_panel_build_tick,
        CronTrigger(hour=1, minute=30, timezone="America/New_York"),
        id="pr15a_nightly_panel_build",
        replace_existing=True, max_instances=1, coalesce=True,
    )
    logger.info(
        "🏗️ PR #15A panel-build cron scheduled (1:30 AM ET)"
    )

    async def _pr15b_nightly_refit_tick():
        try:
            from lib.statistical_engine.socrata_client import (
                SocrataClient,
            )
            from lib.server_http import ServerHttpClient
            async with ServerHttpClient(timeout=10.0) as _http:
                _socrata = SocrataClient(_http)
                stats = await _stat_engine.nightly_refit_for_all_projects(
                    db, _socrata,
                )
            logger.info(f"[pr15b_nightly_refit] tick complete: {stats!r}")
        except Exception as e:
            logger.error(
                f"[pr15b_nightly_refit] tick crashed: {e!r}",
                exc_info=True,
            )

    async def _pr15b_validation_audit_tick():
        try:
            from lib.statistical_engine.socrata_client import (
                SocrataClient,
            )
            from lib.server_http import ServerHttpClient
            async with ServerHttpClient(timeout=10.0) as _http:
                _socrata = SocrataClient(_http)
                stats = await _stat_engine.validation_audit_sweep(
                    db, _socrata,
                )
            logger.info(f"[pr15b_validation_audit] tick complete: {stats!r}")
        except Exception as e:
            logger.error(
                f"[pr15b_validation_audit] tick crashed: {e!r}",
                exc_info=True,
            )

    scheduler.add_job(
        _pr15b_nightly_refit_tick,
        CronTrigger(hour=2, minute=45, timezone="America/New_York"),
        id="pr15b_nightly_panel_refit",
        replace_existing=True,
        max_instances=1,
        coalesce=True,
    )
    scheduler.add_job(
        _pr15b_validation_audit_tick,
        CronTrigger(hour=4, minute=15, timezone="America/New_York"),
        id="pr15b_validation_audit_sweep",
        replace_existing=True,
        max_instances=1,
        coalesce=True,
    )
    logger.info(
        "🔮 PR #15B prediction engine crons scheduled "
        "(refit 2:45 AM ET, audit 4:15 AM ET)"
    )

    # Phase 1 Week 3 PR-C — weekly cohort baseline aggregator. Reads
    # the Phase 1 Week 1 backfilled historical data + the PR-A/PR-B
    # phase tracking, writes per-cohort 30d violation rates to
    # violation_baseline_aggregates. Mondays at 3:00 AM ET — off-peak,
    # downstream of the nightly panel build + refit so the most recent
    # daily_log.phase values are visible to the aggregator.
    async def _phase1w3_weekly_baseline_aggregator_tick():
        try:
            from lib.statistical_engine.violation_baseline_aggregator import (
                compute_baseline_aggregates,
            )
            result = await compute_baseline_aggregates(db)
            logger.info(
                f"[phase1w3_baseline_aggregator] tick complete: {result!r}",
            )
        except Exception as e:
            logger.error(
                f"[phase1w3_baseline_aggregator] tick crashed: {e!r}",
                exc_info=True,
            )

    scheduler.add_job(
        _phase1w3_weekly_baseline_aggregator_tick,
        CronTrigger(
            day_of_week="mon", hour=3, minute=0,
            timezone="America/New_York",
        ),
        id="phase1w3_weekly_baseline_aggregator",
        replace_existing=True,
        max_instances=1,
        coalesce=True,
    )
    logger.info(
        "📊 Phase 1 Week 3 baseline aggregator cron scheduled "
        "(Mondays 3:00 AM ET)"
    )

    # Phase 1 Week 13-19 PR-A — weekly causal lift matrix computation.
    # Reads the Phase 1 Week 1 backfilled complaints + violations data,
    # writes the 300-cell (10 buckets × 10 buckets × 3 windows)
    # causal_lift_matrix collection. Mondays at 3:30 AM ET — 30 minutes
    # after baseline_aggregator so the two run sequentially, not
    # concurrently (both read from the same historical collections).
    async def _phase1w13_weekly_causal_lift_tick():
        try:
            from lib.statistical_engine.causal_lift import (
                compute_causal_lift_matrix,
            )
            result = await compute_causal_lift_matrix(db)
            logger.info(
                f"[phase1w13_causal_lift] tick complete: {result!r}",
            )
        except Exception as e:
            logger.error(
                f"[phase1w13_causal_lift] tick crashed: {e!r}",
                exc_info=True,
            )

    scheduler.add_job(
        _phase1w13_weekly_causal_lift_tick,
        CronTrigger(
            day_of_week="mon", hour=3, minute=30,
            timezone="America/New_York",
        ),
        id="phase1w13_weekly_causal_lift",
        replace_existing=True,
        max_instances=1,
        coalesce=True,
    )
    logger.info(
        "🔗 Phase 1 Week 13-19 causal lift cron scheduled "
        "(Mondays 3:30 AM ET — 30 min after baseline aggregator)"
    )

    # PR #48 — weekly Gemini phase inference. Iterates active projects,
    # infers each project's current lifecycle phase from the last 7 days
    # of daily logs, persists to db.projects.ai_inferred_phase. Sunday
    # 4:00 AM ET — ~23h before the Monday 3:00 AM baseline_aggregator so
    # the downstream resolver (live_mutation._resolve_schedule_position)
    # reads fresh phase signals. Per-project failure tolerant.
    async def _weekly_phase_inference_tick():
        try:
            from lib.ai.phase_inference import run_weekly_phase_inference
            result = await run_weekly_phase_inference(db)
            logger.info(
                f"[pr48_phase_inference] tick complete: {result!r}",
            )
        except Exception as e:
            logger.exception(
                f"[pr48_phase_inference] tick crashed: {e!r}",
            )

    scheduler.add_job(
        _weekly_phase_inference_tick,
        CronTrigger(
            day_of_week="sun", hour=4, minute=0,
            timezone="America/New_York",
        ),
        id="weekly_phase_inference",
        replace_existing=True,
        max_instances=1,
        coalesce=True,
    )
    logger.info(
        "🤖 PR #48 weekly phase inference cron scheduled "
        "(Sundays 4:00 AM ET — day before baseline aggregator)"
    )

    # V2.3 Commit 5 — compound index on peer_stats_cache for the
    # refresh cron's eligibility query. Status has small cardinality
    # (~4 values: ready / pending / failed / absent), so the
    # status-key prefix narrows the scan tightly; the
    # last_refreshed_at second key directly covers the stale-ready
    # clause's sort. Failed and orphan-pending clauses still scan
    # within their status bucket but the bucket is small.
    # _ensure_index_resilient is idempotent — survives both an
    # already-existing index and a spec change.
    await _ensure_index_resilient(
        db.projects,
        keys=[
            ("peer_stats_cache.status", 1),
            ("peer_stats_cache.last_refreshed_at", 1),
        ],
        name="projects_peer_stats_status_refreshed_at",
    )

    # V2.3 Commit 7 — notifications inbox indexes. Five compound
    # indexes covering the four FE-facing query shapes + the
    # cleanup cron's sweep:
    #   • (user_id, created_at DESC) — primary list view
    #   • (user_id, read_at, created_at DESC) — unread-only filter
    #   • (project_id, created_at DESC) — per-project audit
    #   • (expires_at) — cleanup cron's expired-active scan
    #   • (source_kind, source_id) — dedup lookup at dispatch time
    # Read-heavy collection so the write-amplification of 5 indexes
    # is acceptable. Cleanup cron + 90-day read retention bound
    # collection size; with ~1000 active projects × maybe 5
    # predictions/month × maybe 10 recipients each, expected
    # steady-state is ~50K rows — trivial for indexed reads.
    _notif_coll = db[_notifications_inbox.NOTIFICATIONS_COLLECTION]
    await _ensure_index_resilient(
        _notif_coll,
        keys=[("user_id", 1), ("created_at", -1)],
        name="notifications_user_created",
    )
    await _ensure_index_resilient(
        _notif_coll,
        keys=[("user_id", 1), ("read_at", 1), ("created_at", -1)],
        name="notifications_user_read_created",
    )
    await _ensure_index_resilient(
        _notif_coll,
        keys=[("project_id", 1), ("created_at", -1)],
        name="notifications_project_created",
    )
    await _ensure_index_resilient(
        _notif_coll,
        keys=[("expires_at", 1)],
        name="notifications_expires",
    )
    await _ensure_index_resilient(
        _notif_coll,
        keys=[("source_kind", 1), ("source_id", 1)],
        name="notifications_source_lookup",
    )

    # risk_scores collection retains its index from V2.1 — V2.2
    # produces fresh rows in the same shape so the FE
    # (RiskScoreCircle / RiskScoreDrawer) reads via the same
    # query pattern. Old V2.1 risk_score_reviews and
    # risk_score_calibration collections are no longer indexed
    # here; existing rows on production are inert (V2.2 doesn't
    # write to or read from them).
    await _ensure_index_resilient(
        db.risk_scores,
        keys=[("project_id", 1), ("calculated_at", -1)],
        name="risk_scores_project_calculated_desc",
    )
    await _ensure_index_resilient(
        db.risk_scores,
        keys=[("company_id", 1), ("project_id", 1), ("calculated_at", -1)],
        name="risk_scores_company_project_calculated",
    )

    # worker_project_trades — the per-worker-per-project trade/company store.
    # See the collection's contract + the ACCEPTED-DEBT note on
    # worker_enrollments at WORKER_PROJECT_TRADES_COLLECTION above.
    #
    # UNIQUE on (worker_id, project_id): the pairing IS the identity of the
    # row, so the DB — not application code — guarantees one trade per worker
    # per project. Both gate paths upsert on exactly this key, so a
    # double-tap at the gate can never mint a second, divergent pairing.
    # Created through _ensure_index_resilient like every other index here, so
    # a future key-shape change drops-and-recreates instead of bricking
    # startup on an IndexKeySpecsConflict.
    await _ensure_index_resilient(
        db[WORKER_PROJECT_TRADES_COLLECTION],
        keys=[("worker_id", 1), ("project_id", 1)],
        name="worker_project_trades_worker_project_unique",
        unique=True,
    )

    # Phase B1a — digest_dispatcher cron. 15-minute cadence, same
    # interval as the DOB nightly_dob_scan so digest-eligible items
    # never wait more than one tick past their scheduled_send_at.
    # max_instances=1 + coalesce=True follow the pattern of the
    # eligibility shadow sweep below: a slow run skips its
    # successor instead of stacking.
    try:
        from lib.notification_preferences import dispatch_digests as _dispatch_digests
        from lib.notifications import send_notification as _digest_send_fn

        async def _digest_dispatcher_tick():
            try:
                await _dispatch_digests(
                    db, send_notification_fn=_digest_send_fn,
                )
            except Exception as _e:
                logger.error(
                    "[digest_dispatcher] tick failed: %r", _e,
                )

        scheduler.add_job(
            _digest_dispatcher_tick,
            IntervalTrigger(minutes=15),
            id='digest_dispatcher',
            replace_existing=True,
            max_instances=1,
            coalesce=True,
            next_run_time=datetime.now(timezone.utc) + timedelta(minutes=2),
        )
        logger.info(
            "📬 Digest dispatcher scheduled (every 15 min)"
        )
    except Exception as _digest_job_err:
        logger.error(
            "digest_dispatcher scheduler wire failed: %r", _digest_job_err,
        )

    scheduler.start()
    logger.info("📧 Report email scheduler started")
    logger.info("🏗️ DOB compliance scanner scheduled (every 30 minutes)")
    logger.info("🔍 Nightly compliance check scheduled (10 PM)")
    logger.info("💬 WhatsApp daily summary scheduled (every 30 min, per-group config)")
    logger.info("✅ WhatsApp checklist extraction scheduled (every 30 min, per-group config)")

    # WhatsApp startup migrations — bot_config backfill, indexes, TTL
    await run_whatsapp_startup_migrations()
    # Separate await, so a failure in the WhatsApp migrations cannot skip it.
    await ensure_dropbox_sync_indexes()
    # Also separate, and it never belonged inside the WhatsApp runner at all —
    # document_page_index is the plan-query pipeline. See its docstring.
    await ensure_document_page_indexes()

    # Account activation gating — backfill existing users to "approved" so the
    # new pending-by-default gate never locks out current accounts.
    await run_account_status_startup_migration()
    
    # DOB collection indexes
    await db.dob_logs.create_index([("project_id", 1), ("detected_at", -1)])
    await db.dob_logs.create_index([("company_id", 1)])

    # MR.14 (commit 2a) — drop the legacy `raw_dob_id` unique index
    # and replace with a non-unique lookup index. The v1 monitoring
    # product's status-change diffing intentionally inserts MULTIPLE
    # rows per raw_dob_id (one per status transition); the prior
    # unique constraint would reject those. Idempotent: drop only
    # if it exists and is the unique-flagged form.
    try:
        existing_indexes = await db.dob_logs.index_information()
        legacy_idx = existing_indexes.get("raw_dob_id_1")
        if legacy_idx and legacy_idx.get("unique"):
            await db.dob_logs.drop_index("raw_dob_id_1")
            logger.info("Dropped legacy unique index dob_logs.raw_dob_id_1 (MR.14)")
    except Exception as _drop_err:
        logger.warning(
            "Could not drop legacy raw_dob_id_1 unique index "
            "(may already be dropped or replaced): %s", _drop_err,
        )
    # Non-unique lookup index. The diffing logic in
    # _query_dob_apis / 311 paths uses find_one(sort=detected_at desc)
    # to pick the most recent doc for status comparison.
    await db.dob_logs.create_index([("raw_dob_id", 1), ("detected_at", -1)])

    # ── TTL retention REMOVED 2026-07-24 ──────────────────────────────
    # Was MR.14 (commit 2a) "operator F8": two TTL indexes keyed on
    # `detected_at` — 90 days for {permit, complaint, inspection,
    # job_status} (dob_logs_ttl_short) and 365 days for {violation, swo}
    # (dob_logs_ttl_long).
    #
    # `detected_at` is a BACKFILL / SYNC timestamp — the moment this app
    # first saw a record — NOT the date the event occurred. Every record
    # on a project carries that project's first-sync time, so a 2019
    # violation and a 2026 violation shared one expiry. The TTL clock
    # therefore measured time-since-first-sync, and would have physically
    # deleted every permit/complaint/inspection/job_status row ~90 days
    # after a project's first sync and every violation/swo row ~365 days
    # after. Re-sync could not restore them: each Socrata endpoint fetches
    # $limit=50, and a re-inserted row resets previous_status and can
    # re-fire Action-severity alerts.
    #
    # `detected_at` MUST NEVER be used as a retention clock. It stays —
    # deliberately — as the activity feed's ordering/date_range field and
    # as the diffing sort key of the (raw_dob_id, detected_at) index above.
    #
    # Any FUTURE retention policy must (1) key on a REAL EVENT DATE
    # (violation_date / complaint_date / expiration_date / inspection_date
    # — today stored as strings, so a BSON-Date field + backfill is
    # required), and (2) carry a documented legal rationale. dob_logs is
    # compliance history: a GC may need to produce a violation record years
    # later. Compare docs/coi-retention-guarantee.md — this product's one
    # deliberate retention decision (7 years, with a written justification).
    #
    # Dropping the two live Atlas indexes is an operational step, not a
    # code one; this removal only stops them being re-created at startup.
    # Runbook: docs/runbooks/dob-logs-ttl-removal-2026-07-24.md

    # MR.14 (commit 3) — index for the activity feed's "unread for me"
    # query. read_by_user is an array of {user_id, read_at} dicts;
    # multikey on the sub-field supports
    # `{read_by_user.user_id: {$ne: <my_id>}}` cheaply.
    await db.dob_logs.create_index([
        ("project_id", 1),
        ("read_by_user.user_id", 1),
        ("status_changed_at", -1),
    ])
    # MR.14 commit 4a — index for seed-suppression filter. Default
    # activity-feed query is `{is_seed_transition: {$ne: true}}`
    # scoped to a project; this composite supports it cheaply.
    await db.dob_logs.create_index([
        ("project_id", 1),
        ("is_seed_transition", 1),
        ("status_changed_at", -1),
    ])

    # 2026-07-25 — dob-summary aggregation dedup index. GET
    # /projects/dob-summary matches on (company_id, record_type) then
    # dedups by raw_dob_id via a (status_changed_at desc, detected_at
    # desc) sort. This compound covers the match prefix AND the dedup
    # sort so the aggregation runs index-ordered instead of a blocking
    # in-memory sort on every dashboard load.
    await db.dob_logs.create_index([
        ("company_id", 1),
        ("record_type", 1),
        ("raw_dob_id", 1),
        ("status_changed_at", -1),
        ("detected_at", -1),
    ], name="dob_logs_summary_dedup")

    # Card audit module init — injects db + R2 + VLM adapter. Must run
    # AFTER _r2_client is initialized (which happens at module import
    # time via the _get_r2_client() call wired into startup below, if
    # present) but BEFORE the first request. Doing it here at end of
    # startup means both are guaranteed ready.
    try:
        import card_audit as _card_audit  # noqa: E402
        _card_audit.init(
            db_ref=db,
            r2_client=_r2_client,
            qwen_vlm=_card_audit_vlm_adapter,
        )
        await _card_audit.ensure_indexes()
        logger.info(
            f"🪪 card_audit wired. bucket={_card_audit.CARD_AUDIT_BUCKET_NAME!r} "
            f"key_prefix={_card_audit.CARD_AUDIT_KEY_PREFIX!r}"
        )
        if not _card_audit.CARD_AUDIT_BUCKET_NAME:
            logger.warning(
                "⚠️  No R2 bucket configured for card audit — card photos "
                "will not persist. Set R2_BUCKET_NAME."
            )
    except Exception as _init_err:
        logger.error(f"card_audit init failed: {_init_err!r}")

    logger.info("Levelog API started successfully with Sync v2.0")
